INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('create', '作り出す、創造する', 'verb', '作るの意味の「creare」が語源で、「create」は"創造する"という意味になった。', NOW(), NOW()),('increase', '増加する／増加', 'verb', '中にの「in-」と"育つ"の「crescere」が結合して"増加する"という意味になった。', NOW(), NOW()),('improve', '改善する、向上させる', 'verb', '中への「in-」と"良くする"の「probare」が結合して"改善する"という意味になった。', NOW(), NOW()),('mean', '意味する、意図する／意味／意地悪な', 'verb', '古英語「mænan（意図する）」が語源で、「mean」は"意味する"という意味になった。', NOW(), NOW()),('include', '含む、含める', 'verb', '中にの「in-」と"閉じる"の「claudere」が結合して"含む"という意味になった。', NOW(), NOW()),('consider', 'よく考える、みなす', 'verb', '共にの「con-」と"星を観る"の「sidus」が結合して"よく考える"という意味になった。', NOW(), NOW()),('allow', '許可する', 'verb', '〜への「ad-」と"束縛を緩める"の「laxare」が変化して"許す"という意味になった。', NOW(), NOW()),('suggest', '提案する', 'verb', '下への「sub-」と"持ち上げる"の「gerere」が結合して"提案する"という意味になった。', NOW(), NOW()),('produce', '生産する、作り出す', 'verb', '前への「pro-」と"導く"の「ducere」が結合して"生み出す"という意味になった。', NOW(), NOW()),('decide', '決定する', 'verb', '離れての「de-」と"切る"の「caedere」が結合して"決定する"という意味になった。', NOW(), NOW()),('offer', '提供する／申し出', 'verb', '〜への「ob-」と"運ぶ"の「ferre」が結合して"差し出す"という意味になった。', NOW(), NOW()),('require', '必要とする、要求する', 'verb', '再びの「re-」と"探し求める"の「quaerere」が結合して"要求する"という意味になった。', NOW(), NOW()),('tend', '傾向がある、世話をする', 'verb', '伸ばすの意味のラテン語「tendere」が語源で、「tend」は"傾向がある"という意味になった。', NOW(), NOW()),('describe', '説明する、描写する', 'verb', '下にの「de-」と"書く"の「scribere」が結合して"記述する"という意味になった。', NOW(), NOW()),('involve', '含む、関与させる', 'verb', '中にの「in-」と"巻き込む"の「volvere」が結合して"巻き込む"という意味になった。', NOW(), NOW()),('reduce', '減らす、縮小する', 'verb', '後ろへの「re-」と"導く"の「ducere」が結合して"減少させる"という意味になった。', NOW(), NOW()),('design', '設計する／デザイン', 'verb', '下にの「de-」と"印をつける"の「signare」が結合して"設計する"という意味になった。', NOW(), NOW()),('force', '強制する／力', 'verb', 'ラテン語「fortis（強い）」が語源で、「force」は"力"という意味になった。', NOW(), NOW()),('affect', '影響を与える', 'verb', '〜への「ad-」と"作る・する"の「facere」が結合して"影響を与える"という意味になった。', NOW(), NOW()),('deal', '対処する／取引', 'verb', '古英語「dælan（分ける）」が語源で、「deal」は"扱う・分配する"という意味になった。', NOW(), NOW()),('avoid', '避ける', 'verb', 'ラテン語「evitare（避ける）」が語源で、「avoid」は"避ける"という意味になった。', NOW(), NOW()),('relate', '関係する', 'verb', '再びの「re-」と"運ぶ"の「ferre」から派生した「relatus」が語源で、"関係づける"という意味になった。', NOW(), NOW()),('realize', '気づく、実現する', 'verb', '再びの「re-」と"現実にする"の「alis（実体の）」が結合して"実現する・悟る"という意味になった。', NOW(), NOW()),('encourage', '励ます、促す', 'verb', '中への「en-」と"心"の「courage」が結合して"励ます"という意味になった。', NOW(), NOW()),('compare', '比較する', 'verb', '共にの「com-」と"並べる"の「parare」が結合して"比較する"という意味になった。', NOW(), NOW()),('measure', '測る／尺度', 'verb', 'ラテン語「mensura（測定）」が語源で、「measure」は"測る"という意味になった。', NOW(), NOW()),('exist', '存在する', 'verb', '外への「ex-」と"立つ"の「sistere」が結合して"存在する"という意味になった。', NOW(), NOW()),('mark', '印をつける／印、記号', 'verb', '古英語「mearc（印）」が語源で、「mark」は"印をつける"という意味になった。', NOW(), NOW()),('depend', '依存する', 'verb', '下にの「de-」と"ぶら下がる"の「pendere」が結合して"依存する"という意味になった。', NOW(), NOW()),('object', '反対する／物体、目的', 'verb', '対しての「ob-」と"投げる"の「iacere」が結合して"反対する・物体"という意味になった。', NOW(), NOW()),('demand', '要求する／需要', 'verb', '強くの「de-」と"命じる"の「mandare」が結合して"要求する"という意味になった。', NOW(), NOW()),('found', '設立する', 'verb', '底を築くのラテン語「fundare」が語源で、「found」は"設立する"という意味になった。', NOW(), NOW()),('complete', '完了する／完全な', 'verb', '共にの「com-」と"満たす"の「plere」が結合して"完成させる"という意味になった。', NOW(), NOW()),('interest', '興味、関心／興味を持たせる', 'verb', '間にの「inter-」と"ある"の「esse」が結合して"関心・利害"という意味になった。', NOW(), NOW()),('research', '研究、調査／研究する', 'verb', '再びの「re-」と"探す"の「cercher（フランス語）」が結合して"研究する"という意味になった。', NOW(), NOW()),('cause', '原因／引き起こす', 'verb', 'ラテン語「causa（理由・訴訟）」が語源で、「cause」は"原因"という意味になった。', NOW(), NOW()),('influence', '影響／影響を与える', 'verb', '中にの「in-」と"流れ"の「fluere」が結合して"影響"という意味になった。', NOW(), NOW()),('value', '価値／評価する', 'verb', 'ラテン語「valere（価値がある、強い）」が語源で、「value」は"価値"という意味になった。', NOW(), NOW()),('practice', '練習、実践／練習する', 'verb', 'ラテン語「practicare（実行する）」が語源で、「practice」は"練習・実行"という意味になった。', NOW(), NOW()),('notice', '気づく、通知', 'verb', 'ラテン語「notitia（知らせ）」が語源で、「notice」は"気づく"という意味になった。', NOW(), NOW()),('refer', '言及する、参照する', 'verb', '後ろへの「re-」と"運ぶ"の「ferre」が結合して"言及する"という意味になった。', NOW(), NOW()),('approach', '接近する、取り組む／方法', 'verb', 'ラテン語「appropiare（近づく）」が語源で、「approach」は"接近する"という意味になった。', NOW(), NOW()),('imagine', '想像する', 'verb', '中にの「in-」と"模倣する"の「imitari」が結合して"想像する"という意味になった。', NOW(), NOW()),('recognize', '認識する、認める', 'verb', '再びの「re-」と"知る"の「cognoscere」が結合して"認識する"という意味になった。', NOW(), NOW()),('solve', '解決する', 'verb', 'ラテン語「solvere（解く）」が語源で、「solve」は"解決する"という意味になった。', NOW(), NOW()),('occur', '発生する', 'verb', '"〜の上に"の「ob-」と"走る"の「currere」が結合して"起こる"という意味になった。', NOW(), NOW()),('argue', '主張する、議論する', 'verb', 'ラテン語「arguere（証明する）」が語源で、「argue」は"議論する"という意味になった。', NOW(), NOW()),('claim', '主張する／主張、要求', 'verb', 'ラテン語「clamare（叫ぶ）」が語源で、「claim」は"主張する"という意味になった。', NOW(), NOW()),('express', '表現する', 'verb', '"外に"の「ex-」と"押し出す"の「primere」が結合して"表現する"という意味になった。', NOW(), NOW()),('draw', '描く、引く', 'verb', '古英語「dragan（引く）」が語源で、「draw」は"引く・描く"という意味になった。', NOW(), NOW()),('waste', '無駄にする／浪費', 'verb', 'ラテン語「vastus（空の、荒れた）」が語源で、「waste」は"浪費する・無駄"という意味になった。', NOW(), NOW()),('advance', '前進する／進歩', 'verb', '"前に"の「ad-」と"歩く"の「vadere」が結合して"前進する"という意味になった。', NOW(), NOW()),('spread', '広げる、広がる／拡散', 'verb', '古英語「spreodian（広げる）」が語源で、「spread」は"広がる"という意味になった。', NOW(), NOW()),('prepare', '準備する', 'verb', '"前もって"の「pre-」と"整える"の「parare」が結合して"準備する"という意味になった。', NOW(), NOW()),('gain', '得る／利益', 'verb', '古フランス語「gaaignier（手に入れる）」が語源で、「gain」は"得る"という意味になった。', NOW(), NOW()),('achieve', '達成する', 'verb', '"〜へ"の「ad-」と"完了する"の「capere（取る）」が結合して"達成する"という意味になった。', NOW(), NOW()),('establish', '設立する、確立する', 'verb', 'ラテン語「stabilire（安定させる）」が語源で、「establish」は"確立する"という意味になった。', NOW(), NOW()),('supply', '供給する／供給', 'verb', '"下に"の「sub-」と"満たす"の「plere」が結合して"供給する"という意味になった。', NOW(), NOW()),('suppose', '仮定する', 'verb', '"下に"の「sub-」と"置く"の「ponere」が結合して"仮定する"という意味になった。', NOW(), NOW()),('perform', '演じる、実行する', 'verb', '"完全に"の「per-」と"形作る"の「formare」が結合して"遂行する"という意味になった。', NOW(), NOW()),('prefer', '好む', 'verb', '"前に"の「prae-」と"運ぶ"の「ferre」が結合して"好む"という意味になった。', NOW(), NOW()),('determine', '決定する、特定する', 'verb', '"完全に"の「de-」と"境界を定める"の「terminare」が結合して"決定する"という意味になった。', NOW(), NOW()),('treat', '扱う、治療する', 'verb', 'ラテン語「tractare（扱う）」が語源で、「treat」は"扱う・治療する"という意味になった。', NOW(), NOW()),('prove', '証明する', 'verb', 'ラテン語「probare（試す、証明する）」が語源で、「prove」は"証明する"という意味になった。', NOW(), NOW()),('apply', '申し込む、適用する', 'verb', '"〜へ"の「ad-」と"折る・重ねる"の「plicare」が結合して"適用する・申し込む"という意味になった。', NOW(), NOW()),('mention', '言及する', 'verb', 'ラテン語「mentio（言及）」が語源で、「mention」は"言及する"という意味になった。', NOW(), NOW()),('communicate', '意思疎通する', 'verb', '"共に"の「com-」と"分け合う"の「municare」が結合して"伝える"という意味になった。', NOW(), NOW()),('contain', '含む', 'verb', '"共に"の「con-」と"保つ"の「tenere」が結合して"含む"という意味になった。', NOW(), NOW()),('contact', '連絡する／接触', 'verb', '"共に"の「con-」と"触れる"の「tangere」が結合して"接触する"という意味になった。', NOW(), NOW()),('regard', 'みなす／配慮', 'verb', '"再び"の「re-」と"見る"の「guarder（古フランス語）」が結合して"みなす"という意味になった。', NOW(), NOW()),('respect', '尊敬する／尊敬', 'verb', '"後ろに"の「re-」と"見る"の「specere」が結合して"尊重する"という意味になった。', NOW(), NOW()),('search', '探す、検索する／探索', 'verb', 'ラテン語「circare（探し回る）」が語源で、「search」は"探す"という意味になった。', NOW(), NOW()),('connect', 'つなぐ、関係づける', 'verb', '"共に"の「con-」と"結ぶ"の「nectere」が結合して"接続する"という意味になった。', NOW(), NOW()),('decline', '減少する、断る／減少', 'verb', '"下に"の「de-」と"傾く"の「clinare」が結合して"減少する・断る"という意味になった。', NOW(), NOW()),('prevent', '防ぐ、阻止する', 'verb', '"前に"の「prae-」と"来る"の「venire」が結合して"防ぐ"という意味になった。', NOW(), NOW()),('suffer', '苦しむ', 'verb', '"下に"の「sub-」と"運ぶ"の「ferre」が結合して"苦しむ"という意味になった。', NOW(), NOW()),('survive', '生き残る', 'verb', '"上から"の「super-」と"生きる"の「vivere」が結合して"生き残る"という意味になった。', NOW(), NOW()),('publish', '出版する、公表する', 'verb', '"公に"の「publicare」が語源で、「publish」は"出版する"という意味になった。', NOW(), NOW()),('trade', '貿易、交換／取引する', 'verb', '中世英語「trade（道・取引）」が語源で、「trade」は"貿易・取引"という意味になった。', NOW(), NOW()),('figure', '数字、人物／計算する', 'verb', 'ラテン語「figura（形）」が語源で、「figure」は"数字・姿・図"という意味になった。', NOW(), NOW()),('stress', 'ストレス、強調／強調する', 'verb', 'ラテン語「strictus（締め付けられた）」が変化して"圧力・緊張"という意味になった。', NOW(), NOW()),('link', '関連、リンク／つなぐ', 'verb', '古英語「hlencan（鎖）」が語源で、「link」は"つなぐ・関連"という意味になった。', NOW(), NOW()),('identify', '特定する、識別する', 'verb', '"同一の"の「idem」と"作る"の「facere」が結合して"識別する"という意味になった。', NOW(), NOW()),('represent', '代表する、表す', 'verb', '"再び"の「re-」と"表す"の「presentare」が結合して"表現する・代表する"という意味になった。', NOW(), NOW()),('indicate', '示す、指し示す', 'verb', '"中へ"の「in-」と"示す"の「dicare」が結合して"示す"という意味になった。', NOW(), NOW()),('manage', '管理する、経営する', 'verb', '「手」の意味のラテン語「manus」と「扱う」のイタリア語「maneggiare」が結合して「管理する」という意味になった。', NOW(), NOW()),('attend', '出席する、通う', 'verb', '「〜へ」の「ad-」と「伸ばす」の「tendere」が結合して「出席する」という意味になった。', NOW(), NOW()),('maintain', '維持する', 'verb', '「手」の「manu」と「保つ」の「tenere」が結合して「維持する」という意味になった。', NOW(), NOW()),('survey', '調査／調査する', 'verb', '「上から」の「super-」と「見る」の「videre」が結合して「調査する」という意味になった。', NOW(), NOW()),('replace', '交換する、取って代わる', 'verb', '「再び」の「re-」と「置く」の「place」が結合して「取り替える」という意味になった。', NOW(), NOW()),('conduct', '実施する／指揮', 'verb', '「共に」の「con-」と「導く」の「ducere」が結合して「導く」という意味になった。', NOW(), NOW()),('attempt', '試みる／試み', 'verb', '「〜へ」の「ad-」と「試す」の「temptare」が結合して「試みる」という意味になった。', NOW(), NOW()),('promote', '促進する、昇進させる', 'verb', '「前へ」の「pro-」と「動かす」の「movere」が結合して「促進する」という意味になった。', NOW(), NOW()),('earn', '稼ぐ、得る', 'verb', '古英語「earnian（稼ぐ）」が語源で、「earn」は「稼ぐ」という意味になった。', NOW(), NOW()),('unite', '団結する、統一する', 'verb', '「一つ」の意味のラテン語「unus」と「する」の「-ire」が結合して「統合する」という意味になった。', NOW(), NOW()),('feed', '餌を与える、養う', 'verb', '古英語「fēdan（養う）」が語源で、「feed」は「食べ物を与える」という意味になった。', NOW(), NOW()),('seek', '探し求める', 'verb', '古英語「sēcan（探す）」が語源で、「seek」は「探す」という意味になった。', NOW(), NOW()),('observe', '観察する、守る', 'verb', '「〜に向かって」の「ob-」と「保つ」の「servare」が結合して「観察する」という意味になった。', NOW(), NOW()),('reveal', '明らかにする、暴露する', 'verb', '「再び」の「re-」と「覆いを取る」の「velare」が結合して「明らかにする」という意味になった。', NOW(), NOW()),('reflect', '反映する、映す', 'verb', '「後ろに」の「re-」と「曲げる」の「flectere」が結合して「反射する・熟考する」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'create'), 'シンプル', 'He wants to create a new app.', '彼は新しいアプリを作りたい。', 'us_mvp_image_0001_create.webp', 'say-4c556c9d-4b214d87-875043d7-030b292b-0dc924ab.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'increase'), 'シンプル', 'The company wants to increase sales.', 'その会社は売上を増やしたい。', 'us_mvp_image_0002_increase.webp', 'say-76e9476d-167a24bb-928828f1-cb088135-957489e7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'improve'), 'シンプル', 'She tries to improve her writing skills.', '彼女は文章力を向上させようとしている。', 'us_mvp_image_0003_improve.webp', 'say-fc8a6628-3af04686-b773346b-14686c7d-c6666a8f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mean'), 'シンプル', 'What does this word mean?', 'この単語はどういう意味ですか？', 'us_mvp_image_0004_mean.webp', 'say-32cfbcc7-c8b70f2c-50325919-cf7775d5-46208e1d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'include'), 'シンプル', 'The price includes tax.', 'その価格には税金が含まれている。', 'us_mvp_image_0006_include.webp', 'say-ea618bee-8c9125aa-e98c54d6-cff2f5ed-a5ba8521.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'consider'), 'シンプル', 'Please consider my proposal.', '私の提案をよく考えてください。', 'us_mvp_image_0007_consider.webp', 'say-d7fe9522-02be4b50-152bb47f-3992614f-413e757c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'allow'), 'シンプル', 'Smoking is not allowed here.', 'ここでは喫煙は許可されていません。', 'us_mvp_image_0008_allow.webp', 'say-74846f68-ac8c8dce-395512fd-f7ac229c-e9d15f6d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'suggest'), 'シンプル', 'Can you suggest a good restaurant?', '良いレストランを提案してくれますか？', 'us_mvp_image_0009_suggest.webp', 'say-8d17e0bc-bfc51c09-58cf2082-6d88b9b0-c7c645a0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'produce'), 'シンプル', 'This factory produces cars.', 'この工場は車を生産している。', 'us_mvp_image_0010_produce.webp', 'say-d3560cab-37849542-43f70914-2f7d5b9c-2e54fd0d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'decide'), 'シンプル', 'I can''t decide what to eat.', '何を食べるか決められない。', 'us_mvp_image_0011_decide.webp', 'say-e968c958-bb100b09-441b2519-0437c7ca-52a1d8d4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'offer'), 'シンプル', 'He offered me a job.', '彼は私に仕事を提供してくれた。', 'us_mvp_image_0012_offer.webp', 'say-07945e47-e9327bd0-cd2360d7-3f6baa33-b312f5d2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'require'), 'シンプル', 'This job requires experience.', 'この仕事には経験が必要だ。', 'us_mvp_image_0013_require.webp', 'say-bf28291d-b7324ade-82f6bb2a-3648693b-5a8b1366.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tend'), 'シンプル', 'She tends to be late.', '彼女は遅れがちだ。', 'us_mvp_image_0016_tend.webp', 'say-3d522d2e-6d3f5e90-fee93331-ced0055c-eb6d2f87.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'describe'), 'シンプル', 'Can you describe the scene?', 'その場面を説明してくれますか？', 'us_mvp_image_0018_describe.webp', 'say-0c88a308-cfc235e3-34cfd8bc-27830b95-bdc642e3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'involve'), 'シンプル', 'The project involves many people.', 'そのプロジェクトには多くの人が関わっている。', 'us_mvp_image_0019_involve.webp', 'say-bf5e9e4e-cd7a6b8f-c46d63a6-b0b96920-18b309c9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reduce'), 'シンプル', 'We need to reduce costs.', 'コストを削減する必要がある。', 'us_mvp_image_0020_reduce.webp', 'say-478c77ae-d0a2e7a3-6c9100cd-83a09f5d-636769a2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'design'), 'シンプル', 'She designed the new logo.', '彼女は新しいロゴをデザインした。', 'us_mvp_image_0021_design.webp', 'say-c38723f9-d7115761-bffa8740-33c8e27d-97a78238.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'force'), 'シンプル', 'Don''t force yourself to eat.', '無理に食べなくていいよ。', 'us_mvp_image_0022_force.webp', 'say-21a8f52b-d96ad614-d89b00fc-8d0b6e5c-e3c6c053.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'affect'), 'シンプル', 'The weather affects my mood.', '天気が私の気分に影響を与える。', 'us_mvp_image_0025_affect.webp', 'say-dff84311-7aede0e3-db534e54-09fb5c69-0ffd8a52.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'deal'), 'シンプル', 'He can deal with stress well.', '彼はストレスにうまく対処できる。', 'us_mvp_image_0026_deal.webp', 'say-64eabb1e-b6f341f9-103709d8-e81cad1c-c39ed056.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'avoid'), 'シンプル', 'You should avoid junk food.', 'ジャンクフードは避けるべきだ。', 'us_mvp_image_0027_avoid.webp', 'say-0f28a3f3-a21b65b3-ae7b8c6d-430e0ba0-72d6ff75.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'relate'), 'シンプル', 'This topic relates to history.', 'この話題は歴史に関係している。', 'us_mvp_image_0028_relate.webp', 'say-69decc10-d9a2c1a0-7aeb567a-3c362ca5-fad9ef78.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'realize'), 'シンプル', 'I just realized my mistake.', '私は自分のミスに気づいた。', 'us_mvp_image_0029_realize.webp', 'say-1edf90c9-cc2d77e8-c7daf516-b8c2f235-466d2703.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'encourage'), 'シンプル', 'My teacher encouraged me to study more.', '先生は私にもっと勉強するよう励ました。', 'us_mvp_image_0030_encourage.webp', 'say-33c20a71-861293ad-c7180e8a-11c27584-0329c124.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compare'), 'シンプル', 'Let''s compare these two options.', 'この2つの選択肢を比較しよう。', 'us_mvp_image_0031_compare.webp', 'say-455a07aa-72d11c91-9f55731f-1be73631-85970cfe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'measure'), 'シンプル', 'Can you measure the table?', 'そのテーブルのサイズを測ってくれますか？', 'us_mvp_image_0032_measure.webp', 'say-70cc25cc-2f634539-a1c2a003-7fa60237-2e29f690.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exist'), 'シンプル', 'Ghosts don''t exist.', '幽霊は存在しない。', 'us_mvp_image_0033_exist.webp', 'say-28d15818-b22b419e-289a45fb-bddce75e-7356099d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mark'), 'シンプル', 'Please mark the correct answer.', '正しい答えに印をつけてください。', 'us_mvp_image_0034_mark.webp', 'say-94504521-f4a3ae87-56e82131-1ae073e2-8558358b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'depend'), 'シンプル', 'It depends on the situation.', 'それは状況による。', 'us_mvp_image_0036_depend.webp', 'say-4c31071e-ab655f28-0f57cddb-ecfa2e22-6dbce885.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'object'), 'シンプル', 'He objected to the plan.', '彼はその計画に反対した。', 'us_mvp_image_0037_object.webp', 'say-571b2112-4b2f3a11-076feedc-167a0ef9-15c36537.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'demand'), 'シンプル', 'The job demands a lot of effort.', 'その仕事は多大な努力を要求する。', 'us_mvp_image_0038_demand.webp', 'say-c95068cf-e707caac-65f8668f-67193881-b7855f22.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'found'), 'シンプル', 'He founded a new company.', '彼は新しい会社を設立した。', 'us_mvp_image_0039_found.webp', 'say-c7a378dc-22e4fe68-5150fad8-d96566de-2092462a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'complete'), 'シンプル', 'I need to complete this task.', 'この作業を完了しなければならない。', 'us_mvp_image_0040_complete.webp', 'say-b3a34acb-4fa60dd7-9addbdef-7bb4c379-eb092a91.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'interest'), 'シンプル', 'He has a strong interest in science.', '彼は科学に強い関心を持っている。', 'us_mvp_image_0044_interest.webp', 'say-3e9adedd-12fff086-acf81f94-efd88c90-6c0f63eb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'research'), 'シンプル', 'She is conducting research on cancer.', '彼女はガンの研究を行っている。', 'us_mvp_image_0045_research.webp', 'say-5bdbfdb6-b81536da-61def7be-4e10db97-7a4e3d79.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cause'), 'シンプル', 'Smoking is a cause of lung cancer.', '喫煙は肺がんの原因の一つだ。', 'us_mvp_image_0046_cause.webp', 'say-e07ae435-c33c6855-5e3caa03-9bbb1a21-bbd6ed75.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'influence'), 'シンプル', 'His ideas had a great influence on me.', '彼の考えは私に大きな影響を与えた。', 'us_mvp_image_0049_influence.webp', 'say-5f71cdc9-064fb6cd-d5f814d6-4869af4a-c07eed84.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'value'), 'シンプル', 'Education has great value.', '教育には大きな価値がある。', 'us_mvp_image_0055_value.webp', 'say-e41232de-fc6372bb-1dae58fc-7da144b6-7c2cb9b3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'practice'), 'シンプル', 'You need more practice to improve.', '上達するにはもっと練習が必要だ。', 'us_mvp_image_0060_practice.webp', 'say-a5037647-3761d6e4-e81dd3a1-8218af3b-3ba39834.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'notice'), 'シンプル', 'Did you notice the new sign?', '新しい看板に気づきましたか？', 'us_mvp_image_0101_notice.webp', 'say-a1c90e12-1df1d96f-ad6c02b8-08721559-a5f57ff9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'refer'), 'シンプル', 'Please refer to page 10.', '10ページを参照してください。', 'us_mvp_image_0102_refer.webp', 'say-36fc2b09-5184bed1-b2f02ec4-d114e7c2-4d6fa432.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'approach'), 'シンプル', 'We need a new approach to this problem.', 'この問題には新しいアプローチが必要だ。', 'us_mvp_image_0103_approach.webp', 'say-3da47577-f8912167-10f9e4a9-76b7b6a8-3713b2b4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'imagine'), 'シンプル', 'Can you imagine living on Mars?', '火星での生活を想像できますか？', 'us_mvp_image_0105_imagine.webp', 'say-bdfe3a2c-e1f2ab52-424d8acc-00f19fc0-1f8161ca.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'recognize'), 'シンプル', 'I recognized her voice.', '彼女の声を認識した。', 'us_mvp_image_0106_recognize.webp', 'say-6c5fe15d-79303e20-c0e9999f-8847cea4-dd1acf0b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'solve'), 'シンプル', 'We need to solve this issue.', 'この問題を解決する必要がある。', 'us_mvp_image_0107_solve.webp', 'say-53882d4a-f23edc32-cc919595-685501ab-9b4ffee4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'occur'), 'シンプル', 'Accidents occur frequently here.', 'ここでは事故が頻繁に発生する。', 'us_mvp_image_0108_occur.webp', 'say-903549cf-1d0c7d52-8cd5b944-3f9b4aa7-3e9d237d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'argue'), 'シンプル', 'They often argue about politics.', '彼らはよく政治について議論する。', 'us_mvp_image_0109_argue.webp', 'say-9deb7159-cc805166-d720917f-0a932e06-af589644.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'claim'), 'シンプル', 'He claims that he saw a UFO.', '彼はUFOを見たと主張している。', 'us_mvp_image_0110_claim.webp', 'say-59e735a4-7c87e766-beed9923-c5d05567-14bda118.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'express'), 'シンプル', 'She expressed her feelings clearly.', '彼女は自分の気持ちをはっきり表現した。', 'us_mvp_image_0111_express.webp', 'say-610a6aa3-aba1a7d9-11d12a02-00af4e20-cc3c7c27.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'draw'), 'シンプル', 'He drew a beautiful picture.', '彼は美しい絵を描いた。', 'us_mvp_image_0112_draw.webp', 'say-4c5def53-0396cc88-691e9a85-d479d8af-6d7b3364.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'waste'), 'シンプル', 'Don''t waste your time.', '時間を無駄にしないで。', 'us_mvp_image_0113_waste.webp', 'say-d7ba83a1-1b054d5f-d0cf4013-0d041337-282b8827.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'advance'), 'シンプル', 'Technology has advanced rapidly.', '技術は急速に進歩した。', 'us_mvp_image_0114_advance.webp', 'say-f2127f61-4cb33017-656906c6-172d7640-90888202.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spread'), 'シンプル', 'The news spread quickly.', 'そのニュースはすぐに広まった。', 'us_mvp_image_0115_spread.webp', 'say-92a0cba6-d58d1c4f-2f2955b0-2cc7a2f6-495439aa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prepare'), 'シンプル', 'We need to prepare for the exam.', '試験の準備をする必要がある。', 'us_mvp_image_0116_prepare.webp', 'say-c3f4146f-1856c84c-7ed468ec-4adcb5d3-d5b45478.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'gain'), 'シンプル', 'She gained a lot of experience.', '彼女は多くの経験を得た。', 'us_mvp_image_0117_gain.webp', 'say-0532abef-460b8f45-b8d0f23d-399861f0-f0b2d5af.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'achieve'), 'シンプル', 'He achieved his goal.', '彼は目標を達成した。', 'us_mvp_image_0118_achieve.webp', 'say-633044ae-113ccab8-cc91e2a6-a43ccc4a-ce3db7e6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'establish'), 'シンプル', 'The company was established in 1990.', 'その会社は1990年に設立された。', 'us_mvp_image_0119_establish.webp', 'say-dad6cfdb-0568fa85-7c5e149a-fab88401-9284483e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'supply'), 'シンプル', 'This company supplies electricity.', 'この会社は電気を供給している。', 'us_mvp_image_0120_supply.webp', 'say-bda58805-2364857b-03c23cd7-50e8470e-58f6dd31.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'suppose'), 'シンプル', 'I suppose you are right.', 'あなたが正しいと思う。', 'us_mvp_image_0121_suppose.webp', 'say-59f5c664-ced58514-fd5f1184-e39998ec-e9dc83be.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'perform'), 'シンプル', 'The band performed well.', 'そのバンドは良い演奏をした。', 'us_mvp_image_0122_perform.webp', 'say-aba3d3a2-5947cc0e-da5ef988-8c1b8463-ca9664f5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prefer'), 'シンプル', 'I prefer tea to coffee.', '私はコーヒーよりも紅茶が好きだ。', 'us_mvp_image_0123_prefer.webp', 'say-a9d0f538-01bf8f43-ed219afc-b3eb3599-3a68d3c0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'determine'), 'シンプル', 'We need to determine the cause.', '原因を特定する必要がある。', 'us_mvp_image_0124_determine.webp', 'say-43238a4e-585687ec-b1d69cd8-2ba99c71-04aa3f39.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'treat'), 'シンプル', 'Doctors treat patients with care.', '医師は患者を丁寧に治療する。', 'us_mvp_image_0125_treat.webp', 'say-eb6c1def-d9da0be0-04e26c97-b528cc92-9b76b51f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prove'), 'シンプル', 'He proved his innocence.', '彼は自分の無実を証明した。', 'us_mvp_image_0126_prove.webp', 'say-36a3ad33-7cf8b6e3-2b6855e0-55b6f3ab-152228d5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'apply'), 'シンプル', 'You should apply for the job.', 'その仕事に応募すべきだ。', 'us_mvp_image_0127_apply.webp', 'say-2d0d9dc0-31a4e47d-2a792039-b3393767-d52f171b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mention'), 'シンプル', 'He never mentioned his past.', '彼は過去について決して言及しなかった。', 'us_mvp_image_0128_mention.webp', 'say-decf7d42-d67a0373-0f490675-5633a09d-d7a0d64c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'communicate'), 'シンプル', 'We need to communicate more.', 'もっと意思疎通を図る必要がある。', 'us_mvp_image_0129_communicate.webp', 'say-04dec5c5-7bafec5d-03e8ad0a-12ad984d-88071e64.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'contain'), 'シンプル', 'This box contains old books.', 'この箱には古い本が入っている。', 'us_mvp_image_0130_contain.webp', 'say-c8a5a1f6-f72f0988-92edc131-444330ef-708440b8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'contact'), 'シンプル', 'Please contact me if you need help.', '助けが必要なら連絡してください。', 'us_mvp_image_0131_contact.webp', 'say-99d9309b-1c2df020-29cfc94d-f7eba908-d8c0843b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'regard'), 'シンプル', 'He is highly regarded as a teacher.', '彼は優れた教師として評価されている。', 'us_mvp_image_0132_regard.webp', 'say-f6b52162-56bbc752-837bd24c-8685691a-374e6fa7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'respect'), 'シンプル', 'We should respect each other.', '私たちはお互いを尊重すべきだ。', 'us_mvp_image_0133_respect.webp', 'say-edcab790-c4d72c38-0e1aace7-85ff7f18-132cab29.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'search'), 'シンプル', 'I searched the internet for information.', '私はインターネットで情報を検索した。', 'us_mvp_image_0134_search.webp', 'say-fc45b72a-ed43ead7-26198bea-7f16e665-efeed3ea.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'connect'), 'シンプル', 'The bridge connects two cities.', 'その橋は二つの都市をつないでいる。', 'us_mvp_image_0135_connect.webp', 'say-2e724075-8bcf3f94-2ee9615d-aa21f259-f67f753d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'decline'), 'シンプル', 'The birth rate is declining.', '出生率が減少している。', 'us_mvp_image_0136_decline.webp', 'say-3e162442-785760ce-f10529fc-590013cc-fa601ab3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prevent'), 'シンプル', 'Wearing a mask prevents infection.', 'マスクの着用は感染を防ぐ。', 'us_mvp_image_0137_prevent.webp', 'say-ecdc7779-304f8d4f-a437c766-e6d8cc1d-bd25439b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'suffer'), 'シンプル', 'He suffers from a rare disease.', '彼は珍しい病気に苦しんでいる。', 'us_mvp_image_0138_suffer.webp', 'say-028a5d79-1a4cc2af-bb18efba-95f298d4-0af52146.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'survive'), 'シンプル', 'They survived the accident.', '彼らはその事故を生き延びた。', 'us_mvp_image_0139_survive.webp', 'say-5ed8db48-1015086c-ddc476c0-f4995b73-d710140d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'publish'), 'シンプル', 'She published her first novel.', '彼女は最初の小説を出版した。', 'us_mvp_image_0140_publish.webp', 'say-eec9c54b-54215075-a6c70dbc-3ca20a37-7040f355.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trade'), 'シンプル', 'Japan has strong trade relations.', '日本は強い貿易関係を持っている。', 'us_mvp_image_0148_trade.webp', 'say-1d4fa84c-79dd57a0-c71a93ae-81a6552e-ec0f95e3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'figure'), 'シンプル', 'He is a famous historical figure.', '彼は有名な歴史上の人物だ。', 'us_mvp_image_0150_figure.webp', 'say-3a91c064-7b6d9531-8cbf082b-0fb60062-40e4d2e8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'stress'), 'シンプル', 'Meditation helps reduce stress.', '瞑想はストレスを軽減するのに役立つ。', 'us_mvp_image_0154_stress.webp', 'say-190256f0-ac7a9edd-23135e86-0b6a4c8e-dff4f5a8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'link'), 'シンプル', 'There is a strong link between diet and health.', '食事と健康には強い関連がある。', 'us_mvp_image_0177_link.webp', 'say-10b205a8-22dd90c6-dbc7fb13-049e3308-03a83b7d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'identify'), 'シンプル', 'He can identify different bird species.', '彼はさまざまな鳥の種を識別できる。', 'us_mvp_image_0201_identify.webp', 'say-f7deba99-a28e1613-e7ed6084-26e160f3-892b3885.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'represent'), 'シンプル', 'This flag represents our country.', 'この旗は私たちの国を表している。', 'us_mvp_image_0202_represent.webp', 'say-6593174a-35d2ceb4-a8feef82-1b7f2256-9e3e2c1e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'indicate'), 'シンプル', 'The map indicates the location.', 'その地図は場所を示している。', 'us_mvp_image_0203_indicate.webp', 'say-afed66cb-75a61f11-9583fc34-c2489ab4-72aec83c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'manage'), 'シンプル', 'She manages a small company.', '彼女は小さな会社を経営している。', 'us_mvp_image_0204_manage.webp', 'say-1169d9c7-a1ab06a5-83644646-c11ae79a-0fe9b7e3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'attend'), 'シンプル', 'He attends a university in Tokyo.', '彼は東京の大学に通っている。', 'us_mvp_image_0205_attend.webp', 'say-c4e44fc8-aa55797e-4fd4cd87-e5d56d7c-d78fc5a7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'maintain'), 'シンプル', 'It’s important to maintain good health.', '健康を維持することは大切だ。', 'us_mvp_image_0206_maintain.webp', 'say-8f2e4eb1-bb9a8aa0-c40643af-f6003bd3-831f22e7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'survey'), 'シンプル', 'They conducted a survey on climate change.', '彼らは気候変動について調査を行った。', 'us_mvp_image_0207_survey.webp', 'say-6dd2467e-65de5aea-cabe2006-78c86f34-f4c5f48c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'replace'), 'シンプル', 'We need to replace the old batteries.', '古い電池を交換する必要がある。', 'us_mvp_image_0208_replace.webp', 'say-35b641e6-3c4527c8-dfcde853-73520ed8-d6004d92.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'conduct'), 'シンプル', 'The scientist conducted an experiment.', 'その科学者は実験を実施した。', 'us_mvp_image_0210_conduct.webp', 'say-686c2ab0-35201384-aa2904ad-22ad80d5-5d411dec.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'attempt'), 'シンプル', 'He attempted to climb the mountain.', '彼はその山に登ろうと試みた。', 'us_mvp_image_0212_attempt.webp', 'say-6b2e0a56-ffb9fd30-e72ab26f-825a0fd1-3ce908e0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'promote'), 'シンプル', 'The company promotes healthy eating.', 'その会社は健康的な食事を推進している。', 'us_mvp_image_0213_promote.webp', 'say-0bb70a83-a85a44e0-7274ad6e-fdd2f99a-208e122f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'earn'), 'シンプル', 'She earns a high salary.', '彼女は高い給料を稼いでいる。', 'us_mvp_image_0214_earn.webp', 'say-8d74b0d1-c91cf510-df79a010-bd49595d-9b6f3f08.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'unite'), 'シンプル', 'The leaders united to solve the issue.', '指導者たちは問題解決のために団結した。', 'us_mvp_image_0215_unite.webp', 'say-424a9c84-965b22d4-3363ce14-c37c30d3-a930f904.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'feed'), 'シンプル', 'He feeds his cat every morning.', '彼は毎朝猫に餌をやる。', 'us_mvp_image_0216_feed.webp', 'say-1a082e65-6231bf40-6d8b24d8-4840ea18-bd2133ec.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'seek'), 'シンプル', 'She is seeking a new job.', '彼女は新しい仕事を探している。', 'us_mvp_image_0217_seek.webp', 'say-10e904c8-705b7af4-5e47df17-30240dc1-76018aa4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'observe'), 'シンプル', 'Scientists observe animal behavior.', '科学者は動物の行動を観察する。', 'us_mvp_image_0218_observe.webp', 'say-87ea4edd-dabb6798-17b247b2-7d81ba6c-0ca8f504.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reveal'), 'シンプル', 'The report revealed new facts.', 'その報告書は新事実を明らかにした。', 'us_mvp_image_0219_reveal.webp', 'say-bc13dc4b-dfd1dd93-d8c483ea-28381cab-b28caacc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reflect'), 'シンプル', 'The water reflects the sky.', '水面が空を映している。', 'us_mvp_image_0221_reflect.webp', 'say-dbd141a7-5e39be5d-99e7a710-50818301-cb26bd71.mp3', NOW(), NOW());
