INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('attract', '引きつける、魅了する', 'verb', '「〜の方へ」の「ad-」と「引く」の「trahere」が結合して「引きつける」という意味になった。', NOW(), NOW()),('decrease', '減少する／減少', 'verb', '「下に」の「de-」と「育つ」の「crescere」が結合して「減少する」という意味になった。', NOW(), NOW()),('ignore', '無視する', 'verb', '「知らない」のラテン語「ignorare」が語源で、「ignore」は「無視する」という意味になった。', NOW(), NOW()),('define', '定義する', 'verb', '「完全に」の「de-」と「境界を定める」の「finire」が結合して「定義する」という意味になった。', NOW(), NOW()),('adapt', '適応する、順応する', 'verb', '「〜に」の「ad-」と「合う」の「aptare」が結合して「適応する」という意味になった。', NOW(), NOW()),('contribute', '貢献する', 'verb', '「共に」の「con-」と「運ぶ」の「tribuere」が結合して「貢献する」という意味になった。', NOW(), NOW()),('exchange', '交換する／交換', 'verb', '「外へ」の「ex-」と「変える」の「cambiare」が結合して「交換する」という意味になった。', NOW(), NOW()),('display', '展示する／展示', 'verb', '「離れて」の「dis-」と「折る、広げる」の「plicare」が結合して「展示する」という意味になった。', NOW(), NOW()),('respond', '返答する、対応する', 'verb', '「再び」の「re-」と「約束する」の「spondere」が結合して「応答する」という意味になった。', NOW(), NOW()),('hide', '隠す、隠れる', 'verb', '古英語「hydan（隠す）」が語源で、「hide」は「隠す」という意味になった。', NOW(), NOW()),('remove', '取り除く', 'verb', '「離れて」の「re-」と「動かす」の「movere」が結合して「取り除く」という意味になった。', NOW(), NOW()),('assume', '仮定する、引き受ける', 'verb', '「〜へ」の「ad-」と「取る」の「sumere」が結合して「仮定する・引き受ける」という意味になった。', NOW(), NOW()),('relax', 'くつろぐ、緩める', 'verb', '「後ろに」の「re-」と「緩める」の「laxare」が結合して「くつろぐ」という意味になった。', NOW(), NOW()),('satisfy', '満足させる', 'verb', '「十分に」の「satis」と「作る」の「facere」が結合して「満足させる」という意味になった。', NOW(), NOW()),('desire', '欲する／欲望', 'verb', '「〜から」の「de-」と「星」の「sidus」が結合して「強く望む」という意味になった。', NOW(), NOW()),('succeed', '成功する', 'verb', '「後ろに」の「sub-」と「行く」の「cedere」が結合して「成功する」という意味になった。', NOW(), NOW()),('charge', '料金、責任／請求する', 'verb', '「車に積む」の意味のラテン語「carricare」が語源で、「charge」は「課す・料金」という意味になった。', NOW(), NOW()),('contrast', '対比／対照をなす', 'verb', '「反対に」の「contra-」と「立つ」の「stare」が結合して「対比する」という意味になった。', NOW(), NOW()),('reward', '報酬／報いる', 'verb', '「再び」の「re-」と「見る・気を配る」の「warder」が結合して「報酬」という意味になった。', NOW(), NOW()),('conflict', '衝突、対立／対立する', 'verb', '「共に」の「com-」と「打つ」の「fligere」が結合して「対立・衝突」という意味になった。', NOW(), NOW()),('struggle', '苦闘、努力／奮闘する', 'verb', '中期英語「struglen（もがく）」が語源で、「struggle」は「闘争・苦労する」という意味になった。', NOW(), NOW()),('balance', 'バランス、均衡／釣り合う', 'verb', '「二つ」の「bi-」と「皿」の「lanx」が結合して「天秤」を意味するラテン語「bilanx」から派生し、「均衡」という意味になった。', NOW(), NOW()),('track', '跡、軌道／追跡する', 'verb', 'オランダ語「trekken（引く）」が語源で、「道筋・追跡する」という意味になった。', NOW(), NOW()),('progress', '進歩／進む', 'verb', '「前へ」の「pro-」と「歩く」の「gradi」が結合して「進歩する」という意味になった。', NOW(), NOW()),('predict', '予測する', 'verb', '「前に」の「pre-」と「言う」の「dicere」が結合して「予測する」という意味になった。', NOW(), NOW()),('examine', '調査する、診察する', 'verb', '「外に」の「ex-」と「試す」の「aminare」が結合して「調査する」という意味になった。', NOW(), NOW()),('trust', '信頼する／信頼', 'verb', 'ラテン語「credere（信じる）」に由来し、古英語「treowian（信じる）」を通じて「信頼する」という意味になった。', NOW(), NOW()),('emerge', '現れる、浮かび上がる', 'verb', '「外に」の「e-」と「出る」の「mergere」が結合して「現れる」という意味になった。', NOW(), NOW()),('vary', '異なる、変化する', 'verb', 'ラテン語「varius（多様な）」が語源で、「変わる」という意味になった。', NOW(), NOW()),('release', '解放する、発表する／解放', 'verb', '「後ろに」の「re-」と「緩める」の「laxare」が結合して「解放する」という意味になった。', NOW(), NOW()),('divide', '分ける、分割する', 'verb', '「離して」の「dis-」と「分ける」の「videre」が結合して「分ける」という意味になった。', NOW(), NOW()),('enable', '可能にする', 'verb', '「〜にする」の「en-」と「能力」の「able」が結合して「可能にする」という意味になった。', NOW(), NOW()),('judge', '判断する、裁判官', 'verb', 'ラテン語「judicium（判断）」が語源で、「判断する・裁く」という意味になった。', NOW(), NOW()),('rely', '頼る、依存する', 'verb', '「後ろに」の「re-」と「縛る」の「ligare」が結合して「頼る」という意味になった。', NOW(), NOW()),('engage', '従事する、関与する', 'verb', '「中に」の「en-」と「誓約」の「gage」が結合して「従事する・関与する」という意味になった。', NOW(), NOW()),('shift', '変える、移る／変化', 'verb', '古英語「sciftan（分ける、変える）」が語源で、「移動する・変える」という意味になった。', NOW(), NOW()),('adopt', '採用する、養子にする', 'verb', '「〜へ」の「ad-」と「選ぶ・望む」の「optare」が結合して「採用する・養子にする」という意味になった。', NOW(), NOW()),('acquire', '習得する、獲得する', 'verb', '「〜へ」の「ad-」と「求める」の「quaerere」が結合して「獲得する」という意味になった。', NOW(), NOW()),('expand', '拡大する、広げる', 'verb', '「外に」の「ex-」と「広げる」の「pandere」が結合して「拡大する」という意味になった。', NOW(), NOW()),('refuse', '拒否する', 'verb', '「離れて」の「re-」と「否定する」の「fuser」が結合して「拒否する」という意味になった。', NOW(), NOW()),('strike', '打つ、ストライキをする／打撃', 'verb', '古英語「strican（打つ、こする）」が語源で、「打つ・ストライキをする」という意味になった。', NOW(), NOW()),('repeat', '繰り返す', 'verb', '「再び」の「re-」と「求める」の「petere」が結合して「繰り返す」という意味になった。', NOW(), NOW()),('consume', '消費する', 'verb', '「完全に」の「com-」と「取る」の「sumere」が結合して「消費する」という意味になった。', NOW(), NOW()),('confuse', '混乱させる', 'verb', '「共に」の「com-」と「注ぐ」の「fundere」が結合して「混乱させる」という意味になった。', NOW(), NOW()),('select', '選ぶ', 'verb', '「分けて」の「se-」と「集める」の「legere」が結合して「選ぶ」という意味になった。', NOW(), NOW()),('evolve', '進化する', 'verb', '「外に」の「e-」と「回る」の「volvere」が結合して「進化する」という意味になった。', NOW(), NOW()),('convince', '納得させる、説得する', 'verb', '「完全に」の「com-」と「征服する」の「vincere」が結合して「納得させる」という意味になった。', NOW(), NOW()),('recall', '思い出す／回収', 'verb', '「再び」の「re-」と「呼ぶ」の「call」が結合して「思い出す・呼び戻す」という意味になった。', NOW(), NOW()),('destroy', '破壊する', 'verb', '「離れて」の「de-」と「積み上げる」の「struere」が結合して「破壊する」という意味になった。', NOW(), NOW()),('preserve', '保護する、保存する', 'verb', '「前もって」の「pre-」と「保つ」の「servare」が結合して「保存する」という意味になった。', NOW(), NOW()),('organize', '整理する、組織する', 'verb', '「器官・道具」の「organon」と「〜化する」の「-ize」が結合して「組織する」という意味になった。', NOW(), NOW()),('warn', '警告する', 'verb', '古英語「wearnian（注意する）」が語源で、「警告する」という意味になった。', NOW(), NOW()),('operate', '操作する、運営する', 'verb', 'ラテン語「operari（働く）」が語源で、「操作する・機能する」という意味になった。', NOW(), NOW()),('participate', '参加する', 'verb', '「部分」の「pars」と「取る」の「capere」が結合して「参加する」という意味になった。', NOW(), NOW()),('surround', '囲む', 'verb', '「下に」の「sub-」と「波・流れ」の「undare」が結合して「取り囲む」という意味になった。', NOW(), NOW()),('flow', '流れる／流れ', 'verb', '古英語「flowan（流れる）」が語源で、「流れる」という意味になった。', NOW(), NOW()),('bore', '退屈させる／退屈', 'verb', '古英語「borian（穴を開ける）」が語源で、「退屈させる・穴を開ける」という意味になった。', NOW(), NOW()),('complain', '文句を言う', 'verb', '「共に」の「com-」と「泣く・嘆く」の「plangere」が結合して「不平を言う」という意味になった。', NOW(), NOW()),('combine', '組み合わせる', 'verb', '「共に」の「com-」と「縛る」の「binare」が結合して「結合する」という意味になった。', NOW(), NOW()),('extend', '延長する、広げる', 'verb', '「外に」の「ex-」と「伸ばす」の「tendere」が結合して「拡張する」という意味になった。', NOW(), NOW()),('appreciate', '感謝する、評価する', 'verb', '「〜へ」の「ad-」と「価値ある」の「pretium」が結合して「感謝する・評価する」という意味になった。', NOW(), NOW()),('profit', '利益／利益を得る', 'verb', '「前へ」の「pro-」と「行う」の「facere」が結合して「利益」という意味になった。', NOW(), NOW()),('vote', '投票／投票する', 'verb', 'ラテン