((SELECT id FROM words WHERE word_text = 'attract'), 'シンプル', 'The park attracts many tourists.', 'その公園は多くの観光客を引きつける。', 'us_mvp_image_0222_attract.webp', 'say-be2ef48c-8e8b4565-503e8e7f-9e2f6332-e9169aca.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'decrease'), 'シンプル', 'The population is decreasing.', '人口が減少している。', 'us_mvp_image_0223_decrease.webp', 'say-03d1887c-e8a0e8bd-2d74c751-6ac79455-393b53e9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ignore'), 'シンプル', 'He ignored my message.', '彼は私のメッセージを無視した。', 'us_mvp_image_0224_ignore.webp', 'say-53dd467a-a2519738-044fab72-efea2b75-f4d7ffaa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'define'), 'シンプル', 'Can you define this word?', 'この単語を定義できますか？', 'us_mvp_image_0226_define.webp', 'say-c1a6343d-7cb2972f-b762d18f-bbdd9135-b08fe95a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'adapt'), 'シンプル', 'Animals adapt to their environment.', '動物は環境に適応する。', 'us_mvp_image_0227_adapt.webp', 'say-32c19da3-fe09d694-a8577df8-a132f9a3-ba2d3939.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'contribute'), 'シンプル', 'He contributed to the project.', '彼はそのプロジェクトに貢献した。', 'us_mvp_image_0228_contribute.webp', 'say-af515aab-641b7572-dc9a6c75-bd44fc6e-d3f93bff.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exchange'), 'シンプル', 'We exchanged gifts at the party.', '私たちはパーティーでプレゼントを交換した。', 'us_mvp_image_0229_exchange.webp', 'say-37bf532c-659b52c4-3e88d55c-d7a09da5-2d25d837.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'display'), 'シンプル', 'The store displays new products.', 'その店は新商品を展示している。', 'us_mvp_image_0230_display.webp', 'say-1ca8e937-d650d9af-309c6ace-7a0eb7f8-952577ee.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'respond'), 'シンプル', 'He responded quickly to my email.', '彼は私のメールにすぐに返事をした。', 'us_mvp_image_0231_respond.webp', 'say-ea856eaf-28bed57b-b7b2df0e-2aa0af0b-2f3dbf7d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_t