7c3063c-c398bd0c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'flow'), 'シンプル', 'The river flows into the ocean.', 'その川は海へと流れる。', 'us_mvp_image_0334_flow.webp', 'say-90bdf6ea-ad8977c2-c68acad6-26ee03b3-153d57df.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bore'), 'シンプル', 'The lecture bored me.', 'その講義は私を退屈させた。', 'us_mvp_image_0335_bore.webp', 'say-c782a7b9-5340c65b-d6ec6125-88741443-8c62fb11.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'complain'), 'シンプル', 'He complained about the service.', '彼はサービスについて文句を言った。', 'us_mvp_image_0336_complain.webp', 'say-d3426730-c9a9d5de-a3541266-23e24adc-31aefcd0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'combine'), 'シンプル', 'We combined our ideas.', '私たちはアイデアを組み合わせた。', 'us_mvp_image_0338_combine.webp', 'say-691d15c8-523cbcf0-c658da56-4999c6bb-dfca6f32.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'extend'), 'シンプル', 'The company extended the deadline.', 'その会社は締め切りを延長した。', 'us_mvp_image_0339_extend.webp', 'say-4c6ceecc-1677600d-256bab9a-f0588fe6-c10808e0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'appreciate'), 'シンプル', 'I appreciate your help.', 'あなたの助けに感謝します。', 'us_mvp_image_0340_appreciate.webp', 'say-efd09a44-3cd3fdbd-d84eca37-e59879f8-57e58153.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'profit'), 'シンプル', 'The company made a big profit.', 'その会社は大きな利益を得た。', 'us_mvp_image_0349_profit.webp', 'say-c9f31833-9e2c8db5-3b6456f8-0db61be1-c9b03b6f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'vote'), 'シンプル', 'Many people voted in the election.', '多くの人が選挙で投票した。', 'us_mvp_image_0357_vote.webp', 'say-00725790-b679e838-4b1472e7-75b7ecef-75f9c613.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'campaign'), 'シンプル', 'The company started a new advertising campaign.', 'その会社は新しい広告キャンペーンを始めた。', 'us_mvp_image_0359_campaign.webp', 'say-c61f5fe4-1608c9a6-18c9688b-b8d23d92-4a4af35d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'demonstrate'), 'シンプル', 'He demonstrated how the machine works.', '彼はその機械の動作を実演した。', 'us_mvp_image_0401_demonstrate.webp', 'say-df35656a-6ab02904-79e40e6d-b87c7ac3-36492426.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'behave'), 'シンプル', 'Children should behave in class.', '子どもたちは授業中に行儀よくするべきだ。', 'us_mvp_image_0402_behave.webp', 'say-ddecef4e-6d11ad5c-b7930ec7-93b65928-70855b3d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'educate'), 'シンプル', 'Schools educate children.', '学校は子どもたちを教育する。', 'us_mvp_image_0403_educate.webp', 'say-02e3112d-8e5cfd89-5925dd7b-2e70a922-4c985403.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'purchase'), 'シンプル', 'I purchased a new laptop.', '私は新しいノートパソコンを購入した。', 'us_mvp_image_0404_purchase.webp', 'say-defa9bfe-f9491c10-2d681c90-6fe187bd-692e52f5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'recommend'), 'シンプル', 'Can you recommend a good restaurant?', '良いレストランを推薦してくれますか？', 'us_mvp_image_0405_recommend.webp', 'say-4491ea24-4994db50-a422c763-b4d26b4c-e7eb7207.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'admit'), 'シンプル', 'He admitted his mistake.', '彼は自分のミスを認めた。', 'us_mvp_image_0406_admit.webp', 'say-f3d71f0d-644275f0-a12e10a2-42a57fed-d307e995.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'generate'), 'シンプル', 'This machine generates electricity.', 'この機械は電気を生み出す。', 'us_mvp_image_0407_generate.webp', 'say-7d9eeae5-0cd77aca-b74c4bc5-a45b4a53-3c50508a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'explore'), 'シンプル', 'They explored the jungle.', '彼らはジャングルを探検した。', 'us_mvp_image_0408_explore.webp', 'say-6717620d-dd0244ac-be608783-98404a90-fe3e35ce.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'amaze'), 'シンプル', 'His skills amazed everyone.', '彼の技術は皆を驚かせた。', 'us_mvp_image_0409_amaze.webp', 'say-a3ad4954-a3c65178-85227fc3-6eedc00b-ceb48906.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'settle'), 'シンプル', 'They settled in a new country.', '彼らは新しい国に定住した。', 'us_mvp_image_0411_settle.webp', 'say-0741de3d-dffbe56b-500746fb-733a828f-78741793.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'afford'), 'シンプル', 'I can''t afford to buy a car.', '私には車を買う余裕がない。', 'us_mvp_image_0412_afford.webp', 'say-c53f613f-a8f1a4d7-420c73d4-2d1ad329-d7245f95.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'conclude'), 'シンプル', 'The meeting concluded at 5 p.m.', '会議は午後5時に終了した。', 'us_mvp_image_0413_conclude.webp', 'say-636138f6-4c307f8e-d2efe857-2401cece-a8eab4e5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'advertise'), 'シンプル', 'The company advertised its new product.', 'その会社は新商品を広告した。', 'us_mvp_image_0414_advertise.webp', 'say-52e918b4-da8f51dd-c5d7ee53-b7f481fb-8903b149.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'encounter'), 'シンプル', 'We encountered a problem.', '私たちは問題に遭遇した。', 'us_mvp_image_0415_encounter.webp', 'say-ce276160-a899d788-2d219bfa-925edb42-74ee1e0e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'remind'), 'シンプル', 'Please remind me to call him.', '彼に電話するのを思い出させてください。', 'us_mvp_image_0416_remind.webp', 'say-8c0f97a6-dc40eee1-19cdcbcd-16960e4a-cbb9d3c3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'locate'), 'シンプル', 'The hotel is located near the station.', 'そのホテルは駅の近くにある。', 'us_mvp_image_0417_locate.webp', 'say-e8370e04-2b56afbd-4087c7aa-b83e54a1-61def637.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'aid'), 'シンプル', 'They provided medical aid to the victims.', '彼らは被災者に医療支援を提供した。', 'us_mvp_image_0418_aid.webp', 'say-13772015-f9e44a06-57120598-8d7de909-1da63bb5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bite'), 'シンプル', 'The dog bit my hand.', 'その犬は私の手を噛んだ。', 'us_mvp_image_0419_bite.webp', 'say-df6f1b2c-7ec64f79-bc18b8c9-747dd15f-e97fdd01.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'deliver'), 'シンプル', 'The package was delivered on time.', '荷物は時間通りに配達された。', 'us_mvp_image_0420_deliver.webp', 'say-832a432b-8f85639d-f07eec2f-a177869c-1f2f4d3d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'perceive'), 'シンプル', 'She perceived a change in his attitude.', '彼女は彼の態度の変化を感じ取った。', 'us_mvp_image_0421_perceive.webp', 'say-01ecd46c-ff02bbf0-8bcb23f8-788e4297-78d5244a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'distinguish'), 'シンプル', 'It''s hard to distinguish between them.', 'それらを区別するのは難しい。', 'us_mvp_image_0422_distinguish.webp', 'say-ccbd1ca0-a8d0fd63-ac3001cf-a580ec5e-e541726c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'imply'), 'シンプル', 'His words implied a hidden meaning.', '彼の言葉は隠された意味を暗示していた。', 'us_mvp_image_0423_imply.webp', 'say-17a31995-ef46e140-434c9756-62a3cb37-a800fe9b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'handle'), 'シンプル', 'He can handle the situation well.', '彼はその状況をうまく対処できる。', 'us_mvp_image_0424_handle.webp', 'say-06230f69-45343f47-74c99e6a-d8d3061e-f1687836.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'appeal'), 'シンプル', 'His speech appealed to the audience.', '彼のスピーチは聴衆に訴えかけた。', 'us_mvp_image_0426_appeal.webp', 'say-1f729d6b-75da5522-c9d3d761-50b2f8e6-7fa9c47d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'insist'), 'シンプル', 'She insisted on going alone.', '彼女は一人で行くと主張した。', 'us_mvp_image_0427_insist.webp', 'say-b86ef8a6-29bcfef6-da1ecae7-efec01e2-0453791f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compete'), 'シンプル', 'Many athletes compete in the Olympics.', '多くの選手がオリンピックで競争する。', 'us_mvp_image_0428_compete.webp', 'say-5b56d906-1b4114d8-4830dcea-7cd9baaa-f4314468.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rank'), 'シンプル', 'She ranks first in her class.', '彼女はクラスで1位だ。', 'us_mvp_image_0429_rank.webp', 'say-af0cdfbb-24303bfe-6b603d63-8a028116-a5d2437f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'deny'), 'シンプル', 'He denied the accusation.', '彼はその非難を否定した。', 'us_mvp_image_0430_deny.webp', 'say-0c2c93be-4892131d-11268ae0-dc3f241d-7bf67467.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reject'), 'シンプル', 'The proposal was rejected.', 'その提案は拒否された。', 'us_mvp_image_0431_reject.webp', 'say-e72a9fde-d520aa7a-046bb2a2-6d364913-20f7a096.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'intend'), 'シンプル', 'I intend to study abroad.', '私は留学するつもりだ。', 'us_mvp_image_0432_intend.webp', 'say-2f00ee1f-a3d011b6-bf4665db-536e2e7b-ea6ff59d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'expose'), 'シンプル', 'He was exposed to the sun for hours.', '彼は何時間も太陽にさらされていた。', 'us_mvp_image_0433_expose.webp', 'say-d9654f63-5ae1d35c-93314af9-1e89f0e3-70df960e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'inspire'), 'シンプル', 'His story inspired many people.', '彼の話は多くの人を感動させた。', 'us_mvp_image_0435_inspire.webp', 'say-a0ff9008-1adebc87-d4066e49-872dc3af-5b94d8b5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'propose'), 'シンプル', 'He proposed a new idea.', '彼は新しいアイデアを提案した。', 'us_mvp_image_0436_propose.webp', 'say-133f3aa6-1f246ae4-f1ecc2d4-05eef0e8-1363ffd2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spell'), 'シンプル', 'Can you spell your name?', 'あなたの名前を綴ってもらえますか？', 'us_mvp_image_0437_spell.webp', 'say-ae46507e-437e668f-1a88d146-2e029160-865d3f32.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'breathe'), 'シンプル', 'Take a deep breath and relax.', '深く息を吸ってリラックスしよう。', 'us_mvp_image_0438_breathe.webp', 'say-ce5fc07f-34518cff-4dae60da-d45f2b94-e13e3b21.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'repair'), 'シンプル', 'The car needs repairing.', 'その車は修理が必要だ。', 'us_mvp_image_0439_repair.webp', 'say-6549a3dc-b42715ba-79131bf4-a4809ee1-91c5fede.mp3', NOW(), NOW());
