INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('consist', '～から成る', 'verb', '「共に」の「con-」と「立つ」の「sistere」が結合して「成り立つ」という意味になった。', NOW(), NOW()),('harm', '害、傷害／害を与える', 'verb', '古英語「hearm（害）」が語源で、「害」という意味になった。', NOW(), NOW()),('review', '評価、見直し／見直す', 'verb', '「再び」の「re-」と「見る」の「videre」が結合して「再検討する」という意味になった。', NOW(), NOW()),('interpret', '解釈する、通訳する', 'verb', '「間に」の「inter-」と「運ぶ」の「portare」が結合して「解釈する」という意味になった。', NOW(), NOW()),('translate', '翻訳する、訳す', 'verb', '「越えて」の「trans-」と「運ぶ」の「latus」が結合して「翻訳する」という意味になった。', NOW(), NOW()),('concentrate', '集中する', 'verb', '「完全に」の「con-」と「中心」の「centrum」が結合して「集中する」という意味になった。', NOW(), NOW()),('request', '要求、依頼／要求する', 'verb', '「再び」の「re-」と「探し求める」の「quaerere」が結合して「要求する」という意味になった。', NOW(), NOW()),('criticize', '批判する、非難する', 'verb', 'ギリシャ語「kritikos（判断する）」が語源で、「批判する」という意味になった。', NOW(), NOW()),('overcome', '克服する', 'verb', '「上に」の「over-」と「来る」の「come」が結合して「克服する」という意味になった。', NOW(), NOW()),('obtain', '得る、手に入れる', 'verb', '「〜へ」の「ob-」と「保つ」の「tenere」が結合して「得る」という意味になった。', NOW(), NOW()),('inform', '知らせる、通知する', 'verb', '「中に」の「in-」と「形作る」の「formare」が結合して「知らせる」という意味になった。', NOW(), NOW()),('ensure', '確実にする、保証する', 'verb', '「〜に」の「en-」と「確実な」の「sure」が結合して「保証する」という意味になった。', NOW(), NOW()),('announce', '発表する、告知する', 'verb', '「〜へ」の「ad-」と「知らせる」の「nuntiare」が結合して「発表する」という意味になった。', NOW(), NOW()),('grant', '与える、認める／助成金', 'verb', 'ラテン語「credere（信じる）」がフランス語「graanter」を通して「与える」という意味になった。', NOW(), NOW()),('freeze', '凍る、凍らせる', 'verb', '古英語「freosan（凍る）」が語源で、「凍る・凍らせる」という意味になった。', NOW(), NOW()),('oppose', '反対する', 'verb', '「反対の」の「ob-」と「置く」の「ponere」が結合して「反対する」という意味になった。', NOW(), NOW()),('differ', '異なる', 'verb', '「離れて」の「dis-」と「運ぶ」の「ferre」が結合して「異なる」という意味になった。', NOW(), NOW()),('hate', '憎む、嫌う／憎しみ', 'verb', '古英語「hatian（憎む）」が語源で、「憎む」という意味になった。', NOW(), NOW()),('emphasize', '強調する', 'verb', '「中に」の「en-」と「現れる」の「phainein」が結合して「強調する」という意味になった。', NOW(), NOW()),('employ', '雇う、使用する', 'verb', '「中に」の「en-」と「折る」の「plicare」が結合して「雇う」という意味になった。', NOW(), NOW()),('transform', '変える、変形する', 'verb', '「越えて」の「trans-」と「形作る」の「formare」が結合して「変形する」という意味になった。', NOW(), NOW()),('construct', '建設する、組み立てる', 'verb', '「共に」の「con-」と「積み上げる」の「struere」が結合して「建設する」という意味になった。', NOW(), NOW()),('arise', '生じる、発生する', 'verb', '「上に」の「a-」と「立ち上がる」の「rise」が結合して「生じる」という意味になった。', NOW(), NOW()),('beat', '打ち負かす、たたく／鼓動', 'verb', '古英語「bēatan（打つ）」が語源で、「打つ」という意味になった。', NOW(), NOW()),('regret', '後悔する／後悔', 'verb', 'フランス語「regret（嘆き）」が語源で、「後悔する」という意味になった。', NOW(), NOW()),('alter', '変更する、改める', 'verb', 'ラテン語「alter（他の）」が語源で、「変更する」という意味になった。', NOW(), NOW()),('absorb', '吸収する', 'verb', '「離れて」の「ab-」と「吸う」の「sorbere」が結合して「吸収する」という意味になった。', NOW(), NOW()),('disappoint', 'がっかりさせる', 'verb', '「否定」の「dis-」と「任命する」の「appoint」が結合して「失望させる」という意味になった。', NOW(), NOW()),('transport', '輸送する／輸送', 'verb', '「越えて」の「trans-」と「運ぶ」の「portare」が結合して「輸送する」という意味になった。', NOW(), NOW()),('rush', '急ぐ、突進する／急ぎ', 'verb', '古フランス語「ruser（急ぐ）」が語源で、「急ぐ」という意味になった。', NOW(), NOW()),('hang', '掛ける、吊るす', 'verb', '古英語「hōn（吊るす）」が語源で、「吊るす」という意味になった。', NOW(), NOW()),('blame', '非難する／責任', 'verb', 'ラテン語「blasphemare（非難する）」が語源で、「非難する」という意味になった。', NOW(), NOW()),('ban', '禁止する／禁止', 'verb', '古ノルド語「banna（禁止する）」が語源で、「禁止する」という意味になった。', NOW(), NOW()),('fascinate', '魅了する', 'verb', 'ラテン語「fascinare（魅了する）」が語源で、「魅了する」という意味になった。', NOW(), NOW()),('recover', '回復する、取り戻す', 'verb', 'ラテン語「recuperare（回復する）」が語源で、「回復する」という意味になった。', NOW(), NOW()),('celebrate', '祝う', 'verb', 'ラテン語「celebrare（祝う）」が語源で、「祝う」という意味になった。', NOW(), NOW()),('manufacture', '製造する／製造', 'verb', '「手」の「manus」と「作る」の「facere」が結合して「製造する」という意味になった。', NOW(), NOW()),('interact', '交流する、相互作用する', 'verb', '「間で」の「inter-」と「行う」の「agere」が結合して「相互作用する」という意味になった。', NOW(), NOW()),('arrange', '手配する、並べる', 'verb', '「〜へ」の「ad-」と「整える」の「ranger」が結合して「整える・手配する」という意味になった。', NOW(), NOW()),('adjust', '調整する、適応する', 'verb', '「〜へ」の「ad-」と「結合する」の「iugere」が結合して「調整する」という意味になった。', NOW(), NOW()),('confirm', '確認する、承認する', 'verb', '「共に」の「con-」と「強くする」の「firmare」が結合して「確認する」という意味になった。', NOW(), NOW()),('commit', '犯す、取り組む', 'verb', '"共に"の「com-」と"送る、任せる"の「mittere」が結合して「委ねる、犯す」という意味になった。', NOW(), NOW()),('stimulate', '刺激する', 'verb', '"刺す"の意味のラテン語「stimulus」に由来し、「刺激する」という意味になった。', NOW(), NOW()),('enhance', '高める、向上させる', 'verb', '"高く"の意味の古フランス語「enhauncer」に由来し、「高める」という意味になった。', NOW(), NOW()),('pursue', '追求する、追跡する', 'verb', '"後ろに"の「pro-」と"追う"の「sequi」が結合して「追求する」という意味になった。', NOW(), NOW()),('react', '反応する', 'verb', '"再び"の「re-」と"行う"の「agere」が結合して「反応する」という意味になった。', NOW(), NOW()),('disagree', '意見が合わない', 'verb', '"否定のdis-"と"同意する"の「agree」が結合して「意見が合わない」という意味になった。', NOW(), NOW()),('stare', 'じっと見る／凝視', 'verb', '古英語「starian（じっと見る）」に由来し、「じっと見る」という意味になった。', NOW(), NOW()),('abandon', '放棄する、見捨てる', 'verb', '"〜に"の「ad-」と"命令"の「bandon（権力）」が結合して「任せる、放棄する」という意味になった。', NOW(), NOW()),('quit', 'やめる、辞める', 'verb', 'ラテン語「quietus（静かな、休んだ）」に由来し、「やめる、離れる」という意味になった。', NOW(), NOW()),('capture', '捕らえる／捕獲', 'verb', '"取る"の意味のラテン語「capere」に由来し、「捕らえる」という意味になった。', NOW(), NOW()),('transfer', '移動する、転勤する／移動', 'verb', '"越えて"の「trans-」と"運ぶ"の「ferre」が結合して「移す、転送する」という意味になった。', NOW(), NOW()),('bother', '悩ませる、困らせる', 'verb', '不確かな起源だが、16世紀の「煩わせる」意味の俗語から発展したとされる。', NOW(), NOW()),('persuade', '説得する', 'verb', '"完全に"の「per-」と"納得させる"の「suadere」が結合して「説得する」という意味になった。', NOW(), NOW()),('rent', '借りる／賃貸料', 'verb', 'ラテン語「rendere（裂く）」に由来し、「借りる、賃貸する」という意味に派生した。', NOW(), NOW()),('breed', '繁殖する／品種', 'verb', '古英語「bredan（育てる、繁殖する）」に由来し、「繁殖させる」という意味になった。', NOW(), NOW()),('invest', '投資する', 'verb', '"中に"の「in-」と"着せる"の「vestire」が結合して「投資する、任命する」という意味になった。', NOW(), NOW()),('reserve', '予約する、確保する／蓄え', 'verb', '"後に"の「re-」と"保つ"の「servare」が結合して「取っておく、予約する」という意味になった。', NOW(), NOW()),('trace', '追跡する／痕跡', 'verb', '"引く"の意味のラテン語「tractus」に由来し、「跡をたどる」という意味になった。', NOW(), NOW()),('illustrate', '例示する、図解する', 'verb', '"明るくする"の意味のラテン語「illustrare」に由来し、「例示する、説明する」という意味になった。', NOW(), NOW()),('advise', '助言する', 'verb', '"〜に向けて"の「ad-」と"見る"の「videre」が結合して「助言する」という意味になった。', NOW(), NOW()),('convey', '伝える、運ぶ', 'verb', '"共に"の「con-」と"運ぶ"の「via（道）」が結合して「運ぶ、伝える」という意味になった。', NOW(), NOW()),('attach', '添付する、取り付ける', 'verb', '"〜へ"の「ad-」と"固定する"の「taccare（俗ラテン語）」が結合して「取り付ける」という意味になった。', NOW(), NOW()),('stretch', '伸ばす／広がり', 'verb', '古英語「streccan」に由来し、「伸ばす」という意味になった。', NOW(), NOW()),('disturb', '妨害する、邪魔をする', 'verb', '"離れて"の「dis-」と"かき乱す"の「turbare」が結合して「邪魔する、不安にさせる」という意味になった。', NOW(), NOW()),('crash', '衝突する／衝突', 'verb', '擬音語的起源を持ち、「衝突する、激突する」という意味になった。', NOW(), NOW()),('cope', '対処する', 'verb', 'ラテン語「colpus（打撃）」が中期英語「copen（戦う）」に変化し、「対処する」という意味になった。', NOW(), NOW()),('permit', '許可する／許可証', 'verb', '"通して"の「per-」と"送る、許す"の「mittere」が結合して「許可する」という意味になった。', NOW(), NOW()),('impress', '感銘を与える', 'verb', '"中に"の「in-」と"押す"の「premere」が結合して「印象を与える」という意味になった。', NOW(), NOW()),('suspect', '疑う／容疑者', 'verb', '"下に"の「sub-」と"見る"の「specere」が結合して「疑う」という意味になった。', NOW(), NOW()),('frighten', '怖がらせる', 'verb', '古英語「fyrhtu（恐怖）」に由来し、「怖がらせる」という意味になった。', NOW(), NOW()),('import', '輸入する／輸入品', 'verb', '"中に"の「in-」と"運ぶ"の「portare」が結合して「輸入する」という意味になった。', NOW(), NOW()),('export', '輸出する／輸出品', 'verb', '"外に"の「ex-」と"運ぶ"の「portare」が結合して「輸出する」という意味になった。', NOW(), NOW()),('investigate', '調査する', 'verb', '"中に"の「in-」と"追う"の「vestigare」が結合して「調査する」という意味になった。', NOW(), NOW()),('calculate', '計算する', 'verb', 'ラテン語「calculus（小石）」から派生し、「計算する」という意味になった（昔は小石で数えた）。', NOW(), NOW()),('eliminate', '排除する、なくす', 'verb', '"外へ"の「e-」と"境界、門"の「limen」が結合して「取り除く」という意味になった。', NOW(), NOW()),('launch', '発射する、開始する／開始', 'verb', '古フランス語「lancier（槍を投げる）」に由来し、「開始する、発射する」という意味になった。', NOW(), NOW()),('burden', '負担、重荷／負担をかける', 'verb', '古英語「byrthen（運ぶもの）」に由来し、「重荷、負担」という意味になった。', NOW(), NOW()),('award', '賞／授与する', 'verb', '"〜へ"の「ad-」と"注意を払う"の古フランス語「warder」が結合して「（注意を向けて）与える」→「授与する、賞」という意味になった。', NOW(), NOW()),('bond', '絆、結びつき／結びつける', 'verb', 'ラテン語「bindan（縛る）」に由来し、「結びつき、絆」という意味になった。', NOW(), NOW()),('trick', 'いたずら、手品／だます', 'verb', 'ラテン語「tricari（ごまかす）」に由来し、「策略、いたずら」という意味になった。', NOW(), NOW()),('possess', '所有する、持つ', 'verb', '"完全に"の「potis（支配する）」と"所有する"の「sedere（座る）」が結合して「所有する」という意味になった。', NOW(), NOW()),('dominate', '支配する、圧倒する', 'verb', 'ラテン語「dominari（支配する）」に由来し、「支配する」という意味になった。', NOW(), NOW()),('guarantee', '保証する／保証', 'verb', 'フランス語「garantir（保証する）」に由来し、スペイン語・ドイツ語系の「warant」から派生して「保証する」という意味になった。', NOW(), NOW()),('embarrass', '恥ずかしい思いをさせる', 'verb', '"中に"の「em-」と"妨げる"のスペイン語「barras（障害物）」が結合して「困惑させる」という意味になった。', NOW(), NOW()),('discourage', '萎えさせる、落胆させる', 'verb', '"否定のdis-"と"勇気"の「courage」が結合して「落胆させる」という意味になった。', NOW(), NOW()),('detect', '検出する、見つける', 'verb', '"離れて"の「de-」と"覆う"の「tegere」が結合して「覆いを取る」→「発見する」という意味になった。', NOW(), NOW()),('devote', '捧げる、専念する', 'verb', '"完全に"の「de-」と"誓う"の「votum」が結合して「献身する」という意味になった。', NOW(), NOW()),('urge', '促す／衝動', 'verb', 'ラテン語「urgere（押す、追い立てる）」に由来し、「促す、衝動」という意味になった。', NOW(), NOW()),('lend', '貸す', 'verb', '古英語「laenan（貸す）」に由来し、「貸す」という意味になった。', NOW(), NOW()),('restrict', '制限する、禁止する', 'verb', '"後ろに"の「re-」と"縛る"の「stringere」が結合して「制限する」という意味になった。', NOW(), NOW()),('isolate', '孤立させる、分離する', 'verb', '"島"の意味のイタリア語「isola」に由来し、「孤立させる」という意味になった。', NOW(), NOW()),('accompany', '同行する、伴う', 'verb', '"共に"の「ad-」と"パン"の「panis」が結合して「一緒にパンを食べる仲間」→「同行する」という意味になった。', NOW(), NOW()),('exhaust', '疲れ果てさせる、使い果たす', 'verb', '"外に"の「ex-」と"使い果たす"の「haurire」が結合して「使い尽くす」→「疲れ果てさせる」という意味になった。', NOW(), NOW()),('annoy', 'いらだたせる', 'verb', 'ラテン語「inodiare（嫌にさせる）」に由来し、「いら立たせる」という意味になった。', NOW(), NOW()),('acknowledge', '認める、承認する', 'verb', '"〜の方へ"の「ac-」と"知る"の「know」＋「-ledge（名詞語尾）」が結合して「認める」という意味になった。', NOW(), NOW()),('admire', '尊敬する、感心する', 'verb', '"〜の方へ"の「ad-」と"驚嘆する"の「mirari」が結合して「賞賛する」という意味になった。', NOW(), NOW()),('evaluate', '評価する', 'verb', '"価値"の「value」にラテン語の動詞化語尾「-ate」が付いて「評価する」という意味になった。', NOW(), NOW()),('declare', '宣言する、公表する', 'verb', '"完全に"の「de-」と"明らかにする"の「clarare」が結合して「宣言する」という意味になった。', NOW(), NOW()),('secure', '確保する、安全な', 'verb', '"離れて"の「se-」と"気にする、気をつける"の「cura」が結合して「安全な、確保する」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'consist'), 'シンプル', 'The team consists of five members.', 'そのチームは5人のメンバーで構成されている。', 'us_mvp_image_0440_consist.webp', 'say-bddbe856-527d375f-718cf9d0-f0ff42b8-28a5114d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'harm'), 'シンプル', 'Smoking can cause serious harm.', '喫煙は深刻な害を及ぼす可能性がある。', 'us_mvp_image_0448_harm.webp', 'say-6037179e-08c10ab3-3f98fa91-680e9dc5-a98ff19f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'review'), 'シンプル', 'I read a movie review online.', '私はオンラインで映画のレビューを読んだ。', 'us_mvp_image_0454_review.webp', 'say-df32b3b0-b5b5a529-7df56986-cdb72576-c7e34b4c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'interpret'), 'シンプル', 'He interpreted the data differently.', '彼はそのデータを異なる解釈をした。', 'us_mvp_image_0501_interpret.webp', 'say-437d4158-4e032e73-d411ef30-7d08634b-d4d80980.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'translate'), 'シンプル', 'She translated the book into English.', '彼女はその本を英語に翻訳した。', 'us_mvp_image_0502_translate.webp', 'say-e88ccf92-d27b0771-af132d49-153a1d1b-77439f07.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'concentrate'), 'シンプル', 'I need to concentrate on my work.', '私は仕事に集中する必要がある。', 'us_mvp_image_0503_concentrate.webp', 'say-5136b5c0-0546d020-1f664cd5-de66f150-6d0dc342.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'request'), 'シンプル', 'He made a request for more time.', '彼はもっと時間が欲しいと要求した。', 'us_mvp_image_0504_request.webp', 'say-5e427860-2efeb2a4-85273204-2ddb6d49-ebf086bd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'criticize'), 'シンプル', 'He criticized the government’s policy.', '彼は政府の政策を批判した。', 'us_mvp_image_0505_criticize.webp', 'say-1fc3cfbe-eee22e56-cd7cf868-602eaae5-af9451b0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'overcome'), 'シンプル', 'She overcame her fear of heights.', '彼女は高所恐怖症を克服した。', 'us_mvp_image_0506_overcome.webp', 'say-ab1a8b54-59dda8c7-c152fa02-74f22fbc-b25c