)),((SELECT id FROM words WHERE word_text = 'emphasize'), 'シンプル', 'The teacher emphasized the importance of reading.', '先生は読書の重要性を強調した。', 'us_mvp_image_0516_emphasize.webp', 'say-243063d5-fa189717-a372f7a9-364966f3-f767aea9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'employ'), 'シンプル', 'The company employs over 500 workers.', 'その会社は500人以上の労働者を雇用している。', 'us_mvp_image_0517_employ.webp', 'say-2f3f00ea-651fdb2c-17d8e3d5-2e1153cf-ae2fab7a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'transform'), 'シンプル', 'The city has transformed over the years.', 'その都市は年月とともに変化した。', 'us_mvp_image_0519_transform.webp', 'say-7a37ef40-9d92951b-1582f77c-4a027d96-4241bbcd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'construct'), 'シンプル', 'They constructed a new bridge.', '彼らは新しい橋を建設した。', 'us_mvp_image_0520_construct.webp', 'say-5e786404-a1c15134-f9ff4799-91021b14-500b72b7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'arise'), 'シンプル', 'A problem arose during the meeting.', '会議中に問題が発生した。', 'us_mvp_image_0521_arise.webp', 'say-7467cfc0-ef191a9d-4a343be0-f79cac31-37f2eef6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'beat'), 'シンプル', 'Our team beat the opponents easily.', '私たちのチームは相手を簡単に打ち負かした。', 'us_mvp_image_0522_beat.webp', 'say-a3c983c1-3cec9493-2a55e10f-3704f32d-15e26b22.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'regret'), 'シンプル', 'I regret not studying harder.', 'もっと勉強しなかったことを後悔している。', 'us_mvp_image_0523_regret.webp', 'say-ebb6ce6f-51759085-fba2114e-f345823a-497d290f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'alter'), 'シンプル', 'He altered his schedule.', '彼はスケジュールを変更した。', 'us_mvp_image_0524_alter.webp', 'say-4548c1df-c3281623-2c5fa8f1-d8498c9c-bd253a38.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'absorb'), 'シンプル', 'Plants absorb water from the soil.', '植物は土壌から水を吸収する。', 'us_mvp_image_0525_absorb.webp', 'say-7e12bbb6-e325be29-c0708961-96014411-b8f0fa16.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disappoint'), 'シンプル', 'His failure disappointed his parents.', '彼の失敗は両親をがっかりさせた。', 'us_mvp_image_0526_disappoint.webp', 'say-704037d4-65b9b7e9-be463d08-b1a488ce-e347352b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'transport'), 'シンプル', 'Goods are transported by truck.', '商品はトラックで輸送される。', 'us_mvp_image_0528_transport.webp', 'say-b6ce5485-ab0643b0-7939cb99-a20f06d0-e0eef74e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rush'), 'シンプル', 'Don''t rush your decision.', '決断を急がないで。', 'us_mvp_image_0529_rush.webp', 'say-55a04087-60bf35a9-c1320d88-cb85d00d-868a1dea.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'hang'), 'シンプル', 'He hung the picture on the wall.', '彼は壁に絵を掛けた。', 'us_mvp_image_0530_hang.webp', 'say-9183c5f1-48ccc571-801affb2-5bf9ae91-5a8fea11.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'blame'), 'シンプル', 'Don’t blame others for your mistakes.', '自分のミスを他人のせいにしないで。', 'us_mvp_image_0531_blame.webp', 'say-3f2931c1-b55d7825-b660fb55-1e5ffc05-6b54364f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ban'), 'シンプル', 'Smoking is banned in public places.', '公共の場での喫煙は禁止されている。', 'us_mvp_image_0532_ban.webp', 'say-92e7ee5a-976c5557-da145df9-fdd7e47a-1e952476.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fascinate'), 'シンプル', 'The story fascinated the audience.', 'その物語は観客を魅了した。', 'us_mvp_image_0533_fascinate.webp', 'say-c8511022-406470f1-c40472af-0752ccc4-746200e3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'recover'), 'シンプル', 'She recovered from her illness.', '彼女は病気から回復した。', 'us_mvp_image_0534_recover.webp', 'say-f986982f-f16f7dc1-3226fbec-14641512-be1655f0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'celebrate'), 'シンプル', 'They celebrated their anniversary.', '彼らは記念日を祝った。', 'us_mvp_image_0535_celebrate.webp', 'say-0e90315d-f82b1285-9f8211b7-b492a059-c3702f76.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'manufacture'), 'シンプル', 'This company manufactures cars.', 'この会社は車を製造している。', 'us_mvp_image_0536_manufacture.webp', 'say-fa473f4b-b413b615-70727d55-693fc6e3-5e395df3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'interact'), 'シンプル', 'Children interact with each other.', '子どもたちは互いに交流する。', 'us_mvp_image_0537_interact.webp', 'say-39b188f8-dd8d86fb-1eedcda7-3f1b45bb-4cc1dad4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'arrange'), 'シンプル', 'She arranged a meeting.', '彼女は会議を手配した。', 'us_mvp_image_0538_arrange.webp', 'say-124b7494-17d84273-a9926715-71707fc3-53fc5cc0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'adjust'), 'シンプル', 'He adjusted the seat height.', '彼はシートの高さを調整した。', 'us_mvp_image_0539_adjust.webp', 'say-83c4fd95-26d057c2-356e10de-fff05cf2-60537efe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'confirm'), 'シンプル', 'Please confirm your reservation.', '予約を確認してください。', 'us_mvp_image_0540_confirm.webp', 'say-3d0142b4-7459bd76-ef760271-218a3f3b-cb0d000d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'commit'), 'シンプル', 'He committed a serious crime.', '彼は重大な犯罪を犯した。', 'us_mvp_image_0601_commit.webp', 'say-7d108aef-dc3ae667-d23f34a8-85aa312e-875b2cbe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'stimulate'), 'シンプル', 'The teacher stimulated the students'' curiosity.', '先生は生徒の好奇心を刺激した。', 'us_mvp_image_0602_stimulate.webp', 'say-e2aee226-4306e163-676fcfd1-7b8f2f94-fb727636.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'enhance'), 'シンプル', 'This software enhances image quality.', 'このソフトウェアは画像の品質を向上させる。', 'us_mvp_image_0603_enhance.webp', 'say-583faa34-4412b0ca-4472de31-f7b6e501-c738698d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pursue'), 'シンプル', 'He decided to pursue a career in medicine.', '彼は医学の道を追求することに決めた。', 'us_mvp_image_0604_pursue.webp', 'say-b9c8b3eb-7415443a-9021e2de-e9ee521b-81830312.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'react'), 'シンプル', 'She reacted quickly to the news.', '彼女はそのニュースに素早く反応した。', 'us_mvp_image_0605_react.webp', 'say-9c8c8a96-b1572d6e-4a36aeb0-f5dac569-5505c8fc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disagree'), 'シンプル', 'I disagree with your opinion.', '私はあなたの意見に反対だ。', 'us_mvp_image_0606_disagree.webp', 'say-8d6c10e4-2b402919-53a7863e-be7268a9-89353230.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'stare'), 'シンプル', 'He stared at the painting for hours.', '彼は何時間もその絵をじっと見ていた。', 'us_mvp_image_0607_stare.webp', 'say-2cfab9c4-1966bf96-29ec7b1e-7bf86743-131731fd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'abandon'), 'シンプル', 'The dog was abandoned by its owner.', 'その犬は飼い主に捨てられた。', 'us_mvp_image_0608_abandon.webp', 'say-106887d6-c5c1d576-c92071b9-1e2b4af2-508f7133.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'quit'), 'シンプル', 'He quit smoking last year.', '彼は昨年タバコをやめた。', 'us_mvp_image_0609_quit.webp', 'say-36203538-690e8bfe-a1aa323c-953ec183-48718edf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'capture'), 'シンプル', 'The police captured the suspect.', '警察は容疑者を捕らえた。', 'us_mvp_image_0610_capture.webp', 'say-922417c4-f44f714b-2ac6b60d-90c7df5e-7a7c1c21.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'transfer'), 'シンプル', 'She was transferred to a new office.', '彼女は新しいオフィスに転勤した。', 'us_mvp_image_0611_transfer.webp', 'say-4da34fdb-f53e1411-754a0919-1386ff3f-6e49d086.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bother'), 'シンプル', 'Sorry to bother you, but I need help.', 'お邪魔してすみませんが、助けが必要です。', 'us_mvp_image_0612_bother.webp', 'say-ff95e2c6-8bd8705b-0223aa30-0c2680c4-7b789ff1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'persuade'), 'シンプル', 'He persuaded me to join the team.', '彼は私をチームに入るよう説得した。', 'us_mvp_image_0613_persuade.webp', 'say-d16dd861-0138d97c-8fb0ad02-a6eb9c47-78635b23.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rent'), 'シンプル', 'We rented a car for the trip.', '私たちは旅行のために車を借りた。', 'us_mvp_image_0614_rent.webp', 'say-a3e5e31d-802e78c9-a71504b1-5ea747f7-68569b03.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'breed'), 'シンプル', 'This dog breeds easily in captivity.', 'この犬は飼育環境で簡単に繁殖する。', 'us_mvp_image_0615_breed.webp', 'say-b77b50e4-ec04a675-40654db7-431edaca-3ebbbc01.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'invest'), 'シンプル', 'He invested in the stock market.', '彼は株式市場に投資した。', 'us_mvp_image_0616_invest.webp', 'say-76b72284-a099cf56-4b9d19ef-1a52d08d-b7e4aabd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reserve'), 'シンプル', 'I reserved a table for dinner.', '私は夕食のために席を予約した。', 'us_mvp_image_0617_reserve.webp', 'say-0b0ca603-c3245fc6-9668d9c4-a05c8b86-f12f2149.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trace'), 'シンプル', 'The police traced the suspect’s phone.', '警察は容疑者の電話を追跡した。', 'us_mvp_image_0618_trace.webp', 'say-37b12adf-55fcad31-8f4a8f3c-72d9f2e0-acd61067.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'illustrate'), 'シンプル', 'The chart illustrates the trend.', 'その図は傾向を示している。', 'us_mvp_image_0619_illustrate.webp', 'say-77143dd4-c329b13f-3c7d6a14-2a0fc95e-ed214e19.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'advise'), 'シンプル', 'My teacher advised me to study harder.', '先生は私にもっと勉強するよう助言した。', 'us_mvp_image_0620_advise.webp', 'say-a93c437f-0242ab9b-31ba79ef-c156896e-2653aa29.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'convey'), 'シンプル', 'The movie conveys a strong message.', 'その映画は強いメッセージを伝えている。', 'us_mvp_image_0621_convey.webp', 'say-3bf8ef56-057000a3-266f4d15-e60ab903-e4116b70.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'attach'), 'シンプル', 'Please attach the file to the email.', 'メールにファイルを添付してください。', 'us_mvp_image_0622_attach.webp', 'say-717dd329-2f98d9fd-8bdacb84-697d1e86-e98f61e2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'stretch'), 'シンプル', 'She stretched her arms.', '彼女は腕を伸ばした。', 'us_mvp_image_0623_stretch.webp', 'say-6b1f19af-93ce5bdf-21593a6f-8077eeb4-065b2c7e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disturb'), 'シンプル', 'Don’t disturb him while he’s working.', '彼が仕事中に邪魔しないでください。', 'us_mvp_image_0625_disturb.webp', 'say-05efaafb-aededcf1-ec45a0c8-4c0f351f-5f29ea23.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'crash'), 'シンプル', 'The car crashed into the wall.', 'その車は壁に衝突した。', 'us_mvp_image_0626_crash.webp', 'say-fd9596e1-5e300bac-713f84e1-d3d70bf4-732210e2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cope'), 'シンプル', 'She copes well with stress.', '彼女はストレスにうまく対処する。', 'us_mvp_image_0627_cope.webp', 'say-de32fd7e-8027f60b-bde7b0d1-560c2078-70917d47.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'permit'), 'シンプル', 'Smoking is not permitted here.', 'ここでは喫煙は許可されていない。', 'us_mvp_image_0628_permit.webp', 'say-c0f4a032-c3b46799-6c6cc6cf-02c82f3d-4d6a33d3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'impress'), 'シンプル', 'His speech impressed the audience.', '彼のスピーチは聴衆に感銘を与えた。', 'us_mvp_image_0629_impress.webp', 'say-9f96c221-2fc69c7e-ef9c9b3c-663ea055-b852a868.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'suspect'), 'シンプル', 'I suspect he is lying.', '彼が嘘をついていると疑っている。', 'us_mvp_image_0630_suspect.webp', 'say-fc3fa10d-d9b61672-b3b1925b-8780b5e7-e656243f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'frighten'), 'シンプル', 'The thunder frightened the child.', '雷がその子を怖がらせた。', 'us_mvp_image_0632_frighten.webp', 'say-12964997-1f5abaa4-f4d28151-c8b02bd6-6911f2f9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'import'), 'シンプル', 'The country imports oil.', 'その国は石油を輸入している。', 'us_mvp_image_0633_import.webp', 'say-282a6656-fb44772e-160d5259-06c1db96-69e75eeb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'export'), 'シンプル', 'Japan exports cars to many countries.', '日本は多くの国に車を輸出している。', 'us_mvp_image_0634_export.webp', 'say-5e3b1928-1ecd8a64-1e5a7611-b7a53010-07a6f8d9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'investigate'), 'シンプル', 'The police are investigating the case.', '警察はその事件を調査している。', 'us_mvp_image_0635_investigate.webp', 'say-0a3857cf-f28cab76-2b506a86-3fb2f5e1-710ea052.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'calculate'), 'シンプル', 'He calculated the total cost.', '彼は合計費用を計算した。', 'us_mvp_image_0637_calculate.webp', 'say-bbfda699-2f67b10e-55ceff26-186dd8bf-a606cc44.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'eliminate'), 'シンプル', 'The new law eliminates unfair taxes.', '新しい法律は不公平な税を廃止する。', 'us_mvp_image_0638_eliminate.webp', 'say-cf2ddf63-4c8218f0-ae8e3eb3-08d545ac-2c9a3a23.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'launch'), 'シンプル', 'The company launched a new product.', 'その会社は新商品を発表した。', 'us_mvp_image_0640_launch.webp', 'say-a330a7df-f7926271-49837e5c-882b86a4-568f262b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'burden'), 'シンプル', 'The tax increase is a burden on citizens.', '増税は市民にとって負担だ。', 'us_mvp_image_0647_burden.webp', 'say-29d0547c-27488899-9786dc69-eb230cf0-8e4efeb7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'award'), 'シンプル', 'She won an award for her research.', '彼女は研究で賞を受賞した。', 'us_mvp_image_0650_award.webp', 'say-266ebce0-cf14e8e9-9d50d194-f9517a3e-1f437ddb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bond'), 'シンプル', 'They have a strong bond.', '彼らは強い絆で結ばれている。', 'us_mvp_image_0656_bond.webp', 'say-6d4845b3-e5dfbaac-5298d520-13ce9e50-c5da02d7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trick'), 'シンプル', 'He played a trick on his friend.', '彼は友達にいたずらをした。', 'us_mvp_image_0670_trick.webp', 'say-575b21d0-ca095fa8-0c525940-3bb1237a-3636ec77.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'possess'), 'シンプル', 'He possesses great talent.', '彼は素晴らしい才能を持っている。', 'us_mvp_image_0701_possess.webp', 'say-431c3b20-1b144f44-c50c2ca1-becece38-861ed9d1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dominate'), 'シンプル', 'The team dominated the match.', 'そのチームは試合を支配した。', 'us_mvp_image_0702_dominate.webp', 'say-a4eff945-0701e94f-d467107f-0c1d1c44-fa622a23.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'guarantee'), 'シンプル', 'The company guarantees product quality.', 'その会社は製品の品質を保証している。', 'us_mvp_image_0703_guarantee.webp', 'say-5f058af6-87e9bb3f-1993f1df-5f272440-5afd6d2c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'embarrass'), 'シンプル', 'His mistake embarrassed him.', '彼のミスは彼を恥ずかしい思いにさせた。', 'us_mvp_image_0705_embarrass.webp', 'say-9077a476-59e799ee-e82d713d-2121cc1b-9802e82e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'discourage'), 'シンプル', 'His failure discouraged him.', '彼の失敗は彼を落胆させた。', 'us_mvp_image_0706_discourage.webp', 'say-73fd08ae-e8e211ae-af646570-359ee2dc-91d39264.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'detect'), 'シンプル', 'The doctor detected a problem.', '医者は問題を検出した。', 'us_mvp_image_0707_detect.webp', 'say-5f2ab885-3f162aaa-8efe9824-2053cbc8-a0bd1780.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'devote'), 'シンプル', 'She devotes her time to research.', '彼女は研究に時間を捧げている。', 'us_mvp_image_0708_devote.webp', 'say-f3c80799-ece11d4e-2d2068d9-52747277-6a4e7fc2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'urge'), 'シンプル', 'He urged me to apply for the job.', '彼は私にその仕事に応募するよう促した。', 'us_mvp_image_0709_urge.webp', 'say-cdea1e5d-3063c1d0-e5a36847-4c2cb9a2-113129c5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'lend'), 'シンプル', 'Can you lend me your book?', '本を貸してくれますか？', 'us_mvp_image_0710_lend.webp', 'say-0d4c8eb7-81b7143f-ada7b1f4-4acc1530-12d67b20.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'restrict'), 'シンプル', 'The law restricts smoking in public.', 'その法律は公共の場での喫煙を制限している。', 'us_mvp_image_0711_restrict.webp', 'say-5f708c39-31bcfaf9-b9fbfe19-121533fc-7ef3b993.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'isolate'), 'シンプル', 'He was isolated from the group.', '彼はグループから孤立した。', 'us_mvp_image_0712_isolate.webp', 'say-42a2fcfe-15f4bc92-b2ba3906-78038d66-4bd7b4be.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'accompany'), 'シンプル', 'He accompanied her to the hospital.', '彼は彼女に付き添って病院へ行った。', 'us_mvp_image_0713_accompany.webp', 'say-5ceff596-50ca7539-6c9a2bc6-bd43664e-ad44d4f5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exhaust'), 'シンプル', 'The long workday exhausted him.', '長い労働時間が彼を疲れ果てさせた。', 'us_mvp_image_0714_exhaust.webp', 'say-55bff7ce-6954194b-89611aad-1657c06a-ff36105a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'annoy'), 'シンプル', 'His constant talking annoys me.', '彼の絶え間ないおしゃべりが私をいらだたせる。', 'us_mvp_image_0715_annoy.webp', 'say-86cb2a90-f5f84938-6420178c-6b0c71d6-c3fcb9ad.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'acknowledge'), 'シンプル', 'He acknowledged his mistake.', '彼は自分のミスを認めた。', 'us_mvp_image_0717_acknowledge.webp', 'say-ddf7d341-df6fe860-0e6bb76c-5fef76a1-79cd4cb6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'admire'), 'シンプル', 'I admire his courage.', '私は彼の勇気に感心する。', 'us_mvp_image_0718_admire.webp', 'say-a1f11401-c1956cf5-e17844c9-e18c6d1b-ab1002d6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'evaluate'), 'シンプル', 'The teacher evaluated the students’ work.', '先生は生徒の課題を評価した。', 'us_mvp_image_0719_evaluate.webp', 'say-8e335e17-e5ef5b6b-8311e4fb-2496aff2-cb4b9b1c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'declare'), 'シンプル', 'The president declared a state of emergency.', '大統領は非常事態を宣言した。', 'us_mvp_image_0720_declare.webp', 'say-8054d7d1-dcb1ff9c-36ac7b1a-0268cff1-69c8ad17.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'secure'), 'シンプル', 'We need to secure funding for the project.', '私たちはプロジェクトの資金を確保する必要がある。', 'us_mvp_image_0721_secure.webp', 'say-f217869d-84730018-c5e62a45-17fbd028-30249ca9.mp3', NOW(), NOW());
