INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('specialize', '専門とする', 'verb', '「特別な」の意味の「special」に接尾辞「-ize」が付き、「専門とする」という意味になった。', NOW(), NOW()),('pretend', 'ふりをする', 'verb', '"前に"の「prae-」と"伸ばす、示す"の「tendere」が結合して「見せかける」という意味になった。', NOW(), NOW()),('bury', '埋める', 'verb', '古英語「byrgan（埋める）」に由来し、「埋葬する」という意味になった。', NOW(), NOW()),('reverse', '逆転する／逆', 'verb', '"後ろに"の「re-」と"向ける"の「vertere」が結合して「逆にする」という意味になった。', NOW(), NOW()),('resist', '抵抗する、耐える', 'verb', '"逆らって"の「re-」と"立つ"の「sistere」が結合して「抵抗する」という意味になった。', NOW(), NOW()),('scare', '怖がらせる／恐怖', 'verb', '古ノルド語「skirra（怖がらせる）」に由来し、「怖がらせる」という意味になった。', NOW(), NOW()),('assist', '助ける', 'verb', '"〜の方へ"の「ad-」と"立つ"の「sistere」が結合して「助ける」という意味になった。', NOW(), NOW()),('resemble', '似ている', 'verb', '"再び"の「re-」と"似る"の「similis」が結合して「似ている」という意味になった。', NOW(), NOW()),('retire', '退職する', 'verb', '"後ろに"の「re-」と"引く"の「tirer（引く）」が結合して「退く、引退する」という意味になった。', NOW(), NOW()),('neglect', '怠る、無視する', 'verb', '"否定のneg-"と"拾う、選ぶ"の「legere」が結合して「無視する、怠る」という意味になった。', NOW(), NOW()),('collapse', '崩壊する／崩壊', 'verb', '"共に"の「com-」と"落ちる"の「labi」が結合して「崩れる、倒壊する」という意味になった。', NOW(), NOW()),('reform', '改革する／改革', 'verb', '"再び"の「re-」と"形づくる"の「formare」が結合して「改革する、改良する」という意味になった。', NOW(), NOW()),('protest', '抗議する／抗議', 'verb', '"前に"の「pro-」と"証言する"の「testari」が結合して「抗議する」という意味になった。', NOW(), NOW()),('owe', '借りている、恩義がある', 'verb', '古英語「agan（所有する）」に由来し、「借りている、義務がある」という意味になった。', NOW(), NOW()),('sustain', '維持する、支える', 'verb', '"下で"の「sub-」と"保つ"の「tenere」が結合して「支える、持続する」という意味になった。', NOW(), NOW()),('assign', '割り当てる、任命する', 'verb', '"〜に"の「ad-」と"印をつける"の「signare」が結合して「割り当てる」という意味になった。', NOW(), NOW()),('accomplish', '達成する、成し遂げる', 'verb', '"〜へ"の「ad-」と"満たす"の「complere」が結合して「成し遂げる」という意味になった。', NOW(), NOW()),('guard', '警備員、守る', 'verb', '古フランス語「garder（守る）」に由来し、「守る、警備する」という意味になった。', NOW(), NOW()),('assess', '評価する、査定する', 'verb', '"〜へ"の「ad-」と"座らせる"の「sedere」が結合して「評価する、査定する」という意味になった。', NOW(), NOW()),('approve', '承認する、賛成する', 'verb', '"〜の方へ"の「ad-」と"試す、証明する"の「probare」が結合して「承認する」という意味になった。', NOW(), NOW()),('remark', '発言、意見／述べる', 'verb', '"再び"の「re-」と"気づく"の「mark」が結合して「述べる、注目する」という意味になった。', NOW(), NOW()),('pose', '提起する、ポーズをとる／姿勢', 'verb', 'ラテン語「ponere（置く）」に由来し、「置く、提示する」という意味になった。', NOW(), NOW()),('yield', '産出する、譲る／収穫', 'verb', '古英語「gieldan（与える、屈する）」に由来し、「産出する、屈する」という意味になった。', NOW(), NOW()),('exhibit', '展示する／展示', 'verb', '"外に"の「ex-」と"示す"の「habere（持つ）」が結合して「展示する、示す」という意味になった。', NOW(), NOW()),('distribute', '配布する、分配する', 'verb', '"離れて"の「dis-」と"分ける"の「tribuere」が結合して「分配する」という意味になった。', NOW(), NOW()),('command', '命じる、指揮する／命令', 'verb', '"共に"の「com-」と"命じる"の「mandare」が結合して「命令する、指揮する」という意味になった。', NOW(), NOW()),('occupy', '占める、占領する', 'verb', '"〜の方へ"の「ob-」と"取る"の「capere」が結合して「占める、占領する」という意味になった。', NOW(), NOW()),('pop', 'ポンとはじける／流行', 'verb', '擬音語由来で、「破裂する、現れる、流行の」という意味になった。', NOW(), NOW()),('pile', '積み重ね／積み上げる', 'verb', 'ラテン語「pila（柱、杭）」に由来し、「積み重ね、山」という意味になった。', NOW(), NOW()),('greet', '挨拶する', 'verb', '古英語「gretan（近づく、迎える）」に由来し、「挨拶する、迎える」という意味になった。', NOW(), NOW()),('apologize', '謝る', 'verb', 'ギリシア語「apologia（弁明）」がラテン語、フランス語を経て「謝る」という意味になった。', NOW(), NOW()),('frustrate', 'いらだたせる', 'verb', 'ラテン語「frustra（無駄に）」と「frustrare（妨げる）」が結合して「挫折させる、欲求不満にする」という意味になった。', NOW(), NOW()),('relieve', '和らげる、安心させる', 'verb', '"再び"の「re-」と"軽くする"の「levare」が結合して「軽減する、安心させる」という意味になった。', NOW(), NOW()),('derive', '由来する、得る', 'verb', '"下から"の「de-」と"流れる"の「rivus」が結合して「引き出す、由来する」という意味になった。', NOW(), NOW()),('deserve', '値する、ふさわしい', 'verb', '"完全に"の「de-」と"仕える、務める"の「servire」が結合して「値する」という意味になった。', NOW(), NOW()),('defeat', '打ち負かす／敗北', 'verb', '"下に"の「de-」と"打つ"の「facere」が結合して「打ち負かす、敗北させる」という意味になった。', NOW(), NOW()),('convert', '変換する、改宗する', 'verb', '"共に"の「con-」と"向きを変える"の「vertere」が結合して「転換する、改宗する」という意味になった。', NOW(), NOW()),('wed', '結婚する', 'verb', '古英語「weddian（結婚する）」に由来し、「結婚する、誓約する」という意味になった。', NOW(), NOW()),('endure', '耐える、持ちこたえる', 'verb', '"中に"の「en-」と"持続する"の「durare」が結合して「耐える、持ちこたえる」という意味になった。', NOW(), NOW()),('correspond', '一致する、対応する', 'verb', '"共に"の「cor-」と"応じる"の「respondere」が結合して「一致する、対応する」という意味になった。', NOW(), NOW()),('impose', '課す、押しつける', 'verb', '"上に"の「im-」と"置く"の「ponere」が結合して「課す、押しつける」という意味になった。', NOW(), NOW()),('rescue', '救助する／救助', 'verb', 'ラテン語「rescutere（振り戻す）」が中世フランス語を経て「救出する」という意味になった。', NOW(), NOW()),('resolve', '解決する、決心する／決議', 'verb', '"再び"の「re-」と"解く"の「solvere」が結合して「解決する、決意する」という意味になった。', NOW(), NOW()),('register', '登録する／登録', 'verb', 'ラテン語「regere（記録する、支配する）」が変化して「登録する、記録する」という意味になった。', NOW(), NOW()),('interrupt', '邪魔をする、中断する', 'verb', '"間に"の「inter-」と"壊す、破る"の「rumpere」が結合して「妨げる、中断する」という意味になった。', NOW(), NOW()),('rid', '取り除く', 'verb', '古英語「hriddan（掃除する）」に由来し、「取り除く」という意味になった。', NOW(), NOW()),('prohibit', '禁止する', 'verb', '"前に"の「pro-」と"持つ、保つ"の「habere」が結合して「禁止する」という意味になった。', NOW(), NOW()),('compose', '構成する、作曲する', 'verb', '"共に"の「com-」と"置く"の「ponere」が結合して「構成する、作曲する」という意味になった。', NOW(), NOW()),('misunderstand', '誤解する', 'verb', '"誤って"の「mis-」と"理解する"の「understand」が結合して「誤解する」という意味になった。', NOW(), NOW()),('punish', '罰する', 'verb', 'ラテン語「poena（罰）」が派生して「罰する」という意味になった。', NOW(), NOW()),('ruin', '台無しにする／廃墟', 'verb', 'ラテン語「ruere（崩れる）」に由来し、「破壊、崩壊」という意味になった。', NOW(), NOW()),('defend', '守る、弁護する', 'verb', '"離れて"の「de-」と"打つ"の「fendere」が結合して「守る、防御する」という意味になった。', NOW(), NOW()),('embrace', '受け入れる、抱きしめる／抱擁', 'verb', '"中に"の「en-」と"腕"の「bracchium」が結合して「抱きしめる、受け入れる」という意味になった。', NOW(), NOW()),('modify', '修正する、変更する', 'verb', 'ラテン語「modus（方法）」と"作る"の「facere」が結合して「変更する」という意味になった。', NOW(), NOW()),('qualify', '資格を得る', 'verb', 'ラテン語「qualis（どんな）」と「facere（作る）」が結合して「資格を与える、適格とする」という意味になった。', NOW(), NOW()),('chase', '追いかける／追跡', 'verb', '古フランス語「chacier（追う）」に由来し、「追跡する」という意味になった。', NOW(), NOW()),('sue', '訴える', 'verb', 'ラテン語「sequi（従う）」が変化し、法的に「訴える」という意味になった。', NOW(), NOW()),('gaze', 'じっと見つめる／凝視', 'verb', '中期英語「gasen（見つめる）」に由来し、「じっと見る」という意味になった。', NOW(), NOW()),('slip', '滑る、こっそり動く／滑ること', 'verb', '中期英語「slippen（滑る）」に由来し、「滑る、滑らせる」という意味になった。', NOW(), NOW()),('overwhelm', '圧倒する、打ちのめす', 'verb', '「上に」の「over-」と「押しつぶす」意味の「helm（覆う、押さえる）」が結合して「圧倒する」という意味になった。', NOW(), NOW()),('wander', '歩き回る、さまよう', 'verb', '古英語「wandrian（さまよう）」に由来し、「歩き回る、さまよう」という意味になった。', NOW(), NOW()),('pour', '注ぐ、降り注ぐ', 'verb', '古フランス語「pourer（注ぐ）」に由来し、「注ぐ、流れ出る」という意味になった。', NOW(), NOW()),('pronounce', '発音する、宣言する', 'verb', 'ラテン語「pro-（前に）」と「nuntiare（告げる）」が結合して「発音する、宣言する」という意味になった。', NOW(), NOW()),('shrink', '縮む、減る', 'verb', '古英語「scrincan（縮む）」に由来し、「縮む、減る」という意味になった。', NOW(), NOW()),('restore', '修復する、回復させる', 'verb', 'ラテン語「re-（再び）」と「staurare（立て直す）」が結合して「回復させる」という意味になった。', NOW(), NOW()),('trigger', '引き起こす／引き金', 'verb', 'オランダ語「trekken（引く）」に由来し、「引き金、きっかけ」という意味になった。', NOW(), NOW()),('grab', 'つかむ、素早く取る／つかむこと', 'verb', 'スカンジナビア系言語「grapa（つかむ）」に由来し、「つかむ、奪う」という意味になった。', NOW(), NOW()),('retain', '保持する、維持する', 'verb', 'ラテン語「re-（後ろに）」と「tenere（保つ）」が結合して「保持する」という意味になった。', NOW(), NOW()),('reproduce', '再現する、繁殖する', 'verb', 'ラテン語「re-（再び）」と「producere（生み出す）」が結合して「再生する、繁殖する」という意味になった。', NOW(), NOW()),('entertain', '楽しませる、もてなす', 'verb', 'ラテン語「inter-（間で）」と「tenere（保つ）」が結合して「楽しませる、もてなす」という意味になった。', NOW(), NOW()),('interfere', '干渉する、妨害する', 'verb', '"間に"の「inter-」と"打つ"の「ferire」が結合して「干渉する、邪魔をする」という意味になった。', NOW(), NOW()),('underlie', '基礎となる、根底にある', 'verb', '「下に」の「under-」と"横たわる"の「lie」が結合して「根底にある、基礎となる」という意味になった。', NOW(), NOW()),('anticipate', '予測する、期待する', 'verb', '"前に"の「ante-」と"取る、つかむ"の「capere」が結合して「予期する」という意味になった。', NOW(), NOW()),('justify', '正当化する', 'verb', 'ラテン語「justus（正しい）」と「facere（作る）」が結合して「正当化する」という意味になった。', NOW(), NOW()),('regulate', '規制する、調整する', 'verb', 'ラテン語「regula（規則）」に由来し、「規制する、調整する」という意味になった。', NOW(), NOW()),('scan', 'ざっと見る、スキャンする', 'verb', 'ラテン語「scandere（登る）」が比喩的に「吟味する」という意味に変化して「細かく見る」という意味になった。', NOW(), NOW()),('classify', '分類する', 'verb', 'ラテン語「classis（分類）」と「facere（作る）」が結合して「分類する」という意味になった。', NOW(), NOW()),('submit', '提出する', 'verb', '"下に"の「sub-」と"送る"の「mittere」が結合して「提出する、服従する」という意味になった。', NOW(), NOW()),('pause', '一時停止する／一時停止', 'verb', 'ラテン語「pausare（止まる）」に由来し、「一時停止する」という意味になった。', NOW(), NOW()),('lean', '傾く、寄りかかる', 'verb', '古英語「hleonian（傾ける、もたれる）」に由来し、「傾く、寄りかかる」という意味になった。', NOW(), NOW()),('hesitate', 'ためらう', 'verb', 'ラテン語「haesitare（ためらう）」に由来し、「ためらう」という意味になった。', NOW(), NOW()),('pump', 'くみ上げる／ポンプ', 'verb', '擬音語的起源を持ち、「ポンプでくむ、汲み上げる」という意味になった。', NOW(), NOW()),('mount', '増加する、取り付ける', 'verb', 'ラテン語「mons（山）」に由来し、「登る、載せる」という意味になった。', NOW(), NOW()),('exceed', '超える', 'verb', '"外に"の「ex-」と"行く"の「cedere」が結合して「超える」という意味になった。', NOW(), NOW()),('undergo', '経験する、受ける', 'verb', '「下に」の「under-」と"行く"の「go」が結合して「経験する、被る」という意味になった。', NOW(), NOW()),('confront', '直面する、対峙する', 'verb', '"共に"の「com-」と"向かい合う"の「frontem」が結合して「直面する」という意味になった。', NOW(), NOW()),('consult', '相談する、診察を受ける', 'verb', '"共に"の「con-」と"助言する"の「sulere（助言を求める）」が結合して「相談する」という意味になった。', NOW(), NOW()),('fulfill', '果たす、満たす', 'verb', '「満たす」の「full」と「実行する」の「fill」が結合して「果たす、遂行する」という意味になった。', NOW(), NOW()),('abuse', '乱用、虐待／乱用する、虐待する', 'verb', '"離れて"の「ab-」と"使う"の「uti」が結合して「乱用、虐待する」という意味になった。', NOW(), NOW()),('stroke', '脳卒中、一撃、泳法', 'verb', '古英語「strac（打撃）」に由来し、「打つこと、発作、一撃」という意味になった。', NOW(), NOW()),('negotiate', '交渉する、取り決める', 'verb', 'ラテン語「negotiari（取引する）」に由来し、「交渉する」という意味になった。', NOW(), NOW()),('grasp', '理解する、つかむ／理解、把握', 'verb', '古ノルド語「grapa（つかむ）」に由来し、「つかむ、理解する」という意味になった。', NOW(), NOW()),('donate', '寄付する、提供する', 'verb', 'ラテン語「donare（与える）」に由来し、「寄付する」という意味になった。', NOW(), NOW()),('arrest', '逮捕する／逮捕', 'verb', 'ラテン語「ad-（〜へ）」と「restare（止まる）」が結合して「逮捕する、止める」という意味になった。', NOW(), NOW()),('crack', 'ひびが入る、割る／ひび、割れ目', 'verb', '擬音語的起源を持ち、「ひび、割れる」という意味になった。', NOW(), NOW()),('tap', '軽くたたく、利用する／軽い一撃', 'verb', '擬音語的起源を持ち、「軽く叩く、蛇口、盗聴する」という意味になった。', NOW(), NOW()),('split', '分裂する、分ける／分裂、裂け目', 'verb', '古ノルド語「splita（裂く）」に由来し、「分裂する、割る」という意味になった。', NOW(), NOW()),('exclude', '除外する、締め出す', 'verb', '「外へ」の「ex-」と「閉める」の「claudere」が結合して「除外する」という意味になった。', NOW(), NOW()),('overlook', '見落とす、見渡す', 'verb', '「上から見る」という意味から「見落とす、監視する、見逃す」という多義的な意味になった。', NOW(), NOW()),('forbid', '禁じる', 'verb', '古英語「forbeodan（禁じる）」に由来し、「禁止する」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'specialize'), 'シンプル', 'He specializes in computer science.', '彼はコンピューター科学を専門としている。', 'us_mvp_image_0722_specialize.webp', 'say-54d8ccfb-17979f0b-d6ee2aad-f94584b2-74efec6a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pretend'), 'シンプル', 'She pretended not to hear him.', '彼女は彼の声が聞こえないふりをした。', 'us_mvp_image_0724_pretend.webp', 'say-98ffe7d6-8745047b-4fb635c7-65ca7158-7973606c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bury'), 'シンプル', 'They buried the treasure underground.', '彼らは宝を地中に埋めた。', 'us_mvp_image_0725_bury.webp', 'say-04b190ad-b13bd744-1297c8b7-0657ec24-18f3c605.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reverse'), 'シンプル', 'The decision was reversed.', 'その決定は覆された。', 'us_mvp_image_0726_reverse.webp', 'say-b9974dc2-25e75e80-068c3295-871f16da-51e389de.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'resist'), 'シンプル', 'He resisted the temptation to eat sweets.', '彼は甘いものを食べる誘惑に抵抗した。', 'us_mvp_image_0727_resist.webp', 'say-1995c90a-1d87cb14-162f31dc-21018338-b1aa674c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'scare'), 'シンプル', 'The movie scared me.', 'その映画は私を怖がらせた。', 'us_mvp_image_0728_scare.webp', 'say-c8df4e08-7df0b9fb-ca95a750-48ebefea-4d69fe5a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'assist'), 'シンプル', 'He assisted me with my homework.', '彼は私の宿題を手伝ってくれた。', 'us_mvp_image_0730_assist.webp', 'say-9bd928e3-6d4823c2-c8abd655-9be0d8d2-0e360e07.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'resemble'), 'シンプル', 'She resembles her mother.', '彼女は母親に似ている。', 'us_mvp_image_0731_resemble.webp', 'say-a3aebf65-aa985727-43dbfffe-bda25f2a-a557240e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'retire'), 'シンプル', 'He retired at the age of 65.', '彼は65歳で退職した。', 'us_mvp_image_0732_retire.webp', 'say-195708d3-df0063ff-63d423a0-c0e3945e-aa6626a4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'neglect