p', 'say-44d59cfe-929ac682-f693ee8e-5449e16a-cd6f05fa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prohibit'), 'シンプル', 'Smoking is prohibited in this area.', 'ここでは喫煙が禁止されている。', 'us_mvp_image_0832_prohibit.webp', 'say-4c7236be-23684acc-1d8f17fc-8304f3a1-38c62e6c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compose'), 'シンプル', 'He composed a new song.', '彼は新しい曲を作曲した。', 'us_mvp_image_0833_compose.webp', 'say-2b52c5e3-bab4bb93-6abfd512-596a80f3-2a55ad36.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'misunderstand'), 'シンプル', 'I misunderstood his words.', '私は彼の言葉を誤解した。', 'us_mvp_image_0834_misunderstand.webp', 'say-3ac4a855-e85a4c4f-e2bb4bd8-88daf2e3-a621bdcb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'punish'), 'シンプル', 'The teacher punished the students.', '先生は生徒を罰した。', 'us_mvp_image_0835_punish.webp', 'say-82776f99-f17c83f9-a72a04f1-c0e8996a-6eb0b0c0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ruin'), 'シンプル', 'The storm ruined our picnic.', '嵐が私たちのピクニックを台無しにした。', 'us_mvp_image_0836_ruin.webp', 'say-0ea9d8ac-5e8c8721-d78d801d-5ac96932-42221445.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'defend'), 'シンプル', 'The lawyer defended his client.', '弁護士は依頼人を弁護した。', 'us_mvp_image_0837_defend.webp', 'say-503d3f0d-5085efd7-ac50184c-41ea3d60-6d32bf94.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'embrace'), 'シンプル', 'She embraced the new idea.', '彼女は新しい考えを受け入れた。', 'us_mvp_image_0838_embrace.webp', 'say-80e6ed63-819bf459-cd9443c8-abfbf3b7-fe17dac0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'modify'), 'シンプル', 'The design was modified slightly.', 'デザインが少し変更された。', 'us_mvp_image_0839_modify.webp', 'say-3f201c34-6891ddb6-7392b5a6-b20dd2f7-aa55975d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'qualify'), 'シンプル', 'She qualified for the finals.', '彼女は決勝戦への資格を得た。', 'us_mvp_image_0840_qualify.webp', 'say-c4281547-e9e94f5e-140ee169-1023fac1-1676e7b6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'chase'), 'シンプル', 'The police chased the suspect.', '警察は容疑者を追跡した。', 'us_mvp_image_0901_chase.webp', 'say-e85bd43c-b3cb9b50-6a7ede59-8dc0db05-155da489.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sue'), 'シンプル', 'She sued the company for negligence.', '彼女は過失で会社を訴えた。', 'us_mvp_image_0902_sue.webp', 'say-0c816971-13ddb5c9-dbe970a7-25d1df84-6c6e944b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'gaze'), 'シンプル', 'He gazed at the stars.', '彼は星をじっと見つめた。', 'us_mvp_image_0903_gaze.webp', 'say-926c497a-0b2a268c-582101c0-6663a21f-58f6cf67.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'slip'), 'シンプル', 'She slipped on the ice.', '彼女は氷の上で滑った。', 'us_mvp_image_0904_slip.webp', 'say-c8ce56e6-f8db2e7d-20ccc2ad-be93563e-109241c9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'overwhelm'), 'シンプル', 'The beauty of the place overwhelmed me.', 'その場所の美しさに圧倒された。', 'us_mvp_image_0906_overwhelm.webp', 'say-b565abd8-0496a556-46c3d656-0118105f-a9809ef6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'wander'), 'シンプル', 'He wandered through the forest.', '彼は森の中をさまよった。', 'us_mvp_image_0907_wander.webp', 'say-6fcaf645-109c122d-2a349be8-0ede3f92-78c755fb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pour'), 'シンプル', 'She poured coffee into the cup.', '彼女はカップにコーヒーを注いだ。', 'us_mvp_image_0909_pour.webp', 'say-4b95c825-d5088f34-ab201b79-d5a72a74-0771d905.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pronounce'), 'シンプル', 'How do you pronounce this word?', 'この単語はどう発音しますか？', 'us_mvp_image_0911_pronounce.webp', 'say-7cb1c763-6b528969-dcbc279e-49d54785-f0b460f9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'shrink'), 'シンプル', 'My sweater shrank in the wash.', '私のセーターは洗濯で縮んだ。', 'us_mvp_image_0912_shrink.webp', 'say-89a5319e-e5f622bb-a79e6b50-b64918c8-99566c0c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'restore'), 'シンプル', 'The government restored the old building.', '政府はその古い建物を修復した。', 'us_mvp_image_0913_restore.webp', 'say-70cf1914-9c128c91-03d7a9ee-48354592-6f524587.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trigger'), 'シンプル', 'The incident triggered a crisis.', 'その事件が危機を引き起こした。', 'us_mvp_image_0914_trigger.webp', 'say-f7640b74-107d5c4f-73757099-c14fa07a-ac641b70.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'grab'), 'シンプル', 'He grabbed his coat and left.', '彼はコートをつかんで出かけた。', 'us_mvp_image_0915_grab.webp', 'say-a9d52b40-88e1043f-630761f0-bd06b379-97a8daa3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'retain'), 'シンプル', 'The company retains its employees well.', 'その会社は従業員をしっかりと維持している。', 'us_mvp_image_0916_retain.webp', 'say-e47d6bc6-ec9df447-c05f03d0-25b94f26-108e3b54.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reproduce'), 'シンプル', 'The experiment was successfully reproduced.', 'その実験は成功裏に再現された。', 'us_mvp_image_0917_reproduce.webp', 'say-17799071-961eecee-343fe22d-4d443f70-5f92d0fd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'entertain'), 'シンプル', 'The comedian entertained the audience.', 'そのコメディアンは観客を楽しませた。', 'us_mvp_image_0919_entertain.webp', 'say-b3ed23d2-d830019b-1ffc5c1e-7bd66c0f-ee38e294.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'interfere'), 'シンプル', 'Don’t interfere in their business.', '彼らの仕事に干渉しないで。', 'us_mvp_image_0920_interfere.webp', 'say-7039c634-f7b8eb3c-3695cfcb-bd68d83b-ecdccda8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'underlie'), 'シンプル', 'Economic factors underlie this issue.', '経済的要因がこの問題の根底にある。', 'us_mvp_image_0922_underlie.webp', 'say-9f69c87e-c6e75c25-3e559047-e66cbcf9-88b83ab5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'anticipate'), 'シンプル', 'We anticipated an increase in sales.', '私たちは売上の増加を予測した。', 'us_mvp_image_0923_anticipate.webp', 'say-97a84b32-0f8e4f1a-b2ff7d87-76c80866-2f3fc12a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'justify'), 'シンプル', 'He tried to justify his actions.', '彼は自分の行動を正当化しようとした。', 'us_mvp_image_0924_justify.webp', 'say-8d3b93c2-6e4e247c-39633751-37c5d2a4-0af92967.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'regulate'), 'シンプル', 'The government regulates food safety.', '政府は食品の安全を規制している。', 'us_mvp_image_0925_regulate.webp', 'say-976f6d0a-551c6b14-27905dbe-db475523-8194c379.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'scan'), 'シンプル', 'He scanned the document quickly.', '彼は書類を素早くスキャンした。', 'us_mvp_image_0926_scan.webp', 'say-c61c580b-db82e281-f35fc4a6-4f6c91b6-114d91e6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'classify'), 'シンプル', 'The books are classified by subject.', '本は科目ごとに分類されている。', 'us_mvp_image_0927_classify.webp', 'say-d8fa2596-18f4056f-3bff1dcc-42a2c902-879e30d1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'submit'), 'シンプル', 'Please submit your report by Friday.', '金曜日までにレポートを提出してください。', 'us_mvp_image_0928_submit.webp', 'say-105f2d0b-f06e9ac2-286696fe-2e78ff4d-9c52ed01.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pause'), 'シンプル', 'He paused before answering.', '彼は答える前に少し間を取った。', 'us_mvp_image_0929_pause.webp', 'say-e6c0a4b9-b1c8e4e6-a76e0943-f8044bfd-5ef94adf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'lean'), 'シンプル', 'She leaned against the wall.', '彼女は壁にもたれかかった。', 'us_mvp_image_0930_lean.webp', 'say-853b81ae-0281ea7f-4cdc8b7f-c1c77ac5-3d008c84.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'hesitate'), 'シンプル', 'He hesitated before speaking.', '彼は話す前にためらった。', 'us_mvp_image_0933_hesitate.webp', 'say-5c23f34f-0db1dc4b-17b0bdfd-1aa1c228-7793eba1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pump'), 'シンプル', 'The machine pumps water from the well.', 'その機械は井戸から水をくみ上げる。', 'us_mvp_image_0934_pump.webp', 'say-5fcb7f64-cea03790-9c1bfeda-797b418f-7a0418c4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mount'), 'シンプル', 'The pressure is mounting on the team.', 'チームへのプレッシャーが高まっている。', 'us_mvp_image_0935_mount.webp', 'say-a2ab02af-d17a61c9-368850ef-ebc7b8a5-0d0790f6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exceed'), 'シンプル', 'The speed limit was exceeded.', '制限速度が超えられた。', 'us_mvp_image_0936_exceed.webp', 'say-130017a3-cdd94108-339d1b8a-cd90f288-f77442e0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'undergo'), 'シンプル', 'He will undergo training next month.', '彼は来月研修を受ける予定です。', 'us_mvp_image_0937_undergo.webp', 'say-cd628dbe-96e709df-f37b7a88-9cef64c4-d9744d55.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'confront'), 'シンプル', 'He confronted his fears.', '彼は自分の恐怖と向き合った。', 'us_mvp_image_0938_confront.webp', 'say-3a489be9-8217061b-90fcce58-19110c82-815d2bb6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'consult'), 'シンプル', 'You should consult a doctor.', '医者に相談したほうがいい。', 'us_mvp_image_0939_consult.webp', 'say-d0061f93-5f2a1958-5f0f80b7-00f34dab-af893484.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fulfill'), 'シンプル', 'She fulfilled her dream.', '彼女は夢を果たした。', 'us_mvp_image_0940_fulfill.webp', 'say-07ef6afb-4f2a24ad-b2adb4c3-7642f0d6-1e7b90b3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'abuse'), 'シンプル', 'He suffered from child abuse in his youth.', '彼は幼少期に児童虐待を受けた。', 'us_mvp_image_0952_abuse.webp', 'say-b1a30cc7-ae9c8f8a-0b1af1ae-30a3488e-7f219b30.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'stroke'), 'シンプル', 'He suffered a stroke last year.', '彼は昨年、脳卒中を患った。', 'us_mvp_image_0970_stroke.webp', 'say-f7cb19f3-a7005b4d-7559e6b5-f0af4e8c-3234cbe3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'negotiate'), 'シンプル', 'They are trying to negotiate a better deal.', '彼らはより良い取引を交渉しようとしている。', 'us_mvp_image_1001_negotiate.webp', 'say-b7499897-3bf70f37-4238d795-83b763e4-6710055d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'grasp'), 'シンプル', 'She quickly grasped the main idea.', '彼女はすぐに要点を理解した。', 'us_mvp_image_1002_grasp.webp', 'say-3602c80d-25507217-1137be9c-08e9194d-17da03de.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'donate'), 'シンプル', 'He donated money to the charity.', '彼はその慈善団体に寄付をした。', 'us_mvp_image_1003_donate.webp', 'say-02e15cd8-947dd9fb-28a455b1-449427d6-485b5ca4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'arrest'), 'シンプル', 'The police arrested the suspect.', '警察は容疑者を逮捕した。', 'us_mvp_image_1004_arrest.webp', 'say-977b8a57-7fa3dd14-73f02237-cf6ca083-fea302cd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'crack'), 'シンプル', 'The glass cracked when it fell.', 'そのガラスは落ちたときにひびが入った。', 'us_mvp_image_1005_crack.webp', 'say-7970d8b0-80fdf32a-e3864d5d-3703fb90-b8781737.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tap'), 'シンプル', 'He tapped her on the shoulder.', '彼は彼女の肩を軽くたたいた。', 'us_mvp_image_1006_tap.webp', 'say-965a392a-e238cdd0-2f45b597-cc4e805e-e0b59e71.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'split'), 'シンプル', 'They split the bill equally.', '彼らは請求書を均等に分けた。', 'us_mvp_image_1007_split.webp', 'say-e315ac10-2c7ebe3a-be09aff6-7166b80f-3bb12c10.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exclude'), 'シンプル', 'They excluded him from the meeting.', '彼らは彼を会議から除外した。', 'us_mvp_image_1009_exclude.webp', 'say-b3430ebd-6c6adade-9baee157-46a942c6-ad94a76d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'overlook'), 'シンプル', 'He overlooked an important detail.', '彼は重要な細部を見落とした。', 'us_mvp_image_1010_overlook.webp', 'say-6e055ae6-10b24867-f48de362-267b5f78-938978f5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'forbid'), 'シンプル', 'The school forbids smoking.', 'その学校は喫煙を禁じている。', 'us_mvp_image_1013_forbid.webp', 'say-aac01097-3732487a-bb9e1205-bf119a67-a31d81d5.mp3', NOW(), NOW());
