INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('install', '設置する、導入する', 'verb', '"中に"の「in-」と"置く"の「stallare（設置する）」が結合して「設置する、インストールする」という意味になった。', NOW(), NOW()),('diminish', '減少する、弱まる', 'verb', '"離れて"の「de-」と"小さくする"の「minuere」が結合して「減少させる」という意味になった。', NOW(), NOW()),('cite', '引用する、言及する', 'verb', 'ラテン語「citare（呼び出す、引用する）」に由来し、「引用する、言及する」という意味になった。', NOW(), NOW()),('quote', '引用する／引用', 'verb', 'ラテン語「quotare（数える、引用する）」に由来し、「引用する」という意味になった。', NOW(), NOW()),('distract', '注意をそらす、気を散らす', 'verb', '"離れて"の「dis-」と"引く"の「trahere」が結合して「気を散らす」という意味になった。', NOW(), NOW()),('cheat', 'だます、カンニングする／不正行為', 'verb', 'ラテン語「escheat（没収財産）」が変化し、「だます、カンニングする」という意味になった。', NOW(), NOW()),('foster', '促進する、育てる', 'verb', '古英語「fostrian（養う）」に由来し、「育てる、助長する」という意味になった。', NOW(), NOW()),('bend', '曲げる、屈する', 'verb', '古英語「bendan（曲げる）」に由来し、「曲げる、屈する」という意味になった。', NOW(), NOW()),('deprive', '奪う、剥奪する', 'verb', '"離れて"の「de-」と"奪う"の「privare」が結合して「奪う、剥奪する」という意味になった。', NOW(), NOW()),('govern', '統治する、管理する', 'verb', 'ラテン語「gubernare（統治する）」に由来し、「統治する、管理する」という意味になった。', NOW(), NOW()),('transmit', '送る、伝える', 'verb', '"通して"の「trans-」と"送る"の「mittere」が結合して「伝える、送る」という意味になった。', NOW(), NOW()),('leap', '跳ぶ、急増する／跳躍', 'verb', '古英語「hlēapan（跳ぶ）」に由来し、「跳ぶ、跳躍」という意味になった。', NOW(), NOW()),('blend', '混ぜる、調和する／混合', 'verb', '古ノルド語「blanda（混ぜる）」に由来し、「混ぜる、調和する」という意味になった。', NOW(), NOW()),('complicate', '複雑にする、困難にする', 'verb', 'ラテン語「com-（共に）」と「plicare（折る）」が結合して「複雑にする」という意味になった。', NOW(), NOW()),('persist', '持続する、固執する', 'verb', '"完全に"の「per-」と"立つ"の「sistere」が結合して「持続する、粘り強く続ける」という意味になった。', NOW(), NOW()),('dedicate', '捧げる、専念する', 'verb', '"完全に"の「de-」と"言う"の「dicare」が結合して「捧げる、専念する」という意味になった。', NOW(), NOW()),('equip', '装備する、備える', 'verb', 'フランス語「equiper（装備する）」に由来し、「装備する」という意味になった。', NOW(), NOW()),('input', '入力、意見', 'verb', '「中に」の「in-」と「put（置く）」が結合して「入力、投入」という意味になった。', NOW(), NOW()),('shade', '陰、日よけ、色合い／陰にする', 'verb', '古英語「sceadu（影）」に由来し、「日陰、陰影」という意味になった。', NOW(), NOW()),('file', 'ファイル、書類／整理する、提出する', 'verb', 'ラテン語「filum（糸）」が中世ラテン語で「列、文書束」を意味し、「ファイル、綴じる」という意味になった。', NOW(), NOW()),('brave', '勇敢な', 'verb', 'ラテン語「barbarus（野蛮な）」を語源とし、中世フランス語で「勇敢な」という意味に変化した。', NOW(), NOW()),('proceed', '進む、続行する', 'verb', '「前に」の「pro-」と「行く」の「cedere」が結合して「進む、続行する」という意味になった。', NOW(), NOW()),('orient', '適応させる、方向付ける', 'verb', 'ラテン語「oriens（東、昇る）」に由来し、「東に向ける、適応させる」という意味になった。', NOW(), NOW()),('bind', '縛る、束縛する', 'verb', '古英語「bindan（縛る）」に由来し、「縛る、結びつける」という意味になった。', NOW(), NOW()),('reinforce', '強化する、補強する', 'verb', '「再び」の「re-」と「強くする」の「fortis」が結合して「強化する」という意味になった。', NOW(), NOW()),('accumulate', '蓄積する、積もる', 'verb', 'ラテン語「ad-（〜へ）」と「cumulare（積み上げる）」が結合して「蓄積する」という意味になった。', NOW(), NOW()),('bet', '賭ける／賭け', 'verb', '古英語「bætan（誓う）」に由来し、「賭ける、賭け」という意味になった。', NOW(), NOW()),('advocate', '提唱する／提唱者', 'verb', 'ラテン語「ad-（〜へ）」と「vocare（呼ぶ）」が結合して「支持する、擁護者」という意味になった。', NOW(), NOW()),('constitute', '構成する、占める', 'verb', 'ラテン語「con-（共に）」と「statuere（立てる）」が結合して「構成する、設立する」という意味になった。', NOW(), NOW()),('undertake', '引き受ける、着手する', 'verb', '「下に」の「under-」と「取る」の「take」が結合して「引き受ける、着手する」という意味になった。', NOW(), NOW()),('dismiss', '解雇する、却下する', 'verb', 'ラテン語「dis-（離れて）」と「mittere（送る）」が結合して「解雇する、退ける」という意味になった。', NOW(), NOW()),('fade', '色あせる、消えていく', 'verb', 'ラテン語「fatuus（ぼんやりした）」が変化し、「色あせる、消える」という意味になった。', NOW(), NOW()),('conceal', '隠す', 'verb', 'ラテン語「con-（完全に）」と「celare（隠す）」が結合して「隠す、秘密にする」という意味になった。', NOW(), NOW()),('seal', '密閉する、封をする／印章、アザラシ', 'verb', 'ラテン語「sigillum（印章）」に由来し、「封をする、印」という意味になった。', NOW(), NOW()),('migrate', '移住する、移動する', 'verb', 'ラテン語「migrare（移動する）」に由来し、「移動する、移住する」という意味になった。', NOW(), NOW()),('exaggerate', '誇張する、大げさに言う', 'verb', 'ラテン語「ex-（外へ）」と「aggerare（積む）」が結合して「誇張する」という意味になった。', NOW(), NOW()),('accuse', '非難する、告発する', 'verb', 'ラテン語「ad-（〜に）」と「causa（訴訟）」が結合して「告発する、責める」という意味になった。', NOW(), NOW()),('wipe', '拭く、ぬぐう', 'verb', '古英語「wipian（拭く）」に由来し、「拭く、ぬぐう」という意味になった。', NOW(), NOW()),('sweep', '掃く、一掃する', 'verb', '古英語「swāpan（掃く）」に由来し、「掃く、一掃する」という意味になった。', NOW(), NOW()),('mislead', '誤解させる、惑わせる', 'verb', '「誤った」の「mis-」と「導く」の「lead」が結合して「誤解させる、欺く」という意味になった。', NOW(), NOW()),('explode', '爆発する', 'verb', '「外へ」の「ex-」と「拍手する、鳴らす」の「plaudere」が結合して「爆発する、破裂する」という意味になった。', NOW(), NOW()),('decorate', '飾る、装飾する', 'verb', 'ラテン語「decorare（飾る）」に由来し、「装飾する」という意味になった。', NOW(), NOW()),('postpone', '延期する', 'verb', '「後ろに」の「post-」と「置く」の「ponere」が結合して「延期する」という意味になった。', NOW(), NOW()),('cease', 'やめる、終わる', 'verb', 'ラテン語「cessare（やめる）」に由来し、「やめる、終える」という意味になった。', NOW(), NOW()),('elect', '選ぶ、選出する', 'verb', '「外に」の「e-」と「選ぶ」の「legere」が結合して「選出する」という意味になった。', NOW(), NOW()),('extract', '抽出する、抜き取る／抽出物', 'verb', '「外へ」の「ex-」と「引く」の「trahere」が結合して「引き出す、抜き取る」という意味になった。', NOW(), NOW()),('inherit', '相続する、受け継ぐ', 'verb', 'ラテン語「in-（中に）」と「hereditare（相続する）」が結合して「受け継ぐ」という意味になった。', NOW(), NOW()),('caution', '注意、警戒／注意を促す', 'verb', 'ラテン語「cavere（注意する）」から派生し、「注意、警告」という意味になった。', NOW(), NOW()),('infer', '推測する、推論する', 'verb', 'ラテン語「in-（中に）」と「ferre（運ぶ）」が結合して「推論する」という意味になった。', NOW(), NOW()),('tackle', '取り組む、対処する／タックル', 'verb', 'オランダ語「takel（装備）」に由来し、「取り組む、タックルする」という意味になった。', NOW(), NOW()),('accelerate', '加速する、促進する', 'verb', 'ラテン語「ad-（〜へ）」と「celer（速い）」が結合して「加速する」という意味になった。', NOW(), NOW()),('accustom', '慣れさせる', 'verb', '「〜へ」の「ad-」と「習慣」の「custom」が結合して「慣れさせる」という意味になった。', NOW(), NOW()),('flourish', '繁栄する、栄える', 'verb', 'ラテン語「florere（花が咲く）」に由来し、「繁栄する、栄える」という意味になった。', NOW(), NOW()),('thrive', '成長する、繁栄する', 'verb', '古ノルド語「þrifask（繁栄する）」に由来し、「繁栄する、成長する」という意味になった。', NOW(), NOW()),('click', 'クリックする、カチッと鳴る／クリック音', 'verb', '擬音語的起源で、「カチッという音を立てる、クリックする」という意味になった。', NOW(), NOW()),('spin', '回転する、紡ぐ／回転', 'verb', '古英語「spinnan（紡ぐ）」に由来し、「回転する、紡ぐ」という意味になった。', NOW(), NOW()),('drag', '引きずる、引っ張る', 'verb', '古ノルド語「draga（引く）」に由来し、「引きずる、ドラッグする」という意味になった。', NOW(), NOW()),('cast', '投げる、配役する／キャスト、投げること', 'verb', '古ノルド語「kasta（投げる）」に由来し、「投げる、配役する」という意味になった。', NOW(), NOW()),('scatter', 'まき散らす、分散させる', 'verb', '古ノルド語「skatr（飛び散る）」に由来し、「まき散らす、分散させる」という意味になった。', NOW(), NOW()),('tempt', '誘惑する、そそのかす', 'verb', 'ラテン語「temptare（試す）」に由来し、「誘惑する、引きつける」という意味になった。', NOW(), NOW()),('withdraw', '引き出す、撤退する', 'verb', '「後ろに」の「with-」と「引く」の「draw」が結合して「引き出す、撤退する」という意味になった。', NOW(), NOW()),('enforce', '施行する、強制する', 'verb', '「中へ」の「en-」と「力」の「force」が結合して「施行する、強制する」という意味になった。', NOW(), NOW()),('suspend', '一時停止する、停職にする', 'verb', '「下に」の「sub-」と「掛ける」の「pendere」が結合して「吊るす、中断する」という意味になった。', NOW(), NOW()),('drift', '漂う、流される／漂流', 'verb', '古ノルド語「drifa（吹雪く、流れる）」に由来し、「漂う、流れる」という意味になった。', NOW(), NOW()),('revise', '修正する、改訂する', 'verb', 'ラテン語「re-（再び）」と「videre（見る）」が結合して「見直す、修正する」という意味になった。', NOW(), NOW()),('recruit', '募集する、採用する／新入社員', 'verb', 'ラテン語「recrescere（再び成長する）」がフランス語を経て「新しく人を加える」という意味になった。', NOW(), NOW()),('crush', '押しつぶす／粉砕', 'verb', '古フランス語「croissir（割る）」に由来し、「押しつぶす、粉砕する」という意味になった。', NOW(), NOW()),('pin', '留める／ピン', 'verb', 'ラテン語「penna（羽根、留め具）」に由来し、「ピンで留める、小さな留め具」という意味になった。', NOW(), NOW()),('uncover', '明らかにする、暴く', 'verb', '否定の「un-」と「覆う」の「cover」が結合して「明らかにする、暴く」という意味になった。', NOW(), NOW()),('exploit', '利用する、搾取する／偉業', 'verb', 'ラテン語「ex-（外へ）」と「plicare（折る）」が派生して「利用する、搾取する」という意味になった。', NOW(), NOW()),('implement', '実行する、導入する／道具', 'verb', 'ラテン語「implere（満たす）」が変化して「道具、実行する」という意味になった。', NOW(), NOW()),('integrate', '統合する、融合させる', 'verb', 'ラテン語「integer（完全な）」に由来し、「統合する」という意味になった。', NOW(), NOW()),('incorporate', '組み入れる、法人化する', 'verb', '「中に」の「in-」と「体」の「corpus」が結合して「組み入れる、法人化する」という意味になった。', NOW(), NOW()),('jail', '牢獄、刑務所／投獄する', 'verb', 'ラテン語「cavea（囲い）」がフランス語「jaiole（檻）」に変化して「刑務所」という意味になった。', NOW(), NOW()),('drill', '訓練、ドリル／訓練する、穴を開ける', 'verb', '古英語「drilian（穴をあける）」に由来し、「訓練、ドリル、穴あけ」という意味になった。', NOW(), NOW()),('bug', '虫、欠陥／悩ます', 'verb', '中期英語「bugge（お化け）」に由来し、「虫、欠陥、バグ」という意味になった。', NOW(), NOW()),('consent', '同意／同意する', 'verb', '「共に」の「con-」と「感じる」の「sentire」が結合して「同意する」という意味になった。', NOW(), NOW()),('deliberate', '意図的な／熟考する', 'verb', 'ラテン語「deliberare（慎重に考える）」に由来し、「意図的な、慎重な」という意味になった。', NOW(), NOW()),('assure', '保証する、確信させる', 'verb', 'ラテン語「ad-（〜に）」と「securus（安心した）」が結合して「保証する、安心させる」という意味になった。', NOW(), NOW()),('precede', '先行する、前にくる', 'verb', 'ラテン語「prae（前に）」と「cedere（行く）」が結合して「先行する、優先する」という意味になった。', NOW(), NOW()),('revive', '生き返らせる、復活させる', 'verb', 'ラテン語「re-（再び）」と「vivere（生きる）」が結合して「生き返る、復活する」という意味になった。', NOW(), NOW()),('compel', '強いる、強制する', 'verb', 'ラテン語「com-（完全に）」と「pellere（押す）」が結合して「強制する」という意味になった。', NOW(), NOW()),('violate', '違反する、侵害する', 'verb', 'ラテン語「violare（傷つける、破る）」に由来し、「侵害する、違反する」という意味になった。', NOW(), NOW()),('suppress', '抑える、鎮圧する', 'verb', 'ラテン語「sub-（下に）」と「premere（押す）」が結合して「抑える、鎮圧する」という意味になった。', NOW(), NOW()),('deceive', '騙す、欺く', 'verb', 'ラテン語「de-（下に、離れて）」と「capere（取る）」が結合して「だます」という意味になった。', NOW(), NOW()),('manipulate', '操作する、巧みに扱う', 'verb', 'ラテン語「manus（手）」と「plere（満たす、操作する）」が結合して「操る、操作する」という意味になった。', NOW(), NOW()),('flee', '逃げる、避難する', 'verb', '古英語「flēon（逃げる）」に由来し、「逃げる」という意味になった。', NOW(), NOW()),('confine', '制限する、閉じ込める', 'verb', 'ラテン語「con-（共に）」と「finis（境界）」が結合して「制限する、閉じ込める」という意味になった。', NOW(), NOW()),('swing', '揺れる、振る／揺れ、スイング', 'verb', '古英語「swingan（揺れる、打つ）」に由来し、「揺れる、振る」という意味になった。', NOW(), NOW()),('prolong', '延ばす、長引かせる', 'verb', 'ラテン語「pro-（前へ）」と「longus（長い）」が結合して「延ばす、長引かせる」という意味になった。', NOW(), NOW()),('depict', '描写する、表現する', 'verb', 'ラテン語「de-（下に）」と「pingere（描く）」が結合して「描写する」という意味になった。', NOW(), NOW()),('shed', '流す、脱ぐ／小屋', 'verb', '古英語「sceadan（分ける）」に由来し、「落とす、脱ぐ、発する」という意味になった。', NOW(), NOW()),('emit', '放出する、発する', 'verb', 'ラテン語「e-（外に）」と「mittere（送る）」が結合して「放出する」という意味になった。', NOW(), NOW()),('renew', '更新する、新たにする', 'verb', 'ラテン語「re-（再び）」と「novare（新しくする）」が結合して「更新する、再開する」という意味になった。', NOW(), NOW()),('utilize', '利用する、活用する', 'verb', 'ラテン語「utilis（役立つ）」に由来し、「利用する」という意味になった。', NOW(), NOW()),('assert', '主張する、断言する', 'verb', 'ラテン語「ad-（〜に）」と「serere（結びつける）」が結合して「断言する、主張する」という意味になった。', NOW(), NOW()),('strive', '努力する、奮闘する', 'verb', '古フランス語「estriver（努力する、争う）」に由来し、「努力する、奮闘する」という意味になった。', NOW(), NOW()),('boast', '自慢する／自慢', 'verb', '中期英語「bosten（自慢する）」に由来し、「自慢する、誇る」という意味になった。', NOW(), NOW()),('compute', '計算する', 'verb', 'ラテン語「com-（共に）」と「putare（計算する）」が結合して「計算する」という意味になった。', NOW(), NOW()),('assemble', '組み立てる、集める', 'verb', 'ラテン語「ad-（〜に）」と「simulare（集める）」が結合して「集める、組み立てる」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'install'), 'シンプル', 'They installed security cameras in the building.', '彼らは建物に防犯カメラを設置した。', 'us_mvp_image_1014_install.webp', 'say-079dd87b-d1eee348-98fbcb12-a0411974-588c4a17.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'diminish'), 'シンプル', 'His influence has diminished over time.', '彼の影響力は時間とともに減少した。', 'us_mvp_image_1015_diminish.webp', 'say-e5af0469-19715591-dcebe1df-935f762a-61e82c8a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cite'), 'シンプル', 'She cited a famous scientist in her paper.', '彼女は論文で有名な科学者を引用した。', 'us_mvp_image_1016_cite.webp', 'say-45f9ed88-1e490900-02cf0ced-30b140ae-2a71ed89.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'quote'), 'シンプル', 'He quoted a line from the book.', '彼はその本の一節を引用した。', 'us_mvp_image_1017_quote.webp', 'say-7fa1a775-d728a672-9e56568b-b6d61104-0f53cbfb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'distract'), 'シンプル', 'The noise distracted him from his work.', '騒音が彼の仕事の集中を妨げた。', 'us_mvp_image_1020_distract.webp', 'say-82228522-cb0c700f-b00e0168-fdbf9840-5c5381c1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cheat'), 'シンプル', 'He cheated on the test.', '彼は試験でカンニングをした。', 'us_mvp_image_1021_cheat.webp', 'say-23d9590f-fcc24f04-89dcc846-15dfff31-f713882a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'foster'), 'シンプル', 'The teacher fosters creativity in students.', 'その教師は生徒の創造力を育てる。', 'us_mvp_image_1022_foster.webp', 'say-15706822-240ed636-5d52574e-014c1d2c-bebc6e9d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bend'), 'シンプル', 'He bent the wire into a circle.', '彼はワイヤーを円形に曲げた。', 'us_mvp_image_1024_bend.webp', 'say-899e3ca1-491ab395-885ee6ff-189ca7d0-1b5284cd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'deprive'), 'シンプル', 'They were deprived of their rights.', '彼らは権利を奪われた。', 'us_mvp_image_1025_deprive.webp', 'say-e5ef7782-792d375f-418ad44d-4d9bae22-a3dcffd7.mp3', NOW(), N