INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('worsen', '悪化する', 'verb', '「悪い」の「worse」に動詞化語尾「-en」がついて「悪化する」という意味になった。', NOW(), NOW()),('flip', 'はじく、裏返す／反転、軽い動作', 'verb', '擬音語的起源で、「はじく、軽く投げる、めくる」という意味になった。', NOW(), NOW()),('rub', 'こする、摩擦する', 'verb', '古英語「rūbban（こする）」に由来し、「こする、擦る」という意味になった。', NOW(), NOW()),('compensate', '補償する、埋め合わせる', 'verb', 'ラテン語「com-（共に）」と「pensare（重さを量る、償う）」が結合して「補償する」という意味になった。', NOW(), NOW()),('comprise', '構成する、含む', 'verb', 'ラテン語「com-（共に）」と「prehendere（つかむ）」が変化して「構成される」という意味になった。', NOW(), NOW()),('prevail', '普及する、打ち勝つ', 'verb', 'ラテン語「pre-（前に）」と「valere（強くある）」が結合して「広まる、打ち勝つ」という意味になった。', NOW(), NOW()),('update', '更新する／最新情報', 'verb', '"上へ"の「up-」と"日付"の「date」が結合して「更新する」という意味になった。', NOW(), NOW()),('induce', '誘発する、引き起こす', 'verb', '"中へ"の「in-」と"導く"の「ducere」が結合して「引き起こす、誘導する」という意味になった。', NOW(), NOW()),('attain', '達成する、到達する', 'verb', '"〜に向かって"の「ad-」と"触れる"の「tangere」が結合して「達成する」という意味になった。', NOW(), NOW()),('spray', '噴霧する／スプレー', 'verb', '古英語「spræg（はじける）」に由来し、「噴霧する、まき散らす」という意味になった。', NOW(), NOW()),('retrieve', '取り戻す、回収する', 'verb', '"再び"の「re-」と"得る"の「trouver（古フランス語）」が結合して「取り戻す」という意味になった。', NOW(), NOW()),('portray', '描写する、演じる', 'verb', '"前に"の「por-」と"描く"の「trahere」が結合して「描写する」という意味になった。', NOW(), NOW()),('designate', '指定する、任命する', 'verb', '"明確に"の「de-」と"印をつける"の「signare」が結合して「指名する、指定する」という意味になった。', NOW(), NOW()),('contradict', '矛盾する、反論する', 'verb', '"反対に"の「contra-」と"話す"の「dicere」が結合して「矛盾する、反論する」という意味になった。', NOW(), NOW()),('sigh', 'ため息をつく／ため息', 'verb', '古英語「sican（ため息をつく）」に由来し、「ため息をつく」という意味になった。', NOW(), NOW()),('disrupt', '混乱させる、中断させる', 'verb', '"分離する"の「dis-」と"壊す"の「rumpere」が結合して「混乱させる、破壊する」という意味になった。', NOW(), NOW()),('depart', '出発する、離れる', 'verb', '"離れて"の「de-」と"分かれる"の「partire」が結合して「出発する、離れる」という意味になった。', NOW(), NOW()),('diagnose', '診断する', 'verb', '"分ける"の「dia-」と"知る"の「gnosis」が結合して「診断する」という意味になった。', NOW(), NOW()),('oblige', '義務付ける、強いる', 'verb', '"縛る"の意味のラテン語「ligare」に「ob-（〜に向かって）」がついて「義務を負わせる」という意味になった。', NOW(), NOW()),('underestimate', '過小評価する', 'verb', '"下に"の「under-」と"評価する"の「estimate」が結合して「過小評価する」という意味になった。', NOW(), NOW()),('clarify', '明確にする、はっきりさせる', 'verb', 'ラテン語「clarus（明るい）」と"〜にする"の「-fy」が結合して「明確にする」という意味になった。', NOW(), NOW()),('spark', '引き起こす、火花を散らす／火花', 'verb', '古英語「spearca（火花）」に由来し、「火花、引き起こす」という意味になった。', NOW(), NOW()),('seize', 'つかむ、押収する', 'verb', 'ラテン語「sacire（つかむ）」が古フランス語を経て「捕らえる」という意味になった。', NOW(), NOW()),('soar', '急上昇する', 'verb', '古フランス語「essorer（高く飛ぶ）」に由来し、「急上昇する、舞い上がる」という意味になった。', NOW(), NOW()),('distort', 'ゆがめる、歪曲する', 'verb', '"離れて"の「dis-」と"ねじる"の「torquere」が結合して「歪める」という意味になった。', NOW(), NOW()),('undermine', '弱体化させる、損なう', 'verb', '"下に"の「under-」と"掘る"の「mine」が結合して「弱体化させる、徐々に害する」という意味になった。', NOW(), NOW()),('abolish', '廃止する', 'verb', '"離れて"の「ab-」と"育てる、成長させる"の「olere」が結合して「廃止する」という意味になった。', NOW(), NOW()),('strip', '剥がす、取り除く／細長い部分', 'verb', '古英語「stripian（裸にする）」に由来し、「剥ぎ取る」という意味になった。', NOW(), NOW()),('dispose', '処分する', 'verb', '"離れて"の「dis-」と"置く"の「ponere」が結合して「処分する、配置する」という意味になった。', NOW(), NOW()),('dump', '捨てる／ゴミ捨て場', 'verb', '擬音語的起源で、「どさっと落とす、投棄する」という意味になった。', NOW(), NOW()),('weave', '織る、編む', 'verb', '古英語「wefan（織る）」に由来し、「織る、編む」という意味になった。', NOW(), NOW()),('refine', '洗練する、精製する', 'verb', '"再び"の「re-」と"終える、仕上げる"の「finire」が結合して「洗練する」という意味になった。', NOW(), NOW()),('enrich', '豊かにする、高める', 'verb', '"中に"の「en-」と"富"の「rich」が結合して「豊かにする」という意味になった。', NOW(), NOW()),('coordinate', '調整する、統合する', 'verb', '"共に"の「co-」と"秩序"の「ordinare」が結合して「調整する」という意味になった。', NOW(), NOW()),('remedy', '治療法、解決策', 'verb', '"再び"の「re-」と"癒す"の「mederi」が結合して「治療、改善策」という意味になった。', NOW(), NOW()),('patch', '部分、継ぎ／修理する', 'verb', '不明確な語源だが、17世紀ごろから「当て布、補修」という意味で使用されるようになった。', NOW(), NOW()),('triumph', '勝利、成功／勝利する', 'verb', 'ラテン語「triumphus（凱旋）」に由来し、「勝利」という意味になった。', NOW(), NOW()),('despite', '～にもかかわらず', 'preposition', 'ラテン語「despectus（軽蔑）」が語源で、「despite」は"〜にもかかわらず"という意味になった。', NOW(), NOW()),('via', '～を経由して、～によって', 'preposition', 'ラテン語「via（道）」に由来し、「〜を通じて、経由して」という意味になった。', NOW(), NOW()),('versus', '～対、～に対して', 'preposition', 'ラテン語「vertere（向かう）」の過去分詞「versus」から、「〜対、〜に対して」という意味になった。', NOW(), NOW()),('share', '共有する／分け前', 'noun', '古英語「scearu（分け前）」が語源で、「share」は"分け合う"という意味になった。', NOW(), NOW()),('store', '保管する／店', 'noun', 'ラテン語「instaurare（補充する）」が変化して、「store」は"蓄える"という意味になった。', NOW(), NOW()),('concern', '心配する／関心、懸念', 'noun', '共にの「con-」と"ふれる"の「cernere」が結合して"関係する"という意味になった。', NOW(), NOW()),('limit', '制限する／制限', 'noun', 'ラテン語「limes（境界）」が語源で、「limit」は"制限する"という意味になった。', NOW(), NOW()),('bear', '耐える、負担する', 'noun', '古英語「beran（運ぶ）」が語源で、「bear」は"耐える"や"産む"という意味になった。', NOW(), NOW()),('challenge', '挑戦する／挑戦', 'noun', 'ラテン語「calumnia（言いがかり）」が変化して、「challenge」は"挑戦"という意味になった。', NOW(), NOW()),('idea', 'アイデア、考え', 'noun', 'ギリシャ語「idéa（形・概念）」が語源で、「idea」は"考え"という意味になった。', NOW(), NOW()),('accord', '一致、合意／与える', 'noun', '〜への「ad-」と"心"の「cor」が結合して"一致する"という意味になった。', NOW(), NOW()),('company', '会社、仲間', 'noun', '共にの「com-」と"パンを食べる仲間"の「panis」が結合して"仲間・会社"という意味になった。', NOW(), NOW()),('reason', '理由', 'noun', '再びの「re-」と"計算する・考える"の「reri」が結合して"理由"という意味になった。', NOW(), NOW()),('effect', '効果、影響', 'noun', '外への「ex-」と"作る"の「facere」が結合して"結果"という意味になった。', NOW(), NOW()),('situation', '状況', 'noun', '位置を表すラテン語「situatio」が語源で、「situation」は"状況・位置"という意味になった。', NOW(), NOW()),('environment', '環境', 'noun', '周囲の「environ」＋名詞化接尾辞「-ment」が結合して"環境"という意味になった。', NOW(), NOW()),('skill', '技能、スキル', 'noun', '古ノルド語「skil（区別、知識）」が語源で、「skill」は"技能"という意味になった。', NOW(), NOW()),('matter', '事柄、問題／重要である', 'noun', 'ラテン語「materia（物質、素材）」が語源で、「matter」は"物質・問題"という意味になった。', NOW(), NOW()),('view', '眺め、見解／見る', 'noun', 'ラテン語「videre（見る）」が語源で、「view」は"見ること・景観・意見"という意味になった。', NOW(), NOW()),('species', '種（生物分類）', 'noun', 'ラテン語「species（外見・種類）」が語源で、「species」は"種・種類"という意味になった。', NOW(), NOW()),('knowledge', '知識', 'noun', '知るの「know」と名詞化接尾辞「-ledge」が結合して"知識"という意味になった。', NOW(), NOW()),('memory', '記憶', 'noun', 'ラテン語「memoria（記憶）」が語源で、「memory」は"記憶"という意味になった。', NOW(), NOW()),('benefit', '利益、恩恵／利益をもたらす', 'noun', '良いの「bene-」と"作る"の「facere」が結合して"利益"という意味になった。', NOW(), NOW()),('theory', '理論', 'noun', 'ギリシャ語「theoria（観察・考察）」が語源で、「theory」は"理論"という意味になった。', NOW(), NOW()),('issue', '問題、発行／発行する', 'noun', 'ラテン語「exire（出る）」が語源で、「issue」は"問題・発行物"という意味になった。', NOW(), NOW()),('experiment', '実験／実験する', 'noun', '外にの「ex-」と"試す"の「periri」が結合して"実験"という意味になった。', NOW(), NOW()),('article', '記事、論文', 'noun', 'ラテン語「articulus（小さな接続部、文）」が語源で、「article」は"記事・冠詞・品物"という意味になった。', NOW(), NOW()),('focus', '焦点、集中／集中する', 'noun', 'ラテン語「focus（炉・家庭）」が語源で、「focus」は"焦点"という意味になった。', NOW(), NOW()),('subject', '科目、主題', 'noun', '下にの「sub-」と"投げる"の「iacere」が結合して"主題・従属するもの"という意味になった。', NOW(), NOW()),('project', 'プロジェクト／計画する', 'noun', '前にの「pro-」と"投げる"の「iacere」が結合して"計画・企画・投影"という意味になった。', NOW(), NOW()),('quality', '質、品質', 'noun', 'ラテン語「qualitas（性質）」が語源で、「quality」は"品質"という意味になった。', NOW(), NOW()),('role', '役割', 'noun', 'フランス語「rôle（役割）」が語源で、「role」は"役割"という意味になった。', NOW(), NOW()),('term', '用語、期間', 'noun', 'ラテン語「terminus（終点、境界）」が語源で、「term」は"期間・用語・条件"という意味になった。', NOW(), NOW()),('statement', '声明、発言', 'noun', '述べるの「state」に名詞化接尾辞「-ment」が結合して"声明・陳述"という意味になった。', NOW(), NOW()),('material', '材料、資料', 'noun', 'ラテン語「materia（素材）」が語源で、「material」は"物質・材料"という意味になった。', NOW(), NOW()),('evidence', '証拠', 'noun', '外への「ex-」と"見る"の「videre」が結合して"証拠"という意味になった。', NOW(), NOW()),('source', '源、情報源', 'noun', 'ラテン語「surgere（湧き出る）」が変化して、「source」は"源・出所"という意味になった。', NOW(), NOW()),('community', '地域社会、共同体', 'noun', '共にの「com-」と"務める"の「munus」が結合して"共同体"という意味になった。', NOW(), NOW()),('technology', '技術', 'noun', 'ギリシャ語「techne（技術）」と「-logia（学）」が結合して"技術"という意味になった。', NOW(), NOW()),('culture', '文化', 'noun', 'ラテン語「colere（耕す）」が語源で、「culture」は"文化・教養"という意味になった。', NOW(), NOW()),('individual', '個人／個々の', 'noun', '分けての「in-」と"分割する"の「dividere」が結合して"個人"という意味になった。', NOW(), NOW()),('native', '母国の、先住の／母国語話者', 'noun', 'ラテン語「nativus（生まれた）」が語源で、「native」は"生まれつきの・先住の"という意味になった。', NOW(), NOW()),('wonder', '疑問に思う／驚き', 'noun', '古英語「wundor（驚き）」が語源で、「wonder」は"不思議に思う"という意味になった。', NOW(), NOW()),('opportunity', '機会、チャンス', 'noun', 'ラテン語「opportunitas（好機）」が語源で、「opportunity」は"機会"という意味になった。', NOW(), NOW()),('task', '任務、仕事', 'noun', '古ノルド語「taske（税・仕事）」が語源で、「task」は"仕事・任務"という意味になった。', NOW(), NOW()),('industry', '産業、工業', 'noun', '"内に"の「in-」と"努力する"の「struere」が結合して"産業・勤勉"という意味になった。', NOW(), NOW()),('medium', '手段、媒体', 'noun', 'ラテン語「medius（中間の）」が語源で、「medium」は"媒体・手段"という意味になった。', NOW(), NOW()),('economy', '経済', 'noun', 'ギリシャ語「oikonomia（家の管理）」が語源で、「economy」は"経済"という意味になった。', NOW(), NOW()),('policy', '政策、方針', 'noun', 'ギリシャ語「polis（都市国家）」が語源で、「policy」は"政策・方針"という意味になった。', NOW(), NOW()),('account', '口座、説明／説明する', 'noun', '"〜へ"の「ad-」と"数える"の「computare」が結合して"勘定・説明"という意味になった。', NOW(), NOW()),('model', '模型、手本', 'noun', 'ラテン語「modulus（小さな尺度）」が語源で、「model」は"模型・模範"という意味になった。', NOW(), NOW()),('cell', '細胞、携帯電話、独房', 'noun', 'ラテン語「cella（小部屋）」が語源で、「cell」は"細胞・小部屋"という意味になった。', NOW(), NOW()),('image', '画像、印象', 'noun', 'ラテン語「imago（像）」が語源で、「image」は"像・映像・イメージ"という意味になった。', NOW(), NOW()),('emotion', '感情', 'noun', '"外へ"の「e-」と"動かす"の「movere」が結合して"感情"という意味になった。', NOW(), NOW()),('decade', '10年間', 'noun', 'ギリシャ語「dekas（10）」が語源で、「decade」は"10年"という意味になった。', NOW(), NOW()),('range', '範囲／及ぶ', 'noun', '古フランス語「rangier（並べる）」が語源で、「range」は"範囲・並び"という意味になった。', NOW(), NOW()),('character', '性格、登場人物、文字', 'noun', 'ギリシャ語「kharaktēr（刻まれた印）」が語源で、「character」は"性格・文字"という意味になった。', NOW(), NOW()),('advantage', '利点、強み', 'noun', '"前に"の「ad-」と"来る"の「venire」が結合して"有利"という意味になった。', NOW(), NOW()),('phrase', '句、表現', 'noun', 'ギリシャ語「phrasis（言い回し）」が語源で、「phrase」は"句・表現"という意味になった。', NOW(), NOW()),('damage', '損害／損害を与える', 'noun', 'ラテン語「damnum（損害）」がフランス語を経て「damage」となり、"損害"という意味になった。', NOW(), NOW()),('impact', '影響、衝撃／影響を与える', 'noun', '"中に"の「im-」と"押し付ける"の「pangere」が結合して"衝撃・影響"という意味になった。', NOW(), NOW()),('method', '方法、手法', 'noun', '"後を"の「meta-」と"道"の「hodos」が結合して"方法"という意味になった。', NOW(), NOW()),('resource', '資源、手段', 'noun', '"再び"の「re-」と"湧き出る"の「surgere」が結合して"資源"という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'worsen'), 'シンプル', 'The situation has worsened over time.', 'その状況は時間とともに悪化した。', 'us_mvp_image_1334_worsen.webp', 'say-9495d2cd-e7053338-935ab848-ad9488dc-bedf3b77.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'flip'), 'シンプル', 'He flipped the pancake.', '彼はパンケーキを裏返した。', 'us_mvp_image_1335_flip.webp', 'say-207b51d2-12cc42e2-8a8dbd66-f01403b9-3d210135.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rub'), 'シンプル', 'She rubbed her hands together to keep warm.', '彼女は手をこすって温めた。', 'us_mvp_image_1336_rub.webp', 'say-047c7bc7-6bd7cf1b-4cde0da8-d7397cfc-ceddf062.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compensate'), 'シンプル', 'The company compensated him for the damage.', '会社は彼に損害を補償した。', 'us_mvp_image_1338_compensate.webp', 'say-2399a2e0-9875d6b5-3a114220-10ba0e09-0fa5ab53.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'comprise'), 'シンプル', 'The team comprises ten members.', 'そのチームは10人のメンバーで構成されている。', 'us_mvp_image_1339_comprise.webp', 'say-6783a2db-f916d8c1-ec276292-78029c04-c2169a69.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prevail'), 'シンプル', 'Justice will prevail in the end.', '最終的には正義が勝つだろう。', 'us_mvp_image_1340_prevail.webp', 'say-f8ffc2ae-f0c518ec-2947264e-536b32c0-a6cce4e0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'update'), 'シンプル', 'She updated the software on her computer.', '彼女はコンピュータのソフトウェアを更新した。', 'us_mvp_image_1401_update.webp', 'say-bc8917d0-ba42d135-47277c7e-99cf4ba9-3b13742b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'induce'), 'シンプル', 'The medicine may induce sleepiness.', 'その薬は眠気を引き起こす可能性がある。', 'us_mvp_image_1405_induce.webp', 'say-481d7bca-fc81926d-7e4a424b-f733726e-debb0495.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'attain'), 'シンプル', 'She finally attained her dream of becoming a doctor.', '彼女はついに医者になるという夢を達成した。', 'us_mvp_image_1406_attain.webp', 'say-94eaefcf-3b261098-a1397305-e6570b71-4c0b4226.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spray'), 'シンプル', 'She sprayed perfume on her wrist.', '彼女は手首に香水を吹きかけた。', 'us_mvp_image_1407_spray.webp', 'say-564c6c98-a364867e-87d3eb56-7c6d12a8-844b90bf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'retrieve'), 'シンプル', 'He retrieved the lost data from his computer.', '彼はコンピュータから失われたデータを回収した。', 'us_mvp_image_1408_retrieve.webp', 'say-a4c211d2-6b3fdc0f-ab5d1e53-dbcf33bc-48818e5a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'portray'), 'シンプル', 'The actor portrayed a brave hero in the movie.', 'その俳優は映画で勇敢なヒーローを演じた。', 'us_mvp_image_1409_portray.webp', 'say-8de222ac-62fba9f1-811a3679-3c868de6-88ad83d0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'designate'), 'シンプル', 'The area was designated as a national park.', 'その地域は国立公園に指定された。', 'us_mvp_image_1411_designate.webp', 'say-08ce763a-398204c9-f9a791ce-cf5aad27-0cec7be5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'contradict'), 'シンプル', 'His actions contradict his words.', '彼の行動は彼の言葉と矛盾している。', 'us_mvp_image_1412_contradict.webp', 'say-29e3aba9-1907b4e9-87ab7dc4-53144a40-fe3381d1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sigh'), 'シンプル', 'She sighed in relief.', '彼女は安心してため息をついた。', 'us_mvp_image_1413_sigh.webp', 'say-8bf6d053-009bb7e8-a80e9e6b-dace367b-f0e48f9e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disrupt'), 'シンプル', 'The protest disrupted traffic in the city.', 'その抗議活動は市内の交通を混乱させた。', 'us_mvp_image_1414_disrupt.webp', 'say-1ca2d9d5-46d9919e-bafb4e82-022709ab-82fcc506.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'depart'), 'シンプル', 'The train departs at 10 AM.', 'その列車は午前10時に出発する。', 'us_mvp_image_1415_depart.webp', 'say-b299fa2c-ffdb4c87-a7fd912a-ceee3699-d38bfdbe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'diagnose'), 'シンプル', 'The doctor diagnosed him with diabetes.', '医者は彼を糖尿病と診断した。', 'us_mvp_image_1419_diagnose.webp', 'say-90899acf-0077d395-d9f25eed-2cd4ebea-57ce60c3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'oblige'), 'シンプル', 'The law obliges companies to pay taxes.', 'その法律は企業に納税を義務付けている。', 'us_mvp_image_1421_oblige.webp', 'say-431c78c6-58d49412-090e44d7-f30a96f3-9bc36bcc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'underestimate'), 'シンプル', 'Don’t underestimate his abilities.', '彼の能力を過小評価しないで。', 'us_mvp_image_1424_underestimate.webp', 'say-785917bd-ecfc24a6-93ce9707-a983fa36-3d76aa2c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'clarify'), 'シンプル', 'Can you clarify your point?', 'あなたの主張をはっきりさせてもらえますか？', 'us_mvp_image_1425_clarify.webp', 'say-32aece9d-8422a96f-b297d7c8-0879e2a5-d5bbee37.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spark'), 'シンプル', 'The scandal sparked public outrage.', 'そのスキャンダルは国民の怒りを引き起こした。', 'us_mvp_image_1426_spark.webp', 'say-8d1ca287-b303587b-6c0a8940-e4099142-db0a3eb2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'seize'), 'シンプル', 'The police seized illegal drugs.', '警察は違法薬物を押収した。', 'us_mvp_image_1427_seize.webp', 'say-f5a3c04c-3a7f29de-df03d4c0-908a70c2-f3093140.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'soar'), 'シンプル', 'The prices of gas soared last month.', '先月、ガソリンの価格が急上昇した。', 'us_mvp_image_1428_soar.webp', 'say-dda5bfcb-05619ccb-3069f2c1-e199c1be-6f2c4d5f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'distort'), 'シンプル', 'The media distorted the facts.', 'メディアは事実を歪曲した。', 'us_mvp_image_1431_distort.webp', 'say-1a99e301-6053e1a2-9c540c15-c55217bf-9c524291.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'undermine'), 'シンプル', 'Corruption undermines trust in government.', '汚職は政府への信頼を損なう。', 'us_mvp_image_1432_undermine.webp', 'say-d97193ed-c66d56e1-a71742b3-0f9e190c-1b588fcb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'abolish'), 'シンプル', 'Slavery was abolished in the 19th century.', '奴隷制度は19世紀に廃止された。', 'us_