3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'challenge'), 'シンプル', 'This task is a big challenge.', 'この課題は大きな挑戦だ。', 'us_mvp_image_0035_challenge.webp', 'say-04f0b236-803e0b01-e36b2c49-4111326d-9882dc5c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'idea'), 'シンプル', 'That''s a great idea!', 'それは素晴らしいアイデアだ！', 'us_mvp_image_0041_idea.webp', 'say-db669ec0-78311b1e-f5a64109-0d5de1be-8d37dcdf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'accord'), 'シンプル', 'His words are in accord with his actions.', '彼の言葉は行動と一致している。', 'us_mvp_image_0042_accord.webp', 'say-c766f1a9-2e9096e9-5c461490-0046c00e-b1324fcc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'company'), 'シンプル', 'He works for a big company.', '彼は大企業で働いている。', 'us_mvp_image_0043_company.webp', 'say-cb508f78-cd54292d-ea21cf0b-48f23c00-b9c56f64.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reason'), 'シンプル', 'What is the reason for your absence?', 'あなたの欠席の理由は何ですか？', 'us_mvp_image_0047_reason.webp', 'say-ab134495-da347afb-d8ea5415-03403f00-3e3b6f6f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'effect'), 'シンプル', 'This medicine has strong effects.', 'この薬には強い効果がある。', 'us_mvp_image_0048_effect.webp', 'say-72aded8c-33bda4b3-b7203f22-e9cbde00-b44b4a0e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'situation'), 'シンプル', 'The situation is getting worse.', '状況は悪化している。', 'us_mvp_image_0050_situation.webp', 'say-1d410454-98980eaf-8a9972b7-55d3e752-b9f88f55.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'environment'), 'シンプル', 'We must protect the environment.', '私たちは環境を守らなければならない。', 'us_mvp_image_0051_environment.webp', 'say-923c2355-28033d5a-d5eda688-e22c5746-b5b6b8a5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'skill'), 'シンプル', 'Good communication skills are important.', '良いコミュニケーション能力は重要だ。', 'us_mvp_image_0052_skill.webp', 'say-38d99243-d2f09d76-9a7fa9c7-c4b7b86e-4b6d1387.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'matter'), 'シンプル', 'Money doesn’t matter to me.', '私にとってお金は重要ではない。', 'us_mvp_image_0053_matter.webp', 'say-79fb2b27-ecee7625-e860d3d7-ae1362d6-5a29cfae.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'view'), 'シンプル', 'She has a different view on the issue.', '彼女はその問題について異なる見解を持っている。', 'us_mvp_image_0054_view.webp', 'say-1c298269-6f824dd0-9e994ce4-6572aa20-9834e6d3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'species'), 'シンプル', 'Many species are endangered.', '多くの種が絶滅の危機に瀕している。', 'us_mvp_image_0056_species.webp', 'say-1cb47b77-a1c00529-9317bd98-aa71f684-6a395b4f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'knowledge'), 'シンプル', 'His knowledge of history is impressive.', '彼の歴史の知識は素晴らしい。', 'us_mvp_image_0058_knowledge.webp', 'say-012c998a-7af93017-99803c26-b3966e01-08a91d19.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'memory'), 'シンプル', 'I have a good memory for faces.', '私は顔を覚えるのが得意だ。', 'us_mvp_image_0059_memory.webp', 'say-908e11d5-80d41631-9b11bc59-bd96abcc-4f339de1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'benefit'), 'シンプル', 'Exercise has many benefits.', '運動には多くの利点がある。', 'us_mvp_image_0061_benefit.webp', 'say-cf0058d0-69d2d6ef-ce70b2f8-a14e619b-6512f7a9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'theory'), 'シンプル', 'His theory is difficult to prove.', '彼の理論は証明が難しい。', 'us_mvp_image_0062_theory.webp', 'say-226e875b-056737ba-27cf37d9-5a5a1b19-92a6246f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'issue'), 'シンプル', 'Climate change is a serious issue.', '気候変動は深刻な問題だ。', 'us_mvp_image_0063_issue.webp', 'say-a4561ea7-2013351b-871b981e-d8c93ee6-17ce0f47.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'experiment'), 'シンプル', 'The scientist conducted an experiment.', 'その科学者は実験を行った。', 'us_mvp_image_0064_experiment.webp', 'say-686c2ab0-35201384-aa2904ad-22ad80d5-5d411dec.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'article'), 'シンプル', 'I read an interesting article today.', '今日、興味深い記事を読んだ。', 'us_mvp_image_0065_article.webp', 'say-b8a9bc23-6bf119d6-43a7eeb0-3a3de440-fcb889c3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'focus'), 'シンプル', 'You should focus on your studies.', '勉強に集中するべきだ。', 'us_mvp_image_0066_focus.webp', 'say-5886c4fd-a51f3e31-865ad431-fe347b89-c2162277.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'subject'), 'シンプル', 'Math is my favorite subject.', '数学は私の好きな科目だ。', 'us_mvp_image_0067_subject.webp', 'say-bd9d7692-cfeb2a43-d97f3fbd-ba3c5ac4-2ab63047.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'project'), 'シンプル', 'We are working on a new project.', '私たちは新しいプロジェクトに取り組んでいる。', 'us_mvp_image_0068_project.webp', 'say-8b00e1f2-3ce832b5-cb8488f9-330c50bb-438a8fd9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'quality'), 'シンプル', 'This product has high quality.', 'この製品は品質が高い。', 'us_mvp_image_0069_quality.webp', 'say-965eae1c-240e390b-4f0f0436-9ded3c90-39eedfc6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'role'), 'シンプル', 'She plays an important role in the team.', '彼女はチームで重要な役割を果たしている。', 'us_mvp_image_0070_role.webp', 'say-6267e6fc-391ee05f-ecfee30b-fd951021-61392e44.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'term'), 'シンプル', 'This term is commonly used in science.', 'この用語は科学でよく使われる。', 'us_mvp_image_0071_term.webp', 'say-0889b170-e7034d81-ff238680-6e08cc2b-f798e2a6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'statement'), 'シンプル', 'His statement was very clear.', '彼の発言はとても明確だった。', 'us_mvp_image_0072_statement.webp', 'say-86232615-df46f81f-b6dc08e8-70371d73-66825ec1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'material'), 'シンプル', 'This book is good material for learning.', 'この本は学習に良い資料だ。', 'us_mvp_image_0073_material.webp', 'say-d7128b03-551df92e-0f502909-427c857c-c86158ee.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'evidence'), 'シンプル', 'There is no evidence to support his claim.', '彼の主張を裏付ける証拠はない。', 'us_mvp_image_0074_evidence.webp', 'say-a2ea54ac-8f11aeca-ddc2c8c3-e7c30dd1-39ee611e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'source'), 'シンプル', 'Always check the source of the information.', '情報の出所を必ず確認しなさい。', 'us_mvp_image_0075_source.webp', 'say-785c91e0-7d178e58-7175fc68-2913a3e5-7f7a0797.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'community'), 'シンプル', 'This is a close-knit community.', 'これは結束の強い共同体だ。', 'us_mvp_image_0076_community.webp', 'say-6ba88ac3-3f0d0988-8ccfe284-eb2b0a92-00033add.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'technology'), 'シンプル', 'Modern technology is advancing rapidly.', '現代の技術は急速に進歩している。', 'us_mvp_image_0077_technology.webp', 'say-b485fa9c-7c7dcde8-c67adde2-fe2f0a89-9317b301.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'culture'), 'シンプル', 'Japanese culture is fascinating.', '日本の文化は魅力的だ。', 'us_mvp_image_0078_culture.webp', 'say-a7ce5b62-70256557-d3d0eb72-bf853990-6f67c402.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'individual'), 'シンプル', 'Each individual has different needs.', '各個人には異なるニーズがある。', 'us_mvp_image_0082_individual.webp', 'say-ede345d1-d9743712-0c8c403c-c19b6619-63a805a0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'native'), 'シンプル', 'She is a native speaker of English.', '彼女は英語のネイティブスピーカーだ。', 'us_mvp_image_0094_native.webp', 'say-68246464-5acba0e9-00f0996a-fff12357-e50e2291.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'wonder'), 'シンプル', 'I wonder if he will come.', '彼が来るかどうか疑問に思う。', 'us_mvp_image_0104_wonder.webp', 'say-082211ba-19458bd2-3bc14e5d-b51af547-5fa45b91.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'opportunity'), 'シンプル', 'This is a great opportunity.', 'これは素晴らしい機会だ。', 'us_mvp_image_0141_opportunity.webp', 'say-82b62b5f-966b3034-c4a045c4-9ca20e52-d71235b0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'task'), 'シンプル', 'My task is to complete this report.', '私の任務はこの報告書を完成させることだ。', 'us_mvp_image_0142_task.webp', 'say-38e29020-3aeda889-65df082b-25cd4e56-a1564eb8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'industry'), 'シンプル', 'The car industry is growing.', '自動車産業は成長している。', 'us_mvp_image_0143_industry.webp', 'say-4d034d6b-c42e3547-f147eac7-2c9dd517-ff10f9ec.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'medium'), 'シンプル', 'TV is a powerful medium.', 'テレビは強力なメディアだ。', 'us_mvp_image_0144_medium.webp', 'say-127599f9-7ee139b7-4bede559-4560847f-dd8c45f9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'economy'), 'シンプル', 'The global economy is recovering.', '世界経済は回復している。', 'us_mvp_image_0145_economy.webp', 'say-e2470471-f31c6715-0d791568-a07d67bc-37e1daf6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'policy'), 'シンプル', 'The government announced a new policy.', '政府は新しい政策を発表した。', 'us_mvp_image_0146_policy.webp', 'say-86166d5c-40b90ce1-b3044462-33e592a2-9b22fbad.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'account'), 'シンプル', 'I opened a bank account.', '私は銀行口座を開設した。', 'us_mvp_image_0147_account.webp', 'say-926bd9b9-b2383931-727d77f9-9e6d16b9-2b5af1fc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'model'), 'シンプル', 'She is a fashion model.', '彼女はファッションモデルだ。', 'us_mvp_image_0149_model.webp', 'say-bb017624-262f6d03-77b1adce-15d1682b-032ad687.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cell'), 'シンプル', 'The human body is made of millions of cells.', '人体は何百万もの細胞でできている。', 'us_mvp_image_0151_cell.webp', 'say-0145fe06-13b6e134-e0e6c3d5-511dfb61-3f7a8b95.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'image'), 'シンプル', 'The image quality is very high.', 'その画像の品質は非常に高い。', 'us_mvp_image_0152_image.webp', 'say-64e95374-38e01b88-0515ff57-edee5ad9-3bc8255a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'emotion'), 'シンプル', 'She couldn''t hide her emotions.', '彼女は感情を隠せなかった。', 'us_mvp_image_0153_emotion.webp', 'say-b45e5951-11a59765-5eef5165-13a198f4-ce405153.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'decade'), 'シンプル', 'He has been a teacher for a decade.', '彼は教師を10年間続けている。', 'us_mvp_image_0155_decade.webp', 'say-02641980-15d79ab6-0ce966d0-0e14beed-b45dd221.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'range'), 'シンプル', 'This store offers a wide range of products.', 'この店は幅広い商品を提供している。', 'us_mvp_image_0156_range.webp', 'say-29d4c847-125a5312-e370df51-c9c6358b-cf91f8a2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'character'), 'シンプル', 'He is a main character in the movie.', '彼はその映画の主要な登場人物だ。', 'us_mvp_image_0157_character.webp', 'say-910ee3ee-a1a6acaa-ec3eea0e-cbd10bea-a91e16eb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'advantage'), 'シンプル', 'Speaking English is an advantage.', '英語を話せることは利点だ。', 'us_mvp_image_0158_advantage.webp', 'say-e4371133-14536350-e70c348b-6c2a5766-3e2ee79e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'phrase'), 'シンプル', 'This phrase is commonly used.', 'この表現はよく使われる。', 'us_mvp_image_0159_phrase.webp', 'say-e2499c37-f7e97741-52092e4c-5d4bc23b-eb695174.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'damage'), 'シンプル', 'The storm caused serious damage.', 'その嵐は深刻な被害をもたらした。', 'us_mvp_image_0160_damage.webp', 'say-25776831-60ac0240-fdfa4d4c-38cf2e15-076dee19.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'impact'), 'シンプル', 'Technology has a big impact on society.', '技術は社会に大きな影響を与える。', 'us_mvp_image_0161_impact.webp', 'say-fc8f9f8e-0e42d114-376caafb-52bb8ec0-23c207a3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'method'), 'シンプル', 'This is an effective method.', 'これは効果的な方法だ。', 'us_mvp_image_0162_method.webp', 'say-f7337205-fbd97a28-10a087da-d93c644f-08d1473e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'resource'), 'シンプル', 'Water is an important natural resource.', '水は重要な天然資源だ。', 'us_mvp_image_0163_resource.webp', 'say-fca62bb3-a792d5b6-1240337a-08312b1e-aa7518cb.mp3', NOW(), NOW());
