INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('laboratory', '研究室、実験室', 'noun', 'ラテン語「laboratorium（労働の場所）」が語源で、「実験室」という意味になった。', NOW(), NOW()),('presence', '存在、出席', 'noun', '「前に」の「prae-」と「ある」の「esse」が結合して「存在・出席」という意味になった。', NOW(), NOW()),('confidence', '自信、信頼', 'noun', '「共に」の「con-」と「信じる」の「fidere」が結合して「信頼」という意味になった。', NOW(), NOW()),('instrument', '楽器、道具', 'noun', '「中に」の「in-」と「築く」の「struere」が結合して「道具」という意味になった。', NOW(), NOW()),('category', '範疇、カテゴリー', 'noun', 'ギリシャ語「katēgoria（分類）」が語源で、「範疇」という意味になった。', NOW(), NOW()),('outcome', '結果', 'noun', '「外へ」の「out」＋「来る」の「come」が結合して「結果」という意味になった。', NOW(), NOW()),('notion', '概念、考え', 'noun', 'ラテン語「notio（知識・考え）」が語源で、「概念・意見」という意味になった。', NOW(), NOW()),('trait', '特徴、特性', 'noun', 'ラテン語「tractus（引くこと）」が語源で、「特性」という意味になった。', NOW(), NOW()),('diversity', '多様性', 'noun', '「離れて」の「dis-」と「向きを変える」の「vertere」が結合して「多様性」という意味になった。', NOW(), NOW()),('victim', '犠牲者、被害者', 'noun', 'ラテン語「victima（犠牲）」が語源で、「犠牲者」という意味になった。', NOW(), NOW()),('occasion', '機会、特別な行事', 'noun', '「〜の方へ」の「ob-」と「落ちる」の「cadere」が結合して「出来事」という意味になった。', NOW(), NOW()),('facility', '施設、設備', 'noun', '「容易な」の「facilis」と名詞化の接尾辞「-ity」が結合して「設備・施設」という意味になった。', NOW(), NOW()),('stock', '在庫、株／仕入れる', 'noun', '古英語「stocc（丸太・幹）」が語源で、「在庫・株」という意味になった。', NOW(), NOW()),('conference', '会議', 'noun', '「共に」の「con-」と「持つ」の「ferre」が結合して「会議」という意味になった。', NOW(), NOW()),('dialect', '方言', 'noun', '「分ける」の「dia-」と「話す」の「legein」が結合して「方言」という意味になった。', NOW(), NOW()),('proportion', '割合、比率', 'noun', '「前に」の「pro-」と「部分」の「portio」が結合して「比率」という意味になった。', NOW(), NOW()),('tip', '助言、先端／傾ける', 'noun', '中英語「tippen（傾ける）」が語源で、「先端・助言・チップ」という意味になった。', NOW(), NOW()),('lawyer', '弁護士', 'noun', '「法」の「law」に「〜する人」の「-er」が結合して「法律家」という意味になった。', NOW(), NOW()),('stuff', 'もの、詰め込む', 'noun', '古フランス語「estoffer（詰める）」が語源で、「物・詰め物」という意味になった。', NOW(), NOW()),('comfort', '快適さ、慰め／慰める', 'noun', '「共に」の「com-」と「強める」の「fortis」が結合して「快適さ・慰め」という意味になった。', NOW(), NOW()),('philosophy', '哲学、考え方', 'noun', '「愛する」の「philo-」と「知恵」の「sophia」が結合して「哲学」という意味になった。', NOW(), NOW()),('quantity', '量、数量', 'noun', 'ラテン語「quantus（どれだけ）」が語源で、「量」という意味になった。', NOW(), NOW()),('landscape', '風景、景色', 'noun', 'オランダ語「landschap（土地の景色）」が語源で、「風景」という意味になった。', NOW(), NOW()),('tribe', '部族', 'noun', 'ラテン語「tribus（部族）」が語源で、「部族」という意味になった。', NOW(), NOW()),('organ', '器官、臓器', 'noun', 'ギリシャ語「organon（道具）」が語源で、「器官・オルガン」という意味になった。', NOW(), NOW()),('trial', '試験、裁判', 'noun', 'ラテン語「triare（試す）」が語源で、「裁判・試み」という意味になった。', NOW(), NOW()),('norm', '規範、標準', 'noun', 'ラテン語「norma（規準）」が語源で、「基準・規範」という意味になった。', NOW(), NOW()),('code', '規則、暗号', 'noun', 'ラテン語「codex（法典・帳簿）」が語源で、「規則・暗号」という意味になった。', NOW(), NOW()),('substance', '物質、内容', 'noun', '「下に」の「sub-」と「立つ」の「stare」が結合して「物質・実体」という意味になった。', NOW(), NOW()),('unknown', '未知の', 'noun', '「否定」の「un-」と「知る」の「know」が結合して「未知の」という意味になった。', NOW(), NOW()),('superior', '優れた、上位の', 'noun', '「上に」の「super-」と比較級の「-ior」が結合して「優れた」という意味になった。', NOW(), NOW()),('credit', '信用、名誉／認める', 'noun', '「信じる」の「credere」が語源で、「信用・信用する」という意味になった。', NOW(), NOW()),('cure', '治療する／治療法', 'noun', 'ラテン語「curare（世話をする）」が語源で、「治療する」という意味になった。', NOW(), NOW()),('insight', '洞察、見識', 'noun', '「中に」の「in-」と「見る」の「sight」が結合して「洞察」という意味になった。', NOW(), NOW()),('innovation', '革新、新技術', 'noun', '「中へ」の「in-」と「新しい」の「novus」が結合して「革新」という意味になった。', NOW(), NOW()),('budget', '予算／予算を立てる', 'noun', 'ラテン語「bulga（財布）」が語源で、「予算」という意味になった。', NOW(), NOW()),('fee', '料金、手数料', 'noun', '古英語「feo（報酬）」が語源で、「料金」という意味になった。', NOW(), NOW()),('expense', '費用、出費', 'noun', '「外へ」の「ex-」と「支払う」の「pendere」が結合して「費用」という意味になった。', NOW(), NOW()),('debt', '借金、負債', 'noun', 'ラテン語「debere（借りがある）」が語源で、「借金」という意味になった。', NOW(), NOW()),('loan', '貸付／貸し付ける', 'noun', '古ノルド語「lán（貸し）」が語源で、「貸付」という意味になった。', NOW(), NOW()),('duty', '義務、職務', 'noun', 'ラテン語「debitum（義務）」が語源で、「義務・職務」という意味になった。', NOW(), NOW()),('alarm', '警報、驚き／警戒させる', 'noun', 'ラテン語「alarma（武器を取れ）」が語源で、「警報」という意味になった。', NOW(), NOW()),('emergency', '緊急事態', 'noun', '「外へ」の「ex-」と「出現する」の「mergere」が結合して「緊急事態」という意味になった。', NOW(), NOW()),('democracy', '民主主義', 'noun', 'ギリシャ語「demos（民衆）」と「kratos（支配）」が結合して「民主主義」という意味になった。', NOW(), NOW()),('minister', '大臣、牧師', 'noun', 'ラテン語「minister（従者、奉仕者）」が語源で、「大臣・牧師」という意味になった。', NOW(), NOW()),('fellow', '仲間／同僚の', 'noun', '古ノルド語「felagi（仲間）」が語源で、「仲間・同僚」という意味になった。', NOW(), NOW()),('candidate', '候補者', 'noun', 'ラテン語「candidatus（白い服を着た人）」が語源で、「候補者」という意味になった。', NOW(), NOW()),('corporation', '企業、法人', 'noun', '「共に」の「com-」と「体」の「corpus」が結合して「法人・会社」という意味になった。', NOW(), NOW()),('stereotype', '典型的なイメージ／固定観念を持つ', 'noun', '「固い」の「stereos」と「型」の「typos」が結合して「固定観念」という意味になった。', NOW(), NOW()),('route', '道、経路', 'noun', 'ラテン語「rupta（道が開かれたもの）」が語源で、「道・経路」という意味になった。', NOW(), NOW()),('disorder', '障害、混乱', 'noun', '「否定」の「dis-」と「秩序」の「order」が結合して「混乱」という意味になった。', NOW(), NOW()),('depression', 'うつ病、不況', 'noun', '「下に」の「de-」と「押す」の「primere」が結合して「うつ病・不況」という意味になった。', NOW(), NOW()),('weapon', '武器', 'noun', '古英語「wǣpen（武器）」が語源で、「武器」という意味になった。', NOW(), NOW()),('immigration', '移民、移住', 'noun', '「中に」の「in-」と「移動する」の「migrare」が結合して「移民」という意味になった。', NOW(), NOW()),('barrier', '障壁、壁', 'noun', '古フランス語「barriere（柵）」が語源で、「障壁」という意味になった。', NOW(), NOW()),('disadvantage', '不利、不都合', 'noun', '「否定」の「dis-」と「有利なこと」の「advantage」が結合して「不利」という意味になった。', NOW(), NOW()),('mood', '気分、雰囲気', 'noun', '古英語「mod（心、精神）」が語源で、「気分・感情」という意味になった。', NOW(), NOW()),('motion', '動き、提案', 'noun', 'ラテン語「motio（動き）」が語源で、「動き・運動」という意味になった。', NOW(), NOW()),('routine', '日課、決まりきった／定例の', 'noun', 'フランス語「route（道）」が語源で、「日課・決まりきった手順」という意味になった。', NOW(), NOW()),('discipline', '規律、訓練／しつける', 'noun', 'ラテン語「disciplina（訓練）」が語源で、「規律・訓練」という意味になった。', NOW(), NOW()),('myth', '神話、作り話', 'noun', 'ギリシャ語「mythos（物語）」が語源で、「神話」という意味になった。', NOW(), NOW()),('hypothesis', '仮説', 'noun', '「下に」の「hypo-」と「置く」の「thesis」が結合して「仮説」という意味になった。', NOW(), NOW()),('physician', '医師', 'noun', 'ギリシャ語「physis（自然）」と「学者」の「-ician」が結合して「医師」という意味になった。', NOW(), NOW()),('client', '顧客、依頼人', 'noun', 'ラテン語「clinare（頼る、訴える）」が語源で、「依頼人・顧客」という意味になった。', NOW(), NOW()),('colony', '植民地、群れ', 'noun', '「耕す人々」の「colonus」から派生し、「植民地」という意味になった。', NOW(), NOW()),('statistics', '統計', 'noun', 'ラテン語「status（状態）」が語源で、「統計」という意味になった。', NOW(), NOW()),('grain', '穀物、粒', 'noun', 'ラテン語「granum（種子）」が語源で、「穀物」という意味になった。', NOW(), NOW()),('ingredient', '材料、成分', 'noun', '「中に」の「in-」と「進む」の「gradus」が結合して「材料」という意味になった。', NOW(), NOW()),('contract', '契約／契約する、縮む', 'noun', '「共に」の「con-」と「引く」の「trahere」が結合して「契約」という意味になった。', NOW(), NOW()),('welfare', '福祉、幸福', 'noun', '「よくあること」の「well」と「fare（進む）」が結合して「福祉」という意味になった。', NOW(), NOW()),('alien', '異質の、外国の／宇宙人', 'noun', '"他の"の意味のラテン語「alius」に由来し、「外国の、異質な」という意味になった。', NOW(), NOW()),('puzzle', '困惑させる／パズル', 'noun', 'ラテン語「pusle（混乱）」に由来し、「困惑させる、謎」という意味になった。', NOW(), NOW()),('monitor', '監視する／モニター', 'noun', 'ラテン語「monere（警告する）」に由来し、「監視する、モニターする」という意味になった。', NOW(), NOW()),('ease', '和らげる／容易さ', 'noun', '古フランス語「aisier（楽にする）」に由来し、「楽にする、軽減する」という意味になった。', NOW(), NOW()),('sequence', '順序、連続', 'noun', '"後に続く"の意味のラテン語「sequi」に由来し、「連続、順序」という意味になった。', NOW(), NOW()),('therapy', '治療、療法', 'noun', '"治療"の意味のギリシア語「therapeia」に由来し、「治療、療法」という意味になった。', NOW(), NOW()),('symptom', '症状、兆候', 'noun', '"共に"の「sym-」と"落ちる、起こる"の「piptein」が結合して「一緒に現れるもの」→「症状」という意味になった。', NOW(), NOW()),('incident', '出来事、事件', 'noun', '"中に"の「in-」と"落ちる"の「cadere」が結合して「（中に）起こること」→「出来事、事件」という意味になった。', NOW(), NOW()),('witness', '目撃者／目撃する', 'noun', '古英語「witness（証人）」に由来し、「見る者、証言者」という意味になった。', NOW(), NOW()),('sum', '合計、要約／合計する', 'noun', 'ラテン語「summa（総計、最上）」に由来し、「合計、総額」という意味になった。', NOW(), NOW()),('tone', '口調、音色', 'noun', '"音"の意味のギリシア語「tonos（張る、調子）」に由来し、「音調、語調」という意味になった。', NOW(), NOW()),('honor', '名誉／称える', 'noun', 'ラテン語「honor（名誉）」に由来し、「名誉、敬意」という意味になった。', NOW(), NOW()),('priority', '優先事項', 'noun', 'ラテン語「prior（前の）」に由来し、「優先、重要事項」という意味になった。', NOW(), NOW()),('logic', '論理、道理', 'noun', '"言葉、理性"の意味のギリシア語「logos」に由来し、「論理、論法」という意味になった。', NOW(), NOW()),('minimum', '最小限／最小の', 'noun', 'ラテン語「minimus（最小）」に由来し、「最小限」という意味になった。', NOW(), NOW()),('exception', '例外', 'noun', '"外に"の「ex-」と"取る"の「capere」が結合して「取り除かれたもの」→「例外」という意味になった。', NOW(), NOW()),('clue', '手がかり、ヒント', 'noun', '古英語「clew（糸玉）」が「手がかり」の比喩となり、「ヒント、手がかり」という意味になった。', NOW(), NOW()),('virus', 'ウイルス', 'noun', 'ラテン語「virus（毒液）」に由来し、「ウイルス、病原体」という意味になった。', NOW(), NOW()),('surgery', '手術', 'noun', 'ギリシア語「cheir（手）」＋「ergon（働き）」に由来し、「手術、外科」という意味になった。', NOW(), NOW()),('insurance', '保険', 'noun', '"安全"の意味のラテン語「securus」に由来するフランス語「assurance」から派生し、「保険、保証」という意味になった。', NOW(), NOW()),('frame', '枠、骨組み／組み立てる', 'noun', '古英語「framian（形成する）」に由来し、「枠、骨組み」という意味になった。', NOW(), NOW()),('shelter', '避難所、住居／保護する', 'noun', '中英語「sheltron（盾の集団）」に由来し、「避難所、保護」という意味になった。', NOW(), NOW()),('territory', '領土、縄張り', 'noun', '"土地"の意味のラテン語「terra」と接尾辞「-orium」が結合して「領土」という意味になった。', NOW(), NOW()),('boundary', '境界、限界', 'noun', '「境界」を意味するラテン語「bodina」または中期英語「bound」に由来し、「境界」という意味になった。', NOW(), NOW()),('habitat', '生息地', 'noun', 'ラテン語「habitare（住む）」に由来し、「生息地」という意味になった。', NOW(), NOW()),('district', '地区、区域', 'noun', '"離れて"の「dis-」と"引く"の「trahere」が結合して「引き離された区域」→「地区」という意味になった。', NOW(), NOW()),('conservation', '保護、保存', 'noun', '"共に"の「con-」と"保つ"の「servare」が結合して「保存、保護」という意味になった。', NOW(), NOW()),('harvest', '収穫／収穫する', 'noun', '古英語「hærfest（秋、収穫期）」に由来し、「収穫」という意味になった。', NOW(), NOW()),('predator', '捕食者', 'noun', '"前もって"の「prae-」と"獲る"の「dari」が結合して「狩る者」→「捕食者」という意味になった。', NOW(), NOW()),('trap', '罠／閉じ込める', 'noun', '北欧古語「trappe（踏む装置）」に由来し、「罠」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'laboratory'), 'シンプル', 'He works in a laboratory.', '彼は研究室で働いている。', 'us_mvp_image_0445_laboratory.webp', 'say-6f8bdb31-6527f734-09114540-218a64b4-21e46c92.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'presence'), 'シンプル', 'His presence made a big difference.', '彼の存在が大きな違いを生んだ。', 'us_mvp_image_0446_presence.webp', 'say-4ed63cf5-27f0a476-5e98f406-7db1abac-007bbefc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'confidence'), 'シンプル', 'She spoke with confidence.', '彼女は自信を持って話した。', 'us_mvp_image_0447_confidence.webp', 'say-cfd9ccb2-cdf14575-5e3c639c-d10d1400-4eef6336.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'instrument'), 'シンプル', 'He plays a musical instrument.', '彼は楽器を演奏する。', 'us_mvp_image_0449_instrument.webp', 'say-7351c46c-2937bded-2a788c14-84f99ffd-bf61c19d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'category'), 'シンプル', 'This book belongs to the fiction category.', 'この本はフィクションのカテゴリーに属する。', 'us_mvp_image_0450_category.webp', 'say-8162b1b5-0dfd2068-d5323717-181cf0cf-77b7a93c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'outcome'), 'シンプル', 'The outcome of the experiment was surprising.', 'その実験の結果は驚くべきものだった。', 'us_mvp_image_0452_outcome.webp', 'say-365c7a03-28de7d8d-990c8e16-f1957052-62627bbc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'notion'), 'シンプル', 'He had a wrong notion about the law.', '彼は法律について誤った概念を持っていた。', 'us_mvp_image_0453_notion.webp', 'say-dd496723-3ca492b5-7773add5-289b3e4c-621df821.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trait'), 'シンプル', 'Honesty is an important trait.', '正直さは重要な特性だ。', 'us_mvp_image_0455_trait.webp', 'say-35393777-8722ee1e-819b55cb-eb2b968c-226186c3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'diversity'), 'シンプル', 'Cultural diversity is valuable.', '文化の多様性は貴重だ。', 'us_mvp_image_0456_diversity.webp', 'say-426aab0e-b819b6e9-4087cb7d-5e7ffe93-cb3629d1.mp3', NOW(),