, 'say-75b3027d-ee8d3f8e-1f3cb968-fdf409c4-5196f82b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disadvantage'), 'シンプル', 'Being late is a disadvantage in exams.', '試験で遅れることは不利だ。', 'us_mvp_image_0563_disadvantage.webp', 'say-3c7896f1-e5c7719a-83fff6e6-da2553dd-0caab812.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mood'), 'シンプル', 'She is in a good mood today.', '彼女は今日は機嫌がいい。', 'us_mvp_image_0564_mood.webp', 'say-860ef585-3607076b-d852c1ee-a1017e4e-fc466acf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'motion'), 'シンプル', 'The car was in motion.', '車は動いていた。', 'us_mvp_image_0565_motion.webp', 'say-350bd8a2-dbfccebb-52666a2d-aab4ec85-dd44f7b2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'routine'), 'シンプル', 'Exercise is part of my daily routine.', '運動は私の日課の一部だ。', 'us_mvp_image_0566_routine.webp', 'say-d9257316-278ad115-77469001-26d88f0b-cc0c516c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'discipline'), 'シンプル', 'Good discipline is important in school.', '学校では良い規律が重要だ。', 'us_mvp_image_0567_discipline.webp', 'say-996c629d-f52846e3-5966ef85-36486cf8-36f67e8c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'myth'), 'シンプル', 'The story is just a myth.', 'その話は単なる作り話だ。', 'us_mvp_image_0568_myth.webp', 'say-146e51c6-d7fbbe8b-08648154-f0bb47c6-124c69de.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'hypothesis'), 'シンプル', 'The scientist tested his hypothesis.', 'その科学者は仮説を検証した。', 'us_mvp_image_0569_hypothesis.webp', 'say-283582e0-641f3abe-33c3b4fb-380c7535-f1ab0793.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'physician'), 'シンプル', 'He is a physician at the hospital.', '彼はその病院の医師だ。', 'us_mvp_image_0570_physician.webp', 'say-01bf1b4e-205d5887-6fd39032-aa2bcc53-a69da538.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'client'), 'シンプル', 'The lawyer met with a client.', '弁護士は依頼人と会った。', 'us_mvp_image_0571_client.webp', 'say-98211bb6-df4b5441-f248c519-cbf812cd-d983b772.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'colony'), 'シンプル', 'India was once a British colony.', 'インドはかつてイギリスの植民地だった。', 'us_mvp_image_0572_colony.webp', 'say-f9fdc0df-0e49e9d6-037d8b60-ac820605-cde9de7a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'statistics'), 'シンプル', 'The report includes important statistics.', 'その報告には重要な統計が含まれている。', 'us_mvp_image_0573_statistics.webp', 'say-b9b25c48-20db64c0-deaf86cb-50f96d8c-03fd1373.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'grain'), 'シンプル', 'The field is full of grain.', 'その畑は穀物でいっぱいだ。', 'us_mvp_image_0574_grain.webp', 'say-b8a0136c-61f7621f-50c971d4-104a1125-9cfed8ed.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ingredient'), 'シンプル', 'Sugar is a key ingredient in cake.', '砂糖はケーキの主要な材料だ。', 'us_mvp_image_0575_ingredient.webp', 'say-d4fc7cba-74bfa254-5fbc8c49-308a6bd0-4f67b0fe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'contract'), 'シンプル', 'He signed a business contract.', '彼はビジネス契約に署名した。', 'us_mvp_image_0577_contract.webp', 'say-6e195027-2e077adf-c43f71ae-960c3849-1ef349e5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'welfare'), 'シンプル', 'The government focuses on public welfare.', '政府は公共福祉に力を入れている。', 'us_mvp_image_0578_welfare.webp', 'say-5e30cddd-fcf2bd75-59184eb0-f87f6f81-86311971.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'alien'), 'シンプル', 'The culture felt alien to me.', 'その文化は私には異質に感じられた。', 'us_mvp_image_0596_alien.webp', 'say-f9f9354d-82292dc0-a7c079b3-5f08a104-cac6e3c5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'puzzle'), 'シンプル', 'His words puzzled me.', '彼の言葉は私を困惑させた。', 'us_mvp_image_0624_puzzle.webp', 'say-901fb045-64a312b1-94ac137d-d68e02f6-fa8a8ad5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'monitor'), 'シンプル', 'The doctor monitors the patient’s condition.', '医者は患者の状態を監視している。', 'us_mvp_image_0636_monitor.webp', 'say-aa9c6077-a268f27f-9a65ffea-487a924d-ad6cd420.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ease'), 'シンプル', 'The medicine eased my pain.', 'その薬は私の痛みを和らげた。', 'us_mvp_image_0639_ease.webp', 'say-8bfcd83b-ffb9a2fa-18a0797c-449c720a-91b56eec.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sequence'), 'シンプル', 'The story follows a logical sequence.', 'その物語は論理的な順序で進む。', 'us_mvp_image_0641_sequence.webp', 'say-0faadb3d-8345e92e-86e16cb8-5a06b4b1-cbffdcb7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'therapy'), 'シンプル', 'He is undergoing physical therapy.', '彼は理学療法を受けている。', 'us_mvp_image_0642_therapy.webp', 'say-e563222d-f48cfe75-a67d6fb6-4a2bd601-1bbf8e52.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'symptom'), 'シンプル', 'Fever is a common symptom of the flu.', '発熱はインフルエンザの一般的な症状だ。', 'us_mvp_image_0643_symptom.webp', 'say-2b99b4e2-9cb24a15-9aa2fdfa-e891220b-3c007502.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'incident'), 'シンプル', 'There was a minor incident at school.', '学校で小さな事件があった。', 'us_mvp_image_0644_incident.webp', 'say-fd5f38e6-1a9b972b-47263741-ba636153-390ef401.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'witness'), 'シンプル', 'She was a witness to the accident.', '彼女はその事故の目撃者だった。', 'us_mvp_image_0645_witness.webp', 'say-ed1ad46f-0d282cf7-80bc14a0-435e0ca5-c258f42f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sum'), 'シンプル', 'The sum of 5 and 10 is 15.', '5と10の合計は15だ。', 'us_mvp_image_0646_sum.webp', 'say-6ab6df78-31809491-5cb9407f-b5464585-20860b1d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tone'), 'シンプル', 'His tone of voice was serious.', '彼の声の調子は深刻だった。', 'us_mvp_image_0648_tone.webp', 'say-039871da-9344df6f-2a3d08a3-4b33ccda-b770cfe2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'honor'), 'シンプル', 'It is an honor to meet you.', 'あなたにお会いできて光栄です。', 'us_mvp_image_0649_honor.webp', 'say-0f197f86-0bd67839-fa115a75-030b0811-aa3ee1c8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'priority'), 'シンプル', 'Safety is our top priority.', '安全が私たちの最優先事項だ。', 'us_mvp_image_0651_priority.webp', 'say-d8db0c72-c1f23999-3dae04fb-2b8f7398-929cb7ad.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'logic'), 'シンプル', 'His argument lacks logic.', '彼の主張には論理が欠けている。', 'us_mvp_image_0652_logic.webp', 'say-8b1d0094-f37c39b2-11b6cd1b-67b188a5-5f152a57.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'minimum'), 'シンプル', 'The minimum age to vote is 18.', '投票の最低年齢は18歳だ。', 'us_mvp_image_0653_minimum.webp', 'say-775a34f3-96d0de76-b57ed586-b76caf53-764334d6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exception'), 'シンプル', 'There is no exception to the rule.', 'その規則には例外がない。', 'us_mvp_image_0654_exception.webp', 'say-c7189ba5-0b2a1cee-bef5139b-b0025be4-ae633f4a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'clue'), 'シンプル', 'The detective found a clue.', 'その探偵は手がかりを見つけた。', 'us_mvp_image_0655_clue.webp', 'say-35cfec72-9410b9b2-4791a7c1-1a0c1bf0-a41174bf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'virus'), 'シンプル', 'The flu is caused by a virus.', 'インフルエンザはウイルスによって引き起こされる。', 'us_mvp_image_0657_virus.webp', 'say-ccb5df8d-1c530cc2-0d58a8fa-9a035977-f266479c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'surgery'), 'シンプル', 'He had heart surgery last year.', '彼は昨年心臓の手術を受けた。', 'us_mvp_image_0658_surgery.webp', 'say-ca9ede8b-14258d95-ba14983a-b9ce9260-51880411.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'insurance'), 'シンプル', 'I need health insurance.', '私は健康保険が必要だ。', 'us_mvp_image_0659_insurance.webp', 'say-a8742014-ac9eade7-0d1aa7c6-e038c292-8932fb17.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'frame'), 'シンプル', 'The picture is in a wooden frame.', 'その絵は木のフレームに入っている。', 'us_mvp_image_0660_frame.webp', 'say-78369f95-b8b9b314-e70f8d0b-f673a17e-ffca8fe9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'shelter'), 'シンプル', 'Many animals need shelter.', '多くの動物が住処を必要としている。', 'us_mvp_image_0661_shelter.webp', 'say-e71eb574-881fdbbd-ef6d890f-4334666e-95862918.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'territory'), 'シンプル', 'This is our country’s territory.', 'ここは私たちの国の領土だ。', 'us_mvp_image_0662_territory.webp', 'say-54260c26-163881e7-8d23e0e5-fcdf415f-0e4b4f80.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'boundary'), 'シンプル', 'The river forms the boundary between the two countries.', 'その川は二国間の境界を形成している。', 'us_mvp_image_0663_boundary.webp', 'say-ff37c028-6209b188-7720fbd1-e0c717fe-f81f99db.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'habitat'), 'シンプル', 'The forest is a natural habitat for bears.', 'その森はクマの自然の生息地だ。', 'us_mvp_image_0664_habitat.webp', 'say-7f991e51-d55b2aee-83fc86ba-936ec6e3-a8d9a309.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'district'), 'シンプル', 'This is a shopping district.', 'ここはショッピング地区だ。', 'us_mvp_image_0665_district.webp', 'say-17667948-0b855b30-62ff8c69-25926b85-e0445699.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'conservation'), 'シンプル', 'Wildlife conservation is important.', '野生動物の保護は重要だ。', 'us_mvp_image_0666_conservation.webp', 'say-cffecb23-d9e7c01b-7f73f0d8-f3591e8c-e4a041e4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'harvest'), 'シンプル', 'Farmers are busy with the harvest.', '農家は収穫で忙しい。', 'us_mvp_image_0667_harvest.webp', 'say-10b97c83-e500c0ab-48f7ba09-b1229a8b-d4a36382.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'predator'), 'シンプル', 'Lions are natural predators.', 'ライオンは自然の捕食者だ。', 'us_mvp_image_0668_predator.webp', 'say-f721fc32-ef2da7ca-d14333f3-621f32a2-8a807821.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trap'), 'シンプル', 'The mouse was caught in a trap.', 'そのネズミは罠にかかった。', 'us_mvp_image_0669_trap.webp', 'say-4b7d0bdf-bf57e215-6b1f650c-57aa65e6-b2201685.mp3', NOW(), NOW());
