INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('fault', '責任、欠陥', 'noun', 'ラテン語「fallere（だます、間違う）」から派生し、「過失、欠点」という意味になった。', NOW(), NOW()),('discount', '割引／値引きする', 'noun', '"反対の"の「dis-」と"数える"の「computare」が結合して「差し引く」→「割引」という意味になった。', NOW(), NOW()),('bias', '偏見／偏らせる', 'noun', 'ギリシア語「epikarsios（斜めの）」がフランス語「biais」に変化して「偏り」という意味になった。', NOW(), NOW()),('cooperation', '協力', 'noun', '"共に"の「co-」と"働く"の「operari」が結合して「協力」という意味になった。', NOW(), NOW()),('patent', '特許／特許を取得する', 'noun', '"開かれた"の意味のラテン語「patere」に由来し、「特許（公開された権利）」という意味になった。', NOW(), NOW()),('component', '部品、構成要素', 'noun', '"共に"の「com-」と"置く"の「ponere」が結合して「構成要素」という意味になった。', NOW(), NOW()),('reputation', '評判、名声', 'noun', '"再び"の「re-」と"考える、評する"の「putare」が結合して「評判、名声」という意味になった。', NOW(), NOW()),('solid', '固体の、しっかりした', 'noun', 'ラテン語「solidus（固い）」に由来し、「固体の、堅実な」という意味になった。', NOW(), NOW()),('attribute', '～のせいにする／特性', 'noun', '"〜に"の「ad-」と"与える"の「tribuere」が結合して「〜のせいにする」という意味になった。', NOW(), NOW()),('wisdom', '知恵、賢明さ', 'noun', '古英語「wis（賢い）」と名詞語尾「-dom」が結合して「知恵」という意味になった。', NOW(), NOW()),('mission', '使命、任務', 'noun', '"送る"の意味のラテン語「mittere」が名詞化して「任務、使命」という意味になった。', NOW(), NOW()),('license', '許可、免許／許可する', 'noun', 'ラテン語「licere（許されている）」が変化して「許可、免許」という意味になった。', NOW(), NOW()),('elite', 'エリート、選ばれた者／選ばれた', 'noun', 'ラテン語「eligere（選ぶ）」が派生して「選ばれた者」→「エリート」という意味になった。', NOW(), NOW()),('layer', '層／重ねる', 'noun', '古英語「leger（寝床、層）」に由来し、「層」という意味になった。', NOW(), NOW()),('motor', 'モーター、原動機／運動の', 'noun', 'ラテン語「movere（動かす）」に由来し、「モーター、原動力」という意味になった。', NOW(), NOW()),('protein', 'タンパク質', 'noun', 'ギリシア語「proteios（第一の）」に由来し、「タンパク質」という意味になった（生命の基本要素として）。', NOW(), NOW()),('profession', '職業、専門職', 'noun', '"前に"の「pro-」と"述べる"の「fateri」が結合して「公に述べる職業」→「職業、専門職」という意味になった。', NOW(), NOW()),('editor', '編集者', 'noun', 'ラテン語「edere（出す）」に由来し、「編集者」という意味になった。', NOW(), NOW()),('agent', '代理人、仲介者', 'noun', '"行う"の意味のラテン語「agere」に由来し、「代理人、作用者」という意味になった。', NOW(), NOW()),('globe', '地球、球体', 'noun', 'ラテン語「globus（球）」に由来し、「地球、球体」という意味になった。', NOW(), NOW()),('row', '列／こぐ', 'noun', '古英語「ræw（列、並び）」に由来し、「列、並び」という意味になった。', NOW(), NOW()),('sacrifice', '犠牲／犠牲にする', 'noun', '"神聖な"の「sacer」と"作る"の「facere」が結合して「神への供物」→「犠牲」という意味になった。', NOW(), NOW()),('session', '会議、講習', 'noun', '"座る"の意味のラテン語「sedere」が派生して「会期、集まりの時間」という意味になった。', NOW(), NOW()),('league', '連盟、リーグ', 'noun', 'ラテン語「ligare（結ぶ）」から派生して「同盟、リーグ」という意味になった。', NOW(), NOW()),('contest', '競技、コンテスト／争う', 'noun', '"共に"の「con-」と"努力する、主張する"の「testari」が結合して「争う、競争」という意味になった。', NOW(), NOW()),('opponent', '対戦相手、敵', 'noun', '"反対の"の「ob-」と"置く"の「ponere」が結合して「敵、対戦相手」という意味になった。', NOW(), NOW()),('glance', 'ちらっと見る／一見', 'noun', '中期英語「glencen（横目で見る）」に由来し、「ちらりと見る」という意味になった。', NOW(), NOW()),('divorce', '離婚／離婚する', 'noun', '"分離"の「dis-」と"向きを変える"の「vertere」が結合して「離婚する、分離する」という意味になった。', NOW(), NOW()),('tissue', '組織、ティッシュ', 'noun', 'ラテン語「texere（織る）」がフランス語「tissu（織物）」になり、「組織、生地」という意味になった。', NOW(), NOW()),('liquid', '液体／液体の', 'noun', 'ラテン語「liquere（液体である）」に由来し、「液体の」という意味になった。', NOW(), NOW()),('inequality', '不平等', 'noun', '"否定のin-"と"等しい"の「aequalis」が結合して「不平等」という意味になった。', NOW(), NOW()),('prejudice', '偏見／偏見を持たせる', 'noun', '"前もって"の「prae-」と"判断する"の「judicium」が結合して「偏見」という意味になった。', NOW(), NOW()),('justice', '正義、公正', 'noun', 'ラテン語「justitia（正義）」に由来し、「正義、公正」という意味になった。', NOW(), NOW()),('guideline', '指針、ガイドライン', 'noun', '「導く」意味の「guide」と「線」や「方向」の「line」が結合して「指針」という意味になった。', NOW(), NOW()),('platform', 'プラットフォーム、基盤', 'noun', '「平らな」の「plat」と「形」の「form」が結合して「台、壇、基盤」という意味になった。', NOW(), NOW()),('sector', '部門、分野', 'noun', 'ラテン語「sectus（切られたもの）」に由来し、「部門、区域」という意味になった。', NOW(), NOW()),('channel', 'チャンネル、経路', 'noun', 'ラテン語「canalis（水路）」に由来し、「水路、経路、チャンネル」という意味になった。', NOW(), NOW()),('usage', '使用法、語法', 'noun', 'フランス語「usage（使用）」に由来し、「使用法、慣用」という意味になった。', NOW(), NOW()),('fortune', '財産、運', 'noun', 'ラテン語「fortuna（運）」に由来し、「運命、財産」という意味になった。', NOW(), NOW()),('correlation', '相関関係', 'noun', '"共に"の「cor-」と"関係"の「relatio」が結合して「相関関係」という意味になった。', NOW(), NOW()),('classic', '古典的な／古典', 'noun', 'ラテン語「classicus（一流の）」に由来し、「古典的な、伝統的な」という意味になった。', NOW(), NOW()),('concrete', '具体的な／コンクリート', 'noun', '"共に"の「con-」と"育つ、増す"の「crescere」が結合して「具体的な、実体のある」という意味になった。', NOW(), NOW()),('peer', 'じっと見る／同僚、仲間', 'noun', 'ラテン語「par（等しい）」が変化して「同等の人、仲間」という意味になった。', NOW(), NOW()),('delight', '喜ばせる／喜び', 'noun', 'ラテン語「delectare（喜ばせる）」に由来し、「喜ばせる、歓喜」という意味になった。', NOW(), NOW()),('boost', '増加させる／向上', 'noun', 'オランダ語「boosten（持ち上げる）」に由来し、「高める、押し上げる」という意味になった。', NOW(), NOW()),('passion', '情熱', 'noun', 'ラテン語「pati（苦しむ）」から派生し、「情熱、苦しみ」という意味になった。', NOW(), NOW()),('enthusiasm', '熱意、熱中', 'noun', 'ギリシア語「entheos（神が内にいる）」に由来し、「熱意、情熱」という意味になった。', NOW(), NOW()),('phase', '段階、局面', 'noun', 'ギリシア語「phasis（現れ）」に由来し、「段階、相」という意味になった。', NOW(), NOW()),('mode', '方法、形式、モード', 'noun', 'ラテン語「modus（やり方、様式）」に由来し、「方式、モード」という意味になった。', NOW(), NOW()),('span', '期間、範囲／及ぶ', 'noun', '古英語「spann（手を広げた幅）」に由来し、「期間、範囲」という意味になった。', NOW(), NOW()),('gravity', '重力、重大さ', 'noun', 'ラテン語「gravitas（重さ）」に由来し、「重力、重さ、真面目さ」という意味になった。', NOW(), NOW()),('core', '核心、中心部', 'noun', 'ラテン語「cor（心、中心）」に由来し、「中心、核心」という意味になった。', NOW(), NOW()),('soul', '魂、精神', 'noun', '古英語「sawol（魂）」に由来し、「魂、精神」という意味になった。', NOW(), NOW()),('nerve', '神経、勇気', 'noun', 'ラテン語「nervus（腱、筋）」に由来し、「神経、勇気」という意味になった。', NOW(), NOW()),('infection', '感染症、感染', 'noun', '"中に"の「in-」と"作る、汚す"の「facere」が結合して「感染、伝染」という意味になった。', NOW(), NOW()),('mall', 'ショッピングモール', 'noun', 'イタリア語「pallamaglio（球技場）」から派生し、最終的に「ショッピングモール」という意味になった。', NOW(), NOW()),('grocery', '食料品、食料品店', 'noun', 'ラテン語「grossus（大きな）」がフランス語「grosserie（大口商品）」を経て「食料雑貨」という意味になった。', NOW(), NOW()),('humor', 'ユーモア', 'noun', 'ラテン語「umor（液体）」に由来し、体液説から転じて「気分、ユーモア」という意味になった。', NOW(), NOW()),('instinct', '本能、直感', 'noun', '"中に"の「in-」と"突く、駆り立てる"の「stinguere」が結合して「本能」という意味になった。', NOW(), NOW()),('faith', '信仰、信頼', 'noun', 'ラテン語「fides（信頼）」に由来し、「信頼、信仰」という意味になった。', NOW(), NOW()),('incentive', '動機、奨励策', 'noun', '"中に"の「in-」と"歌う"の「cantare」が結合して「刺激、動機」という意味になった。', NOW(), NOW()),('prospect', '見込み、展望', 'noun', '"前に"の「pro-」と"見る"の「specere」が結合して「見込み、展望」という意味になった。', NOW(), NOW()),('obstacle', '障害、困難', 'noun', '"逆らって"の「ob-」と"立つ"の「stare」が結合して「障害、妨げ」という意味になった。', NOW(), NOW()),('architecture', '建築、建築学', 'noun', 'ラテン語「architectura（建築）」に由来し、「建築、構造」という意味になった。', NOW(), NOW()),('stem', '茎、幹／生じる', 'noun', '古英語「stemn（幹、支え）」に由来し、「茎、幹、語幹、起因する」という意味になった。', NOW(), NOW()),('illusion', '幻想、錯覚', 'noun', '"中に"の「in-」と"だます"の「ludere」が結合して「幻想、錯覚」という意味になった。', NOW(), NOW()),('discrimination', '差別、識別', 'noun', '"分離"の「dis-」と"区別する"の「criminare」が結合して「差別、識別」という意味になった。', NOW(), NOW()),('flavor', '風味、味', 'noun', 'ラテン語「flavus（黄色）」に由来する説もあるが、中期英語「flavour（香り）」から「風味、味」という意味になった。', NOW(), NOW()),('portion', '部分、一人前', 'noun', 'ラテン語「portio（分け前、部分）」に由来し、「部分、一部、分け前」という意味になった。', NOW(), NOW()),('recipe', 'レシピ、調理法', 'noun', 'ラテン語「recipere（受け取る）」の命令形「recipe（取れ）」が由来で、「料理法、処方」という意味になった。', NOW(), NOW()),('luxury', '贅沢、豪華', 'noun', 'ラテン語「luxus（贅沢）」に由来し、「贅沢、豪華」という意味になった。', NOW(), NOW()),('chip', '欠けた部分、小片、コンピュータチップ／欠ける、削る', 'noun', '古英語「cipp（削ったかけら）」に由来し、「かけら、小片」という意味になった。', NOW(), NOW()),('ritual', '儀式、習慣', 'noun', 'ラテン語「ritus（宗教的儀式）」に由来し、「儀式、習慣」という意味になった。', NOW(), NOW()),('sake', '目的、～のために', 'noun', '日本語「酒」または「目的」の「sake」に由来し、文脈により「利益、目的、理由」という意味になる（英語では主に後者）。', NOW(), NOW()),('council', '議会、評議会', 'noun', 'ラテン語「concilium（集まり、評議会）」に由来し、「会議、評議会」という意味になった。', NOW(), NOW()),('administration', '行政、管理', 'noun', 'ラテン語「ad-（〜に）」と「ministrare（仕える）」が結合して「管理、行政」という意味になった。', NOW(), NOW()),('curriculum', 'カリキュラム、教育課程', 'noun', 'ラテン語「currere（走る）」の名詞形で「学習課程、カリキュラム」という意味になった。', NOW(), NOW()),('instant', '即時の／瞬間', 'noun', 'ラテン語「instare（差し迫る）」に由来し、「即時の、瞬間的な」という意味になった。', NOW(), NOW()),('load', '積む、負荷をかける／積荷', 'noun', '古英語「hladan（積む）」に由来し、「積荷、積む」という意味になった。', NOW(), NOW()),('float', '浮かぶ', 'noun', '古英語「flotan（浮く）」に由来し、「浮く、漂う」という意味になった。', NOW(), NOW()),('substitute', '代わりに使う／代用品', 'noun', 'ラテン語「sub（下）」と「statuere（立てる、置く）」が結合して「代わりのもの」という意味になった。', NOW(), NOW()),('fold', '折る、畳む', 'noun', '古英語「fealdan（折る）」に由来し、「折る、畳む」という意味になった。', NOW(), NOW()),('privilege', '特権、恩恵', 'noun', 'ラテン語「privus（個人の）」と「lex（法）」が結合して「特権」という意味になった。', NOW(), NOW()),('formation', '形成、構造', 'noun', 'ラテン語「formare（形作る）」に由来し、「形成、構成」という意味になった。', NOW(), NOW()),('dimension', '寸法、次元、側面', 'noun', '"離れて"の「dis-」と"測る"の「metiri」が結合して「次元、寸法」という意味になった。', NOW(), NOW()),('neuron', '神経細胞、ニューロン', 'noun', 'ギリシア語「neuron（神経、腱）」に由来し、「ニューロン、神経細胞」という意味になった。', NOW(), NOW()),('sensation', '感覚、感動', 'noun', 'ラテン語「sentire（感じる）」が名詞化して「感覚、感情」という意味になった。', NOW(), NOW()),('chart', '図表、チャート／図示する', 'noun', 'ラテン語「charta（紙、地図）」に由来し、「図、表、地図」という意味になった。', NOW(), NOW()),('geography', '地理、地形', 'noun', 'ギリシア語「geo（地球）」と「graphia（記述）」が結合して「地理学」という意味になった。', NOW(), NOW()),('panel', '委員会、パネル、板', 'noun', 'ラテン語「panis（布、板）」が中期英語で「パネル、委員会」という意味になった。', NOW(), NOW()),('semester', '学期', 'noun', 'ラテン語「sex（6）」と「mensis（月）」が結合して「6ヶ月間」→「学期」という意味になった。', NOW(), NOW()),('workforce', '労働力、従業員', 'noun', '「労働（work）」と「力、集団（force）」が結合して「労働力、従業員」という意味になった。', NOW(), NOW()),('mill', '製粉所、工場／粉をひく', 'noun', 'ラテン語「molere（挽く）」が古英語で「mill（製粉所）」に変化し、「工場、粉ひき場」という意味になった。', NOW(), NOW()),('vice', '悪徳、欠点', 'noun', 'ラテン語「vitium（欠陥、悪）」に由来し、「悪徳、欠点」という意味になった。', NOW(), NOW()),('fate', '運命、宿命', 'noun', 'ラテン語「fatum（語られたこと）」に由来し、「運命、宿命」という意味になった。', NOW(), NOW()),('scenario', 'シナリオ、筋書き', 'noun', 'ラテン語「scaena（舞台）」に由来し、「筋書き、想定シナリオ」という意味になった。', NOW(), NOW()),('wound', '傷／傷つける', 'noun', '古英語「wund」に由来し、「傷、負傷」という意味になった。', NOW(), NOW()),('vaccine', 'ワクチン', 'noun', 'ラテン語「vacca（牛）」に由来し、牛痘から発展して「ワクチン」という意味になった。', NOW(), NOW()),('metaphor', '隠喩、比喩', 'noun', 'ギリシア語「meta（越えて）」と「pherein（運ぶ）」が結合して「比喩（意味を運び変える）」という意味になった。', NOW(), NOW()),('fare', '料金、運賃', 'noun', '古英語「faran（旅する）」に由来し、「運賃、食事、やりくりする」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'fault'), 'シンプル', 'It was not my fault.', 'それは私のせいではない。', 'us_mvp_image_0671_fault.webp', 'say-b90857ac-07a1d2cb-6db0ca32-a0c7a256-ed963316.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'discount'), 'シンプル', 'The store is offering a 10% discount.', 'その店は10%の割引を提供している。', 'us_mvp_image_0672_discount.webp', 'say-60fe2279-50c066f9-620b0b85-5883939c-edfac9d5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bias'), 'シンプル', 'The media often shows bias.', 'メディアはしばしば偏見を示す。', 'us_mvp_image_0673_bias.webp', 'say-e9aec247-15aa196b-081e3b36-cb26c978-6e68d4ea.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cooperation'), 'シンプル', 'Cooperation is key to success.', '協力は成功の鍵だ。', 'us_mvp_image_0674_cooperation.webp', 'say-e0153cf8-7b5ca6f2-28d67717-4cb53278-0ceba4bf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'patent'), 'シンプル', 'He applied for a patent.', '彼は特許を申請した。', 'us_mvp_image_0675_patent.webp', 'say-a5b5234e-b7e41871-b2784df7-24d95199-819b0442.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'component'), 'シンプル', 'This machine has several components.', 'この機械にはいくつかの部品がある。', 'us_mvp_image_0677_component.webp', 'say-04112a7a-9889fc9d-57bbadc6-343c17eb-6678807e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reputation'), 'シンプル', 'The company has a great reputation.', 'その会社は素晴らしい評判を持っている。', 'us_mvp_image_0678_reputation.webp', 'say-32a22b6f-e208cd6f-aaf3369c-39ed8389-54a8cb58.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'solid'), 'シンプル', 'The table is made of solid wood.', 'そのテーブルは無垢材で作られている。', 'us_mvp_image_0681_solid.webp', 'say-72000304-756a2355-61ea7f3c-961791d1-e00832cb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'attribute'), 'シンプル', 'He attributes his success to hard work.', '彼は成功を努力の賜物だとしている。', 'us_mvp_image_0723_attribute.webp', 'say-40bbbb5e-078e4c45-6db0aa13-35ac7b1b-01f014db.mp3', NOW(), NOW()),((SELECT id FROM wor