INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('transition', '移行、変化／移行する', 'noun', 'ラテン語「trans（越えて）」と「ire（行く）」が結合して「移行、変化」という意味になった。', NOW(), NOW()),('maximum', '最大（の）', 'noun', 'ラテン語「maximus（最も大きい）」に由来し、「最大の」という意味になった。', NOW(), NOW()),('mineral', '鉱物、ミネラル', 'noun', 'ラテン語「minerale（鉱物）」に由来し、「鉱物、ミネラル」という意味になった。', NOW(), NOW()),('counterpart', '相当するもの、対応する人・物', 'noun', '「反対の、対応する」の「counter-」と「部分、役割」の「part」が結合して「対応するもの、相手」という意味になった。', NOW(), NOW()),('pedestrian', '歩行者／歩行者の', 'noun', 'ラテン語「pes（足）」に由来し、「歩行者」という意味になった。', NOW(), NOW()),('trail', '小道、跡／後を追う', 'noun', '中期英語「trailen（引きずる）」に由来し、「跡、道、たどる」という意味になった。', NOW(), NOW()),('ecology', '生態学、環境', 'noun', 'ギリシア語「oikos（家）」と「logia（学問）」が結合して「生態学（生物と環境の関係の学問）」という意味になった。', NOW(), NOW()),('ratio', '比率、割合', 'noun', 'ラテン語「ratio（計算、割合）」に由来し、「比率」という意味になった。', NOW(), NOW()),('mixture', '混合物、混合', 'noun', 'ラテン語「miscere（混ぜる）」が名詞化して「混合物」という意味になった。', NOW(), NOW()),('charm', '魅力、お守り／魅了する', 'noun', 'ラテン語「carmen（歌、呪文）」に由来し、「魅力、魔力」という意味になった。', NOW(), NOW()),('ambition', '野心、志', 'noun', 'ラテン語「ambitio（選挙運動、熱望）」に由来し、「野心、熱意」という意味になった。', NOW(), NOW()),('alert', '警戒している／警報', 'noun', 'ラテン語「al（〜へ）」と「erte（高い）」が結合して「警戒した、注意を促す」という意味になった。', NOW(), NOW()),('forecast', '予測する／予測、天気予報', 'noun', '古英語「fore（前）」と「cast（投げる）」が結合して「予測する、予報」という意味になった。', NOW(), NOW()),('burst', '破裂する、突然～しだす／破裂', 'noun', '古英語「berstan（破裂する）」に由来し、「破裂する、突然起こる」という意味になった。', NOW(), NOW()),('dispute', '議論する、異議を唱える／議論、紛争', 'noun', '"反対に"の「dis-」と"考える、論じる"の「putare」が結合して「論争する、異議を唱える」という意味になった。', NOW(), NOW()),('highlight', '強調する／重要点', 'noun', '「high（高い）」と「light（光）」が結合して「強調する、目立たせる」という意味になった。', NOW(), NOW()),('log', '記録する、伐採する／記録、丸太', 'noun', '古英語「logg（丸太）」に由来し、「記録、記録する」という意味になった（航海日誌に丸太を使ったことから）。', NOW(), NOW()),('bully', 'いじめる／いじめっ子', 'noun', 'オランダ語「boel（恋人）」が侮蔑的意味に変化し「いじめる人」という意味になった。', NOW(), NOW()),('pitch', '投げる、売り込む／音の高さ、投球', 'noun', '古英語「pic（タール）」に由来し、後に比喩的に「投げる、売り込む、音の高さ」という意味になった。', NOW(), NOW()),('premise', '前提、敷地', 'noun', 'ラテン語「praemittere（前に置く）」が名詞化して「前提、根拠」という意味になった。', NOW(), NOW()),('merit', '長所、価値／値する', 'noun', 'ラテン語「merere（得る、値する）」に由来し、「功績、価値」という意味になった。', NOW(), NOW()),('sympathy', '同情、共感', 'noun', 'ギリシア語「syn（共に）」と「pathos（感情、苦しみ）」が結合して「共感、同情」という意味になった。', NOW(), NOW()),('infrastructure', 'インフラ、基盤設備', 'noun', 'ラテン語「infra（下）」と「structure（構造）」が結合して「基盤、インフラ」という意味になった。', NOW(), NOW()),('ray', '光線、放射線', 'noun', 'ラテン語「radius（光線、放射）」に由来し、「光線、放射線」という意味になった。', NOW(), NOW()),('distress', '苦悩、苦痛／苦しめる', 'noun', 'ラテン語「dis-（否定）」と「stringere（締め付ける）」が結合して「苦悩、苦しめる」という意味になった。', NOW(), NOW()),('joint', '関節、接合部／共同の', 'noun', 'ラテン語「jungere（つなぐ）」に由来し、「関節、接合部」という意味になった。', NOW(), NOW()),('adolescent', '青年（の）、思春期の', 'noun', 'ラテン語「adolescere（成長する）」に由来し、「思春期の、青年」という意味になった。', NOW(), NOW()),('jury', '陪審、審査員', 'noun', 'ラテン語「jurare（誓う）」に由来し、「陪審、裁判員」という意味になった。', NOW(), NOW()),('penalty', '罰則、刑罰、ペナルティ', 'noun', 'ラテン語「poena（罰）」が変化して「罰、ペナルティ」という意味になった。', NOW(), NOW()),('faculty', '学部、能力、教授陣', 'noun', 'ラテン語「facultas（能力、技能）」に由来し、「能力、学部」という意味になった。', NOW(), NOW()),('scheme', '計画、陰謀／企てる', 'noun', 'ギリシア語「skhema（形、計画）」に由来し、「計画、枠組み」という意味になった。', NOW(), NOW()),('particle', '粒子、微粒子', 'noun', 'ラテン語「particula（小部分）」に由来し、「微粒子、小さな部分」という意味になった。', NOW(), NOW()),('molecule', '分子', 'noun', 'ラテン語「moles（塊）」に縮小辞「-cule」が付いて「小さな塊」→「分子」という意味になった。', NOW(), NOW()),('poll', '世論調査、投票／世論調査を行う', 'noun', '中期英語「pol（頭、数を数える）」に由来し、「世論調査、投票」という意味になった。', NOW(), NOW()),('clinic', '診療所、クリニック', 'noun', 'ギリシア語「klinein（横たわる）」から「臨床、診療所」という意味になった（患者が横たわる場所）。', NOW(), NOW()),('fatigue', '疲労／疲れさせる', 'noun', 'ラテン語「fatigare（疲れさせる）」に由来し、「疲労、疲れ」という意味になった。', NOW(), NOW()),('dilemma', 'ジレンマ、板挟み', 'noun', 'ギリシア語「di-（2つ）」と「lemma（命題）」が結合して「ジレンマ（板ばさみの状態）」という意味になった。', NOW(), NOW()),('queue', '列／列に並ぶ', 'noun', 'ラテン語「coda（尾）」がフランス語「queue（列、尾）」に変化し、「列、並ぶ」という意味になった。', NOW(), NOW()),('curve', '曲線／曲がる', 'noun', 'ラテン語「curvus（曲がった）」に由来し、「曲線、曲がる」という意味になった。', NOW(), NOW()),('narrative', '物語、語り', 'noun', 'ラテン語「narrare（語る）」に由来し、「物語、語りの」という意味になった。', NOW(), NOW()),('pesticide', '農薬、殺虫剤', 'noun', '「害虫」の「pest」と「殺す」の「-cide」が結合して「殺虫剤」という意味になった。', NOW(), NOW()),('panic', '恐慌、パニック／慌てる', 'noun', 'ギリシア神「パン（Pan）」に由来し、「突然の恐怖」という意味になった（彼が引き起こす恐怖から）。', NOW(), NOW()),('fabric', '布地、生地', 'noun', 'ラテン語「fabrica（作ること、構造）」に由来し、「織物、構造」という意味になった。', NOW(), NOW()),('virtue', '美徳、長所', 'noun', 'ラテン語「virtus（力、徳）」に由来し、「美徳、長所」という意味になった。', NOW(), NOW()),('filter', 'ろ過する、フィルターを通す／フィルター', 'noun', 'ラテン語「filtrum（毛織物で濾すもの）」に由来し、「ろ過する、フィルターをかける」という意味になった。', NOW(), NOW()),('resort', '頼る／リゾート地', 'noun', 'ラテン語「resortire（再び頼る）」に由来し、「行楽地、頼る」という意味になった。', NOW(), NOW()),('grip', 'つかむ、握る／握ること', 'noun', '古ノルド語「gripa（つかむ）」に由来し、「握る、支配」という意味になった。', NOW(), NOW()),('compound', '悪化させる、混合する／化合物', 'noun', 'ラテン語「com-（共に）」と「ponere（置く）」が結合して「複合、混合する」という意味になった。', NOW(), NOW()),('commute', '通勤する／通勤', 'noun', '「共に」の「com-」と「変える」の「mutare」が結合して「通勤する、交換する」という意味になった。', NOW(), NOW()),('compromise', '妥協する／妥協', 'noun', '「共に」の「com-」と「約束する」の「promittere」が結合して「妥協する」という意味になった。', NOW(), NOW()),('cue', '合図／合図を出す', 'noun', 'ラテン語「quando（いつ）」を示す舞台指示「q」が短縮されて「合図、きっかけ」という意味になった。', NOW(), NOW()),('enterprise', '企業、事業', 'noun', '「間に」の「inter-」と「つかむ」の「prehendere」が結合して「事業、企業、進取の気性」という意味になった。', NOW(), NOW()),('output', '生産量、出力', 'noun', '「外へ」の「out」と「置く」の「put」が結合して「出力、産出」という意味になった。', NOW(), NOW()),('estate', '不動産、財産', 'noun', 'ラテン語「status（状態）」が中世フランス語を経て「地所、財産」という意味になった。', NOW(), NOW()),('controversy', '論争、議論', 'noun', '「反対の」の「contro-」と「回る」の「vertere」が結合して「論争」という意味になった。', NOW(), NOW()),('consensus', '合意、総意', 'noun', '「共に」の「con-」と「感じる」の「sentire」が結合して「合意」という意味になった。', NOW(), NOW()),('fiber', '繊維、食物繊維', 'noun', 'ラテン語「fibra（糸、繊維）」に由来し、「繊維」という意味になった。', NOW(), NOW()),('beverage', '飲料', 'noun', 'ラテン語「bibere（飲む）」が古フランス語を経て「飲み物」という意味になった。', NOW(), NOW()),('supplement', '補足、サプリメント／補う', 'noun', '「下に」の「sub-」と「満たす」の「plere」が結合して「補足、補うもの」という意味になった。', NOW(), NOW()),('province', '州、地方', 'noun', 'ラテン語「pro-（前もって）」と「vincere（征服する）」が結合して「属州、地方」という意味になった。', NOW(), NOW()),('excess', '過剰／過剰な', 'noun', '「外へ」の「ex-」と「行く」の「cedere」が結合して「過剰」という意味になった。', NOW(), NOW()),('gallery', '美術館、展示室', 'noun', 'ラテン語「galeria（回廊）」に由来し、「美術館、展示室」という意味になった。', NOW(), NOW()),('deadline', '締め切り', 'noun', '「死」の「dead」と「境界線」の「line」が結合して「締切、期限」という意味になった。', NOW(), NOW()),('undergraduate', '大学生、学部生', 'noun', '「学部」の「graduate」に「under-（下の）」が付いて「大学生、学部生」という意味になった。', NOW(), NOW()),('slavery', '奴隷制度、奴隷の状態', 'noun', '「奴隷」の「slave」に接尾辞「-ry」が付き「奴隷制、奴隷状態」という意味になった。', NOW(), NOW()),('prey', '獲物／捕食する', 'noun', 'ラテン語「praeda（獲物）」に由来し、「獲物、捕食対象」という意味になった。', NOW(), NOW()),('mess', '混乱、散らかり／散らかす', 'noun', 'ラテン語「missus（送られたもの）」から中世ラテン語「mensa（食事）」を経て「散らかった状態」という意味になった。', NOW(), NOW()),('recession', '景気後退、不況', 'noun', '「後ろに」の「re-」と「行く」の「cedere」が結合して「景気後退、退却」という意味になった。', NOW(), NOW()),('retreat', '撤退、後退／撤退する', 'noun', '「後ろに」の「re-」と「引く」の「trahere」が結合して「退却、後退」という意味になった。', NOW(), NOW()),('column', '柱、コラム、縦の列', 'noun', 'ラテン語「columna（柱）」に由来し、「柱、欄、コラム」という意味になった。', NOW(), NOW()),('plot', '筋書き、陰謀／計画する', 'noun', '古英語「plot（区画）」に由来し、「筋、陰謀、小区画」という意味になった。', NOW(), NOW()),('sculpture', '彫刻', 'noun', 'ラテン語「sculpere（彫る）」に由来し、「彫刻」という意味になった。', NOW(), NOW()),('acid', '酸／酸性の', 'noun', 'ラテン語「acidus（酸っぱい）」に由来し、「酸、酸性の」という意味になった。', NOW(), NOW()),('hybrid', 'ハイブリッドの、混成の／交配種', 'noun', 'ラテン語「hybrida（雑種）」に由来し、「混成の、雑種の」という意味になった。', NOW(), NOW()),('venture', '冒険、事業／思い切って～する', 'noun', 'ラテン語「adventura（冒険）」に由来し、「冒険、危険を冒して行く」という意味になった。', NOW(), NOW()),('clip', '切る、留める／クリップ、断片', 'noun', '古英語「clyppan（抱く、切る）」に由来し、「切る、留める」という意味になった。', NOW(), NOW()),('dye', '染める／染料', 'noun', '古英語「deag（色）」に由来し、「染める」という意味になった。', NOW(), NOW()),('spill', 'こぼす／こぼれること', 'noun', '古英語「spillan（こぼす）」に由来し、「こぼす、漏れる」という意味になった。', NOW(), NOW()),('drain', '排出する、消耗させる／排水', 'noun', 'ラテン語「dragan（引く）」が変化し、「排出する、排水する」という意味になった。', NOW(), NOW()),('twist', 'ねじる、ひねる／ねじれ', 'noun', '古ノルド語「tvistra（ねじる）」に由来し、「ねじる、ひねる」という意味になった。', NOW(), NOW()),('profile', 'プロフィール、人物紹介／紹介する', 'noun', 'ラテン語「pro-（前に）」と「filare（形作る）」が結合して「横顔、人物像」という意味になった。', NOW(), NOW()),('appetite', '食欲、欲求', 'noun', 'ラテン語「ad-（〜へ）」と「petere（求める）」が結合して「欲求、食欲」という意味になった。', NOW(), NOW()),('impulse', '衝動、刺激', 'noun', 'ラテン語「impellere（押す、駆り立てる）」に由来し、「衝動」という意味になった。', NOW(), NOW()),('script', '台本、脚本', 'noun', 'ラテン語「scribere（書く）」に由来し、「脚本、文字」という意味になった。', NOW(), NOW()),('anniversary', '記念日', 'noun', 'ラテン語「annus（年）」と「vertere（回る）」が結合して「記念日」という意味になった。', NOW(), NOW()),('pension', '年金', 'noun', 'ラテン語「pensio（支払い）」に由来し、「年金」という意味になった。', NOW(), NOW()),('cortex', '皮質、大脳皮質', 'noun', 'ラテン語「cortex（樹皮）」に由来し、「皮質、大脳皮質」という意味になった。', NOW(), NOW()),('syndrome', '症候群', 'noun', 'ギリシア語「syn（共に）」と「dromein（走る）」が結合して「症候群」という意味になった。', NOW(), NOW()),('chamber', '部屋、会議室', 'noun', 'ラテン語「camera（部屋）」に由来し、「部屋、議場、腔」という意味になった。', NOW(), NOW()),('utility', '公共サービス、実用性', 'noun', 'ラテン語「utilis（役立つ）」に由来し、「公共サービス、実用性」という意味になった。', NOW(), NOW()),('cattle', '牛（畜牛）', 'noun', '古ノルド語「köttr（家畜）」に由来し、「牛、家畜」という意味になった。', NOW(), NOW()),('fluid', '液体、流動体／流動的な', 'noun', 'ラテン語「fluere（流れる）」に由来し、「液体、流動性のある」という意味になった。', NOW(), NOW()),('offspring', '子孫、子供', 'noun', '古英語「of（〜から）」と「springan（跳ねる、出る）」が結合して「子孫、結果」という意味になった。', NOW(), NOW()),('commodity', '商品、必需品', 'noun', 'ラテン語「commodus（適した）」が派生し、「商品、必需品」という意味になった。', NOW(), NOW()),('format', '形式、書式／整える', 'noun', 'ラテン語「forma（形）」に由来し、「形式、構成」という意味になった。', NOW(), NOW()),('recipient', '受取人、受賞者', 'noun', '「受け取る」の「recipere」に由来し、「受取人」という意味になった。', NOW(), NOW()),('inability', '無能、できないこと', 'noun', '否定の「in-」と「能力」の「ability」が結合して「無能、できないこと」という意味になった。', NOW(), NOW()),('republic', '共和国', 'noun', 'ラテン語「res publica（公共の事柄）」に由来し、「共和国」という意味になった。', NOW(), NOW()),('combat', '戦闘、対策／戦う、対処する', 'noun', '「共に」の「com-」と「打つ」の「battere」が結合して「戦う、戦闘」という意味になった。', NOW(), NOW()),('fraction', '一部、分数', 'noun', 'ラテン語「frangere（壊す）」の過去分詞「fractio」が由来で、「分数、部分」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'transition'), 'シンプル', 'The transition from summer to autumn is beautiful.', '夏から秋への移り変わりは美しい。', 'us_mvp_image_0964_transition.webp', 'say-1851a5dd-9c1707db-1ab33139-34a0258e-5c26217d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'maximum'), 'シンプル', 'The maximum speed limit is 100 km/h.', '最高速度制限は時速100kmだ。', 'us_mvp_image_0965_maximum.webp', 'say-4922ed9d-98c76d22-c262ed06-1f540c13-113920b9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mineral'), 'シンプル', 'Water contains important minerals for the body.', '水には体に必要なミネラルが含まれている。', 'us_mvp_image_0967_mineral.webp', 'say-9d4705bd-1d188326-cc6dd252-1f31b92e-cf55031f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'counterpart'), 'シンプル', 'The CEO met his Japanese counterpart.', 'そのCEOは日本の同職の人と会った。', 'us_mvp_image_0969_counterpart.webp', 'say-04115352-5766fd21-c6e8a730-dd9057bc-39facf20.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pedestrian'), 'シンプル', 'Pedestrians should use the crosswalk.', '歩行者は横断歩道を利用すべきだ。', 'us_mvp_image_0971_pedestrian.webp', 'say-fa85154b-b1bf30ee-88ac8c3a-55a2f4da-0d3ada4a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trail'), 'シンプル', 'They followed a hiking trail through the forest.', '彼らは森の中のハイキングコースを進んだ。', 'us_mvp_image_0972_trail.webp', 'say-49914408-46193728-577c7502-6cff0e39-e934ec58.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ecology'), 'シンプル', 'Ecology is the study of the relationship between organisms and their environment.', '生態学は生物と環境の関係を研究する学問だ。', 'us_mvp_image_0973_ecology.webp', 'say-83ce21d6-b6fdf0b6-408a6d06-2f674493-a5f82aee.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ratio'), 'シンプル', 'The ratio of men to women in the company is 3:2.', 'その会社の男女比は3対2だ。', 'us_mvp_image_0975_ratio.webp', 'say-00b2be4d-165b2ce3-ba9f820c-14d34e86-f534843a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mixture'), 'シンプル', 'This soup is a mixture of various vegetables.', 'このスープはいろいろな野菜の混合物だ。', 'us_mvp_image_0976_mixture.webp', 'say-370ac411-16078719-6db737d1-df3f17c4-a776f31d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'charm'), 'シンプル', 'She has a natural charm that attracts people.', '彼女には人を惹きつける自然な魅力がある。', 'us_mvp_image_0977_charm.webp', 'say-ad741f92-683259c4-ac572d71-4d9f99a0-b6222022.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ambition'), 'シンプル', 'His ambition is to become a doctor.', '彼の野心は医者になることだ。', 'us_mvp_image_0978_ambition.webp', 'say-ddd60c5f-73954163-e8deb885-fe907695-dbda3397.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'alert'), 'シンプル', 'The soldiers remained alert all night.', '兵士たちは一晩中警戒を続けた。', 'us_mvp_image_0985_alert.webp', 'say-8727d528-5ee29ba9-18338068-ca5989da-67325fcf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'forecast'), 'シンプル', 'The weather forecast predicts rain.', '天気予報では雨が予測されている。', 'us_mvp_image_1008_forecast.webp', 'say-8cf15f91-41b767f9-a2114788-d6552425-20bd85bf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'burst'), 'シンプル', 'The balloon burst suddenly.', '風船が突然破裂した。', 'us_mvp_image_1011_burst.webp', 'say-9d387f4b-5d93ed8a-53ba2d93-f5125d61-7026950c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dispute'), 'シンプル', 'They disputed over the contract terms.', '彼らは契約条件について議論した。', 'us_mvp_image_1018_dispute.webp', 'say-98be57c9-0328a923-a64c33f6-1f8763fe-30b4389b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'highlight'), 'シンプル', 'The report highlights key issues.', 'その報告書は重要な問題を強調している。', 'us_mvp_image_1019_highlight.webp', 'say-25b09ccd-414cd79c-58aef7fd-11f02933-1a542075.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'log'), 'シンプル', 'He logged his daily activities.', '彼は日々の活動を記録した。', 'us_mvp_image_1027_log.webp', 'say-7106976a-8a5ac0de-5c9500d3-6c9de2af-96af221b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bully'), 'シンプル', 'He was bullied at school.', '彼は学校でいじめられた。', 'us_mvp_image_1029_bully.webp', 'say-ec80efe8-d9a9ce83-e4d7c09e-c7e16498-b61a6f7a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pitch'), 'シンプル', 'He pitched his idea to investors.', '彼は投資家に自分のアイデアを売り込んだ。', 'us_mvp_image_1037_pitch.webp', 'say-a99f2dc3-bf733fc2-a13b37aa-9b37323c-0bfcc1b1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'premise'), 'シンプル', 'His argument is based on a false premise.', '彼の主張は誤った前提に基づいている。', 'us_mvp_image_1041_premise.webp', 'say-479fd802-4990c8c5-f0d009d5-bb78a1c6-859110da.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'merit'), 'シンプル', 'His proposal has great merit.', '彼の提案には大きな価値がある。', 'us_mvp_image_1043_merit.webp', 'say-53dab59c-ad888cfd-a4fab9a2-358e494b-a792add3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sympathy'), 'シンプル', 'She showed sympathy for the victims.', '彼女は被害者に同情を示した。', 'us_mvp_image_1044_sympathy.webp', 'say-fc825bc6-7202b153-57a6c991-793e103b-9fad2430.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'infrastructure'), 'シンプル', 'The country needs better infrastructure.', 'その国はより良いインフラを必要としている。', 'us_mvp_image_1046_infrastructure.webp', 'say-d2333eeb-957f44df-c3deaf90-79a0a8a4-6871cf28.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ray'), 'シンプル', 'A ray of sunlight came through the window.', '一筋の太陽光が窓から差し込んだ。', 'us_mvp_image_1047_ray.webp', 'say-79aae420-07bed4e8-57668ca0-f8da131e-053eca26.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'distress'), 'シンプル', 'She was in great distress after the accident.', '彼女は事故の後、大きな苦しみを感じていた。', 'us_mvp_image_1048_distress.webp', 'say-c6f00a9b-1324e8d5-aca5b16b-dbbdc8a7-b2d283e6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'joint'), 'シンプル', 'They made a joint decision.', '彼らは共同で決定を下した。', 'us_mvp_image_1049_joint.webp', 'say-bcaefe04-e0a3db36-727487f5-d48bff0f-b85265e1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'adolescent'), 'シンプル', 'Adolescents often struggle with identity issues.', '青年はしばしば自分のアイデンティティに悩む。', 'us_mvp_image_1051_adolescent.webp', 'say-0774787c-189b7613-b581ae12-79826a87-86635e04.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'jury'), 'シンプル', 'The jury found him guilty.', '陪審は彼に有罪判決を下した。', 'us_mvp_image_1053_jury.webp', 'say-1113f53b-c9d0c552-8ad47793-d1399123-5d0a3883.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'penalty'), 'シンプル', 'He received a penalty for speeding.', '彼はスピード違反で罰則を受けた。', 'us_mvp_image_1055_penalty.webp', 'say-7c82d4eb-0e788417-16e97d9c-5a1cd933-0a9759e1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'faculty'), 'シンプル', 'She teaches in the law faculty.', '彼女は法学部で教えている。', 'us_mvp_image_1056_faculty.webp', 'say-f53b66fd-07ac2497-8ddc2654-99d9120f-4f0ac460.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'scheme'), 'シンプル', 'The company introduced a new bonus scheme.', 'その会社は新しいボーナス制度を導入した。', 'us_mvp_image_1057_scheme.webp', 'say-de9f008a-25e7c39e-ca7f8f88-40aeda66-b67886c9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'particle'), 'シンプル', 'Dust particles floated in the air.', 'ほこりの微粒子が空気中に漂っていた。', 'us_mvp_image_1059_particle.webp', 'say-1b665b40-238e7b5c-3c6359ca-99448367-0c8798e8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'molecule'), 'シンプル', 'A water molecule consists of two hydrogen atoms and one oxygen atom.', '水の分子は2つの水素原子と1つの酸素原子で構成されている。', 'us_mvp_image_1060_molecule.webp', 'say-e357f60e-27de9c37-d35abc04-ee4647d7-affb132e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'poll'), 'シンプル', 'The latest poll shows a change in public opinion.', '最新の世論調査は世論の変化を示している。', 'us_mvp_image_1062_poll.webp', 'say-67fb1b9e-baa1c0a6-fbd8f37f-ed0aa297-23ec9fcf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'clinic'), 'シンプル', 'She went to a dental clinic.', '彼女は歯科クリニックに行った。', 'us_mvp_image_1063_clinic.webp', 'say-813ebc70-24c66e6f-3ed832a2-e3ace