bp', 'say-5ae3bebe-96a43435-c3c9ebdc-746fc0b0-25502baa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'filter'), 'シンプル', 'The air is filtered to remove dust.', '空気はほこりを取り除くためにろ過される。', 'us_mvp_image_1104_filter.webp', 'say-9c4f53fd-22242377-34704cc9-b68f33a4-2ef573a1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'resort'), 'シンプル', 'He had to resort to violence.', '彼はやむを得ず暴力に訴えた。', 'us_mvp_image_1106_resort.webp', 'say-688443b1-1c613974-822e95cc-7051674f-0c54dead.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'grip'), 'シンプル', 'He gripped the handle tightly.', '彼はハンドルをしっかり握った。', 'us_mvp_image_1113_grip.webp', 'say-0f2d40a2-c033fab5-e38e1a6b-983f087c-35f1f378.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compound'), 'シンプル', 'His mistakes compounded the problem.', '彼のミスが問題を悪化させた。', 'us_mvp_image_1129_compound.webp', 'say-1fa8f3a6-5edf2197-f6e31aff-737a9bb0-15bf8a52.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'commute'), 'シンプル', 'He commutes to work by train.', '彼は電車で通勤している。', 'us_mvp_image_1132_commute.webp', 'say-c247fdfb-56fe0279-806f1302-12bcb3a2-44b69be4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compromise'), 'シンプル', 'They reached a compromise on the issue.', '彼らはその問題で妥協に達した。', 'us_mvp_image_1136_compromise.webp', 'say-e108782f-dbca7548-e28fb35c-c5263af9-57ce0428.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cue'), 'シンプル', 'The director gave the actor a cue.', '監督は俳優に合図を出した。', 'us_mvp_image_1142_cue.webp', 'say-11cc887d-7ca899ed-b43602d7-2f3b21f6-336fcc5e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'enterprise'), 'シンプル', 'He runs a successful enterprise.', '彼は成功した企業を経営している。', 'us_mvp_image_1143_enterprise.webp', 'say-0dbf2719-6f3fdfe0-4bc5a2d5-fd535db5-1c916d38.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'output'), 'シンプル', 'The factory’s output has increased.', 'その工場の生産量が増加した。', 'us_mvp_image_1144_output.webp', 'say-03ba518c-eb30b3d2-0a5f3a7e-8ada2c1b-e50b6909.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'estate'), 'シンプル', 'He inherited a large estate.', '彼は広大な不動産を相続した。', 'us_mvp_image_1149_estate.webp', 'say-f5a0a587-2b82dd54-0f226982-c16de88d-2ec1bfc0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'controversy'), 'シンプル', 'The new law caused a major controversy.', 'その新しい法律は大きな論争を引き起こした。', 'us_mvp_image_1152_controversy.webp', 'say-cdf31322-7f6a216d-639b5a19-5de52b3d-a0c51d14.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'consensus'), 'シンプル', 'The team reached a consensus on the project.', 'チームはそのプロジェクトについて合意に達した。', 'us_mvp_image_1153_consensus.webp', 'say-4797dfd6-a4549659-5592ccad-c7e64346-a48e5d89.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fiber'), 'シンプル', 'Fruits and vegetables are rich in fiber.', '果物や野菜には食物繊維が豊富に含まれている。', 'us_mvp_image_1155_fiber.webp', 'say-05ed57dc-6f923832-1881265b-ee115b75-858489f6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'beverage'), 'シンプル', 'Coffee is a popular beverage.', 'コーヒーは人気のある飲み物だ。', 'us_mvp_image_1157_beverage.webp', 'say-c29f5346-9a218b83-7d75f673-ecb8d1a0-8f124205.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'supplement'), 'シンプル', 'She takes vitamin supplements daily.', '彼女は毎日ビタミンサプリを摂取している。', 'us_mvp_image_1158_supplement.webp', 'say-07d4df14-33535ad2-6586bc1e-1754e5a3-c250bdd5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'province'), 'シンプル', 'He lives in a remote province.', '彼は遠く離れた地方に住んでいる。', 'us_mvp_image_1160_province.webp', 'say-b44ac449-eb7c7d41-1d9df6d7-4af12975-e274b882.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'excess'), 'シンプル', 'Excess sugar is bad for your health.', '過剰な糖分は健康に良くない。', 'us_mvp_image_1163_excess.webp', 'say-59f9f87c-bca75373-5ad74759-2e8e8e18-06e1a5f0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'gallery'), 'シンプル', 'The art gallery showcases modern paintings.', 'その美術館は現代絵画を展示している。', 'us_mvp_image_1164_gallery.webp', 'say-7ba13f9f-7bb42c43-0a4680af-0b1d9035-550bbda1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'deadline'), 'シンプル', 'The deadline for the project is next Friday.', 'そのプロジェクトの締め切りは来週の金曜日だ。', 'us_mvp_image_1166_deadline.webp', 'say-409495ef-7583e91d-2241c668-1eef8852-a4022d55.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'undergraduate'), 'シンプル', 'He is an undergraduate student at Harvard.', '彼はハーバード大学の学部生だ。', 'us_mvp_image_1167_undergraduate.webp', 'say-49656373-74e73dfc-fe694024-2673e34c-04ae3bb7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'slavery'), 'シンプル', 'Slavery was abolished in the 19th century.', '奴隷制度は19世紀に廃止された。', 'us_mvp_image_1168_slavery.webp', 'say-092a1e49-5f4251b7-96e834b6-cf7769a3-8eb18796.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'prey'), 'シンプル', 'The lion hunts its prey at night.', 'ライオンは夜に獲物を狩る。', 'us_mvp_image_1169_prey.webp', 'say-27807b71-e3583d57-ab4a9738-36e4b0aa-2ddd6824.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mess'), 'シンプル', 'His room is always a mess.', '彼の部屋はいつも散らかっている。', 'us_mvp_image_1170_mess.webp', 'say-78c4fe04-bc772f1d-dd78adfb-8de3eaa0-4f18a13a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'recession'), 'シンプル', 'The country is experiencing an economic recession.', 'その国は経済不況を経験している。', 'us_mvp_image_1171_recession.webp', 'say-e49bc69f-acccebe5-161675bb-a2505d54-640c2e37.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'retreat'), 'シンプル', 'The army was forced to retreat.', 'その軍隊は撤退を余儀なくされた。', 'us_mvp_image_1172_retreat.webp', 'say-fad19229-ec7be449-abd39912-7fbc2ca6-1a6e8a6b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'column'), 'シンプル', 'The newspaper has a daily advice column.', 'その新聞には毎日のアドバイスコラムがある。', 'us_mvp_image_1174_column.webp', 'say-937554c0-5875826c-b631be2d-488cde87-eb006f5a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'plot'), 'シンプル', 'The movie has an interesting plot.', 'その映画は面白い筋書きを持っている。', 'us_mvp_image_1176_plot.webp', 'say-ef1c25cb-8fd8734d-535854e5-8511cfcd-b08001ef.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sculpture'), 'シンプル', 'The museum has ancient sculptures.', 'その博物館には古代の彫刻がある。', 'us_mvp_image_1177_sculpture.webp', 'say-bdd696ba-710b0440-896a1ad1-10b15452-2ff85bcd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'acid'), 'シンプル', 'Lemon juice contains acid.', 'レモンジュースには酸が含まれている。', 'us_mvp_image_1181_acid.webp', 'say-15dabb3c-cb03dc56-0495a3e7-0c513e05-be97b150.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'hybrid'), 'シンプル', 'This car is a hybrid vehicle.', 'この車はハイブリッド車だ。', 'us_mvp_image_1193_hybrid.webp', 'say-647adee9-8de2c14b-49b39f96-bca20f1c-a43b45a1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'venture'), 'シンプル', 'They started a new business venture.', '彼らは新しい事業を始めた。', 'us_mvp_image_1204_venture.webp', 'say-40a8479a-260a17a1-9262084e-2596da27-36391a72.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'clip'), 'シンプル', 'She clipped the papers together.', '彼女は書類をクリップで留めた。', 'us_mvp_image_1213_clip.webp', 'say-ed55bd59-b2ad6415-ff8498e9-fdeea338-a77af44d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dye'), 'シンプル', 'She dyed her hair red.', '彼女は髪を赤く染めた。', 'us_mvp_image_1221_dye.webp', 'say-1eb2fde7-b7bb80c6-42185a36-c3490dcc-f5748a48.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spill'), 'シンプル', 'He spilled coffee on his shirt.', '彼はシャツにコーヒーをこぼした。', 'us_mvp_image_1222_spill.webp', 'say-da44e812-6d1be72a-aab3282e-e8e2e7f3-473c753d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'drain'), 'シンプル', 'The battery is draining quickly.', 'バッテリーが急速に消耗している。', 'us_mvp_image_1227_drain.webp', 'say-b32332eb-58e3f032-99a3c8fd-955fcc4e-ed70b397.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'twist'), 'シンプル', 'He twisted his ankle while running.', '彼は走っているときに足首をひねった。', 'us_mvp_image_1233_twist.webp', 'say-bb64b959-f51001e1-6347b8fb-cc242e81-d60b8e7c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'profile'), 'シンプル', 'He updated his social media profile.', '彼はSNSのプロフィールを更新した。', 'us_mvp_image_1241_profile.webp', 'say-edcd6693-c5af6ae0-564aba69-69a9d4de-c275f769.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'appetite'), 'シンプル', 'She has a good appetite.', '彼女は食欲旺盛だ。', 'us_mvp_image_1242_appetite.webp', 'say-76470459-aa375a6c-ef1454a8-ecadcaab-c2869fda.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'impulse'), 'シンプル', 'He bought the item on an impulse.', '彼は衝動的にその商品を買った。', 'us_mvp_image_1243_impulse.webp', 'say-3fd87026-eba05a12-cf059704-c4d91ced-1cbceda9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'script'), 'シンプル', 'He wrote a movie script.', '彼は映画の脚本を書いた。', 'us_mvp_image_1244_script.webp', 'say-0036da10-70b29af7-11a9f6fe-68a9bdb7-72f8fd21.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'anniversary'), 'シンプル', 'Today is our wedding anniversary.', '今日は私たちの結婚記念日だ。', 'us_mvp_image_1245_anniversary.webp', 'say-864dea11-9aa096b4-afd8aba8-721d8c6c-31297270.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pension'), 'シンプル', 'He receives a monthly pension.', '彼は毎月年金を受け取っている。', 'us_mvp_image_1246_pension.webp', 'say-f1a80952-e53ef86b-8d7a4827-144bfe4f-d7bd4517.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cortex'), 'シンプル', 'The brain''s cortex controls decision-making.', '脳の皮質は意思決定を制御する。', 'us_mvp_image_1248_cortex.webp', 'say-a2e5fcda-95d94442-47d677c4-3c4c7d1a-cde45d9e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'syndrome'), 'シンプル', 'He was diagnosed with a rare syndrome.', '彼は珍しい症候群と診断された。', 'us_mvp_image_1249_syndrome.webp', 'say-c0ecb1cc-c8935e66-06ff16dd-5e712e3e-580caddd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'chamber'), 'シンプル', 'The king entered the royal chamber.', '国王は王室に入った。', 'us_mvp_image_1250_chamber.webp', 'say-1048a732-2c4973d2-52111281-8f9aaedf-ce85395b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'utility'), 'シンプル', 'Water and electricity are basic utilities.', '水道と電気は基本的な公共サービスだ。', 'us_mvp_image_1251_utility.webp', 'say-17aa1b39-96754bb6-737c245b-ca72de96-b534da5d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cattle'), 'シンプル', 'The farmer owns a large number of cattle.', 'その農夫は多くの牛を飼っている。', 'us_mvp_image_1252_cattle.webp', 'say-eef4c21e-a1ce26a8-caf84a9b-5cdf7fa3-8f121855.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fluid'), 'シンプル', 'Drink plenty of fluids to stay hydrated.', '水分補給のために十分な液体を飲みなさい。', 'us_mvp_image_1254_fluid.webp', 'say-0ac20c7f-38328c40-c74ff963-bbfb7488-ab3ed45f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'offspring'), 'シンプル', 'The lion protected its offspring.', 'そのライオンは自分の子供を守った。', 'us_mvp_image_1258_offspring.webp', 'say-22614108-13a5c624-39fd058a-a7ab7cae-4f7efb3a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'commodity'), 'シンプル', 'Oil is an important commodity in global trade.', '石油は世界貿易において重要な商品だ。', 'us_mvp_image_1262_commodity.webp', 'say-3f5059ae-156e1d3e-759bde0e-c6609a5a-0c022e70.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'format'), 'シンプル', 'The document is in PDF format.', 'その文書はPDF形式だ。', 'us_mvp_image_1263_format.webp', 'say-0a95c08d-ce573284-34dc60a8-2c07465f-d5fe66fb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'recipient'), 'シンプル', 'She was the recipient of the award.', '彼女はその賞の受賞者だった。', 'us_mvp_image_1264_recipient.webp', 'say-fe7936e5-bdc18e61-9309a85a-45c32651-1e485186.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'inability'), 'シンプル', 'His inability to swim was a problem.', '彼が泳げないことが問題だった。', 'us_mvp_image_1266_inability.webp', 'say-7ddbaaff-a2ff319e-7ea75ce0-1574f872-fb075cbf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'republic'), 'シンプル', 'France is a republic.', 'フランスは共和国だ。', 'us_mvp_image_1267_republic.webp', 'say-2389e596-6a0f6755-41fe46fb-d189cafb-1dcf40cb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'combat'), 'シンプル', 'The government is taking steps to combat crime.', '政府は犯罪に対処するための措置を取っている。', 'us_mvp_image_1268_combat.webp', 'say-3c7da817-19b886ac-03ca72df-9b81bbc8-310957fe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fraction'), 'シンプル', 'Only a small fraction of students passed the exam.', 'ほんの一部の生徒しか試験に合格しなかった。', 'us_mvp_image_1271_fraction.webp', 'say-be18bb31-c28a832c-2fe13b74-61ab096a-f148101b.mp3', NOW(), NOW());
