INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('index', '指標、索引／索引を付ける', 'noun', 'ラテン語「index（指さすもの）」に由来し、「索引、指標」という意味になった。', NOW(), NOW()),('motive', '動機、理由', 'noun', 'ラテン語「movere（動かす）」に由来し、「動機、原動力」という意味になった。', NOW(), NOW()),('hierarchy', '階級制度、ヒエラルキー', 'noun', 'ギリシア語「hieros（神聖な）」と「archein（支配する）」が結合して「階層制度、聖職制度」という意味になった。', NOW(), NOW()),('asset', '資産、財産', 'noun', 'ラテン語「ad satis（十分な）」が由来で、「資産、有用なもの」という意味になった。', NOW(), NOW()),('demographic', '人口統計の／人口層', 'noun', 'ギリシア語「demos（人々）」と「graphia（記述）」が結合して「人口統計の」という意味になった。', NOW(), NOW()),('wireless', '無線の', 'noun', '「wire（電線）」と「〜のない」の「-less」が結合して「無線の」という意味になった。', NOW(), NOW()),('whisper', 'ささやく／ささやき', 'noun', '古英語「hwisprian（ささやく）」に由来し、「ささやく」という意味になった。', NOW(), NOW()),('deposit', '預ける、堆積する／預金、堆積物', 'noun', 'ラテン語「de-（下に）」と「ponere（置く）」が結合して「預ける、堆積させる」という意味になった。', NOW(), NOW()),('outline', '概要を述べる／概要、輪郭', 'noun', '「外側」の「out」と「線」の「line」が結合して「輪郭、要点を述べる」という意味になった。', NOW(), NOW()),('strain', '緊張、負担／緊張させる、酷使する', 'noun', 'ラテン語「stringere（締め付ける）」が変化して「緊張、負担、引っ張る」という意味になった。', NOW(), NOW()),('dare', 'あえて～する、挑戦する', 'noun', '古英語「dearr（あえてする）」に由来し、「あえて〜する、挑戦する」という意味になった。', NOW(), NOW()),('paradox', '矛盾、逆説', 'noun', 'ギリシア語「para（逆に）」と「doxa（意見）」が結合して「逆説、矛盾」という意味になった。', NOW(), NOW()),('parliament', '議会、国会', 'noun', 'フランス語「parler（話す）」が語源で、「議会、国会」という意味になった。', NOW(), NOW()),('legislation', '法律、立法', 'noun', 'ラテン語「lex（法）」と「-lation（行為）」が結合して「立法、法律制定」という意味になった。', NOW(), NOW()),('agenda', '議題、課題', 'noun', 'ラテン語「agere（する）」の未来受動分詞で「すべきこと」という意味になった。', NOW(), NOW()),('mainstream', '主流／主流の', 'noun', '「主な」の「main」と「流れ」の「stream」が結合して「主流」という意味になった。', NOW(), NOW()),('troop', '軍隊、部隊', 'noun', 'フランス語「troupe（集団）」に由来し、「軍隊、部隊」という意味になった。', NOW(), NOW()),('outbreak', '発生、突発', 'noun', '「外へ」の「out」と「破裂する」の「break」が結合して「発生、突発」という意味になった。', NOW(), NOW()),('chaos', '混乱、無秩序', 'noun', 'ギリシア語「khaos（混沌、空虚）」に由来し、「混乱、無秩序」という意味になった。', NOW(), NOW()),('horror', '恐怖、戦慄', 'noun', 'ラテン語「horrere（震える、恐れる）」に由来し、「恐怖」という意味になった。', NOW(), NOW()),('cluster', '集団、群れ／群がる', 'noun', '古英語「clyster（束、集まり）」に由来し、「群れ、集団」という意味になった。', NOW(), NOW()),('irrigation', '灌漑、水を引くこと', 'noun', 'ラテン語「irrigo（潤す）」が名詞化して「灌漑、水を引くこと」という意味になった。', NOW(), NOW()),('dose', '服用量、一回分／投与する', 'noun', 'ギリシア語「dosis（与えること）」に由来し、「一服、服用量」という意味になった。', NOW(), NOW()),('suicide', '自殺', 'noun', 'ラテン語「sui（自分自身）」と「caedere（殺す）」が結合して「自殺」という意味になった。', NOW(), NOW()),('rumor', '噂／噂を流す', 'noun', 'ラテン語「rumor（うわさ）」に由来し、「噂、風説」という意味になった。', NOW(), NOW()),('signature', '署名、サイン', 'noun', 'ラテン語「signare（印をつける）」が名詞化して「署名、サイン」という意味になった。', NOW(), NOW()),('formula', '公式、決まり文句', 'noun', 'ラテン語「forma（形）」に由来し、「公式、決まり文句」という意味になった。', NOW(), NOW()),('spectrum', '範囲、スペクトル', 'noun', 'ラテン語「specere（見る）」が名詞化して「光のスペクトル、範囲」という意味になった。', NOW(), NOW()),('kidney', '腎臓', 'noun', '古英語「cydne（腎臓）」に由来し、「腎臓」という意味になった。', NOW(), NOW()),('gear', '道具、歯車／調整する', 'noun', '古ノルド語「gervi（装備）」に由来し、「装置、歯車、装備」という意味になった。', NOW(), NOW()),('aisle', '通路、列', 'noun', 'ラテン語「ala（翼）」から派生し、教会の側廊を指すようになり、「通路」という意味になった。', NOW(), NOW()),('disguise', '変装する、偽る／変装', 'noun', '"反対の"の「dis-」と"姿、風貌"の「guise（外観）」が結合して「変装する」という意味になった。', NOW(), NOW()),('internship', 'インターンシップ、研修', 'noun', '「intern（実習生）」と名詞化の「-ship」が結合して「インターン期間」という意味になった。', NOW(), NOW()),('outlet', '店舗、はけ口', 'noun', '"外へ"の「out-」と"出る"の「let（放す）」が結合して「出口、発散口」という意味になった。', NOW(), NOW()),('pill', '錠剤', 'noun', 'ラテン語「pila（小球）」に由来し、「錠剤」という意味になった。', NOW(), NOW()),('reception', '受付、歓迎会', 'noun', '"後に受け取る"の「re-」と"取る"の「capere」が結合して「受け入れ、受付」という意味になった。', NOW(), NOW()),('transaction', '取引、業務', 'noun', '"通して"の「trans-」と"行う"の「agere」が結合して「取引」という意味になった。', NOW(), NOW()),('mutation', '突然変異', 'noun', 'ラテン語「mutare（変える）」に由来し、「突然変異、変化」という意味になった。', NOW(), NOW()),('census', '国勢調査', 'noun', 'ラテン語「censere（評価する）」に由来し、「国勢調査」という意味になった。', NOW(), NOW()),('encyclopedia', '百科事典', 'noun', 'ギリシア語「enkyklios paideia（全体的な教育）」から、「百科事典」という意味になった。', NOW(), NOW()),('fragment', '破片、断片／粉々にする', 'noun', 'ラテン語「frangere（壊す）」の過去分詞「fragmentum」に由来し、「断片」という意味になった。', NOW(), NOW()),('outlook', '見通し、考え方', 'noun', '"外を見る"の「out-」と"look"が結合して「展望、見通し」という意味になった。', NOW(), NOW()),('breakthrough', '飛躍的進展、突破口', 'noun', '「突き破る」意味の「break」と「通過」意味の「through」が結合して「突破口」という意味になった。', NOW(), NOW()),('ally', '同盟国、味方／同盟を結ぶ', 'noun', '"〜へ"の「ad-」と"結ぶ"の「ligare」が結合して「同盟を結ぶ」という意味になった。', NOW(), NOW()),('sphere', '球、領域', 'noun', 'ギリシア語「sphaira（球）」に由来し、「球、領域」という意味になった。', NOW(), NOW()),('county', '郡、行政区', 'noun', '「伯爵」の意味のラテン語「comes」から派生し、「伯爵領」→「郡」という意味になった。', NOW(), NOW()),('behalf', '～のために、代理で', 'noun', '中英語「bi half（〜側で）」から派生し、「〜のために」という意味になった。', NOW(), NOW()),('interval', '間隔、休止', 'noun', '"間"の「inter-」と"壁"の「vallum」が結合して「間隔、休止」という意味になった。', NOW(), NOW()),('circulation', '循環、流通、発行部数', 'noun', '"回る"の「circulare」から派生し、「循環、流通」という意味になった。', NOW(), NOW()),('theft', '盗難、窃盗', 'noun', '古英語「theof（盗人）」から派生し、「盗み、窃盗」という意味になった。', NOW(), NOW()),('vacuum', '真空、空白', 'noun', 'ラテン語「vacuus（空の）」に由来し、「真空、空白」という意味になった。', NOW(), NOW()),('bargain', 'お買い得品、交渉／交渉する', 'noun', '古フランス語「bargaigner（交渉する）」に由来し、「取引、掘り出し物」という意味になった。', NOW(), NOW()),('revenue', '収益、収入', 'noun', '"戻ってくる"の「re-」と"来る"の「venire」が結合して「歳入、収益」という意味になった。', NOW(), NOW()),('treaty', '条約、協定', 'noun', 'ラテン語「tractare（扱う）」から派生し、「条約、協定」という意味になった。', NOW(), NOW()),('alternate', '交互の、代わりの／交互にする', 'noun', '"他の"の「alter」と「交互の、代わりの」という意味の形容詞語尾「-ate」が結合して「交互の、代替の」という意味になった。', NOW(), NOW()),('own', '所有する／自分自身の', 'determiner', '古英語「āgen（自身の）」が語源で、「own」は"所有する"という意味になった。', NOW(), NOW()),('whereas', '～であるのに対して', 'conjunction', '中英語「wher-as（〜するところの）」が変化して、「一方で」という意味になった。', NOW(), NOW()),('eventually', '最終的に', 'adverb', 'ラテン語「eventus（結果）」に由来し、「eventually」は"最終的に"という意味になった。', NOW(), NOW()),('overseas', '海外の／海外へ', 'adverb', '「海」の「sea」と「越えて」の「over」が結合して「海外の」という意味になった。', NOW(), NOW()),('nevertheless', 'それにもかかわらず', 'adverb', '「それにもかかわらず」の意味で、複合語として形成された。', NOW(), NOW()),('somewhat', 'いくぶん、多少', 'adverb', '「some（ある程度）」と「what（何か）」が結合して「いくぶん」という意味になった。', NOW(), NOW()),('forth', '前へ、外へ', 'adverb', '古英語「forth（前へ）」に由来し、「前へ、以後」という意味になった。', NOW(), NOW()),('nonetheless', 'それにもかかわらず', 'adverb', '「none（何も〜ない）」＋「the」＋「less（にもかかわらず）」が結合して「それでもなお」という意味になった。', NOW(), NOW()),('simultaneously', '同時に', 'adverb', 'ラテン語「simul（同時に）」と「-taneous（〜のような）」が結合して「同時に」という意味になった。', NOW(), NOW()),('appropriate', '適切な', 'adjective', '〜への「ad-」と"自分のものにする"の「propriare」が結合して"適切な"という意味になった。', NOW(), NOW()),('likely', 'ありそうな', 'adjective', '古英語「lic（体裁がよい）」に由来し、「likely」は"ありそうな"という意味になった。', NOW(), NOW()),('possible', '可能な', 'adjective', '〜できるの「possibilis（ラテン語）」が語源で、「possible」は"可能な"という意味になった。', NOW(), NOW()),('public', '公共の／公衆', 'adjective', 'ラテン語「publicus（公共の）」が語源で、「public」は"公共の・公衆"という意味になった。', NOW(), NOW()),('common', '一般的な、共通の', 'adjective', '共にの「com-」と"義務"の「munis」が結合して"共通の"という意味になった。', NOW(), NOW()),('certain', '確実な、ある程度の', 'adjective', '確かなのラテン語「certus」が語源で、「certain」は"確かな"という意味になった。', NOW(), NOW()),('similar', '似ている', 'adjective', 'ラテン語「similis（似た）」が語源で、「similar」は"類似した"という意味になった。', NOW(), NOW()),('recent', '最近の', 'adjective', 'ラテン語「recentem（新しい）」が語源で、「recent」は"最近の"という意味になった。', NOW(), NOW()),('major', '主要な／専攻', 'adjective', 'ラテン語「maior（より大きい）」が語源で、「major」は"主要な・大きい"という意味になった。', NOW(), NOW()),('patient', '患者／忍耐強い', 'adjective', '苦しむのラテン語「patior」が語源で、「patient」は"患者・我慢強い人"という意味になった。', NOW(), NOW()),('particular', '特定の、特別な', 'adjective', 'ラテン語「particularis（部分的な）」が語源で、「particular」は"特定の"という意味になった。', NOW(), NOW()),('physical', '身体の、物理的な', 'adjective', 'ラテン語「physica（自然の学）」が語源で、「physical」は"物理的・身体的"という意味になった。', NOW(), NOW()),('various', 'さまざまな', 'adjective', 'ラテン語「varius（多様な）」が語源で、「various」は"様々な"という意味になった。', NOW(), NOW()),('available', '利用可能な', 'adjective', '〜の方への「ad-」と"跳ぶ"の「valere」が結合して"利用可能な"という意味になった。', NOW(), NOW()),('political', '政治の', 'adjective', 'ギリシャ語「politikos（市民の）」が語源で、「political」は"政治の"という意味になった。', NOW(), NOW()),('due', '期限の、～が原因で', 'adjective', 'ラテン語「debere（〜すべき）」が語源で、「due」は"〜する予定の"という意味になった。', NOW(), NOW()),('blank', '空白の／空白', 'adjective', 'フランス語「blanc（白）」が語源で、「blank」は"空白の"という意味になった。', NOW(), NOW()),('ancient', '古代の', 'adjective', 'ラテン語「ante（前に）」が語源で、「ancient」は"古代の"という意味になった。', NOW(), NOW()),('correct', '正しい／訂正する', 'adjective', '共にの「com-」と"まっすぐにする"の「regere」が結合して"正す"という意味になった。', NOW(), NOW()),('positive', '前向きな、肯定的な', 'adjective', '"置く"の「ponere」から派生し、「positive」は"肯定的な・積極的な"という意味になった。', NOW(), NOW()),('negative', '否定的な、マイナスの', 'adjective', '"否定する"のラテン語「negare」が語源で、「negative」は"否定的な・負の"という意味になった。', NOW(), NOW()),('complex', '複雑な／複合体', 'adjective', '"共に"の「com-」と"編む"の「plectere」が結合して"複雑な"という意味になった。', NOW(), NOW()),('current', '現在の／流れ', 'adjective', 'ラテン語「currere（走る）」が語源で、「current」は"現在の・流れ"という意味になった。', NOW(), NOW()),('mental', '精神の、心の', 'adjective', 'ラテン語「mens（心）」が語源で、「mental」は"精神の"という意味になった。', NOW(), NOW()),('specific', '特定の、具体的な', 'adjective', '"種"を意味するラテン語「species」から派生し、「specific」は"特定の"という意味になった。', NOW(), NOW()),('significant', '重要な、意義のある', 'adjective', '"印をつける"の「signare」と"〜のような"の「-ficant」が結合して"重要な"という意味になった。', NOW(), NOW()),('essential', '必要不可欠な', 'adjective', '"存在する"の「esse」に由来し、「essential」は"本質的な・不可欠な"という意味になった。', NOW(), NOW()),('official', '公式の／公務員', 'adjective', 'ラテン語「officium（職務）」が語源で、「official」は"公式の"という意味になった。', NOW(), NOW()),('financial', '財政の', 'adjective', 'ラテン語「finis（終わり・支払い）」に由来し、「financial」は"財政の"という意味になった。', NOW(), NOW()),('academic', '学問の／学者', 'adjective', 'ギリシャ語「Akadēmeia（プラトンの学園）」が語源で、「academic」は"学問の"という意味になった。', NOW(), NOW()),('aware', '気づいている', 'adjective', '古英語「gewær（気づいて）」が語源で、「aware」は"気づいている"という意味になった。', NOW(), NOW()),('potential', '潜在的な／可能性', 'adjective', '"力"のラテン語「potentia」が語源で、「potential」は"可能性のある"という意味になった。', NOW(), NOW()),('active', '活動的な', 'adjective', 'ラテン語「agere（行う）」が語源で、「active」は"活動的な"という意味になった。', NOW(), NOW()),('digital', 'デジタルの', 'adjective', 'ラテン語「digitus（指）」が語源で、「digital」は"数字の・デジタルの"という意味になった。', NOW(), NOW()),('mobile', '移動できる、携帯の', 'adjective', 'ラテン語「movere（動く）」が語源で、「mobile」は"移動可能な"という意味になった。', NOW(), NOW()),('necessary', '必要な', 'adjective', '"避けられない"のラテン語「necessarius」が語源で、「necessary」は"必要な"という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'index'), 'シンプル', 'The book has a detailed index.', 'その本には詳細な索引がある。', 'us_mvp_image_1272_index.webp', 'say-15d5a1d7-1d2be2c0-298f7e90-566c4766-c97109b3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'motive'), 'シンプル', 'The police investigated his motive for the crime.', '警察は彼の犯罪の動機を調査した。', 'us_mvp_image_1274_motive.webp', 'say-d3e8f1ed-a9095806-8b1b74f6-1c1c06ac-2d71c87d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'hierarchy'), 'シンプル', 'The company has a strict hierarchy.', 'その会社には厳格な階級制度がある。', 'us_mvp_image_1276_hierarchy.webp', 'say-6092ddf7-5b316bef-4f03b01a-b746ea64-f86bb474.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'asset'), 'シンプル', 'His house is his most valuable asset.', '彼の家は最も価値のある資産だ。', 'us_mvp_image_1278_asset.webp', 'say-fa184a85-875dfa38-a8ffbc9e-dda3c856-d5fb3b53.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'demographic'), 'シンプル', 'The company is targeting a younger demographic.', 'その会社は若い人口層をターゲットにしている。', 'us_mvp_image_1288_demographic.webp', 'say-eb714bb4-6ea7b8fe-ac060bc8-2347711d-d571948a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'wireless'), 'シンプル', 'I bought a wireless charger.', '私は無線充電器を買った。', 'us_mvp_image_1299_wireless.webp', 'say-bc5fa0fa-95805765-28bcf2fb-2de7d431-ee7080d5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'whisper'), 'シンプル', 'She whispered a secret to me.', '彼女は私に秘密をささやいた。', 'us_mvp_image_1313_whisper.webp', 'say-cbd34773-c469f3b2-0ccd6784-004b43f8-c25c291e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'deposit'), 'シンプル', 'He deposited $500 into his bank account.', '彼は銀行口座に500ドルを預けた。', 'us_mvp_image_1315_deposit.webp', 'say-47abdc60-ddea4f0a-ba4dbb13-4458943f-165830ba.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'outline'), 'シンプル', 'The teacher outlined the main points.', '先生は要点を説明した。', 'us_mvp_image_1320_outline.webp', 'say-2e5afc87-54fbcadb-0f07cd9a-dceba674-8f7a59cb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'strain'), 'シンプル', 'The heavy workload put a strain on her health.', '重い仕事が彼女の健康に負担をかけた。', 'us_mvp_image_1326_strain.webp', 'say-d5958084-e04536f3-65dcd099-6e8c1e61-82c9362c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dare'), 'シンプル', 'She dared to speak her mind.', '彼女はあえて自分の意見を言った。', 'us_mvp_image_1328_dare.webp', 'say-ec3b41a6-c1809af3-7d2bc521-0bfef6dd-0e010bfe.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'paradox'), 'シンプル', 'It is a paradox that technology makes life easier but more stressful.', '技術が生活を楽にする一方で、ストレスを増やすのは矛盾している。', 'us_mvp_image_1344_paradox.webp', 'say-ad472f86-0eceec5a-3f2c13ea-8d169974-847f0d0c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'parliament'), 'シンプル', 'The law was passed by parliament.', 'その法律は議会で可決された。', 'us_mvp_image_1345_parliament.webp', 'say-f99c6928-e67615ef-6d2738e2-881d1728-f85d16e9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'legislation'), 'シンプル', 'New legislation was introduced to improve education.', '教育改善のために新しい法律が導入された。', 'us_mvp_image_1346_legislation.webp', 'say-9f27f1ad-6db67170-d5218419-7fa795ab-3bab157f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'agenda'), 'シンプル', 'Climate change is on the government''s agenda.', '気候変動は政府の議題にある。', 'us_mvp_image_1347_agenda.webp', 'say-0a5fd95a-399c658a-bc2128e3-41dc093a-7848f326.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mainstream'), 'シンプル', 'His ideas are now part of the mainstream.', '彼の考えは今や主流の一部となっている。', 'us_mvp_image_1348_mainstream.webp', 'say-415231ae-feebc053-2f6a88e2-e7faf2d5-c6d57fa3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'troop'), 'シンプル', 'The country deployed troops to the border.', 'その国は国境に軍隊を配備した。', 'us_mvp_image_1349_troop.webp', 'say-1841ed49-c3990680-403e2a27-e6425063-66663438.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'outbreak'), 'シンプル', 'The outbreak of the disease caused panic.', 'その病気の発生がパニックを引き起こした。', 'us_mvp_image_1351_outbreak.webp', 'say-3b04f190-1e13cf78-381ad3ec-c3d862eb-8676c4b5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'chaos'), 'シンプル', 'The city was in chaos after the earthquake.', 'その地震の後、街は混乱に陥った。', 'us_mvp_image_1352_chaos.webp', 'say-dd344b7d-cb4a3aa4-6472d240-cd927369-971894e6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'horror'), 'シンプル', 'She watched a horror movie alone.', '彼女は一人でホラー映画を見た。', 'us_mvp_image_1354_horror.webp', 'say-d4565401-c5cda8f6-3219f0ca-fab8d3ba-bce37def.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cluster'), 'シンプル', 'A cluster of stars was visible in the sky.', '空に星の集まりが見えた。', 'us_mvp_image_1355_cluster.webp', 'say-6158c7c0-88ee578f-178a63b3-0bf9f343-bea0b043.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'irrigation'), 'シンプル', 'Irrigation systems are essential for farming.', '灌漑システムは農業に不可欠だ。', 'us_mvp_image_1358_irrigation.webp', 'say-deb6f323-8e1ed4a0-49dc5618-84b98bd2-323c0cde.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dose'), 'シンプル', 'Take one dose of medicine before bed.', '寝る前に薬を1回分服用してください。', 'us_mvp_image_1359_dose.webp', 'say-70f74556-87bf6f22-e3f5899c-6a33ade1-841e2bce.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'suicide'), 'シンプル', 'He struggled with depression and attempted suicide.', '彼はうつ病と闘い、自殺を試みた。', 'us_mvp_image_1360_suicide.webp', 'say-1a94986b-d86b0a44-cf52004e-0924cfd8-1af856f6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rumor'), 'シンプル', 'There is a rumor that he will quit his job.', '彼が仕事を辞めるという噂がある。', 'us_mvp_image_1363_rumor.webp', 'say-fe6d7e5e-a3dcb39e-cc769e72-4b0e4415-ee032225.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'signature'), 'シンプル', 'Please put your signature here.', 'ここに署名してください。', 'us_mvp_image_1365_signature.webp', 'say-1103a8ad-3bb31ced-a79ad389-916e1a8a-d1f444f2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'formula'), 'シンプル', 'This chemical formula represents water.', 'この化学式は水を表している。', 'us_mvp_image_1366_formula.webp', 'say-a16ab9b8-a877dbcc-4a8953ef-59a71e13-39838d41.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spectrum'), 'シンプル', 'The political spectrum includes many ideologies.', '政治的スペクトルには多くの思想が含まれる。', 'us_mvp_image_1369_spectrum.webp', 'say-4fa43364-5664dd7e-068398f9-44aaf834-083aa24d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'kidney'), 'シンプル', 'He has a kidney disease.', '彼は腎臓の病気を持っている。', 'us_mvp_image_1370_kidney.webp', 'say-8971768d-5acb0076-537523ef-3095ac09-d680e1d2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'gear'), 'シンプル', 'He put on his hiking gear.', '彼は登山用具を身につけた。', 'us_mvp_image_1371_gear.webp', 'say-adcda4f0-af2bd4dc-ce5f3b8c-ea94175c-a1d8d9e3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'aisle'), 'シンプル', 'She walked down the aisle at her wedding.', '彼女は結婚式で通路を歩いた。', 'us_mvp_image_1372_aisle.webp', 'say-340d5868-6908dbe3-eb60170c-73ab572d-246e2112.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disguise'), 'シンプル', 'He disguised himself as a police officer.', '彼は警察官に変装した。', 'us_mvp_image_1430_disguise.webp', 'say-e71e6cc1-0691ea09-4e680240-fd174530-35b96aa4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'internship'), 'シンプル', 'She got an internship at a famous company.', '彼女は有名な会社でインターンシップを得た。', 'us_mvp_image_1442_internship.webp', 'say-e683a5a1-593c36a5-3fc52a60-4ac8e0e6-e9af57ac.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'outlet'), 'シンプル', 'This brand has many outlets worldwide.', 'このブランドは世界中に多くの店舗を持っている。', 'us_mvp_image_1443_outlet.webp', 'say-b38e90cc-1e6124bc-5f8c8b7b-11251358-aca242c7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pill'), 'シンプル', 'She took a sleeping pill.', '彼女は睡眠薬を飲んだ。', 'us_mvp_image_1445_pill.webp', 'say-f2ec6a9b-d0cb3e37-d45f159f-305cb789-d2f48117.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reception'), 'シンプル', 'The hotel reception is on the first floor.', 'そのホテルの受付は1階にある。', 'us_mvp_image_1446_reception.webp', 'say-ac3924e8-bb292af7-6e4ebc76-8cb419f6-a0e0a89b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'transaction'), 'シンプル', 'The bank records all transactions.', 'その銀行はすべての取引を記録する。', 'us_mvp_image_1447_transaction.webp', 'say-7d61c70e-8aedd6b0-b5e8fbeb-7a4e3da2-a5f003b1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mutation'), 'シンプル', 'Genetic mutation can cause disease.', '遺伝子の突然変異が病気を引き起こすことがある。', 'us_mvp_image_1448_mutation.webp', 'say-deea1f4c-a00dda42-1a266cbe-98211f0a-7d5c343b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'census'), 'シンプル', 'The government conducts a census every ten years.', '政府は10年ごとに国勢調査を実施する。', 'us_mvp_image_1454_census.webp', 'say-95a2aa89-adabaf69-f61fd94b-63180c8a-9dfd95d1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'encyclopedia'), 'シンプル', 'He looked up the information in an encyclopedia.', '彼はその情報を百科事典で調べた。', 'us_mvp_image_1455_encyclopedia.webp', 'say-7a8957f7-5a0a1e85-e58d5846-770a2f8b-faa0e785.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fragment'), 'シンプル', 'The glass broke into fragments.', 'そのガラスは粉々になった。', 'us_mvp_image_1457_fragment.webp', 'say-1e7ac4d7-6de79703-4dd403c4-ebbbac48-96486e9d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'outlook'), 'シンプル', 'The economic outlook is positive.', '経済の見通しは明るい。', 'us_mvp_image_1461_outlook.webp', 'say-553aeade-38f11f02-dd29dec9-872d3828-319e7843.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'breakthrough'), 'シンプル', 'Scientists made a major breakthrough in cancer research.', '科学者たちはがん研究で大きな進展を遂げた。', 'us_mvp_image_1462_breakthrough.webp', 'say-cd2678c9-23194324-dcd86c68-24b82dba-85167baa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ally'), 'シンプル', 'The country is a strong ally of the United States.', 'その国はアメリカの強い同盟国だ。', 'us_mvp_image_1464_ally.webp', 'say-cbb0e066-ffd35c84-b28709df-7dc81308-55407f53.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sphere'), 'シンプル', 'The earth is a sphere.', '地球は球体である。', 'us_mvp_image_1466_sphere.webp', 'say-71f8f76f-c5c685f3-a2e4205a-6928cbb7-53040a5e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'county'), 'シンプル', 'He lives in a small county in Texas.', '彼はテキサス州の小さな郡に住んでいる。', 'us_mvp_image_1467_county.webp', 'say-7f636dc8-6abbf514-c6b6c778-130b1549-448ca761.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'behalf'), 'シンプル', 'She spoke on behalf of her team.', '彼女はチームを代表して話した。', 'us_mvp_image_1468_behalf.webp', 'say-e3eaf1c4-aa33fda6-a38cac6b-7b6285c5-3afbca46.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'interval'), 'シンプル', 'There was a short interval between performances.', '演奏の間に短い休憩があった。', 'us_mvp_image_1469_interval.webp', 'say-71c88e88-d117efa0-e17fa530-5c026602-13482642.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'circulation'), 'シンプル', 'The newspaper has a wide circulation.', 'その新聞は広く流通している。', 'us_mvp_image_1470_circulation.webp', 'say-4b9d1338-5a67b61e-89fe4607-0b2d562e-b668fc4a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'theft'), 'シンプル', 'He was arrested for theft.', '彼は窃盗の罪で逮捕された。', 'us_mvp_image_1472_theft.webp', 'say-f8934f4a-ed506793-6acb2d58-efcba63d-8b62ebe6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'vacuum'), 'シンプル', 'There was a vacuum in leadership after the CEO resigned.', 'CEOが辞任した後、リーダーシップに空白が生じた。', 'us_mvp_image_1473_vacuum.webp', 'say-e4433d2e-083d9540-5bb45b08-78db4930-10dced45.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bargain'), 'シンプル', 'I got a great bargain on this jacket.', '私はこのジャケットをお買い得価格で手に入れた。', 'us_mvp_image_1475_bargain.webp', 'say-23fc0723-0c0d744a-89e03cb7-03bb6d9b-2d503112.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'revenue'), 'シンプル', 'The company’s revenue increased this year.', 'その会社の収益は今年増加した。', 'us_mvp_image_1477_revenue.webp', 'say-a201d669-51c8ac1d-94e00803-a1cf9576-5d2c7f2a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'treaty'), 'シンプル', 'The two countries signed a peace treaty.', 'その2か国は平和条約に署名した。', 'us_mvp_image_1478_treaty.webp', 'say-ebd38375-1bcae520-5fb21e08-af6345f1-6bb1122b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'alternate'), 'シンプル', 'We take alternate routes to avoid traffic.', '私たちは渋滞を避けるために交互のルートを利用する。', 'us_mvp_image_1490_alternate.webp', 'say-33428e9a-bf767bcf-721a9dd8-41266a4a-cae36de7.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'own'), 'シンプル', 'He owns a small business.', '彼は小さな会社を所有している。', 'us_mvp_image_0005_own.webp', 'say-954b89e6-75cf0fac-a1cabae9-3dbf1aff-da11e75e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'whereas'), 'シンプル', 'She likes tea, whereas I prefer coffee.', '彼女は紅茶が好きなのに対し、私はコーヒーが好きだ。', 'us_mvp_image_0300_whereas.webp', 'say-ca92e4b4-449a417f-17ce0c5f-de8617ab-22d0e928.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'eventually'), 'シンプル', 'He eventually became a doctor.', '彼は最終的に医者になった。', 'us_mvp_image_0200_eventually.webp', 'say-b0f58214-831b3df1-8670dcd9-cbcfccb4-f83ca43c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'overseas'), 'シンプル', 'He works for an overseas company.', '彼は海外の会社で働いている。', 'us_mvp_image_0399_overseas.webp', 'say-b40d1076-be2d8d48-96652c4c-3e43b93f-1eafff75.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'nevertheless'), 'シンプル', 'It was raining; nevertheless, we went hiking.', '雨が降っていたが、それでもハイキングに行った。', 'us_mvp_image_0400_nevertheless.webp', 'say-fe162ac9-4649a866-9ec874e9-a1098d79-d6ab726f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'somewhat'), 'シンプル', 'The weather is somewhat cold today.', '今日の天気は少し寒い。', 'us_mvp_image_0500_somewhat.webp', 'say-b20b738c-dad2959f-3b61f998-5445f342-8fd42e59.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'forth'), 'シンプル', 'He stepped forth to speak.', '彼は前へ出て話し始めた。', 'us_mvp_image_0700_forth.webp', 'say-17104bdc-55d75338-fd4e5bf9-c151caf8-98af2a4c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'nonetheless'), 'シンプル', 'It was raining; nonetheless, they went hiking.', '雨が降っていたが、それにもかかわらず彼らはハイキングに行った。', 'us_mvp_image_1000_nonetheless.webp', 'say-01321584-c31d6791-43c53fb5-3dc630b0-10ff112f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'simultaneously'), 'シンプル', 'They spoke simultaneously.', '彼らは同時に話した。', 'us_mvp_image_1099_simultaneously.webp', 'say-dde9d586-04043a8c-ea8833bf-f0dd9fc3-c5c81f66.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'appropriate'), 'シンプル', 'That is not an appropriate comment.', 'それは適切なコメントではない。', 'us_mvp_image_0079_appropriate.webp', 'say-8308ae32-8008d78c-42489b5a-2d258352-f6ec32ec.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'likely'), 'シンプル', 'It is likely to rain tomorrow.', '明日は雨が降る可能性が高い。', 'us_mvp_image_0080_likely.webp', 'say-09e95a8c-d04c1810-320afe29-77c3d122-eea911e0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'possible'), 'シンプル', 'Is it possible to change the plan?', 'その計画を変更することは可能ですか？', 'us_mvp_image_0081_possible.webp', 'say-d4324894-561a2707-b9dcc4c7-a5a71254-a9c4081f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'public'), 'シンプル', 'The park is open to the public.', 'その公園は一般に公開されている。', 'us_mvp_image_0083_public.webp', 'say-dbf6e388-0df6e44d-072dc1a5-4e85df5a-6bf0238e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'common'), 'シンプル', 'This is a common mistake.', 'これはよくある間違いだ。', 'us_mvp_image_0084_common.webp', 'say-4379145c-33204b25-f0d6e9b9-5024aca0-3f030b4a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'certain'), 'シンプル', 'I am certain about my decision.', '私は自分の決定に確信がある。', 'us_mvp_image_0085_certain.webp', 'say-16c67bad-552e54da-a97f65c8-4d864d72-61a69f35.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'similar'), 'シンプル', 'These two designs are similar.', 'この2つのデザインは似ている。', 'us_mvp_image_0086_similar.webp', 'say-ef8bf161-86ba04b5-d9558ae1-642c2974-b0f25fa3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'recent'), 'シンプル', 'This is a recent study.', 'これは最近の研究だ。', 'us_mvp_image_0087_recent.webp', 'say-03309d12-b4f3d3cc-28d8333f-caa3bd5b-18b3571d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'major'), 'シンプル', 'He is a major figure in politics.', '彼は政治の主要な人物だ。', 'us_mvp_image_0088_major.webp', 'say-6b641d8d-018e81bd-7d9ba702-c6d7b88e-f53fb757.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'patient'), 'シンプル', 'The doctor is treating a patient.', 'その医者は患者を診ている。', 'us_mvp_image_0089_patient.webp', 'say-f85b8b23-75a42c03-51cf0be4-171f57df-fceff862.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'particular'), 'シンプル', 'I have a particular interest in music.', '私は音楽に特別な関心がある。', 'us_mvp_image_0090_particular.webp', 'say-e36e1a37-9e1d71d6-f0389068-25b0b8f5-0477fac2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'physical'), 'シンプル', 'Regular exercise is good for physical health.', '定期的な運動は身体の健康に良い。', 'us_mvp_image_0091_physical.webp', 'say-93586c4b-7de929a0-b5c6e81a-ea9867e1-9112d825.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'various'), 'シンプル', 'There are various ways to solve this problem.', 'この問題を解決する方法は様々ある。', 'us_mvp_image_0092_various.webp', 'say-c81f0823-9f39ff3e-94d0a368-4efa7d28-f6068e70.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'available'), 'シンプル', 'The product is available in stores.', 'その商品は店頭で購入できる。', 'us_mvp_image_0093_available.webp', 'say-b216cdee-7feb53b3-81fc174d-50bea7c4-332eb95f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'political'), 'シンプル', 'He is interested in political issues.', '彼は政治問題に関心がある。', 'us_mvp_image_0095_political.webp', 'say-b4b07825-3f48f6ed-d50bcb2c-79b8bb08-ee40e143.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'due'), 'シンプル', 'The report is due tomorrow.', 'その報告書の締め切りは明日だ。', 'us_mvp_image_0096_due.webp', 'say-b0efe831-cd190478-9ebf755e-1cbf626b-3e1a2691.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'blank'), 'シンプル', 'Fill in the blank spaces.', '空白の部分を埋めなさい。', 'us_mvp_image_0097_blank.webp', 'say-968ad817-7f13e2c2-defa1660-8c72d1a7-e2149927.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ancient'), 'シンプル', 'They found ancient ruins.', '彼らは古代の遺跡を発見した。', 'us_mvp_image_0098_ancient.webp', 'say-e5865a9c-13f35d9c-8ab9a817-311323f4-5b58bbc3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'correct'), 'シンプル', 'That answer is correct.', 'その答えは正しい。', 'us_mvp_image_0099_correct.webp', 'say-32b2377e-67950533-9793786b-6e8c299d-cad9a2e3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'positive'), 'シンプル', 'She has a positive attitude.', '彼女は前向きな態度を持っている。', 'us_mvp_image_0179_positive.webp', 'say-dbffb0df-8d1e6678-aac67bdb-37b14d55-9d0c40c4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'negative'), 'シンプル', 'He gave a negative response.', '彼は否定的な返答をした。', 'us_mvp_image_0180_negative.webp', 'say-372b27a9-95b91f2c-32debaf2-fe7b47ab-37c37a4c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'complex'), 'シンプル', 'This is a complex issue.', 'これは複雑な問題だ。', 'us_mvp_image_0181_complex.webp', 'say-162cc186-6b0afc87-72eb4be5-1ebb0da8-6ba261c6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'current'), 'シンプル', 'The current situation is difficult.', '現在の状況は厳しい。', 'us_mvp_image_0182_current.webp', 'say-5cc09fb8-48c697a5-43d6f9da-e0e51c05-45bbf517.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mental'), 'シンプル', 'Mental health is very important.', '精神的な健康はとても重要だ。', 'us_mvp_image_0183_mental.webp', 'say-b918117e-d2e481ed-e2a4eaca-a9f19b6f-4b6bb606.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'specific'), 'シンプル', 'Can you give me a specific example?', 