VALUES
('surface', '表面／浮上する', 'adjective', '「上」の「super-」と「顔」の「facies」が結合して「表面」という意味になった。', NOW(), NOW()),('cognitive', '認知の', 'adjective', '「共に」の「com-」と「知る」の「gnoscere」が結合して「認知の」という意味になった。', NOW(), NOW()),('ideal', '理想的な／理想', 'adjective', 'ギリシャ語「idea（姿・形）」に由来し、「理想的な」という意味になった。', NOW(), NOW()),('efficient', '効率的な', 'adjective', '「外に」の「ex-」と「作る」の「facere」が結合して「効率的な」という意味になった。', NOW(), NOW()),('universal', '普遍的な、世界共通の', 'adjective', '「一つ」の「uni-」と「回る」の「vertere」が結合して「普遍的な」という意味になった。', NOW(), NOW()),('vast', '広大な', 'adjective', 'ラテン語「vastus（広大な、空虚な）」が語源で、「広大な」という意味になった。', NOW(), NOW()),('extra', '追加の／追加', 'adjective', 'ラテン語「extra（外）」が語源で、「追加の・余分の」という意味になった。', NOW(), NOW()),('entire', '全体の', 'adjective', 'ラテン語「integer（完全な）」が語源で、「全体の・完全な」という意味になった。', NOW(), NOW()),('familiar', 'よく知られた、親しみのある', 'adjective', 'ラテン語「familiaris（親しい）」が語源で、「親しい・見慣れた」という意味になった。', NOW(), NOW()),('obvious', '明らかな', 'adjective', '「上に」の「ob-」と「道」の「via」が結合して「明らかな」という意味になった。', NOW(), NOW()),('moral', '道徳的な／道徳', 'adjective', 'ラテン語「mores（習慣）」が語源で、「道徳の」という意味になった。', NOW(), NOW()),('ordinary', '普通の', 'adjective', '「順序」の「ordo」と「形容詞化」の「-arius」が結合して「普通の」という意味になった。', NOW(), NOW()),('equal', '平等な／等しくする', 'adjective', 'ラテン語「aequalis（等しい）」が語源で、「等しい」という意味になった。', NOW(), NOW()),('previous', '以前の', 'adjective', '「前に」の「prae-」と「行く」の「via」が結合して「以前の」という意味になった。', NOW(), NOW()),('false', '誤った', 'adjective', 'ラテン語「falsus（誤った）」が語源で、「偽の」という意味になった。', NOW(), NOW()),('rare', '珍しい', 'adjective', 'ラテン語「rarus（まばらな）」が語源で、「まれな」という意味になった。', NOW(), NOW()),('legal', '法的な、合法の', 'adjective', 'ラテン語「lex（法律）」が語源で、「法律の」という意味になった。', NOW(), NOW()),('independent', '独立した、自立した', 'adjective', '「否定」の「in-」と「依存する」の「dependere」が結合して「独立した」という意味になった。', NOW(), NOW()),('extreme', '極端な／極端', 'adjective', '「外に」の「ex-」と「行く」の「terminare」が結合して「極端な」という意味になった。', NOW(), NOW()),('actual', '実際の', 'adjective', 'ラテン語「actus（行動）」が語源で、「現実の」という意味になった。', NOW(), NOW()),('urban', '都市の', 'adjective', 'ラテン語「urbanus（都市の）」が語源で、「都市の」という意味になった。', NOW(), NOW()),('intelligent', '知的な、賢い', 'adjective', '「間に」の「inter-」と「選ぶ」の「legere」が結合して「知的な」という意味になった。', NOW(), NOW()),('conscious', '意識している', 'adjective', '「共に」の「com-」と「知る」の「scire」が結合して「意識している」という意味になった。', NOW(), NOW()),('capable', '能力がある', 'adjective', '「取る」の「capere」が語源で、「能力がある」という意味になった。', NOW(), NOW()),('accurate', '正確な', 'adjective', '「〜へ」の「ad-」と「注意」の「cura」が結合して「正確な」という意味になった。', NOW(), NOW()),('fundamental', '基本的な', 'adjective', '「土台」の「fundamentum」が語源で、「基本的な」という意味になった。', NOW(), NOW()),('artificial', '人工の', 'adjective', '「技術」の「ars」と「作る」の「facere」が結合して「人工的な」という意味になった。', NOW(), NOW()),('firm', '堅い、確固たる／会社', 'adjective', 'ラテン語「firmus（強固な）」が語源で、「堅い」という意味になった。', NOW(), NOW()),('overall', '全体的な／全体として', 'adjective', '「上に」の「over-」と「すべて」の「all」が結合して「全体の」という意味になった。', NOW(), NOW()),('rural', '田舎の', 'adjective', 'ラテン語「ruralis（田舎の）」が語源で、「田舎の」という意味になった。', NOW(), NOW()),('nuclear', '核の', 'adjective', 'ラテン語「nucleus（核）」が語源で、「核の」という意味になった。', NOW(), NOW()),('biological', '生物学の', 'adjective', '「生命」の「bios」と「学問」の「-logia」が結合して「生物学的な」という意味になった。', NOW(), NOW()),('constant', '一定の', 'adjective', '「共に」の「con-」と「立つ」の「stare」が結合して「一定の」という意味になった。', NOW(), NOW()),('severe', '厳しい、深刻な', 'adjective', 'ラテン語「severus（厳しい）」が語源で、「厳しい」という意味になった。', NOW(), NOW()),('visual', '視覚の', 'adjective', 'ラテン語「videre（見る）」が語源で、「視覚の」という意味になった。', NOW(), NOW()),('enormous', '巨大な', 'adjective', '「外に」の「e-」と「基準」の「norma」が結合して「巨大な」という意味になった。', NOW(), NOW()),('convenient', '便利な', 'adjective', '「共に」の「com-」と「来る」の「venire」が結合して「便利な」という意味になった。', NOW(), NOW()),('domestic', '国内の、家庭の', 'adjective', 'ラテン語「domus（家）」が語源で、「家庭の」という意味になった。', NOW(), NOW()),('typical', '典型的な', 'adjective', 'ギリシャ語「typos（型）」が語源で、「典型的な」という意味になった。', NOW(), NOW()),('capital', '首都、資本／主要な', 'adjective', 'ラテン語「caput（頭）」が語源で、「首都・資本」という意味になった。', NOW(), NOW()),('multiple', '複数の', 'adjective', '「多くの」の「multi-」と「〜倍の」の「-plus」が結合して「複数の」という意味になった。', NOW(), NOW()),('numerous', '数多くの', 'adjective', '「数」の「numerus」に由来し、「多数の」という意味になった。', NOW(), NOW()),('narrow', '狭い、限られた', 'adjective', '古英語「nearu（狭い）」が語源で、「狭い」という意味になった。', NOW(), NOW()),('widespread', '広範囲にわたる', 'adjective', '「広い」の「wide」と「広げる」の「spread」が結合して「広範囲にわたる」という意味になった。', NOW(), NOW()),('sufficient', '十分な', 'adjective', '「下から」の「sub-」と「作る」の「facere」が結合して「十分な」という意味になった。', NOW(), NOW()),('proper', '適切な', 'adjective', 'ラテン語「proprius（自分自身の）」が語源で、「適切な」という意味になった。', NOW(), NOW()),('linguistic', '言語の', 'adjective', '「言語」の「lingua」と形容詞化の「-ic」が結合して「言語の」という意味になった。', NOW(), NOW()),('annual', '毎年の', 'adjective', 'ラテン語「annus（年）」が語源で、「毎年の」という意味になった。', NOW(), NOW()),('contemporary', '現代の、同時代の', 'adjective', '「共に」の「con-」と「時間」の「tempus」が結合して「同時代の」という意味になった。', NOW(), NOW()),('contrary', '反対の／反対', 'adjective', '「反対の」の「contra-」と形容詞化の「-ary」が結合して「反対の」という意味になった。', NOW(), NOW()),('strict', '厳格な', 'adjective', 'ラテン語「strictus（引き締められた）」が語源で、「厳しい」という意味になった。', NOW(), NOW()),('civil', '市民の、民間の', 'adjective', 'ラテン語「civilis（市民の）」が語源で、「市民の」という意味になった。', NOW(), NOW()),('odd', '奇妙な、奇数の', 'adjective', '古ノルド語「oddi（三角形）」が語源で、「奇数の・奇妙な」という意味になった。', NOW(), NOW()),('sensitive', '敏感な', 'adjective', '「感じる」の「sentire」と形容詞化の「-ive」が結合して「敏感な」という意味になった。', NOW(), NOW()),('violent', '暴力的な', 'adjective', 'ラテン語「violentus（激しい）」が語源で、「暴力的な」という意味になった。', NOW(), NOW()),('virtual', '仮想の、事実上の', 'adjective', 'ラテン語「virtus（力・美徳）」が語源で、「実質的な・仮想の」という意味になった。', NOW(), NOW()),('regardless', '～に関係なく', 'adjective', '「〜に関係なく」という意味で、「regard（注意）」と否定の「-less」が結合した形。', NOW(), NOW()),('immediate', '即時の、直接の', 'adjective', '「中に」の「in-」と「挟む・置く」の「medius」が変化して「即時の」という意味になった。', NOW(), NOW()),('crucial', '重要な', 'adjective', 'ラテン語「crux（十字架）」が語源で、「決定的な」という意味になった。', NOW(), NOW()),('prime', '主要な、最良の／最盛期', 'adjective', 'ラテン語「primus（最初の）」が語源で、「主要な」という意味になった。', NOW(), NOW()),('curious', '好奇心が強い', 'adjective', 'ラテン語「cura（注意）」が語源で、「好奇心の強い」という意味になった。', NOW(), NOW()),('dramatic', '劇的な、大げさな', 'adjective', '"行動・演劇"の意味のギリシア語「drama（行為）」に由来し、「劇的な、印象的な」という意味になった。', NOW(), NOW()),('distinct', '明確な、異なる', 'adjective', '"離れて"の「dis-」と"刺す、突く"の意味のラテン語「stinguere」が結合して「はっきり区別された」という意味になった。', NOW(), NOW()),('anxious', '心配して、不安な', 'adjective', '"狭い、不安な"の意味のラテン語「angere」に由来し、「不安な、心配している」という意味になった。', NOW(), NOW()),('vital', '重要な、生命の', 'adjective', '"生命"の「vita（ラテン語）」に由来し、「生命の、重要な」という意味になった。', NOW(), NOW()),('conventional', '従来の、伝統的な', 'adjective', '"共に"の「con-」と"来る"の「venire」が結合し「一緒に集まる」→「慣習的な」という意味になった。', NOW(), NOW()),('abstract', '抽象的な／要約', 'adjective', '"離れて"の「abs-」と"引く"の「trahere」が結合して「引き離す」→「抽象的な」という意味になった。', NOW(), NOW()),('minor', '小さい、重要でない／未成年者', 'adjective', '"小さい"の意味のラテン語「minor」に由来し、「小さい、重要でない」という意味になった。', NOW(), NOW()),('extraordinary', '並外れた', 'adjective', '"外に"の「extra-」と"通常の"の「ordinarius」が結合して「並外れた」という意味になった。', NOW(), NOW()),('stable', '安定した', 'adjective', '"立つ"の意味のラテン語「stabilis（安定した）」に由来し、「安定した」という意味になった。', NOW(), NOW()),('flexible', '柔軟な、適応性のある', 'adjective', '"曲げる"の「flectere」に由来し、「柔軟な、曲がりやすい」という意味になった。', NOW(), NOW()),('brief', '短い／要約', 'adjective', '"短い"の意味のラテン語「brevis」に由来し、「短い、簡潔な」という意味になった。', NOW(), NOW()),('aggressive', '攻撃的な、積極的な', 'adjective', '"〜に向かって"の「ad-」と"進む"の「gradi」が結合して「攻撃的な」という意味になった。', NOW(), NOW()),('visible', '目に見える', 'adjective', '"見る"の意味のラテン語「videre」に由来し、「目に見える」という意味になった。', NOW(), NOW()),('unexpected', '予期しない', 'adjective', '"否定のun-"と"外に"の「ex-」＋"待つ"の「spectare」が結合して「予期していない」という意味になった。', NOW(), NOW()),('ethnic', '民族の、民族的な', 'adjective', '"民族の"の意味のギリシア語「ethnos」に由来し、「民族的な」という意味になった。', NOW(), NOW()),('initial', '最初の／頭文字', 'adjective', '"始まり"の意味のラテン語「initium」に由来し、「初めの」という意味になった。', NOW(), NOW()),('exact', '正確な', 'adjective', '"外へ"の「ex-」と"駆り立てる"の「agere」が結合して「正確な」という意味になった。', NOW(), NOW()),('precise', '精密な', 'adjective', '"前に"の「prae-」と"切る"の「caedere」が結合して「正確な、厳密な」という意味になった。', NOW(), NOW()),('latter', '後者の／後者', 'adjective', '古英語「lætra（遅い）」が比較級化して「後の」という意味になった。', NOW(), NOW()),('upset', '動揺させる／取り乱した', 'adjective', '"逆に"の「up-」と"設定する"の「set」が結合して「ひっくり返す、動揺させる」という意味になった。', NOW(), NOW()),('verbal', '言葉の、口頭の', 'adjective', 'ラテン語「verbum（言葉）」に由来し、「言葉の、口頭の」という意味になった。', NOW(), NOW()),('internal', '内部の、国内の', 'adjective', '"内側の"の意味のラテン語「internus」に由来し、「内部の」という意味になった。', NOW(), NOW()),('remote', '遠く離れた、僻地の', 'adjective', '"後ろへ"の「re-」と"動かす"の「movere」が結合して「遠くにある」という意味になった。', NOW(), NOW()),('principal', '主要な／校長', 'adjective', '"第一の"の「primus」と"取る"の「capere」が結合して「主要な、校長」という意味になった。', NOW(), NOW()),('equivalent', '同等の／同等のもの', 'adjective', '"同じ"の「aequus」と"価値のある"の「valere」が結合して「同等の」という意味になった。', NOW(), NOW()),('rational', '合理的な', 'adjective', '"計算、理由"の意味のラテン語「ratio」に由来し、「理性的な」という意味になった。', NOW(), NOW()),('relevant', '関連のある', 'adjective', '"再び"の「re-」と"持ち上げる"の「levare」が結合して「関係のある」という意味になった。', NOW(), NOW()),('absolute', '絶対的な、完全な', 'adjective', '"離れて"の「ab-」と"解き放つ"の「solvere」が結合して「完全な、絶対的な」という意味になった。', NOW(), NOW()),('frequent', '頻繁な', 'adjective', 'ラテン語「frequens（繰り返される）」に由来し、「頻繁な」という意味になった。', NOW(), NOW()),('permanent', '永久的な', 'adjective', '"通して"の「per-」と"とどまる"の「manere」が結合して「永久の、永続的な」という意味になった。', NOW(), NOW()),('intense', '強烈な', 'adjective', '"中へ"の「in-」と"伸ばす"の「tendere」が結合して「強烈な」という意味になった。', NOW(), NOW()),('meaningful', '意味のある', 'adjective', '"意味"の「meaning」と形容詞化接尾辞「-ful」が結合して「意味のある」という意味になった。', NOW(), NOW()),('evil', '邪悪な／悪', 'adjective', '古英語「yfel」に由来し、「悪い」という意味になった。', NOW(), NOW()),('random', '無作為の、偶然の', 'adjective', '中英語「randon（急ぎ）」に由来し、「無作為な、偶然の」という意味になった。', NOW(), NOW()),('raw', '生の、加工されていない', 'adjective', '古英語「hreaw（生の）」に由来し、「生の、加工されていない」という意味になった。', NOW(), NOW()),('mere', 'ほんの、単なる', 'adjective', '古英語「mer（純粋な）」に由来し、「単なる、純粋な」という意味になった。', NOW(), NOW()),('tropical', '熱帯の', 'adjective', '"回帰線"の意味のギリシア語「tropikos（回転の）」に由来し、「熱帯の」という意味になった。', NOW(), NOW()),('artistic', '芸術的な', 'adjective', '「芸術」の「art」に形容詞語尾「-istic」がついて「芸術的な」という意味になった。', NOW(), NOW()),('literary', '文学の', 'adjective', 'ラテン語「littera（文字）」に由来し、「文学の」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
