OW(), NOW()),((SELECT id FROM words WHERE word_text = 'unexpected'), 'シンプル', 'The news was totally unexpected.', 'そのニュースは完全に予想外だった。', 'us_mvp_image_0594_unexpected.webp', 'say-edfc0405-04bbd4ff-4e90d40c-ba33fc4a-ce3e2ea1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ethnic'), 'シンプル', 'The city has many ethnic groups.', 'その都市には多くの民族がいる。', 'us_mvp_image_0595_ethnic.webp', 'say-9b792f34-911b6f9e-0758b7da-f602bba5-ea490f7b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'initial'), 'シンプル', 'His initial reaction was surprise.', '彼の最初の反応は驚きだった。', 'us_mvp_image_0597_initial.webp', 'say-b30b94c8-fffbc0eb-3b4fff31-fe42a5fc-b35d2982.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exact'), 'シンプル', 'Can you tell me the exact time?', '正確な時間を教えてくれますか？', 'us_mvp_image_0598_exact.webp', 'say-5489eb58-a6534ca3-df4eb80c-ccc745d5-2b482085.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'precise'), 'シンプル', 'The measurements must be precise.', '測定は精密でなければならない。', 'us_mvp_image_0599_precise.webp', 'say-55793fc3-43de8ad2-a71f02eb-60cf0540-f3c5cb39.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'latter'), 'シンプル', 'I prefer the latter option.', '私は後者の選択肢を好む。', 'us_mvp_image_0600_latter.webp', 'say-38369682-8bc407d9-0d456e37-2c6e637a-69781c87.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'upset'), 'シンプル', 'The bad news upset him.', 'その悪いニュースは彼を動揺させた。', 'us_mvp_image_0631_upset.webp', 'say-e3515d7b-78a55cf2-9723f57b-4ce33496-b5f0c242.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'verbal'), 'シンプル', 'He gave a verbal agreement.', '彼は口頭で合意した。', 'us_mvp_image_0679_verbal.webp', 'say-939c28ad-d2aaba42-2f2379e6-36cd8601-5958d518.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'internal'), 'シンプル', 'The company is facing internal issues.', 'その会社は内部の問題に直面している。', 'us_mvp_image_0680_internal.webp', 'say-da8936fb-1db87e97-c0948456-d9baf9cc-f51c10a5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'remote'), 'シンプル', 'He lives in a remote village.', '彼は遠く離れた村に住んでいる。', 'us_mvp_image_0682_remote.webp', 'say-286a03e5-2d1e7cc9-017e084f-1ab5e15d-7467abc0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'principal'), 'シンプル', 'The principal of the school is strict.', 'その学校の校長は厳しい。', 'us_mvp_image_0683_principal.webp', 'say-550d7b75-27afb475-f320e38f-ebc33bb0-41409ce3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'equivalent'), 'シンプル', 'Ten dollars is equivalent to 1,500 yen.', '10ドルは1,500円に相当する。', 'us_mvp_image_0685_equivalent.webp', 'say-e4d42010-4dbc71e6-463ed648-6a779ef4-978bad79.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rational'), 'シンプル', 'His decision was rational.', '彼の決断は合理的だった。', 'us_mvp_image_0686_rational.webp', 'say-5cbe7982-3f894541-a9ec2b0e-37725174-ff5d0ca5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'relevant'), 'シンプル', 'This information is relevant to our study.', 'この情報は私たちの研究に関連している。', 'us_mvp_image_0687_relevant.webp', 'say-2219086c-c1de43f8-00a634cd-f039adf3-057e29c8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'absolute'), 'シンプル', 'There is no absolute truth.', '絶対的な真実は存在しない。', 'us_mvp_image_0688_absolute.webp', 'say-0406b658-f5d9676f-60f3a5ac-cbc33223-911ba331.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'frequent'), 'シンプル', 'He is a frequent visitor to this café.', '彼はこのカフェの常連だ。', 'us_mvp_image_0689_frequent.webp', 'say-a6a22207-c823f6c2-64f28a62-e2ee14a5-a4f03857.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'permanent'), 'シンプル', 'She found a permanent job.', '彼女は正社員の仕事を見つけた。', 'us_mvp_image_0690_permanent.webp', 'say-9914ab2f-b3921284-27441f7f-620c46df-c12ddbae.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'intense'), 'シンプル', 'The pain was intense.', 'その痛みは強烈だった。', 'us_mvp_image_0691_intense.webp', 'say-46adf4ae-e71971af-676f7249-274ab40f-de7eb90c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'meaningful'), 'シンプル', 'He gave a meaningful speech.', '彼は意味のあるスピーチをした。', 'us_mvp_image_0692_meaningful.webp', 'say-d57e5405-9e4dc54c-7f0f2c63-137cf458-d98b7df4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'evil'), 'シンプル', 'The story is about the battle between good and evil.', 'その物語は善と悪の戦いについてだ。', 'us_mvp_image_0693_evil.webp', 'say-5d623cf0-365bd6e7-d086cecf-92ca560c-31d14ce6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'random'), 'シンプル', 'The winner was chosen at random.', '勝者は無作為に選ばれた。', 'us_mvp_image_0695_random.webp', 'say-2eb1e812-a92b19e3-f6138d16-1fa516c9-102e07e0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'raw'), 'シンプル', 'He likes raw fish.', '彼は生魚が好きだ。', 'us_mvp_image_0696_raw.webp', 'say-ad8c6213-f219db41-19b687fd-d989f742-3c33ad4e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mere'), 'シンプル', 'It was a mere coincidence.', 'それは単なる偶然だった。', 'us_mvp_image_0698_mere.webp', 'say-cc23f77d-68b25f64-c9da264c-8c4c4aa7-bb3f85bf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tropical'), 'シンプル', 'They went on vacation to a tropical island.', '彼らは熱帯の島に旅行に行った。', 'us_mvp_image_0699_tropical.webp', 'say-feb34bda-64822ada-6041585f-cfbdef57-ae716971.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'artistic'), 'シンプル', 'She has great artistic talent.', '彼女は素晴らしい芸術的才能を持っている。', 'us_mvp_image_0779_artistic.webp', 'say-bc1bfad5-f4ba2b2a-d14d9d0c-d336a41c-5b0ab0ff.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'literary'), 'シンプル', 'He studies literary history.', '彼は文学史を研究している。', 'us_mvp_image_0780_literary.webp', 'say-8ff46033-d8c014b1-25c448a1-0893db88-accdcb5f.mp3', NOW(), NOW());
