INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('liberal', '自由主義の', 'adjective', 'ラテン語「liber（自由な）」に由来し、「自由主義の、寛大な」という意味になった。', NOW(), NOW()),('slight', 'わずかな', 'adjective', '古ノルド語「sleigr（滑らかな、軽い）」に由来し、「わずかな、軽視する」という意味になった。', NOW(), NOW()),('federal', '連邦の', 'adjective', 'ラテン語「foedus（契約）」に由来し、「連邦の、同盟の」という意味になった。', NOW(), NOW()),('primitive', '原始的な', 'adjective', '"第一の"の「primus」と接尾辞「-itivus」が結合して「原始的な」という意味になった。', NOW(), NOW()),('unfamiliar', 'なじみのない', 'adjective', '否定の「un-」と「なじみのある」の「familiar」が結合して「不慣れな、見知らぬ」という意味になった。', NOW(), NOW()),('subtle', '微妙な', 'adjective', '"下に"の「sub-」と"持ち上げる"の「telere（持ち上げる、持って行く）」が結合して「繊細な、微妙な」という意味になった。', NOW(), NOW()),('plain', '明白な、質素な／平原', 'adjective', 'ラテン語「planus（平らな）」に由来し、「簡素な、明白な」という意味になった。', NOW(), NOW()),('apparent', '明らかな', 'adjective', '"〜の方へ"の「ad-」と"現れる"の「parere」が結合して「明白な、見かけ上の」という意味になった。', NOW(), NOW()),('reluctant', '気が進まない', 'adjective', '"逆に"の「re-」と"引く"の「luctari（もがく）」が結合して「気が進まない」という意味になった。', NOW(), NOW()),('temporary', '一時的な', 'adjective', 'ラテン語「tempus（時間）」に由来し、「一時的な」という意味になった。', NOW(), NOW()),('guilty', '罪悪感のある、有罪の', 'adjective', '古英語「gyltig（罪のある）」に由来し、「有罪の、罪悪感のある」という意味になった。', NOW(), NOW()),('royal', '王室の、豪華な', 'adjective', 'ラテン語「regalis（王の）」に由来し、「王の、王室の」という意味になった。', NOW(), NOW()),('pure', '純粋な、混じりけのない', 'adjective', 'ラテン語「purus（純粋な）」に由来し、「純粋な、混じり気のない」という意味になった。', NOW(), NOW()),('incredible', '信じられない、驚くべき', 'adjective', '"否定のin-"と"信じる"の「credere」が結合して「信じられない」という意味になった。', NOW(), NOW()),('adequate', '十分な、適切な', 'adjective', '"〜へ"の「ad-」と"等しい"の「aequare」が結合して「十分な、適切な」という意味になった。', NOW(), NOW()),('precious', '貴重な、大切な', 'adjective', 'ラテン語「pretium（価値、価格）」に由来し、「貴重な、高価な」という意味になった。', NOW(), NOW()),('generous', '寛大な、気前のよい', 'adjective', 'ラテン語「generosus（高貴な生まれ）」に由来し、「寛大な、気前の良い」という意味になった。', NOW(), NOW()),('casual', '気軽な、カジュアルな', 'adjective', 'ラテン語「casus（偶然、出来事）」に由来し、「偶然の、気軽な」という意味になった。', NOW(), NOW()),('optimistic', '楽観的な', 'adjective', 'ラテン語「optimus（最良）」に由来し、「楽観的な」という意味になった。', NOW(), NOW()),('rough', '荒い、大まかな', 'adjective', '古英語「ruh（毛羽立った、荒い）」に由来し、「粗い、乱暴な」という意味になった。', NOW(), NOW()),('ultimate', '最終的な、究極の', 'adjective', 'ラテン語「ultimus（最も遠い、最後の）」に由来し、「究極の、最終的な」という意味になった。', NOW(), NOW()),('genuine', '本物の、誠実な', 'adjective', 'ラテン語「genuinus（生まれながらの、本物の）」に由来し、「本物の、誠実な」という意味になった。', NOW(), NOW()),('manual', '手動の／取扱説明書', 'adjective', 'ラテン語「manus（手）」に由来し、「手の、手を使う」という意味になった。', NOW(), NOW()),('mechanical', '機械の、機械的な', 'adjective', 'ラテン語「mechanica（機械的な技術）」に由来し、「機械の、機械的な」という意味になった。', NOW(), NOW()),('spare', '予備の／割く、節約する', 'adjective', '古英語「sparian（節約する）」に由来し、「予備の、余分の、割く」という意味になった。', NOW(), NOW()),('immune', '免疫のある', 'adjective', 'ラテン語「immunis（義務を免れた）」に由来し、「免疫の、影響を受けない」という意味になった。', NOW(), NOW()),('harsh', '厳しい、過酷な', 'adjective', '古ノルド語「hǫrskr（荒い）」に由来し、「厳しい、荒い」という意味になった。', NOW(), NOW()),('collective', '集団の、共同の', 'adjective', '「共に」の「col-」と"集める"の「legere」が結合して「集団の、集合的な」という意味になった。', NOW(), NOW()),('inevitable', '避けられない', 'adjective', '「避けられない」の「in-（否定）」と「evitare（避ける）」が結合して「避けられない」という意味になった。', NOW(), NOW()),('profound', '深い、重大な', 'adjective', 'ラテン語「pro-（前に）」と「fundus（底）」が結合して「深い、重大な」という意味になった。', NOW(), NOW()),('steady', '安定した、着実な', 'adjective', '古英語「stede（場所）」に由来し、「安定した、着実な」という意味になった。', NOW(), NOW()),('mature', '成熟した／成熟する', 'adjective', 'ラテン語「maturus（成熟した）」に由来し、「成熟した、熟した」という意味になった。', NOW(), NOW()),('likewise', '同様に、それと同じように', 'adjective', '「同様に」の意の古英語「gelīc（似ている）」と「wise（方法）」が結合して「同様に」という意味になった。', NOW(), NOW()),('antibiotic', '抗生物質', 'adjective', 'ギリシア語「anti（反対）」と「bios（生命）」が結合して「抗生物質（細菌に対抗する）」という意味になった。', NOW(), NOW()),('folk', '人々、民族／民間の', 'adjective', 'ゲルマン語「folc（人々）」に由来し、「人々、民間の」という意味になった。', NOW(), NOW()),('prominent', '著名な、目立つ', 'adjective', '「前に」の「pro-」と"突き出る"の「minere」が結合して「目立つ、著名な」という意味になった。', NOW(), NOW()),('radical', '急進的な、根本的な／急進派', 'adjective', 'ラテン語「radix（根）」に由来し、「根本的な、急進的な」という意味になった。', NOW(), NOW()),('prompt', '即座の／促す', 'adjective', 'ラテン語「promptus（すぐに準備された）」に由来し、「即座の、促す」という意味になった。', NOW(), NOW()),('informal', '形式ばらない、非公式の', 'adjective', '否定の「in-」と「形式的な」の「formal」が結合して「非公式の、くだけた」という意味になった。', NOW(), NOW()),('mutual', '相互の、共通の', 'adjective', 'ラテン語「mutuus（交換の）」に由来し、「相互の」という意味になった。', NOW(), NOW()),('neutral', '中立の、無関係の', 'adjective', 'ラテン語「ne（否定）」と「uter（どちら）」が結合して「中立の、無関係な」という意味になった。', NOW(), NOW()),('magnetic', '磁気の、人を引きつける', 'adjective', 'ギリシア語「Magnesia（磁石の原産地）」に由来し、「磁気の、魅力のある」という意味になった。', NOW(), NOW()),('polar', '極地の、対極的な', 'adjective', 'ラテン語「polus（軸、極）」に由来し、「極の、正反対の」という意味になった。', NOW(), NOW()),('external', '外部の、外の', 'adjective', 'ラテン語「exter（外の）」と「-nal（形容詞語尾）」が結合して「外部の」という意味になった。', NOW(), NOW()),('passive', '受動的な、消極的な', 'adjective', 'ラテン語「pati（耐える）」が変化して「受け身の、消極的な」という意味になった。', NOW(), NOW()),('awful', 'ひどい、恐ろしい', 'adjective', '「畏怖（awe）」と「〜のある」の「-ful」が結合して元は「畏敬の念を起こさせる」→現代では「ひどい」という意味になった。', NOW(), NOW()),('unrelated', '無関係の', 'adjective', '否定の「un-」と「関係ある」の「related」が結合して「無関係の」という意味になった。', NOW(), NOW()),('vulnerable', '傷つきやすい、脆弱な', 'adjective', 'ラテン語「vulnerare（傷つける）」に由来し、「傷つきやすい、弱い」という意味になった。', NOW(), NOW()),('urgent', '緊急の', 'adjective', 'ラテン語「urgere（押す、迫る）」が派生して「緊急の、差し迫った」という意味になった。', NOW(), NOW()),('modest', '控えめな、謙虚な', 'adjective', 'ラテン語「modus（尺度）」に由来し、「控えめな、謙虚な」という意味になった。', NOW(), NOW()),('keen', '熱心な、鋭い', 'adjective', '古英語「cene（勇敢な、鋭い）」に由来し、「熱心な、鋭い」という意味になった。', NOW(), NOW()),('fancy', '派手な、高級な／好む', 'adjective', '「fantasy」の短縮形から派生し、「想像する、装飾的な、気まぐれな」という意味になった。', NOW(), NOW()),('grateful', '感謝している', 'adjective', '「感謝する」の「grate」と「〜に満ちた」の「-ful」が結合して「感謝している」という意味になった。', NOW(), NOW()),('valid', '有効な、正当な', 'adjective', 'ラテン語「valere（強い、価値ある）」に由来し、「有効な、正当な」という意味になった。', NOW(), NOW()),('moderate', '適度な、穏やかな', 'adjective', 'ラテン語「moderari（制御する）」に由来し、「適度な、穏やかな」という意味になった。', NOW(), NOW()),('brilliant', '輝かしい、素晴らしい', 'adjective', 'ラテン語「beryllus（宝石）」と「輝く」の「-ant」が結合して「輝く、優れた」という意味になった。', NOW(), NOW()),('tremendous', '途方もない、素晴らしい', 'adjective', 'ラテン語「tremere（震える）」が派生して「ものすごい、巨大な」という意味になった。', NOW(), NOW()),('oral', '口頭の、口の', 'adjective', 'ラテン語「os（口）」に由来し、「口頭の、口の」という意味になった。', NOW(), NOW()),('innocent', '無罪の、無邪気な', 'adjective', '「否定のin-」と「nocere（害する）」が結合して「無実の、罪のない」という意味になった。', NOW(), NOW()),('subsequent', 'その後の、続いて起こる', 'adjective', '「下に、続いて」の「sub-」と「sequī（従う）」が結合して「次の、続く」という意味になった。', NOW(), NOW()),('shallow', '浅い、浅はかな', 'adjective', '古英語「sceald（浅い）」に由来し、「浅い、表面的な」という意味になった。', NOW(), NOW()),('inferior', '劣った、下位の', 'adjective', 'ラテン語「inferus（下の）」に比較級語尾が付き「下位の、劣った」という意味になった。', NOW(), NOW()),('awkward', '気まずい、不器用な', 'adjective', '古ノルド語「afugr（逆さの）」に由来し、「不器用な、ぎこちない」という意味になった。', NOW(), NOW()),('pregnant', '妊娠している', 'adjective', 'ラテン語「prae-（前に）」と「gnasci（生まれる）」が結合して「妊娠している、満ちている」という意味になった。', NOW(), NOW()),('rear', '育てる／後部', 'adjective', '古英語「raeran（育てる、上げる）」に由来し、「育てる、後部」という意味になった。', NOW(), NOW()),('retail', '小売／小売する', 'adjective', 'フランス語「retailler（切り分ける）」に由来し、「小売する」という意味になった。', NOW(), NOW()),('grave', '墓／深刻な', 'adjective', 'ラテン語「gravis（重い）」に由来し、「重大な、墓」という意味になった。', NOW(), NOW()),('dense', '密集した、濃い', 'adjective', 'ラテン語「densus（濃い）」に由来し、「濃密な、密集した」という意味になった。', NOW(), NOW()),('bitter', '苦い、辛辣な', 'adjective', '古英語「biter（苦い）」に由来し、「苦い、辛辣な」という意味になった。', NOW(), NOW()),('sensible', '賢明な、分別のある', 'adjective', 'ラテン語「sensibilis（感じられる）」に由来し、「賢明な、分別ある」という意味になった。', NOW(), NOW()),('noble', '高貴な、気高い／貴族', 'adjective', 'ラテン語「nobilis（高貴な）」に由来し、「高貴な、立派な」という意味になった。', NOW(), NOW()),('vague', '曖昧な、不明確な', 'adjective', 'ラテン語「vagus（さまよう）」に由来し、「曖昧な、不明確な」という意味になった。', NOW(), NOW()),('parallel', '平行の、類似の／平行線', 'adjective', 'ギリシア語「para（並んで）」と「allelos（互いに）」が結合して「平行な、類似の」という意味になった。', NOW(), NOW()),('tense', '緊張した／時制', 'adjective', 'ラテン語「tendere（張る）」が派生して「緊張した、時制」という意味になった。', NOW(), NOW()),('vertical', '垂直の、縦の', 'adjective', 'ラテン語「vertere（回す）」の派生語で「直立した、垂直の」という意味になった。', NOW(), NOW()),('indigenous', '先住の、固有の', 'adjective', 'ラテン語「indi（中に）」と「genere（生まれる）」が結合して「先住の、固有の」という意味になった。', NOW(), NOW()),('seasonal', '季節の、季節的な', 'adjective', '「季節」の「season」に形容詞語尾「-al」がついて「季節の、季節的な」という意味になった。', NOW(), NOW()),('irrelevant', '無関係な、的外れな', 'adjective', '否定の「ir-」と「関係のある」の「relevant」が結合して「無関係の」という意味になった。', NOW(), NOW()),('ridiculous', 'ばかげた、滑稽な', 'adjective', 'ラテン語「ridere（笑う）」に由来し、「ばかげた、滑稽な」という意味になった。', NOW(), NOW()),('sensory', '感覚の、知覚の', 'adjective', 'ラテン語「sentire（感じる）」に由来し、「感覚の、知覚の」という意味になった。', NOW(), NOW()),('chronic', '慢性的な、長引く', 'adjective', 'ギリシア語「chronos（時間）」に由来し、「慢性的な、長期の」という意味になった。', NOW(), NOW()),('voluntary', '自発的な、任意の', 'adjective', 'ラテン語「voluntas（意志）」に由来し、「自発的な、任意の」という意味になった。', NOW(), NOW()),('decent', 'まともな、礼儀正しい', 'adjective', 'ラテン語「decere（ふさわしい）」に由来し、「きちんとした、礼儀正しい」という意味になった。', NOW(), NOW()),('competent', '有能な、適任な', 'adjective', 'ラテン語「competere（適する、一致する）」に由来し、「有能な、適任の」という意味になった。', NOW(), NOW()),('straightforward', '単純な、率直な', 'adjective', '「まっすぐな」の「straight」と「〜向きの」の「forward」が結合して「率直な、単純な」という意味になった。', NOW(), NOW()),('interior', '内部、内装／内部の', 'adjective', 'ラテン語「inter（中）」に由来し、「内部の、内側の」という意味になった。', NOW(), NOW()),('transparent', '透明な、明白な', 'adjective', '「通して」の「trans-」と「見える」の「parere」が結合して「透明な、明白な」という意味になった。', NOW(), NOW()),('aesthetic', '美的な、審美的な', 'adjective', 'ギリシア語「aisthesis（感覚、知覚）」に由来し、「美的な、感覚的な」という意味になった。', NOW(), NOW()),('innate', '生まれつきの、本質的な', 'adjective', 'ラテン語「in-（中に）」と「nascī（生まれる）」が結合して「生まれつきの、先天的な」という意味になった。', NOW(), NOW()),('mild', '穏やかな、軽い', 'adjective', '古英語「milde（優しい）」に由来し、「穏やかな、軽い」という意味になった。', NOW(), NOW()),('toxic', '有毒な', 'adjective', 'ギリシア語「toxikon（毒）」に由来し、「有毒な」という意味になった。', NOW(), NOW()),('ashamed', '恥じている', 'adjective', '「恥」の「shame」に過去分詞形「-ed」がついて「恥じている」という意味になった。', NOW(), NOW()),('steep', '急な、険しい', 'adjective', '古英語「stēap（急な）」に由来し、「険しい、急な」という意味になった。', NOW(), NOW()),('trivial', '些細な、取るに足らない', 'adjective', 'ラテン語「trivium（三叉路、よくある場所）」に由来し、「些細な、ありふれた」という意味になった。', NOW(), NOW()),('ongoing', '進行中の', 'adjective', '「on（進行中）」と「going（行く）」が結合して「継続中の、進行中の」という意味になった。', NOW(), NOW()),('outstanding', '目立つ、優れた', 'adjective', '"外に"の「out-」と"立つ"の「stand」が結合して「目立つ、傑出した」という意味になった。', NOW(), NOW()),('unprecedented', '前例のない', 'adjective', '"前例のない"の「un-」と"precedent（前例）"が結合して「前例のない」という意味になった。', NOW(), NOW()),('infinite', '無限の、限りない', 'adjective', '"否定のin-"と"限界"の「finis」が結合して「無限の」という意味になった。', NOW(), NOW()),('worthwhile', '価値のある', 'adjective', '"価値"の「worth」と"〜するに値する"の「while」が結合して「価値のある」という意味になった。', NOW(), NOW()),('compulsory', '義務的な、強制の', 'adjective', '"共に"の「com-」と"押す"の「pellere」が結合して「強制的な」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'liberal'), 'シンプル', 'She has a liberal attitude.', '彼女は自由主義的な考え方を持っている。', 'us_mvp_image_0782_liberal.webp', 'say-a7289a16-45b2b598-08018b2b-eced127c-7ef81ec6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'slight'), 'シンプル', 'There is a slight difference.', 'わずかな違いがある。', 'us_mvp_image_0784_slight.webp', 'say-e43d41d5-277cab0b-39c60f17-eb5c983e-3585265e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'federal'), 'シンプル', 'The US has a federal government.', 'アメリカには連邦政府がある。', 'us_mvp_image_0785_federal.webp', 'say-b1a8f0d8-b6faa8fa-f18e5d08-2f102e95-896a6d3b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'primitive'), 'シンプル', 'Early humans used primitive tools.', '初期の人類は原始的な道具を使っていた。', 'us_mvp_image_0786_primitive.webp', 'say-b1145ec3-39ef64cc-c4c0a070-b46545c7-7338243e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'unfamiliar'), 'シンプル', 'This word is unfamiliar to me.', 'この単語は私にはなじみがない。', 'us_mvp_image_0787_unfamiliar.webp', 'say-f7ab9501-d36610c0-be172149-9fdef3d5-1bb171fc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'subtle'), 'シンプル', 'There is a subtle difference.', '微妙な違いがある。', 'us_mvp_image_0788_subtle.webp', 'say-3d0ecac6-a49b963b-4f2795b6-16e7934e-532359de.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'plain'), 'シンプル', 'She wore a plain dress.', '彼女はシンプルなドレスを着ていた。', 'us_mvp_image_0789_plain.webp', 'say-ec1ca344-27eebfcb-a5aa1935-9193809b-7385720a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'apparent'), 'シンプル', 'His success was apparent.', '彼の成功は明らかだった。', 'us_mvp_image_0791_apparent.webp', 'say-5e267e20-825027a1-135ae215-37cea8d7-5ea9ccc6.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reluctant'), 'シンプル', 'He was reluctant to answer.', '彼は答えるのを渋った。', 'us_mvp_image_0792_reluctant.webp', 'say-dbf5e7d7-f586cf86-9a0c5b97-cd5bba3a-172c7800.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'temporary')