, NOW()),((SELECT id FROM words WHERE word_text = 'moderate'), 'シンプル', 'She drinks alcohol in moderate amounts.', '彼女は適度な量のアルコールを飲む。', 'us_mvp_image_1082_moderate.webp', 'say-181914ae-a6d9d39f-d0f802a6-c3d75209-761f7419.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'brilliant'), 'シンプル', 'She had a brilliant idea.', '彼女は素晴らしいアイデアを思いついた。', 'us_mvp_image_1085_brilliant.webp', 'say-bdfc6198-bd2e334c-c993c5d1-5e4e67a6-f3040886.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tremendous'), 'シンプル', 'The project was a tremendous success.', 'そのプロジェクトは大成功だった。', 'us_mvp_image_1086_tremendous.webp', 'say-223c1e02-026dad25-a4c29d69-2731360d-4ab388af.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'oral'), 'シンプル', 'He had an oral exam.', '彼は口頭試験を受けた。', 'us_mvp_image_1087_oral.webp', 'say-a9ac52a6-39ba4553-906dafa1-fe975166-35ffc8c4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'innocent'), 'シンプル', 'The court found him innocent.', '裁判所は彼を無罪とした。', 'us_mvp_image_1088_innocent.webp', 'say-7ab3e388-f8ae4bc7-31210fbf-ae758ec0-8b1fc962.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'subsequent'), 'シンプル', 'The subsequent events changed history.', 'その後の出来事が歴史を変えた。', 'us_mvp_image_1089_subsequent.webp', 'say-ce3af3c0-278cfac5-94442a9a-9e8957fe-83e95bce.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'shallow'), 'シンプル', 'The lake is very shallow here.', 'ここは湖がとても浅い。', 'us_mvp_image_1090_shallow.webp', 'say-a11a4ca8-eae53830-72a3106e-70db47bf-3ca7e1ac.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'inferior'), 'シンプル', 'This product is inferior in quality.', 'この製品は品質が劣っている。', 'us_mvp_image_1092_inferior.webp', 'say-dc1c4f9a-31ed51ca-38f0cccb-a11ba088-33641ab9.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'awkward'), 'シンプル', 'There was an awkward silence.', '気まずい沈黙が流れた。', 'us_mvp_image_1093_awkward.webp', 'say-ea304ed0-996904b7-9694532c-58cd7ddd-169b7bf3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'pregnant'), 'シンプル', 'She is pregnant with her first child.', '彼女は第一子を妊娠している。', 'us_mvp_image_1095_pregnant.webp', 'say-096ea974-1eee0387-cf4ca63d-659eefae-a811062d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'rear'), 'シンプル', 'She reared three children.', '彼女は3人の子供を育てた。', 'us_mvp_image_1140_rear.webp', 'say-169e9587-0a1689b7-15f19748-3ff6855d-d45e72c8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'retail'), 'シンプル', 'This product is available at retail stores.', 'この商品は小売店で購入できる。', 'us_mvp_image_1154_retail.webp', 'say-ef14bf32-be4e5930-3dae62fd-6b525489-f641cc73.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'grave'), 'シンプル', 'He visited his grandfather’s grave.', '彼は祖父の墓を訪れた。', 'us_mvp_image_1173_grave.webp', 'say-7258611e-d6effda3-03641b85-423739e0-a26b6506.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dense'), 'シンプル', 'The forest is very dense.', 'その森はとても密集している。', 'us_mvp_image_1179_dense.webp', 'say-cef788ab-c57703e3-f847b3bc-b1520a85-caf13f15.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bitter'), 'シンプル', 'The medicine tastes bitter.', 'その薬は苦い味がする。', 'us_mvp_image_1182_bitter.webp', 'say-9e3d2e2e-1a36caf0-fb7723e2-e7c0541a-63b0c6ba.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sensible'), 'シンプル', 'That was a sensible decision.', 'それは賢明な決定だった。', 'us_mvp_image_1183_sensible.webp', 'say-315c352c-ad71db8f-b4acdb64-7bdd364d-d968dd47.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'noble'), 'シンプル', 'He has a noble spirit.', '彼は気高い精神を持っている。', 'us_mvp_image_1184_noble.webp', 'say-7ca4117c-df4f6697-d9f13ce4-db68ffcb-b541dcfa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'vague'), 'シンプル', 'Her explanation was vague.', '彼女の説明は曖昧だった。', 'us_mvp_image_1185_vague.webp', 'say-6d1423f4-3ed7d4c7-fee66021-0485b08b-ce21028e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'parallel'), 'シンプル', 'The two roads run parallel to each other.', 'その二本の道路は平行に走っている。', 'us_mvp_image_1186_parallel.webp', 'say-85379554-d79137dd-83af5210-71c447bc-26604ddd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tense'), 'シンプル', 'The atmosphere was tense.', 'その場の雰囲気は緊張していた。', 'us_mvp_image_1187_tense.webp', 'say-d0a6db70-921529ed-4762ada9-a4b4c65e-d94d0a1a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'vertical'), 'シンプル', 'The cliff is almost vertical.', 'その崖はほぼ垂直だ。', 'us_mvp_image_1188_vertical.webp', 'say-955a78ab-08c6f060-4b38b10e-db98f41b-29703afc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'indigenous'), 'シンプル', 'Kangaroos are indigenous to Australia.', 'カンガルーはオーストラリア固有の動物だ。', 'us_mvp_image_1189_indigenous.webp', 'say-8bec6723-9a22f149-945b7109-b5211f99-db12c170.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'seasonal'), 'シンプル', 'This fruit is seasonal.', 'この果物は季節限定だ。', 'us_mvp_image_1191_seasonal.webp', 'say-eca7fb40-d398c390-daa95c98-99b83553-3a03a924.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'irrelevant'), 'シンプル', 'His comment was irrelevant to the topic.', '彼のコメントは話題と無関係だった。', 'us_mvp_image_1194_irrelevant.webp', 'say-06daaaa7-2b4560fa-315b4814-de13c5b2-a1525960.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ridiculous'), 'シンプル', 'That idea is ridiculous.', 'その考えはばかげている。', 'us_mvp_image_1195_ridiculous.webp', 'say-0b52cef7-c9644d53-f474625d-75ca03e7-b82be299.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sensory'), 'シンプル', 'Music stimulates sensory perception.', '音楽は感覚を刺激する。', 'us_mvp_image_1197_sensory.webp', 'say-d8691502-d8c385f3-34ddb88a-2d377803-91f39bd0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'chronic'), 'シンプル', 'He has chronic back pain.', '彼は慢性的な腰痛を抱えている。', 'us_mvp_image_1198_chronic.webp', 'say-37c00ba9-933c1c62-977a67af-9c855116-2129a23e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'voluntary'), 'シンプル', 'He did voluntary work at a shelter.', '彼はシェルターで自発的に働いた。', 'us_mvp_image_1199_voluntary.webp', 'say-e9bcea00-4b8a72f6-1dd43980-d83d91fe-9eaa981c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'decent'), 'シンプル', 'He has a decent job.', '彼はまともな仕事をしている。', 'us_mvp_image_1279_decent.webp', 'say-333e520b-e1cedfbc-55293e2c-1138fe6c-a0ed4657.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'competent'), 'シンプル', 'She is a competent manager.', '彼女は有能なマネージャーだ。', 'us_mvp_image_1280_competent.webp', 'say-9c712ef1-abf1d857-7ad1379c-8e940957-9fafee57.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'straightforward'), 'シンプル', 'His explanation was straightforward.', '彼の説明は単純明快だった。', 'us_mvp_image_1281_straightforward.webp', 'say-34ddb46b-3152bd1f-fb947f03-bec90f1d-2f3d260b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'interior'), 'シンプル', 'The car''s interior is luxurious.', 'その車の内装は豪華だ。', 'us_mvp_image_1284_interior.webp', 'say-dae59c24-bd76d5ee-062b9762-d7c43436-e274d3fc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'transparent'), 'シンプル', 'The glass is transparent.', 'そのガラスは透明だ。', 'us_mvp_image_1285_transparent.webp', 'say-896a1eb6-1c63872d-0923a4db-d6babbcd-30a9b79d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'aesthetic'), 'シンプル', 'The building has great aesthetic value.', 'その建物は美的価値が高い。', 'us_mvp_image_1286_aesthetic.webp', 'say-a3e52403-869a4978-249ab04c-c57dbea5-aaf1391e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'innate'), 'シンプル', 'She has an innate talent for music.', '彼女は生まれつき音楽の才能がある。', 'us_mvp_image_1290_innate.webp', 'say-3f591fd5-48fcb545-5ea1902f-7091d791-8556b73f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mild'), 'シンプル', 'He has a mild fever.', '彼は軽い熱がある。', 'us_mvp_image_1291_mild.webp', 'say-458d624d-49aae713-9e299caa-1af1c0c4-e6783059.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'toxic'), 'シンプル', 'This chemical is highly toxic.', 'この化学物質は非常に有毒だ。', 'us_mvp_image_1292_toxic.webp', 'say-ba877f73-ca821827-e6f5d4d2-583b1b06-db9c36da.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ashamed'), 'シンプル', 'He felt ashamed of his mistake.', '彼は自分のミスを恥じた。', 'us_mvp_image_1293_ashamed.webp', 'say-0f6fd85c-71f3eb0a-340ffb80-9844c9ef-64daae65.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'steep'), 'シンプル', 'The mountain is very steep.', 'その山はとても険しい。', 'us_mvp_image_1296_steep.webp', 'say-68ffb965-c6da9f79-cb7d41c8-0b1b721a-f5e8698b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'trivial'), 'シンプル', 'This is a trivial issue.', 'これは些細な問題だ。', 'us_mvp_image_1297_trivial.webp', 'say-15994403-1a19fb77-09c2a49e-8c8cdb89-beb898c0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ongoing'), 'シンプル', 'The project is ongoing.', 'そのプロジェクトは進行中だ。', 'us_mvp_image_1300_ongoing.webp', 'say-96f29ce7-3a71eaba-158f6bee-5804b24f-94b38445.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'outstanding'), 'シンプル', 'She is an outstanding scientist.', '彼女は優れた科学者だ。', 'us_mvp_image_1379_outstanding.webp', 'say-064f9311-503df395-446e16a0-3856cef9-8874db35.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'unprecedented'), 'シンプル', 'The crisis caused unprecedented damage.', 'その危機は前例のない被害をもたらした。', 'us_mvp_image_1380_unprecedented.webp', 'say-af3a511d-59cc4c26-30a0e7fd-56e5336a-916f8afa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'infinite'), 'シンプル', 'Space seems infinite.', '宇宙は無限に広がっているようだ。', 'us_mvp_image_1381_infinite.webp', 'say-8e0601a9-7c7ecfa1-43ed7f3f-ac08219c-01876902.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'worthwhile'), 'シンプル', 'Helping others is a worthwhile activity.', '他人を助けることは価値のある活動だ。', 'us_mvp_image_1382_worthwhile.webp', 'say-9a0d5a75-77df8f9a-7090855b-58c8369e-17c3d883.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compulsory'), 'シンプル', 'Education is compulsory until the age of 16.', '教育は16歳まで義務である。', 'us_mvp_image_1384_compulsory.webp', 'say-7f8b15f4-b0f22e43-e0f61fa3-f1fb9018-1c1c0acb.mp3', NOW(), NOW());
