INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('probable', '起こりそうな、あり得る', 'adjective', '"試す、認める"のラテン語「probare」に由来し、「ありそうな」という意味になった。', NOW(), NOW()),('obscure', '不明瞭な、目立たない／隠す', 'adjective', '"上に"の「ob-」と"覆う"の「scurus（覆い隠す）」が結合して「不明瞭な」という意味になった。', NOW(), NOW()),('skeptical', '疑い深い、懐疑的な', 'adjective', 'ギリシア語「skeptikos（考察する人）」に由来し、「懐疑的な」という意味になった。', NOW(), NOW()),('fragile', '壊れやすい、もろい', 'adjective', 'ラテン語「frangere（壊す）」に由来し、「壊れやすい」という意味になった。', NOW(), NOW()),('static', '静的な、変化のない', 'adjective', 'ギリシア語「statikos（立っている）」に由来し、「静的な、変化しない」という意味になった。', NOW(), NOW()),('hostile', '敵意のある、対立する', 'adjective', 'ラテン語「hostis（敵）」に由来し、「敵意のある」という意味になった。', NOW(), NOW()),('scarce', '乏しい、少ない', 'adjective', 'ラテン語「excerpere（取り除く）」を語源とし、「乏しい」という意味になった。', NOW(), NOW()),('gross', '総計の、ひどい', 'adjective', 'ラテン語「grossus（厚い、粗い）」に由来し、「総計の、粗野な」という意味になった。', NOW(), NOW()),('inherent', '生来の、本質的な', 'adjective', '"中に"の「in-」と"くっつく"の「haerere」が結合して「内在する、生まれつきの」という意味になった。', NOW(), NOW()),('notable', '注目すべき、著名な', 'adjective', 'ラテン語「notare（記す）」に由来し、「注目すべき」という意味になった。', NOW(), NOW()),('scratch', 'ひっかく、削る／ひっかき傷', 'adjective', '古ノルド語「skrapa（こする）」が語源で、「ひっかく」という意味になった。', NOW(), NOW()),('headline', '見出し', 'adjective', '「head（上部）」と「line（行）」が結合して「見出し」という意味になった。', NOW(), NOW()),('thorough', '徹底的な、完全な', 'adjective', '古英語「thurh（通して）」に由来し、「完全な、徹底的な」という意味になった。', NOW(), NOW()),('naked', '裸の、むき出しの', 'adjective', '古英語「nacod」に由来し、「裸の」という意味になった。', NOW(), NOW()),('insufficient', '不十分な', 'adjective', '"否定のin-"と"下に"の「sub-」＋"作る"の「facere」が結合して「不十分な」という意味になった。', NOW(), NOW()),('acute', '鋭い、深刻な', 'adjective', 'ラテン語「acuere（尖らせる）」に由来し、「鋭い、激しい」という意味になった。', NOW(), NOW()),('monetary', '金銭の、金融の', 'adjective', 'ラテン語「moneta（貨幣、ミント）」に由来し、「金銭の、通貨の」という意味になった。', NOW(), NOW()),('partial', '部分的な、不完全な', 'adjective', 'ラテン語「pars（部分）」に由来し、「部分的な、えこひいきの」という意味になった。', NOW(), NOW()),('sole', '唯一の／足の裏、靴底', 'adjective', 'ラテン語「solus（唯一の）」に由来し、「唯一の、単独の」という意味になった。', NOW(), NOW()),('spontaneous', '自発的な、自然発生的な', 'adjective', 'ラテン語「sponte（自発的に）」に由来し、「自然発生的な、自発的な」という意味になった。', NOW(), NOW()),('spatial', '空間の', 'adjective', 'ラテン語「spatium（空間）」に由来し、「空間の」という意味になった。', NOW(), NOW()),('neat', 'きちんとした、整然とした', 'adjective', 'ラテン語「nitidus（光る、整った）」に由来し、「きちんとした、清潔な」という意味になった。', NOW(), NOW()),('loyal', '忠実な、誠実な', 'adjective', 'ラテン語「legalis（法的な）」に由来し、古フランス語「loial（忠実な）」を経て「忠誠な」という意味になった。', NOW(), NOW()),('thought', '考え、思考', 'noun', '古英語「þencan（考える）」の過去分詞形「þoht」が語源で、「thought」は"考え"という意味になった。', NOW(), NOW()),('willing', 'いとわない、喜んで～する', 'adjective', '古英語「willan（望む）」が語源で、「〜する気がある」という意味になった。', NOW(), NOW()),('humanity', '人類、人間性', 'noun', 'ラテン語「humanitas（人間性）」が語源で、「人類・人間性」という意味になった。', NOW(), NOW()),('mammal', '哺乳類', 'noun', 'ラテン語「mamma（乳房）」が語源で、「哺乳類」という意味になった。', NOW(), NOW()),('treasure', '宝、財産／大切にする', 'noun', 'ラテン語「thesaurus（宝）」が語源で、「財宝」という意味になった。', NOW(), NOW()),('dialogue', '対話、会話', 'noun', '"間で"の「dia-」と"話す"の「logos」が結合して「対話」という意味になった。', NOW(), NOW()),('sophisticated', '洗練された、精巧な', 'adjective', 'ラテン語「sophisticatus（精巧な）」に由来し、「洗練された、複雑な」という意味になった。', NOW(), NOW()),('extinct', '絶滅した', 'adjective', '"外へ"の「ex-」と"消す"の「stinguere」が結合して「絶滅した」という意味になった。', NOW(), NOW()),('rude', '失礼な', 'adjective', 'ラテン語「rudis（未加工の、粗野な）」に由来し、「無礼な、粗雑な」という意味になった。', NOW(), NOW()),('melt', '溶ける、溶かす', 'verb', '古英語「meltan（溶ける）」に由来し、「溶かす、溶ける」という意味になった。', NOW(), NOW()),('endanger', '危険にさらす', 'verb', '"〜の中に"の「en-」と"危険"の「danger」が結合して「危険にさらす」という意味になった。', NOW(), NOW()),('imitate', 'まねる', 'verb', 'ラテン語「imitari（真似る）」に由来し、「模倣する」という意味になった。', NOW(), NOW()),('literacy', '読み書き能力、知識', 'noun', 'ラテン語「littera（文字）」に由来し、「読み書き能力」という意味になった。', NOW(), NOW()),('heritage', '遺産、伝統', 'noun', '古フランス語「eritage（相続）」に由来し、「遺産、継承物」という意味になった。', NOW(), NOW()),('haven', '安全な場所、避難所', 'noun', '古英語「hæfen（港）」に由来し、「避難所、港」という意味になった。', NOW(), NOW()),('means', '手段、方法', 'noun', '"方法、手段"を意味する古英語「menean（意図する）」に由来し、「手段」という意味になった。', NOW(), NOW()),('glacier', '氷河', 'noun', 'フランス語「glacier（氷河）」に由来し、「氷河」という意味になった。', NOW(), NOW()),('primate', '霊長類', 'noun', '"第一の"の「primus」と接尾辞「-ate」が結合し、「霊長類（第一位の動物）」という意味になった。', NOW(), NOW()),('marine', '海の、海洋の', 'adjective', 'ラテン語「mare（海）」に由来し、「海の、海洋の」という意味になった。', NOW(), NOW()),('eager', '熱心な、強く望んでいる', 'adjective', 'ラテン語「acer（鋭い、熱心な）」が変化して「熱心な」という意味になった。', NOW(), NOW()),('orbit', '軌道／周回する', 'noun', 'ラテン語「orbita（車輪の跡）」に由来し、「軌道、循環路」という意味になった。', NOW(), NOW()),('asteroid', '小惑星', 'noun', 'ギリシア語「aster（星）」と「-oid（〜のような）」が結合して「小惑星（星のようなもの）」という意味になった。', NOW(), NOW()),('courage', '勇気', 'noun', 'ラテン語「cor（心）」に由来し、「勇気、度胸」という意味になった。', NOW(), NOW()),('shame', '恥、残念なこと', 'noun', '古英語「scamu」に由来し、「恥、恥ずかしさ」という意味になった。', NOW(), NOW()),('drought', '干ばつ', 'noun', '古英語「drūgath（乾燥）」に由来し、「干ばつ、渇き」という意味になった。', NOW(), NOW()),('prefecture', '県、府', 'noun', 'ラテン語「praefectus（長官）」に由来し、「県、府、省」という意味になった。', NOW(), NOW()),('unpleasant', '不快な', 'adjective', '否定の「un-」と「快い」の「pleasant」が結合して「不快な」という意味になった。', NOW(), NOW()),('Arctic', '北極の／北極', 'adjective', 'ギリシア語「arktikos（北の、北極星に関連）」に由来し、「北極の」という意味になった。', NOW(), NOW()),('deaf', '耳が聞こえない', 'adjective', '古英語「deaf（聞こえない）」に由来し、「耳の聞こえない」という意味になった。', NOW(), NOW()),('bob', '上下に動く', 'verb', '擬音語的起源を持ち、「上下に動く、急に動く」という意味になった。', NOW(), NOW()),('cultivate', '耕す、育てる', 'verb', 'ラテン語「cultivare（耕す）」に由来し、「耕す、育てる、養う」という意味になった。', NOW(), NOW()),('bump', 'ぶつかる／衝撃', 'verb', '擬音語的起源を持ち、「ぶつかる、衝突する」という意味になった。', NOW(), NOW()),('tragedy', '悲劇、惨事', 'noun', 'ギリシア語「tragos（ヤギ）」と「oide（歌）」が結合して「悲劇（元は祭儀での歌）」という意味になった。', NOW(), NOW()),('allergy', 'アレルギー', 'noun', 'ギリシア語「allos（他の）」と「ergon（作用）」が結合して「アレルギー（異なる反応）」という意味になった。', NOW(), NOW()),('galaxy', '銀河', 'noun', 'ギリシア語「galaxias（乳のような）」から「天の川」→「銀河」という意味になった。', NOW(), NOW()),('skeleton', '骨格、骸骨', 'noun', 'ギリシア語「skeletos（乾いた）」に由来し、「骨格」という意味になった。', NOW(), NOW()),('sibling', '兄弟姉妹', 'noun', '古英語「sibb（親族）」に由来し、「兄弟姉妹」という意味になった。', NOW(), NOW()),('fluent', '流暢な', 'adjective', 'ラテン語「fluere（流れる）」に由来し、「流暢な、滑らかな」という意味になった。', NOW(), NOW()),('cruel', '残酷な', 'adjective', 'ラテン語「crudelis（残酷な）」に由来し、「残酷な」という意味になった。', NOW(), NOW()),('fake', '偽の／偽物', 'adjective', 'イタリア語「falsificare（偽造する）」が英語化して「偽物、偽造の」という意味になった。', NOW(), NOW()),('spiritual', '精神的な、宗教的な', 'adjective', 'ラテン語「spiritus（魂、呼吸）」に由来し、「精神的な、宗教的な」という意味になった。', NOW(), NOW()),('heal', '治る、癒す', 'verb', '古英語「hǣlan（治す）」に由来し、「治す、癒す」という意味になった。', NOW(), NOW()),('obey', '従う、守る', 'verb', 'ラテン語「oboedire（従う）」が由来で、「従う、従順である」という意味になった。', NOW(), NOW()),('astonish', '驚かせる', 'verb', 'ラテン語「ex-（外へ）」と「tonare（雷鳴をとどろかす）」が変化して「驚かせる」という意味になった。', NOW(), NOW()),('thrill', 'わくわくさせる／スリル', 'verb', '古英語「thyrlian（穴を開ける）」が比喩的に「感動させる、ゾクゾクさせる」という意味になった。', NOW(), NOW()),('nod', 'うなずく／うなずき', 'verb', '中期英語「noddien」に由来し、「うなずく」という意味になった。', NOW(), NOW()),('bow', 'おじぎする、屈服する／おじぎ', 'verb', '古英語「bugan（曲がる）」に由来し、「お辞儀する、頭を下げる」という意味になった。', NOW(), NOW()),('compliment', '賞賛／褒める', 'noun', 'ラテン語「complementum（補完）」がイタリア語・フランス語を経て「賛辞」という意味になった。', NOW(), NOW()),('expedition', '探検、遠征', 'noun', 'ラテン語「ex-（外に）」と「ped（足）」が結合して「遠征、探検」という意味になった。', NOW(), NOW()),('ethic', '倫理、道徳', 'noun', 'ギリシア語「ethos（習慣、道徳）」に由来し、「倫理、倫理的原則」という意味になった。', NOW(), NOW()),('nutrition', '栄養', 'noun', 'ラテン語「nutrire（養う）」が名詞化して「栄養、栄養摂取」という意味になった。', NOW(), NOW()),('nationality', '国籍', 'noun', '「国家」の「nation」に接尾辞「-ality（性質）」がついて「国籍、国民性」という意味になった。', NOW(), NOW()),('dementia', '認知症', 'noun', 'ラテン語「de-（失う）」と「mens（精神）」が結合して「認知症、精神の喪失」という意味になった。', NOW(), NOW()),('fingerprint', '指紋', 'noun', '「指（finger）」と「印（print）」が結合して「指紋」という意味になった。', NOW(), NOW()),('wilderness', '野生地、未開地', 'noun', '古英語「wild（野生の）」と接尾辞「-ness（状態）」が結合して「荒野、自然地」という意味になった。', NOW(), NOW()),('fantasy', '空想、幻想', 'noun', 'ギリシア語「phantasia（見えるもの、幻）」に由来し、「空想、幻想」という意味になった。', NOW(), NOW()),('elaborate', '精巧な、詳しく述べる', 'adjective', 'ラテン語「e-（外に）」と「laborare（働く）」が結合して「手の込んだ、詳しく述べる」という意味になった。', NOW(), NOW()),('dynamic', '活動的な、動的な', 'adjective', 'ギリシア語「dynamis（力）」に由来し、「力強い、動的な」という意味になった。', NOW(), NOW()),('indifferent', '無関心な、冷淡な', 'adjective', '「否定のin-」と「差のある」の「different」が結合して「無関心な、どうでもいい」という意味になった。', NOW(), NOW()),('obese', '肥満の', 'adjective', 'ラテン語「ob-（過度に）」と「edere（食べる）」が結合して「肥満の」という意味になった。', NOW(), NOW()),('intimate', '親密な、深い', 'adjective', 'ラテン語「intimus（最も内側の）」に由来し、「親密な、深い」という意味になった。', NOW(), NOW()),('medieval', '中世の', 'adjective', 'ラテン語「medium aevum（中世）」が変化して「中世の」という意味になった。', NOW(), NOW()),('sacred', '神聖な', 'adjective', 'ラテン語「sacer（神聖な）」に由来し、「神聖な、崇拝される」という意味になった。', NOW(), NOW()),('surf', '波乗りする、ネットを閲覧する／波', 'verb', '「波」の「surface（表面）」が短縮されて「サーフィンする、波乗り」という意味になった。', NOW(), NOW()),('chew', '噛む', 'verb', '古英語「ceowan（かむ）」に由来し、「かむ」という意味になった。', NOW(), NOW()),('swallow', '飲み込む', 'verb', '古英語「swelgan（飲み込む）」に由来し、「飲み込む、呑む」という意味になった。', NOW(), NOW()),('vanish', '消える、姿を消す', 'verb', 'ラテン語「vanus（空の）」に由来し、「消える、見えなくなる」という意味になった。', NOW(), NOW()),('polish', '磨く／つや出し', 'verb', 'ラテン語「polire（磨く）」に由来し、「磨く、洗練する」という意味になった。', NOW(), NOW()),('spoil', '台無しにする、甘やかす', 'verb', 'ラテン語「spoliare（奪う）」に由来し、「台無しにする、甘やかす」という意味になった。', NOW(), NOW()),('disgust', '嫌悪させる／嫌悪', 'verb', '「離れて」の「dis-」と「味わう」の「gustus」が結合して「嫌悪させる」という意味になった。', NOW(), NOW()),('empathy', '共感、感情移入', 'noun', 'ギリシア語「em-（中に）」と「pathos（感情）」が結合して「感情移入、共感」という意味になった。', NOW(), NOW()),('congress', '議会、会議', 'noun', '「共に」の「con-」と「歩く」の「gradior」が結合して「会議、議会」という意味になった。', NOW(), NOW()),('millennium', '千年紀、千年間', 'noun', '「千」の「mille」と「年」の「annus」が結合して「千年、千周年」という意味になった。', NOW(), NOW()),('mankind', '人類', 'noun', '古英語「man（人）」と「kind（種類）」が結合して「人類」という意味になった。', NOW(), NOW()),('Muslim', 'イスラム教徒／イスラム教の', 'noun', 'アラビア語「muslim（服従する者）」に由来し、「イスラム教徒」という意味になった。', NOW(), NOW()),('landmine', '地雷', 'noun', '「土地」の「land」と「地雷」の「mine」が結合して「地雷」という意味になった。', NOW(), NOW()),('scent', '香り、匂い', 'noun', 'ラテン語「sentire（感じる、嗅ぐ）」に由来し、「香り、匂い」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'probable'), 'シンプル', 'It is probable that he will be late.', '彼が遅れる可能性が高い。', 'us_mvp_image_1385_probable.webp', 'say-5af98f12-914c96dc-9523d4b2-5b80b5d4-9c078810.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'obscure'), 'シンプル', 'The meaning of the text is obscure.', 'その文章の意味は不明瞭だ。', 'us_mvp_image_1387_obscure.webp', 'say-7a98be1c-b30da729-54a91b1e-07751393-e79bd6d1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'skeptical'), 'シンプル', 'She is skeptical about his story.', '彼女は彼の話を疑っている。', 'us_mvp_image_1388_skeptical.webp', 'say-33955d01-f07bedd2-c7b7434f-8d156e48-b44ff86f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fragile'), 'シンプル', 'This glass is very fragile.', 'このガラスはとても壊れやすい。', 'us_mvp_image_1389_fragile.webp', 'say-99d0714e-e7e2f2a2-34343f1c-77cf9b92-91889963.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'static'), 'シンプル', 'The economy has remained static.', '経済は停滞したままだ。', 'us_mvp_image_1390_static.webp', 'say-7e49cfd7-83991a5f-d46733e0-1d6201db-7dae0e46.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'hostile'), 'シンプル', 'He faced a hostile audience.', '彼は敵意のある聴衆に直面した。', 'us_mvp_image_1395_hostile.webp', 'say-5af3a0ab-8f6af542-ac8a3998-f48256dd-83792791.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'scarce'), 'シンプル', 'Water is scarce in the desert.', '砂漠では水が乏しい。', 'us_mvp_image_1397_scarce.webp', 'say-dcfd29a6-b83d1941-7398fc8d-58eb4f38-71f56b3a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'gross'), 'シンプル', 'The company made a gross profit of $1 million.', 'その会社は100万ドルの総利益を得た。', 'us_mvp_image_1398_gross.webp', 'say-34b3d344-5ca3938f-1834e831-344f4dae-ec62d0bb.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'inherent'), 'シンプル', 'The risk is inherent in this business.', 'そのリスクはこのビジネスに本質的に存在する。', 'us_mvp_image_1399_inherent.webp', 'say-2486e683-04fbf29e-3d6d5a69-0d4afe8d-568cebb4.mp3', NOW(), NOW()),((SELECT