-97e520e1-63155904.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tragedy'), 'シンプル', 'The play ended in tragedy.', 'その劇は悲劇的な結末を迎えた。', 'us_mvp_image_0955_tragedy.webp', 'say-11eee14d-ee84e15d-7457dc2a-547c9628-efdc30ac.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'allergy'), 'シンプル', 'He has a severe peanut allergy.', '彼は重度のピーナッツアレルギーを持っている。', 'us_mvp_image_0957_allergy.webp', 'say-e34a9e17-916fe252-ea78a89b-235c2a8c-7a629ecd.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'galaxy'), 'シンプル', 'The Milky Way is a galaxy that contains our solar system.', '天の川は太陽系を含む銀河だ。', 'us_mvp_image_0966_galaxy.webp', 'say-61c5c6ca-313c7847-6f1df3d3-1d9505a2-f8e48bf5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'skeleton'), 'シンプル', 'The human skeleton consists of 206 bones.', '人間の骨格は206本の骨で構成されている。', 'us_mvp_image_0968_skeleton.webp', 'say-d4e43645-db9db866-436dff27-a0027c8b-a239e336.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sibling'), 'シンプル', 'She has three siblings—two brothers and a sister.', '彼女には兄弟姉妹が3人いる（兄2人と姉1人）。', 'us_mvp_image_0974_sibling.webp', 'say-42951c7f-063ce2cc-5bb9a4dc-72ab0927-bfaedeb2.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fluent'), 'シンプル', 'He is fluent in three languages.', '彼は3か国語を流暢に話す。', 'us_mvp_image_0988_fluent.webp', 'say-89d62949-3a0ddd1a-bcf40337-0bb82a35-9a9d0831.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'cruel'), 'シンプル', 'It was cruel to leave the dog outside in the cold.', '犬を寒い外に放置するのは残酷だ。', 'us_mvp_image_0993_cruel.webp', 'say-286754fc-65f76aeb-70397b3b-0b92468a-b0101f0a.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fake'), 'シンプル', 'The painting turned out to be a fake.', 'その絵は偽物だと判明した。', 'us_mvp_image_0994_fake.webp', 'say-7493c846-144dafd5-ed5f7c8e-115b4a54-ac72df84.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spiritual'), 'シンプル', 'She is interested in spiritual healing.', '彼女はスピリチュアルな癒しに興味がある。', 'us_mvp_image_0997_spiritual.webp', 'say-e26fa228-dbae0db2-73d9c2f1-4ce30705-fae9d23f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'heal'), 'シンプル', 'The wound will heal in a few days.', 'その傷は数日で治るだろう。', 'us_mvp_image_1012_heal.webp', 'say-eda4e45e-26c7579c-fb8a4f63-415d682f-e8cc18c0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'obey'), 'シンプル', 'Soldiers must obey orders.', '兵士は命令に従わなければならない。', 'us_mvp_image_1023_obey.webp', 'say-22951dc8-611e9cf3-fd3ebd25-df2cb1c2-be5d7772.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'astonish'), 'シンプル', 'His performance astonished everyone.', '彼の演技は皆を驚かせた。', 'us_mvp_image_1031_astonish.webp', 'say-8bdd35db-13eb9c28-b9cd0271-bbaae345-5e2ce3c5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'thrill'), 'シンプル', 'The roller coaster thrilled the riders.', 'そのジェットコースターは乗客をわくわくさせた。', 'us_mvp_image_1032_thrill.webp', 'say-a405c08a-b4f48b35-48a28478-f3c68549-95296372.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'nod'), 'シンプル', 'She nodded in agreement.', '彼女は同意してうなずいた。', 'us_mvp_image_1033_nod.webp', 'say-f65b0252-b50308af-a5604e06-02b887ff-b056f903.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'bow'), 'シンプル', 'He bowed to the audience.', '彼は観客におじぎをした。', 'us_mvp_image_1034_bow.webp', 'say-413d2fc7-ea7040f1-e44e1831-40a30a4c-13293493.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'compliment'), 'シンプル', 'He gave her a nice compliment.', '彼は彼女に素敵な褒め言葉をかけた。', 'us_mvp_image_1045_compliment.webp', 'say-3c25e6e6-2ef4584f-f82de96d-c9e1d6db-f77b0ae8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'expedition'), 'シンプル', 'The team went on an expedition to the Arctic.', 'そのチームは北極への探検に出発した。', 'us_mvp_image_1050_expedition.webp', 'say-03ec0db3-c2029d76-b0c97265-09af8bc3-81d1143b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ethic'), 'シンプル', 'He follows a strong work ethic.', '彼は強い労働倫理を持っている。', 'us_mvp_image_1054_ethic.webp', 'say-34ebd480-fb526009-8393ac6c-2ab0045f-7c6fc89f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'nutrition'), 'シンプル', 'Good nutrition is essential for health.', '健康には良い栄養が不可欠だ。', 'us_mvp_image_1058_nutrition.webp', 'say-9efe0905-11a57b1c-cde3bfa4-e49b697a-e5648569.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'nationality'), 'シンプル', 'She has dual nationality.', '彼女は二重国籍を持っている。', 'us_mvp_image_1061_nationality.webp', 'say-2a3373fe-0383ac1e-d4167c8a-b8e3e8c9-a2225765.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dementia'), 'シンプル', 'His grandmother suffers from dementia.', '彼の祖母は認知症を患っている。', 'us_mvp_image_1064_dementia.webp', 'say-8d71856c-d452ca65-b98d6ae7-867004ce-a7514021.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fingerprint'), 'シンプル', 'The police took his fingerprints.', '警察は彼の指紋を取った。', 'us_mvp_image_1070_fingerprint.webp', 'say-dc76a771-2a8f34a7-d99412c7-815aa14e-493b0fda.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'wilderness'), 'シンプル', 'They went on an adventure in the wilderness.', '彼らは未開の地で冒険をした。', 'us_mvp_image_1072_wilderness.webp', 'say-1ef51057-d23c792b-cb9768fa-e7e9e5cc-68f3de99.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fantasy'), 'シンプル', 'He lives in a world of fantasy.', '彼は空想の世界に生きている。', 'us_mvp_image_1076_fantasy.webp', 'say-4949f94e-1176c3f3-023571ce-8cac3b18-7475a4d4.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'elaborate'), 'シンプル', 'He gave an elaborate explanation.', '彼は詳しい説明をした。', 'us_mvp_image_1081_elaborate.webp', 'say-45900476-cacd021c-d48e9ccc-786d1cb3-265d2f01.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'dynamic'), 'シンプル', 'She is a dynamic leader.', '彼女は活動的なリーダーだ。', 'us_mvp_image_1083_dynamic.webp', 'say-707f7405-1394dbbd-c4f1dcee-310d5187-21c43ff5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'indifferent'), 'シンプル', 'He was indifferent to the news.', '彼はそのニュースに無関心だった。', 'us_mvp_image_1091_indifferent.webp', 'say-04da3ae6-03597b0b-6a90c684-1e15a663-6ad3f47f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'obese'), 'シンプル', 'He became obese due to poor eating habits.', '彼は不健康な食習慣のために肥満になった。', 'us_mvp_image_1094_obese.webp', 'say-c51a9579-da09dbaa-077b9251-096d5ec6-4be6adb3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'intimate'), 'シンプル', 'They have an intimate friendship.', '彼らは親密な友情を持っている。', 'us_mvp_image_1096_intimate.webp', 'say-b680ac65-427e4b77-c1a23dea-f73f42c9-e076cbe0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'medieval'), 'シンプル', 'The castle dates back to medieval times.', 'その城は中世の時代に遡る。', 'us_mvp_image_1097_medieval.webp', 'say-1fc4f6cf-b8586812-f9fe7447-03780f36-e574f08c.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'sacred'), 'シンプル', 'This temple is sacred to many people.', 'この寺は多くの人にとって神聖だ。', 'us_mvp_image_1098_sacred.webp', 'say-43efeed7-4df66ccd-66563530-22ddf773-a91ac5a5.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'surf'), 'シンプル', 'He loves to surf the internet.', '彼はネットサーフィンをするのが好きだ。', 'us_mvp_image_1103_surf.webp', 'say-1a5a91be-b264dc0f-cc5f57b9-fd29935d-621013d0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'chew'), 'シンプル', 'He chewed his food slowly.', '彼はゆっくりと食べ物を噛んだ。', 'us_mvp_image_1117_chew.webp', 'say-fba81044-553a0074-1a9f8481-6d3b1e27-7661b072.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'swallow'), 'シンプル', 'She swallowed the pill with water.', '彼女は水で薬を飲み込んだ。', 'us_mvp_image_1118_swallow.webp', 'say-aa0a3113-34d329d7-c33e0571-71a24425-d8829a9e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'vanish'), 'シンプル', 'The magician vanished from the stage.', 'そのマジシャンは舞台から姿を消した。', 'us_mvp_image_1123_vanish.webp', 'say-1d6f78ef-de7ef70f-58f423ad-0da9d080-c47bd148.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'polish'), 'シンプル', 'She polished the silverware.', '彼女は銀食器を磨いた。', 'us_mvp_image_1124_polish.webp', 'say-fc7cd3c2-d38ed2bb-209b1bfe-0d581337-88ddf856.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'spoil'), 'シンプル', 'The rain spoiled our picnic.', '雨が私たちのピクニックを台無しにした。', 'us_mvp_image_1128_spoil.webp', 'say-deaf872b-ce32b5c2-fba8560a-3f486437-286328f3.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'disgust'), 'シンプル', 'The sight disgusted him.', 'その光景は彼を嫌悪させた。', 'us_mvp_image_1131_disgust.webp', 'say-29e99594-f9a92fc7-128eed49-2129d906-1697e15d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'empathy'), 'シンプル', 'He showed great empathy for the victims.', '彼は被害者に深い共感を示した。', 'us_mvp_image_1141_empathy.webp', 'say-0d1d1d90-c64a71bd-e2e3e8d1-671ec1e4-87cb920b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'congress'), 'シンプル', 'The Congress passed a new law.', '議会は新しい法律を可決した。', 'us_mvp_image_1145_congress.webp', 'say-cad15318-47013aaa-8f05de09-77ceaff0-2a45fa4d.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'millennium'), 'シンプル', 'The year 2000 marked a new millennium.', '2000年は新たな千年紀の始まりだった。', 'us_mvp_image_1146_millennium.webp', 'say-3c2a3226-cc3de364-ba6a1fd4-48b61066-e9d8886f.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'mankind'), 'シンプル', 'Climate change is a threat to mankind.', '気候変動は人類への脅威だ。', 'us_mvp_image_1147_mankind.webp', 'say-da37c9cf-2cd5f2b9-e6a5da08-ccae2187-b5ca52cc.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'Muslim'), 'シンプル', 'He is a Muslim.', '彼はイスラム教徒だ。', 'us_mvp_image_1148_Muslim.webp', 'say-83579e94-f3265014-e982bafd-921bdb1d-5356ef3e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'landmine'), 'シンプル', 'The area is still dangerous due to landmines.', 'その地域はまだ地雷のために危険だ。', 'us_mvp_image_1150_landmine.webp', 'say-304430fe-31ea55f6-10a291ab-5bfb4188-c9970faa.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'scent'), 'シンプル', 'The flower has a sweet scent.', 'その花は甘い香りがする。', 'us_mvp_image_1156_scent.webp', 'say-52cfca09-b4931882-ad18b3a8-82fe4fa5-830adaa2.mp3', NOW(), NOW());
