INSERT INTO words (word_text, definition, part_of_speech, etymology, created_at, updated_at)
VALUES
('diabetes', '糖尿病', 'noun', 'ギリシア語「diabainein（通り抜ける）」が由来で、「糖尿病」という意味になった（尿が通り抜ける病）。', NOW(), NOW()),('reef', '礁、岩礁', 'noun', 'オランダ語「rif（岩礁）」に由来し、「珊瑚礁、暗礁」という意味になった。', NOW(), NOW()),('microbe', '微生物、細菌', 'noun', 'ギリシア語「mikros（小さい）」と「bios（生命）」が結合して「微生物」という意味になった。', NOW(), NOW()),('fame', '名声、評判', 'noun', 'ラテン語「fama（評判）」に由来し、「名声、評判」という意味になった。', NOW(), NOW()),('scenery', '風景、景色', 'noun', 'ラテン語「scaena（舞台）」に由来し、「景色、風景」という意味になった。', NOW(), NOW()),('tablet', '錠剤、タブレット', 'noun', 'ラテン語「tabula（板）」に由来し、「錠剤、タブレット、板」という意味になった。', NOW(), NOW()),('exotic', '異国風の、珍しい', 'adjective', '「外の」の「exo-」と「出身」の「-tic」が結合して「異国の、珍しい」という意味になった。', NOW(), NOW()),('aboriginal', '先住の／先住民', 'adjective', 'ラテン語「ab origine（起源から）」に由来し、「先住の、原住の」という意味になった。', NOW(), NOW()),('abundant', '豊富な、多量の', 'adjective', '「〜から」の「ab-」と「波打つ」の「undare」が結合して「豊富な」という意味になった。', NOW(), NOW()),('fairy', '妖精', 'noun', 'ラテン語「fata（運命）」に由来する古仏語「faerie」から「妖精」という意味になった。', NOW(), NOW()),('inclined', '傾向がある、傾いた', 'adjective', 'ラテン語「inclinare（傾ける）」の過去分詞形に由来し、「〜する傾向がある、傾いた」という意味になった。', NOW(), NOW()),('esteem', '尊敬、評価／尊敬する', 'noun', 'ラテン語「aestimare（評価する）」に由来し、「尊敬する、評価する」という意味になった。', NOW(), NOW()),('amuse', '楽しませる、面白がらせる', 'verb', '「〜から離れて」の「a-」と「考える」の「muser」が結合して「楽しませる」という意味になった。', NOW(), NOW()),('nurture', '育てる、養育する／養育', 'verb', 'ラテン語「nutrire（育てる）」に由来し、「育てる、養育する」という意味になった。', NOW(), NOW()),('yawn', 'あくびをする／あくび', 'verb', '古英語「ganian（あくびする）」に由来し、「あくびをする」という意味になった。', NOW(), NOW()),('blink', 'まばたきする、点滅する', 'verb', '古ノルド語「blinka（まばたきする）」に由来し、「まばたきする、点滅する」という意味になった。', NOW(), NOW()),('irritate', 'いら立たせる、刺激する', 'verb', 'ラテン語「irritare（刺激する）」に由来し、「苛立たせる、刺激する」という意味になった。', NOW(), NOW()),('insult', '侮辱する／侮辱', 'verb', '「中に」の「in-」と「跳ねる」の「saltare」が結合して「侮辱する」という意味になった。', NOW(), NOW()),('rob', '奪う、強盗をする', 'verb', '古英語「reafian（奪う）」に由来し、「盗む、強奪する」という意味になった。', NOW(), NOW()),('forgive', '許す', 'verb', '「完全に」の「for-」と「与える」の「give」が結合して「許す」という意味になった。', NOW(), NOW()),('temper', '気性、怒り', 'noun', 'ラテン語「temperare（混ぜる、調整する）」に由来し、「気質、加減する」という意味になった。', NOW(), NOW()),('herd', '群れ／群れる', 'noun', '古英語「heord（群れ）」に由来し、「群れ、群れる」という意味になった。', NOW(), NOW()),('pity', '哀れみ、残念なこと／哀れむ', 'noun', 'ラテン語「pietas（敬虔、哀れみ）」に由来し、「哀れみ、同情」という意味になった。', NOW(), NOW()),('priest', '聖職者、神父', 'noun', 'ギリシア語「presbyteros（長老）」に由来し、「司祭、神父」という意味になった。', NOW(), NOW()),('acquaintance', '知人、面識', 'noun', '「知っている」の「acquaint」と名詞化語尾「-ance」が結合して「知人、面識」という意味になった。', NOW(), NOW()),('famine', '飢饉、食糧不足', 'noun', 'ラテン語「fames（飢え）」に由来し、「飢饉、飢え」という意味になった。', NOW(), NOW()),('deforestation', '森林破壊', 'noun', '「除去」の「de-」と「森林」の「forest」＋名詞化語尾「-ation」が結合して「森林伐採」という意味になった。', NOW(), NOW()),('debris', '破片、がれき', 'noun', 'フランス語「debris（破片、瓦礫）」に由来し、「破片、がれき」という意味になった。', NOW(), NOW()),('intuition', '直感', 'noun', '「中に」の「in-」と「見る」の「tueri」が結合して「直感」という意味になった。', NOW(), NOW()),('monument', '記念碑、遺跡', 'noun', 'ラテン語「monere（思い出させる）」が名詞化して「記念碑、記念物」という意味になった。', NOW(), NOW()),('cosmetic', '美容の、表面的な／化粧品', 'noun', 'ギリシア語「kosmos（秩序、飾り）」に由来し、「化粧の、表面的な」という意味になった。', NOW(), NOW()),('delicate', '繊細な、壊れやすい', 'adjective', 'ラテン語「delicatus（快楽好きな、優美な）」に由来し、「繊細な、壊れやすい」という意味になった。', NOW(), NOW()),('prehistoric', '先史時代の', 'adjective', '「前の」の「pre-」と「歴史」の「historic」が結合して「先史時代の」という意味になった。', NOW(), NOW()),('humble', '謙虚な、控えめな', 'adjective', 'ラテン語「humilis（地面の、謙虚な）」に由来し、「謙虚な、控えめな」という意味になった。', NOW(), NOW()),('peculiar', '奇妙な、特有の', 'adjective', 'ラテン語「peculium（私有財産）」に由来し、「独特な、特有の」という意味になった。', NOW(), NOW()),('magnificent', '壮大な、素晴らしい', 'adjective', 'ラテン語「magnus（偉大な）」と「facere（作る）」が結合して「壮大な、素晴らしい」という意味になった。', NOW(), NOW()),('blossom', '花／開花する、発展する', 'verb', '古英語「blostma（花）」に由来し、「開花する、栄える」という意味になった。', NOW(), NOW()),('terrify', '怖がらせる、恐怖を与える', 'verb', 'ラテン語「terrere（怖がらせる）」と「-fy（〜にする）」が結合して「怖がらせる」という意味になった。', NOW(), NOW()),('starve', '飢える、餓死する', 'verb', '古英語「steorfan（死ぬ）」が変化して「餓死する、飢える」という意味になった。', NOW(), NOW()),('yell', '叫ぶ、大声を上げる／叫び声', 'verb', '古英語「gellan（叫ぶ）」に由来し、「叫ぶ、大声で言う」という意味になった。', NOW(), NOW()),('startle', '驚かせる', 'verb', '中英語「sterten（跳ねる）」に由来し、「驚かす」という意味になった。', NOW(), NOW()),('offend', '気分を害する、侮辱する', 'verb', 'ラテン語「ob-（〜に向かって）」と「fendere（打つ）」が結合して「怒らせる、害する」という意味になった。', NOW(), NOW()),('descend', '降りる、下る', 'verb', 'ラテン語「de-（下へ）」と「scandere（登る）」が結合して「降りる、由来する」という意味になった。', NOW(), NOW()),('quest', '探求、探し求めること', 'noun', 'ラテン語「quaerere（探し求める）」に由来し、「探求、探す」という意味になった。', NOW(), NOW()),('dignity', '尊厳、威厳', 'noun', 'ラテン語「dignus（価値のある）」に由来し、「威厳、尊厳」という意味になった。', NOW(), NOW()),('criterion', '基準、尺度', 'noun', 'ギリシア語「kriterion（判断の基準）」に由来し、「基準、尺度」という意味になった。', NOW(), NOW()),('epidemic', '伝染病、流行／流行の', 'noun', 'ギリシア語「epi（上に）」と「demos（人々）」が結合して「流行病」という意味になった。', NOW(), NOW()),('nightmare', '悪夢、恐ろしい出来事', 'noun', '「夜」の「night」と「悪霊」の「mare」が結合して「悪夢」という意味になった。', NOW(), NOW()),('pollen', '花粉', 'noun', 'ラテン語「pollen（粉、花粉）」に由来し、「花粉」という意味になった。', NOW(), NOW()),('hive', 'ミツバチの巣、巣箱', 'noun', '古英語「hyf（蜂の巣）」に由来し、「蜂の巣、群れ」という意味になった。', NOW(), NOW()),('feast', '宴会、ごちそう／ごちそうを食べる', 'noun', 'ラテン語「festum（祭り）」に由来し、「ごちそう、祝宴」という意味になった。', NOW(), NOW()),('cuisine', '料理、食文化', 'noun', 'ラテン語「coquere（料理する）」がフランス語を経て「料理」という意味になった。', NOW(), NOW()),('proverb', 'ことわざ、格言', 'noun', 'ラテン語「pro-（前に）」と「verbum（言葉）」が結合して「ことわざ」という意味になった。', NOW(), NOW()),('tuition', '授業料、教育費', 'noun', 'ラテン語「tueri（守る、教える）」が派生して「授業料、指導」という意味になった。', NOW(), NOW()),('intake', '摂取量、受け入れ', 'noun', '「中に」の「in-」と「取る」の「take」が結合して「摂取、取り入れ」という意味になった。', NOW(), NOW()),('grief', '悲しみ、深い悲しみ', 'noun', 'ラテン語「gravis（重い）」が古フランス語「grief（苦痛）」に変化し、「深い悲しみ」という意味になった。', NOW(), NOW()),('destiny', '運命、宿命', 'noun', '"完全に"の「de-」と"定める"の「stare」が結合して、「運命として定められたもの」という意味になった。', NOW(), NOW()),('skull', '頭蓋骨', 'noun', '中期英語「skulle」に由来し、ゲルマン系語源から「頭蓋骨」という意味になった。', NOW(), NOW()),('tomb', '墓、墓石', 'noun', 'ギリシア語「tymbos（塚）」に由来し、「墓」という意味になった。', NOW(), NOW()),('monk', '修道士、僧侶', 'noun', 'ギリシア語「monos（一人の）」に由来し、「修道士（独りで宗教生活を送る者）」という意味になった。', NOW(), NOW()),('worship', '礼拝、崇拝／崇拝する', 'verb', '古英語「weorthscipe（価値のある状態）」から派生し、「崇拝する」という意味になった。', NOW(), NOW()),('indispensable', '不可欠な、必須の', 'adjective', '"否定のin-"と"離れる"の「dis-」＋"つかむ"の「pendere」が結合して「絶対に必要な」という意味になった。', NOW(), NOW()),('ambiguous', '曖昧な、不明確な', 'adjective', '"両方"の「ambi-」と"動く"の「agere」が結合して「曖昧な、両義的な」という意味になった。', NOW(), NOW()),('gradual', '徐々の、段階的な', 'adjective', 'ラテン語「gradus（段階）」に由来し、「徐々の、段階的な」という意味になった。', NOW(), NOW()),('vocal', '声の、大声で意見を述べる', 'adjective', 'ラテン語「vox（声）」に由来し、「声の、音声の」という意味になった。', NOW(), NOW()),('vivid', '鮮やかな、生き生きとした', 'adjective', 'ラテン語「vivere（生きる）」に由来し、「鮮やかな、生き生きとした」という意味になった。', NOW(), NOW()),('imperial', '帝国の、皇帝の', 'adjective', 'ラテン語「imperium（支配）」に由来し、「帝国の、皇帝の」という意味になった。', NOW(), NOW()),('superficial', '表面的な、浅薄な', 'adjective', '"上に"の「super-」と"面"の「facies」が結合して「表面的な」という意味になった。', NOW(), NOW()),('refresh', '新しくする、リフレッシュする', 'verb', '"再び"の「re-」と"新鮮な"の「fresch（古英語）」が結合して「元気づける、リフレッシュする」という意味になった。', NOW(), NOW()),('bloom', '開花する／花', 'verb', '古ノルド語「blóm（花）」に由来し、「開花する」という意味になった。', NOW(), NOW()),('conquer', '征服する、克服する', 'verb', '"完全に"の「con-」と"探し求める"の「quaerere」が結合して「征服する」という意味になった。', NOW(), NOW()),('navigate', '操縦する、進路を決める', 'verb', 'ラテン語「navis（船）」と"導く"の「agere」が結合して「航行する、操縦する」という意味になった。', NOW(), NOW()),('beg', '乞う、懇願する', 'verb', '古英語「bedecian（請う）」に由来し、「乞う」という意味になった。', NOW(), NOW()),('inhabit', '住む、生息する', 'verb', '"中に"の「in-」と"住む"の「habitare」が結合して「住む、生息する」という意味になった。', NOW(), NOW()),('comprehend', '理解する', 'verb', '"完全に"の「com-」と"つかむ"の「prehendere」が結合して「理解する」という意味になった。', NOW(), NOW()),('cram', '詰め込む、詰め込み勉強をする', 'verb', '中期英語「crammen（押し込む）」に由来し、「詰め込む、詰め込み学習する」という意味になった。', NOW(), NOW()),('flock', '群がる／群れ', 'verb', '古英語「flocc（群れ）」に由来し、「群れる、群れ」という意味になった。', NOW(), NOW()),('glow', '輝く／光', 'verb', '古英語「glowan（輝く）」に由来し、「輝く、光る」という意味になった。', NOW(), NOW()),('dairy', '乳製品', 'noun', '古英語「dæge（乳しぼりをする人）」に由来し、「乳製品、酪農の」という意味になった。', NOW(), NOW()),('compassion', '思いやり、同情', 'noun', '"共に"の「com-」と"苦しむ"の「pati」が結合して「同情、思いやり」という意味になった。', NOW(), NOW()),('posture', '姿勢、態度', 'noun', 'ラテン語「ponere（置く）」から派生し、「姿勢、態度」という意味になった。', NOW(), NOW()),('curse', '呪い、ののしり／呪う、ののしる', 'noun', '中英語「cursein」に由来し、「呪い」という意味になった（正確な語源は不明確）。', NOW(), NOW()),('funeral', '葬式', 'noun', 'ラテン語「funus（葬儀）」に由来し、「葬式」という意味になった。', NOW(), NOW()),('cereal', 'シリアル、穀物', 'noun', 'ローマの農業の女神「Ceres」に由来し、「穀物、シリアル」という意味になった。', NOW(), NOW()),('rubbish', 'ゴミ、くだらないこと', 'noun', '古フランス語「robouse（くず）」が語源で、「ゴミ」という意味になった。', NOW(), NOW()),('maze', '迷路', 'noun', '古英語「masian（驚かせる）」が語源で、「迷路、混乱」という意味になった。', NOW(), NOW()),('spectator', '観客、見物人', 'noun', '"見る"の「specere」に名詞語尾「-tor」がついて「観客」という意味になった。', NOW(), NOW()),('blade', '刃、羽根', 'noun', '古英語「blæd（葉、刃）」に由来し、「刃、ブレード」という意味になった。', NOW(), NOW()),('collision', '衝突', 'noun', '"共に"の「com-」と"ぶつかる"の「laedere」が結合して「衝突」という意味になった。', NOW(), NOW()),('landmark', '目印、歴史的建造物', 'noun', '「目印となる場所」の意味で「land（土地）」と「mark（印）」が結合して「画期的な出来事、目印」という意味になった。', NOW(), NOW()),('supreme', '最高の、至高の', 'adjective', 'ラテン語「super（上）」に由来し、「最高の」という意味になった。', NOW(), NOW()),('sincere', '誠実な、心からの', 'adjective', 'ラテン語「sincerus（純粋な）」に由来し、「誠実な、偽りのない」という意味になった。', NOW(), NOW()),('tame', '飼いならされた／飼いならす', 'adjective', '古英語「tam（手懐けられた）」に由来し、「飼いならされた」という意味になった。', NOW(), NOW()),('dim', '薄暗い／暗くする', 'adjective', '古英語「dim（ぼんやりした）」に由来し、「薄暗い、不明瞭な」という意味になった。', NOW(), NOW()),('disabled', '障がいのある、無効になった', 'adjective', '"否定のdis-"と"能力がある"の「able」が結合して「障害のある、無力にされた」という意味になった。', NOW(), NOW()),('metropolitan', '大都市の、都会の', 'adjective', 'ギリシア語「meter（母）」と「polis（都市）」が結合して「大都市の、首都の」という意味になった。', NOW(), NOW()),('divine', '神聖な、素晴らしい', 'adjective', 'ラテン語「divinus（神の）」に由来し、「神の、神聖な」という意味になった。', NOW(), NOW()),('drastic', '劇的な、抜本的な', 'adjective', 'ギリシア語「drastikos（作用する）」に由来し、「徹底的な、過激な」という意味になった。', NOW(), NOW()),('fierce', '激しい、荒々しい', 'adjective', 'ラテン語「ferus（野生の）」に由来し、「猛烈な、獰猛な」という意味になった。', NOW(), NOW()),('tidy', 'きれいな、整頓された／片付ける', 'adjective', '古ノルド語「tíð（整った状態）」に由来し、「整頓された」という意味になった。', NOW(), NOW())
INSERT INTO example_contents (word_id, theme, sentence_en, sentence_ja, illustration_url, audio_url, created_at, updated_at)
VALUES
((SELECT id FROM words WHERE word_text = 'diabetes'), 'シンプル', 'He was diagnosed with diabetes.', '彼は糖尿病と診断された。', 'us_mvp_image_1159_diabetes.webp', 'say-1a0a08cc-8f1cbc79-ea1cabe6-b595f563-81eb8234.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'reef'), 'シンプル', 'The Great Barrier Reef is a famous tourist attraction.', 'グレートバリアリーフは有名な観光名所だ。', 'us_mvp_image_1161_reef.webp', 'say-93da8ce5-3dc162f1-dd64a46e-cfdcf049-232f57a0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'microbe'), 'シンプル', 'Some microbes are beneficial to humans.', 'いくつかの微生物は人間にとって有益である。', 'us_mvp_image_1162_microbe.webp', 'say-9c02b476-7356569c-fdd2be50-bc190d84-1ba9192b.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'fame'), 'シンプル', 'She rose to fame as a singer.', '彼女は歌手として名声を得た。', 'us_mvp_image_1165_fame.webp', 'say-0068a00b-55fe96d7-a9aaf3be-8ffc6c32-4cb9b3e8.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'scenery'), 'シンプル', 'The mountain scenery is breathtaking.', 'その山の風景は息をのむほど美しい。', 'us_mvp_image_1175_scenery.webp', 'say-1ea31d37-8c0e5859-4c4f8717-c3ff3a93-31f5fb64.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tablet'), 'シンプル', 'He took a painkiller tablet.', '彼は鎮痛剤の錠剤を飲んだ。', 'us_mvp_image_1178_tablet.webp', 'say-d73e55b5-82bd4bf4-2bce24d7-fb97ccf8-1bd8c6d1.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'exotic'), 'シンプル', 'She likes exotic food.', '彼女は異国風の料理が好きだ。', 'us_mvp_image_1180_exotic.webp', 'say-eeacb18e-a2e672da-caf686ff-64cb4327-1dd3267e.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'aboriginal'), 'シンプル', 'The Aboriginal people have a rich culture.', '先住民は豊かな文化を持っている。', 'us_mvp_image_1190_aboriginal.webp', 'say-2be041e8-1ce608a6-b6d1634d-ab3b4792-c0907ebf.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'abundant'), 'シンプル', 'Water is abundant in this region.', 'この地域には水が豊富だ。', 'us_mvp_image_1192_abundant.webp', 'say-283de09e-bce48727-4bd3fd78-0c11bb19-996cbb99.mp3', NOW(), NO