(SELECT id FROM words WHERE word_text = 'intake'), 'シンプル', 'Reduce your sugar intake for better health.', '健康のために糖分の摂取量を減らしなさい。', 'us_mvp_image_1368_intake.webp', 'say-2c2c458c-eabb40fe-98595ae6-51a6f174-859c9de0.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'grief'), 'シンプル', 'She was in deep grief after her loss.', '彼女は喪失の後、深い悲しみにあった。', 'us_mvp_image_1373_grief.webp', 'say-f7c99270-ab4279e1-008bd5ef-860f71f6-0f1b61ff.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'destiny'), 'シンプル', 'He believes it was his destiny to become a doctor.', '彼は医者になることが運命だと信じている。', 'us_mvp_image_1374_destiny.webp', 'say-cb68c5cd-24f78d48-e768848c-3a338411-8353ba99.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'skull'), 'シンプル', 'The X-ray showed a fracture in his skull.', 'レントゲンで彼の頭蓋骨に骨折が見つかった。', 'us_mvp_image_1375_skull.webp', 'say-46ea0dfa-66a2edfc-6beffae8-6fdd3599-70b32727.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'tomb'), 'シンプル', 'The ancient tomb was discovered by archaeologists.', 'その古代の墓は考古学者によって発見された。', 'us_mvp_image_1376_tomb.webp', 'say-ab64d7f0-9358e765-0e809b7b-02180bf7-cd65be26.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'monk'), 'シンプル', 'The monk spent years in meditation.', 'その僧侶は何年も瞑想をしていた。', 'us_mvp_image_1377_monk.webp', 'say-459251ba-caaedced-ecf3eefb-7d3c960d-6a29b704.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'worship'), 'シンプル', 'They worship at the temple every week.', '彼らは毎週寺院で礼拝する。', 'us_mvp_image_1378_worship.webp', 'say-f931eb05-0d59e9d5-c1c6139a-1395dc41-dc021f80.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'indispensable'), 'シンプル', 'Water is indispensable for life.', '水は生命に不可欠だ。', 'us_mvp_image_1383_indispensable.webp', 'say-936f5b27-8e7713f2-6daa9100-f0cc898b-4ab2d975.mp3', NOW(), NOW()),((SELECT id FROM words WHERE word_text = 'ambiguous'), 'シンプル', 'His answer was ambiguous.', '彼の答えは曖昧だった。', 'us_mvp_image_1386_ambiguous.webp', 'say-0829e980-30ba4