-- Batch 1 - Words 1 to 100

ON CONFLICT (word_text) DO UPDATE SET
    definition = EXCLUDED.definition,
    part_of_speech = EXCLUDED.part_of_speech,
    etymology = EXCLUDED.etymology,
    updated_at = NOW();




ON CONFLICT (deck_id, word_id) DO NOTHING;
